window.APEX_DATA_PREMADE_CARDS = {
"phy1-si-units": [
  {id:"phy1-si-units-c5", front:"What is the SI unit of luminous intensity?", back:"The <b>candela (cd)</b> is the SI base unit of luminous intensity."},
  {id:"phy1-si-units-c6", front:"How many base units are there in the SI system?", back:"There are <b>seven base units</b>: metre, kilogram, second, ampere, kelvin, mole, and candela."},
  {id:"phy1-si-units-c7", front:"What is the SI unit of amount of substance?", back:"The <b>mole (mol)</b>, defined as containing as many elementary entities as there are atoms in 12 g of carbon-12."},
  {id:"phy1-si-units-c8", front:"Define 'significant figures' in a measurement.", back:"The digits in a measured value that are <b>reliably known</b> plus one <b>uncertain digit</b>, indicating measurement precision."}
],
"bio36-asexual-reproduction": [
  {id:"bio36-asexual-reproduction-c1", front:"What is binary fission?", back:"Parent cell divides into <b>two</b> equal daughter cells (e.g., Amoeba, Paramecium)."},
  {id:"bio36-asexual-reproduction-c2", front:"Give an example of budding.", back:"<b>Hydra</b> and <b>yeast</b> form an outgrowth (bud) that detaches to form a new individual."},
  {id:"bio36-asexual-reproduction-c3", front:"Which alga reproduces by fragmentation?", back:"<b>Spirogyra</b> — each fragment of the filament grows into a new organism."},
  {id:"bio36-asexual-reproduction-c4", front:"What structure produces spores in Rhizopus?", back:"The <b>sporangium</b>, borne on a sporangiophore."}
],
"bio36-sexual-reproduction": [
  {id:"bio36-sexual-reproduction-c1", front:"Name the three phases of an organism's life span.", back:"<b>Juvenile</b>, <b>reproductive</b>, and <b>senescent</b> phase."},
  {id:"bio36-sexual-reproduction-c2", front:"What is syngamy?", back:"Fusion of male and female <b>gametes</b> to form a diploid <b>zygote</b>."},
  {id:"bio36-sexual-reproduction-c3", front:"Differentiate isogamy from oogamy.", back:"Isogamy: fusing gametes are <b>morphologically similar</b>; Oogamy: one large non-motile and one small motile gamete fuse (e.g. humans)."},
  {id:"bio36-sexual-reproduction-c4", front:"What is vernalisation?", back:"Induction of flowering in plants by exposure to a period of <b>low temperature</b>."}
],
"bio37-animal-husbandry": [
  {id:"bio37-animal-husbandry-c1", front:"What is inbreeding?", back:"Mating between closely related individuals of the <b>same breed</b> for 4-6 generations; increases homozygosity."},
  {id:"bio37-animal-husbandry-c2", front:"What does MOET stand for and do?", back:"<b>Multiple Ovulation Embryo Transfer Technology</b> — induces superovulation in a cow and transfers resulting embryos to surrogate mothers."},
  {id:"bio37-animal-husbandry-c3", front:"Give an example of interspecific hybridisation.", back:"<b>Mule</b> — offspring of a female horse and male donkey."},
  {id:"bio37-animal-husbandry-c4", front:"Name two Indian milch cattle breeds.", back:"<b>Sahiwal</b> and <b>Red Sindhi</b>."}
],
"bio37-plant-breeding": [
  {id:"bio37-plant-breeding-c1", front:"What is the first step in plant breeding?", back:"<b>Collection of genetic variability</b> (germplasm collection)."},
  {id:"bio37-plant-breeding-c2", front:"Which wheat variety is resistant to rust diseases?", back:"<b>Himgiri</b> — resistant to leaf and stripe rust."},
  {id:"bio37-plant-breeding-c3", front:"What is biofortification?", back:"Breeding crops with higher <b>vitamins, minerals, protein or fat</b> content, e.g. vitamin A-rich carrots."},
  {id:"bio37-plant-breeding-c4", front:"Where were semi-dwarf rice varieties like Jaya and Ratna developed?", back:"At <b>IRRI</b> (International Rice Research Institute), Philippines."}
],
"bio37-scp-tissue-culture": [
  {id:"bio37-scp-tissue-culture-c1", front:"What is a Single Cell Protein (SCP) example?", back:"<b>Spirulina</b> — grown on wastewater, rich in protein, minerals and fats."},
  {id:"bio37-scp-tissue-culture-c2", front:"What is totipotency?", back:"Ability of a plant cell to regenerate into a <b>whole new plant</b>; demonstrated by F.C. Steward using carrot cells."},
  {id:"bio37-scp-tissue-culture-c3", front:"What are somaclones?", back:"Genetically <b>identical</b> plants produced in bulk via <b>micropropagation</b>."},
  {id:"bio37-scp-tissue-culture-c4", front:"Which bacterium is a high-yield SCP source?", back:"<b>Methylophilus methylotrophus</b> — ~25 tonnes protein from 250 kg bacteria."}
],
"bio38-air-water-pollution": [
  {id:"bio38-air-water-pollution-c1", front:"What metals are used in catalytic converters?", back:"<b>Platinum, palladium, and rhodium</b> — require unleaded petrol to avoid poisoning."},
  {id:"bio38-air-water-pollution-c2", front:"Define eutrophication.", back:"Nutrient <b>enrichment</b> of a water body causing excess algal growth and <b>oxygen depletion</b>."},
  {id:"bio38-air-water-pollution-c3", front:"What is biomagnification? Give an example.", back:"Increase in <b>toxicant concentration</b> at higher trophic levels; e.g. <b>DDT</b> reaching ~25 ppm in fish-eating birds."},
  {id:"bio38-air-water-pollution-c4", front:"What caused Minamata disease?", back:"Consumption of fish contaminated with <b>methylmercury</b> in Minamata Bay, Japan."}
],
"bio38-solid-waste": [
  {id:"bio38-solid-waste-c1", front:"What is e-waste and why is it hazardous?", back:"Discarded electronics; contains toxic heavy metals like <b>lead, cadmium and mercury</b>."},
  {id:"bio38-solid-waste-c2", front:"What do the 3 R's stand for?", back:"<b>Reduce, Reuse, Recycle</b> — principle to minimise solid waste."},
  {id:"bio38-solid-waste-c3", front:"How is radioactive waste disposed of?", back:"Stored in <b>shielded containers</b> and buried deep underground or in the ocean."},
  {id:"bio38-solid-waste-c4", front:"Why does radioactive waste stay hazardous for long periods?", back:"Many isotopes have a <b>long half-life</b>, decaying slowly over long timescales."}
],
"bio38-global-change": [
  {id:"bio38-global-change-c1", front:"Name three major greenhouse gases.", back:"<b>Carbon dioxide, methane</b>, and <b>CFCs</b> (also water vapour, nitrous oxide)."},
  {id:"bio38-global-change-c2", front:"How do CFCs destroy ozone?", back:"UV light releases <b>chlorine atoms</b> from CFCs, which catalytically break down many <b>ozone (O3)</b> molecules."},
  {id:"bio38-global-change-c3", front:"What treaty controls ozone-depleting substances?", back:"The <b>Montreal Protocol</b> (1987)."},
  {id:"bio38-global-change-c4", front:"Name two consequences of deforestation.", back:"Reduced <b>CO2 absorption</b>, disrupted hydrologic cycle, <b>soil erosion</b>, and biodiversity loss."}
],
"bio33-water-relations": [
  {id:"bio33-water-relations-c1", front:"What is water potential?", back:"Ψw = Ψs (solute potential) + Ψp (pressure potential); water always moves from higher to lower <b>water potential</b>."},
  {id:"bio33-water-relations-c2", front:"Define plasmolysis.", back:"Shrinkage of the <b>protoplast</b> away from the cell wall when a plant cell is placed in a hypertonic (highly concentrated) external solution."},
  {id:"bio33-water-relations-c3", front:"What distinguishes active transport from diffusion?", back:"<b>Active transport</b> requires ATP and moves solutes against their concentration gradient using carrier proteins; diffusion needs no energy."},
  {id:"bio33-water-relations-c4", front:"What is imbibition?", back:"Adsorption of water by solid colloidal particles (e.g., seeds, dry wood) causing them to swell; a special type of <b>diffusion</b> of water along a water potential gradient."}
],
"bio33-long-distance-water": [
  {id:"bio33-long-distance-water-c1", front:"Who proposed the transpiration pull theory?", back:"<b>Dixon and Joly</b>, based on the cohesion-tension mechanism of water transport in the xylem."},
  {id:"bio33-long-distance-water-c2", front:"What is guttation?", back:"Loss of water in liquid form from <b>hydathodes</b> at leaf tips/margins, occurring when root pressure exceeds transpiration rate (e.g., early morning)."},
  {id:"bio33-long-distance-water-c3", front:"What property of water allows it to form an unbroken column in the xylem?", back:"<b>Cohesion</b> (mutual attraction between water molecules) and <b>adhesion</b> to xylem walls give water high tensile strength."},
  {id:"bio33-long-distance-water-c4", front:"What causes root pressure?", back:"Active pumping of mineral ions into the root xylem creates an osmotic gradient that draws water into the xylem, generating <b>root pressure</b>."}
],
"bio33-phloem-transport": [
  {id:"bio33-phloem-transport-c1", front:"Name the hypothesis explaining phloem transport.", back:"<b>Pressure flow (mass flow) hypothesis</b>, proposed by Ernst Münch."},
  {id:"bio33-phloem-transport-c2", front:"Which sugar is mainly translocated in phloem?", back:"<b>Sucrose</b>, transported from source to sink."},
  {id:"bio33-phloem-transport-c3", front:"Is phloem transport unidirectional or bidirectional?", back:"<b>Bidirectional</b> — direction depends on the position of source and sink, unlike the unidirectional upward flow in xylem."},
  {id:"bio33-phloem-transport-c4", front:"What loads sucrose into sieve tubes at the source, and what does it require?", back:"Active loading via companion cells using a <b>proton-sucrose co-transport</b> mechanism that requires ATP."}
],
"bio34-essential-elements": [
  {id:"bio34-essential-elements-c1", front:"How many elements are considered essential for plants?", back:"<b>17</b> essential elements — 9 macronutrients and 8 micronutrients."},
  {id:"bio34-essential-elements-c2", front:"Name the three criteria of essentiality (Arnon and Stout).", back:"Element must be necessary to complete the <b>life cycle</b>, its requirement must be <b>specific</b> (non-replaceable), and it must be <b>directly involved</b> in metabolism."},
  {id:"bio34-essential-elements-c3", front:"Deficiency symptoms of mobile elements (like N, K, Mg) appear first where?", back:"In <b>older/senescent leaves</b>, since mobile elements are retranslocated to younger, actively growing tissues."},
  {id:"bio34-essential-elements-c4", front:"What is chlorosis?", back:"Loss of <b>chlorophyll</b> leading to yellowing of leaves, a common deficiency symptom (e.g., of N, Mg, S, Fe)."}
],
"bio34-absorption-nitrogen": [
  {id:"bio34-absorption-nitrogen-c1", front:"Which enzyme catalyses biological nitrogen fixation?", back:"<b>Nitrogenase</b> (a MoFe protein), which reduces atmospheric N2 to NH3."},
  {id:"bio34-absorption-nitrogen-c2", front:"What is the role of leghaemoglobin in root nodules?", back:"It is an <b>oxygen scavenger</b> that protects the oxygen-sensitive nitrogenase enzyme from inactivation."},
  {id:"bio34-absorption-nitrogen-c3", front:"Name the key pathway for ammonia assimilation into amino acids.", back:"The <b>GS-GOGAT pathway</b> (glutamine synthetase + glutamate synthase/GOGAT)."},
  {id:"bio34-absorption-nitrogen-c4", front:"What are the two mechanisms of mineral ion absorption by roots?", back:"<b>Passive</b> transport (diffusion, no energy) and <b>active</b> transport (against gradient, requires ATP and carrier proteins)."}
],
"bio35-alimentary-canal": [
  {id:"bio35-alimentary-canal-c1", front:"What is the human dental formula (permanent teeth)?", back:"<b>2123/2123</b>, giving a total of 32 permanent teeth (diphyodont, thecodont dentition)."},
  {id:"bio35-alimentary-canal-c2", front:"Name the three regions of the small intestine.", back:"<b>Duodenum</b>, <b>jejunum</b>, and <b>ileum</b>."},
  {id:"bio35-alimentary-canal-c3", front:"What are the three types of cells in gastric glands?", back:"<b>Mucous neck cells</b> (mucus), <b>peptic/chief cells</b> (pepsinogen), and <b>parietal/oxyntic cells</b> (HCl and intrinsic factor)."},
  {id:"bio35-alimentary-canal-c4", front:"Is the pancreas an exocrine or endocrine gland?", back:"Both — it is a <b>heterocrine (mixed) gland</b>, exocrine (pancreatic juice) and endocrine (islets of Langerhans secrete insulin & glucagon)."}
],
"bio35-digestion-absorption": [
  {id:"bio35-digestion-absorption-c1", front:"What activates pepsinogen to pepsin?", back:"<b>HCl</b> (hydrochloric acid) secreted by parietal cells of the stomach."},
  {id:"bio35-digestion-absorption-c2", front:"What activates trypsinogen to trypsin?", back:"<b>Enterokinase</b>, an enzyme secreted by the intestinal mucosa."},
  {id:"bio35-digestion-absorption-c3", front:"How are absorbed fats transported from the intestine?", back:"As <b>chylomicrons</b> via lacteals into the lymphatic system, then into the blood."},
  {id:"bio35-digestion-absorption-c4", front:"What causes jaundice?", back:"Liver dysfunction leading to deposition of the bile pigment <b>bilirubin</b> in tissues, causing yellowing of skin and eyes."}
],
"math15-principle": [
  {id:"math15-principle-c1", front:"What is the base case in mathematical induction?", back:"The verification that the statement <b>P(1)</b> (or the smallest relevant n) is true — the starting point of the proof."},
  {id:"math15-principle-c2", front:"What is the inductive hypothesis?", back:"The assumption that <b>P(k) is true</b> for some arbitrary natural number k, used to prove P(k+1)."},
  {id:"math15-principle-c3", front:"What is the inductive step?", back:"Proving that <b>P(k) ⟹ P(k+1)</b>, i.e., the truth of P(k) forces the truth of P(k+1)."},
  {id:"math15-principle-c4", front:"Why does induction prove a statement for all natural numbers, not just the checked cases?", back:"Because the base case plus the inductive step form a <b>chain reaction</b>: P(1)→P(2)→P(3)→… covering every natural number."}
],
"math16-statements-connectives": [
  {id:"math16-statements-connectives-c1", front:"What makes a sentence a 'mathematically acceptable statement'?", back:"It must be a declarative sentence that is <b>either true or false, but not both</b> (not an opinion, question, command, or exclamation)."},
  {id:"math16-statements-connectives-c2", front:"How do you negate 'All A are B'?", back:"The negation is <b>'Some A are not B'</b> (not 'No A are B')."},
  {id:"math16-statements-connectives-c3", front:"When is the compound statement 'p and q' true?", back:"Only when <b>both p and q are true</b>; if either is false, 'p and q' is false."},
  {id:"math16-statements-connectives-c4", front:"What kind of 'or' does mathematics use?", back:"The <b>inclusive or</b> — 'p or q' is true if p is true, q is true, or <b>both</b> are true."}
],
"math16-implications-validity": [
  {id:"math16-implications-validity-c1", front:"What is the contrapositive of 'If p, then q'?", back:"'<b>If not q, then not p</b>' — it is logically equivalent to the original statement."},
  {id:"math16-implications-validity-c2", front:"What is the converse of 'If p, then q'?", back:"'<b>If q, then p</b>' — it is NOT logically equivalent to the original."},
  {id:"math16-implications-validity-c3", front:"When is 'p ⇒ q' false?", back:"Only when <b>p is true and q is false</b>; in every other case (including when p is false) it is true."},
  {id:"math16-implications-validity-c4", front:"How do you prove 'if p then q' by contradiction?", back:"Assume <b>p is true and q is false</b>, then show this assumption leads to a logical contradiction."}
],
"math17-algebraic-one-variable": [
  {id:"math17-algebraic-one-variable-c1", front:"What happens to an inequality sign when you multiply or divide both sides by a negative number?", back:"The inequality sign <b>reverses</b> (flips direction)."},
  {id:"math17-algebraic-one-variable-c2", front:"How is a strict inequality (< or >) shown on a number line?", back:"With an <b>open circle</b> (hollow dot) at the boundary point, since that point is excluded."},
  {id:"math17-algebraic-one-variable-c3", front:"How is a non-strict inequality (≤ or ≥) shown on a number line?", back:"With a <b>closed (filled) circle</b> at the boundary point, since that point is included."},
  {id:"math17-algebraic-one-variable-c4", front:"How do you solve a system of two linear inequalities in one variable?", back:"Solve each inequality separately, then take the <b>intersection</b> of their solution sets."}
],
"math17-graphical-two-variable": [
  {id:"math17-graphical-two-variable-c1", front:"How do you decide whether to draw the boundary line solid or dashed?", back:"<b>Solid</b> for ≤ or ≥ (boundary included); <b>dashed</b> for < or > (boundary excluded)."},
  {id:"math17-graphical-two-variable-c2", front:"How do you find which side of the boundary line to shade?", back:"Substitute a convenient <b>test point</b> (usually the origin, if not on the line) into the inequality — shade the side containing points that satisfy it."},
  {id:"math17-graphical-two-variable-c3", front:"What region do the constraints x≥0 and y≥0 always represent?", back:"The <b>first quadrant</b> (including both axes)."},
  {id:"math17-graphical-two-variable-c4", front:"How do you find the vertices of a feasible region formed by several inequalities?", back:"Find the points where pairs of <b>boundary lines intersect</b> (solve them simultaneously), keeping only those satisfying all constraints."}
],
"math18-formulation": [
  {id:"math18-formulation-c1", front:"What are 'decision variables' in an LPP?", back:"The unknown quantities (e.g., x, y) that we control and want to determine, usually representing quantities produced or purchased."},
  {id:"math18-formulation-c2", front:"What is the 'objective function' in an LPP?", back:"The <b>linear function</b> (e.g., Z = ax+by) that is to be <b>maximized or minimized</b>."},
  {id:"math18-formulation-c3", front:"What are 'constraints' in an LPP?", back:"The <b>linear inequalities or equations</b> (including non-negativity restrictions) that the decision variables must satisfy."},
  {id:"math18-formulation-c4", front:"Why are non-negativity restrictions (x≥0, y≥0) always included?", back:"Because decision variables typically represent physical quantities (units produced, kg used) that <b>cannot be negative</b>."}
],
"math18-graphical-method": [
  {id:"math18-graphical-method-c1", front:"What does the Corner Point Theorem state?", back:"If an optimal value of the objective function exists, it occurs at a <b>corner point (vertex)</b> of the feasible region."},
  {id:"math18-graphical-method-c2", front:"What is the feasible region?", back:"The <b>common region</b> of points satisfying all the constraints (including non-negativity) simultaneously."},
  {id:"math18-graphical-method-c3", front:"When is a feasible region called 'bounded'?", back:"When it can be <b>enclosed within a circle</b> of finite radius — then both maximum and minimum of Z exist."},
  {id:"math18-graphical-method-c4", front:"How do you check for a maximum on an unbounded feasible region?", back:"Check whether the open half-plane <b>Z > M</b> (M = value at the largest corner) has points in common with the feasible region; if not, M is the maximum."}
],
"math18-problem-types": [
  {id:"math18-problem-types-c1", front:"What is a 'diet problem' in LPP?", back:"A problem that <b>minimizes cost</b> subject to <b>minimum nutritional requirement</b> (≥) constraints."},
  {id:"math18-problem-types-c2", front:"What is a 'manufacturing problem' in LPP?", back:"A problem that typically <b>maximizes profit</b> subject to limited <b>resource</b> constraints (labor, machine hours, raw material — usually ≤)."},
  {id:"math18-problem-types-c3", front:"What direction do resource constraints usually take in a manufacturing LPP?", back:"<b>≤ (less than or equal to)</b>, since resources like time and materials are limited/available in fixed supply."},
  {id:"math18-problem-types-c4", front:"What direction do requirement constraints usually take in a diet/nutrition LPP?", back:"<b>≥ (greater than or equal to)</b>, since at least a minimum amount of each nutrient is needed."}
],
"phy21-thermal-expansion": [
  {id:"phy21-thermal-expansion-c1", front:"What is the relation between the coefficients of linear, areal, and cubical expansion for an isotropic solid?", back:"<b>β = 2α, γ = 3α</b> (so α : β : γ = 1 : 2 : 3)"},
  {id:"phy21-thermal-expansion-c2", front:"At what temperature does water have maximum density?", back:"<b>4°C</b> — due to the anomalous expansion of water"},
  {id:"phy21-thermal-expansion-c3", front:"What is the formula for thermal stress in a rod rigidly fixed at both ends?", back:"<b>Thermal stress = YαΔT</b> (Y = Young's modulus)"},
  {id:"phy21-thermal-expansion-c4", front:"How does a bimetallic strip behave on heating?", back:"It <b>bends towards the metal with lower α</b> — used in thermostats and thermal switches"}
],
"phy21-calorimetry": [
  {id:"phy21-calorimetry-c1", front:"State the principle of calorimetry.", back:"In an isolated system, <b>heat lost by hot body = heat gained by cold body</b>"},
  {id:"phy21-calorimetry-c2", front:"What is the formula relating heat, mass, specific heat, and temperature change?", back:"<b>Q = mcΔT</b>"},
  {id:"phy21-calorimetry-c3", front:"What is latent heat, and what is its formula?", back:"Heat absorbed/released during change of state at constant temperature: <b>Q = mL</b>"},
  {id:"phy21-calorimetry-c4", front:"What are the approximate latent heats of fusion and vaporization of water?", back:"L<sub>fusion</sub> ≈ <b>336 J/g (80 cal/g)</b>; L<sub>vaporization</sub> ≈ <b>2260 J/g (540 cal/g)</b>"}
],
"phy21-heat-transfer": [
  {id:"phy21-heat-transfer-c1", front:"State Fourier's law of heat conduction.", back:"Rate of heat flow <b>dQ/dt = kA(ΔT/x)</b>, where k is thermal conductivity"},
  {id:"phy21-heat-transfer-c2", front:"State Wien's displacement law.", back:"<b>λ_max T = b</b> (b = 2.9×10⁻³ m·K, Wien's constant)"},
  {id:"phy21-heat-transfer-c3", front:"State the Stefan-Boltzmann law.", back:"Power radiated by a black body: <b>P = σAT⁴</b> (σ = 5.67×10⁻⁸ W/m²K⁴)"},
  {id:"phy21-heat-transfer-c4", front:"State Newton's law of cooling.", back:"Rate of cooling <b>∝ (T − T₀)</b>, valid only for small temperature differences with surroundings"}
],
"phy24-elements-bandwidth": [
  {id:"phy24-elements-bandwidth-c1", front:"Name the three basic elements of a communication system.", back:"<b>Transmitter, Channel (medium), Receiver</b>"},
  {id:"phy24-elements-bandwidth-c2", front:"What is 'attenuation' in signal transmission?", back:"<b>Loss of signal strength</b> while propagating through a medium"},
  {id:"phy24-elements-bandwidth-c3", front:"What is the approximate bandwidth needed for telephone-quality speech signals?", back:"About <b>0.3–3.4 kHz</b>"},
  {id:"phy24-elements-bandwidth-c4", front:"Which transmission medium offers the largest bandwidth?", back:"<b>Optical fibre</b> (potential bandwidth in the THz range)"}
],
"phy24-modulation": [
  {id:"phy24-modulation-c1", front:"Why is modulation needed for transmitting low-frequency signals?", back:"Low-frequency (audio) signals need <b>impractically large antennas</b> and don't radiate efficiently — modulation superimposes them on a high-frequency carrier"},
  {id:"phy24-modulation-c2", front:"Give the formula for the modulation index in AM.", back:"<b>μ = A_m / A_c</b> (also μ = (A_max − A_min)/(A_max + A_min))"},
  {id:"phy24-modulation-c3", front:"What changes in AM vs FM?", back:"AM: <b>amplitude</b> of carrier varies; FM: <b>frequency</b> of carrier varies (amplitude stays constant)"},
  {id:"phy24-modulation-c4", front:"What is the bandwidth of an AM signal in terms of message frequency f_m?", back:"<b>Bandwidth = 2f_m</b> (upper and lower sidebands at f_c ± f_m)"}
],
"phy24-propagation": [
  {id:"phy24-propagation-c1", front:"What is ground wave propagation used for?", back:"Low-frequency <b>AM/MW</b> broadcasts — the wave travels along the Earth's surface"},
  {id:"phy24-propagation-c2", front:"What enables sky wave propagation, and what is its typical frequency range?", back:"Reflection from the <b>ionosphere</b>; effective up to about <b>30–40 MHz</b> (short wave)"},
  {id:"phy24-propagation-c3", front:"Give the formula for the maximum line-of-sight distance from a transmitting antenna of height h.", back:"<b>d = √(2Rh)</b> (R = radius of Earth)"},
  {id:"phy24-propagation-c4", front:"What altitude and orbital period does a geostationary communication satellite have?", back:"Altitude ≈ <b>36,000 km</b>, orbital period = <b>24 hours</b> (matches Earth's rotation)"}
],
"ch27-dihydrogen": [
  {id:"ch27-dihydrogen-c1", front:"Why is hydrogen placed separately in the periodic table?", back:"It resembles alkali metals (forms <b>H+</b>) and halogens (forms <b>H-</b>, exists as diatomic H2) at once."},
  {id:"ch27-dihydrogen-c2", front:"Name the three isotopes of hydrogen.", back:"<b>Protium</b> (no neutron), <b>Deuterium</b> (1 neutron), <b>Tritium</b> (2 neutrons, radioactive)."},
  {id:"ch27-dihydrogen-c3", front:"What is the lab reaction for preparing dihydrogen?", back:"<b>Zn + dilute H2SO4 → ZnSO4 + H2</b>"},
  {id:"ch27-dihydrogen-c4", front:"What catalyst is used in the Haber process for making ammonia from H2 and N2?", back:"<b>Finely divided iron</b> (with Mo promoter), at ~673 K and 200 atm."}
],
"ch27-hydrides-water": [
  {id:"ch27-hydrides-water-c1", front:"What are the three classes of binary hydrides?", back:"<b>Ionic (saline)</b>, <b>covalent (molecular)</b>, and <b>metallic (interstitial)</b> hydrides."},
  {id:"ch27-hydrides-water-c2", front:"Give an example each of electron-deficient, electron-precise, and electron-rich hydrides.", back:"<b>B2H6</b> (deficient), <b>CH4</b> (precise), <b>NH3/H2O</b> (rich)."},
  {id:"ch27-hydrides-water-c3", front:"What is the H-O-H bond angle in water?", back:"About <b>104.5°</b>, due to sp3 oxygen with two lone pairs."},
  {id:"ch27-hydrides-water-c4", front:"How is permanent hardness of water removed?", back:"By adding <b>washing soda (Na2CO3)</b> or using an <b>ion-exchange (zeolite)</b> process."}
],
"ch27-peroxide-fuel": [
  {id:"ch27-peroxide-fuel-c1", front:"What is the lab method to prepare H2O2?", back:"Treat <b>barium peroxide</b> with dilute <b>H2SO4</b>; BaSO4 precipitates out."},
  {id:"ch27-peroxide-fuel-c2", front:"Describe the structure of H2O2.", back:"Non-planar '<b>open book</b>' structure with a dihedral angle (~111.5° in gas phase)."},
  {id:"ch27-peroxide-fuel-c3", front:"Why is H2O2 stored in wax-lined bottles, in the dark, with urea added?", back:"To prevent <b>catalytic decomposition (disproportionation)</b> into water and oxygen."},
  {id:"ch27-peroxide-fuel-c4", front:"What is the main advantage of hydrogen as a fuel?", back:"High <b>calorific value</b>, and combustion gives only <b>water</b> — a clean, non-polluting fuel."}
],
"ch28-s-block": [
  {id:"ch28-s-block-c1", front:"What flame colours do Na, K, and Ca impart?", back:"Na = <b>golden yellow</b>, K = <b>lilac</b>, Ca = <b>brick red</b>."},
  {id:"ch28-s-block-c2", front:"Why is beryllium anomalous among Group 2 elements?", back:"Very <b>small size</b> and <b>high ionization enthalpy</b> give it mostly <b>covalent</b> chemistry (diagonal relation to Al)."},
  {id:"ch28-s-block-c3", front:"What is Plaster of Paris and how is it made?", back:"<b>CaSO4·½H2O</b>, made by heating <b>gypsum</b> at 393 K."},
  {id:"ch28-s-block-c4", front:"Name the key biological roles of Ca2+ and Mg2+.", back:"Ca2+: <b>bones, teeth, blood clotting</b>. Mg2+: central atom in <b>chlorophyll</b>, enzyme cofactor."}
],
"ch29-group13": [
  {id:"ch29-group13-c1", front:"What is boron's maximum covalency and why?", back:"<b>4</b> — it has no d-orbitals, so only one s and three p orbitals are available for bonding."},
  {id:"ch29-group13-c2", front:"Describe the bonding in diborane, B2H6.", back:"4 terminal 2c-2e B-H bonds + 2 bridging <b>3-centre-2-electron (banana) bonds</b>."},
  {id:"ch29-group13-c3", front:"Which oxidation state of thallium is more stable, and why?", back:"<b>Tl(I)</b> is more stable than Tl(III) due to the <b>inert pair effect</b>."},
  {id:"ch29-group13-c4", front:"How is aluminium extracted industrially?", back:"By the <b>Hall-Héroult process</b> — electrolysis of alumina dissolved in molten <b>cryolite</b>."}
],
"ch29-group14": [
  {id:"ch29-group14-c1", front:"Why does carbon show maximum catenation among Group 14 elements?", back:"Small size plus a very strong, stable <b>C-C bond</b>."},
  {id:"ch29-group14-c2", front:"Compare hybridization in diamond vs graphite.", back:"Diamond: <b>sp3</b> (3D network). Graphite: <b>sp2</b> (planar layers, delocalized electrons conduct electricity)."},
  {id:"ch29-group14-c3", front:"Why is C60 (fullerene) called the purest form of carbon?", back:"It has a definite <b>molecular formula/structure</b>, unlike the giant networks of diamond and graphite."},
  {id:"ch29-group14-c4", front:"What is the basic structural unit of silicates?", back:"The <b>SiO4^4- tetrahedron</b>."}
],
"ch30-atmospheric-pollution": [
  {id:"ch30-atmospheric-pollution-c1", front:"What distinguishes classical (London) smog from photochemical smog?", back:"Classical smog is <b>reducing</b> (SO2+smoke+fog); photochemical smog is <b>oxidising</b> (NO2+hydrocarbons+sunlight, forms O3, PAN)."},
  {id:"ch30-atmospheric-pollution-c2", front:"What causes stratospheric ozone depletion?", back:"<b>CFCs</b> release <b>Cl radicals</b> under UV light that catalytically destroy O3 molecules."},
  {id:"ch30-atmospheric-pollution-c3", front:"Name three major greenhouse gases.", back:"<b>CO2, CH4, N2O</b> (also water vapour and O3)."},
  {id:"ch30-atmospheric-pollution-c4", front:"What do catalytic converters remove from vehicle exhaust?", back:"Convert <b>CO, unburnt hydrocarbons, and NOx</b> into CO2, H2O, and N2."}
],
"ch30-water-soil-pollution": [
  {id:"ch30-water-soil-pollution-c1", front:"Define BOD.", back:"<b>Biochemical Oxygen Demand</b> — oxygen needed by microbes to decompose organic matter in water; clean water has BOD < 5 ppm."},
  {id:"ch30-water-soil-pollution-c2", front:"What is eutrophication and what causes it?", back:"Excess <b>nitrates/phosphates</b> cause algal bloom; decomposition of dead algae depletes <b>dissolved oxygen</b>, killing aquatic life."},
  {id:"ch30-water-soil-pollution-c3", front:"Why is DDT an environmental concern?", back:"It is <b>non-biodegradable</b> and undergoes <b>biomagnification</b> up the food chain."},
  {id:"ch30-water-soil-pollution-c4", front:"What is the safe fluoride limit in drinking water?", back:"About <b>1 ppm</b>; excess causes <b>fluorosis</b>."}
],
"ch30-green-chemistry": [
  {id:"ch30-green-chemistry-c1", front:"Define green chemistry.", back:"Designing chemical processes/products to <b>reduce or eliminate hazardous substances</b>."},
  {id:"ch30-green-chemistry-c2", front:"What is atom economy?", back:"<b>(Mass of desired product / total mass of reactants) × 100</b> — higher value means less waste."},
  {id:"ch30-green-chemistry-c3", front:"Give an NCERT green chemistry example for dry cleaning.", back:"Using <b>liquid CO2 with a detergent</b> instead of tetrachloroethene."},
  {id:"ch30-green-chemistry-c4", front:"What is the 3R approach to waste management?", back:"<b>Reduce, Reuse, Recycle</b>."}
],
"ch24-classification-polymerization": [
  {id:"ch24-classification-polymerization-c1", front:"What are the two main classes of polymers based on source?", back:"<b>Natural polymers</b> (e.g. starch, cellulose, natural rubber) and <b>synthetic polymers</b> (e.g. polythene, nylon)"},
  {id:"ch24-classification-polymerization-c2", front:"What is chain-growth (addition) polymerization?", back:"Rapid addition of monomer units (usually containing a double bond) to a growing chain via a <b>free radical, cationic, or anionic</b> mechanism, without loss of any small molecule"},
  {id:"ch24-classification-polymerization-c3", front:"What is a copolymer? Give an example.", back:"A polymer formed from <b>two or more different monomers</b>; e.g. <b>Buna-S</b> (1,3-butadiene + styrene)"},
  {id:"ch24-classification-polymerization-c4", front:"Name the three steps of free radical addition polymerization.", back:"<b>Initiation, Propagation, and Termination</b>"}
],
"ch24-important-polymers": [
  {id:"ch24-important-polymers-c1", front:"What monomer forms Teflon?", back:"<b>Tetrafluoroethylene</b>, polymerized under high pressure with a free radical/persulphate catalyst"},
  {id:"ch24-important-polymers-c2", front:"What is bakelite made from?", back:"A condensation polymer of <b>phenol and formaldehyde</b> (a phenol-formaldehyde resin)"},
  {id:"ch24-important-polymers-c3", front:"What is vulcanization?", back:"Heating natural rubber with <b>sulfur</b> (with additives) to introduce cross-links, improving elasticity and reducing tackiness"},
  {id:"ch24-important-polymers-c4", front:"What are the two monomers of Nylon-6,6?", back:"<b>Hexamethylenediamine</b> and <b>adipic acid</b>"}
],
"ch24-molecular-mass-biodegradable": [
  {id:"ch24-molecular-mass-biodegradable-c1", front:"Define number-average molecular mass, Mn.", back:"\\( M_n = \\dfrac{\\sum N_i M_i}{\\sum N_i} \\), the average based on the <b>number of molecules</b> of each size"},
  {id:"ch24-molecular-mass-biodegradable-c2", front:"What does PDI (polydispersity index) measure?", back:"<b>Mw/Mn</b> — a measure of the breadth of chain-length distribution; PDI = 1 means a perfectly uniform (monodisperse) sample"},
  {id:"ch24-molecular-mass-biodegradable-c3", front:"Give an example of a biodegradable polymer.", back:"<b>PHBV</b> (poly-β-hydroxybutyrate-co-β-hydroxyvalerate)"},
  {id:"ch24-molecular-mass-biodegradable-c4", front:"What is Nylon-2-nylon-6 made from?", back:"Condensation of <b>glycine</b> and <b>6-aminohexanoic acid</b>"}
],
"ch25-drugs-classification": [
  {id:"ch25-drugs-classification-c1", front:"What is the difference between an agonist and an antagonist drug?", back:"<b>Agonists</b> bind to a receptor and activate it (mimic the natural messenger); <b>antagonists</b> bind and block the receptor without activating it"},
  {id:"ch25-drugs-classification-c2", front:"Name two ways drugs can be classified.", back:"By <b>pharmacological effect</b> (e.g. all analgesics) or by <b>chemical structure</b> (e.g. all sulphonamides)"},
  {id:"ch25-drugs-classification-c3", front:"What are the two main molecular targets of most drugs in the body?", back:"<b>Enzymes</b> and <b>receptors</b> — both are proteins"},
  {id:"ch25-drugs-classification-c4", front:"How does a competitive inhibitor act on an enzyme?", back:"It binds to the enzyme's <b>active site</b>, blocking the substrate from binding, thereby reducing catalytic activity"}
],
"ch25-drugs-action": [
  {id:"ch25-drugs-action-c1", front:"How do antacids relieve acidity?", back:"They <b>neutralize excess HCl</b> in the stomach"},
  {id:"ch25-drugs-action-c2", front:"What is the difference between bactericidal and bacteriostatic drugs?", back:"<b>Bactericidal</b> drugs kill bacteria (e.g. penicillin); <b>bacteriostatic</b> drugs only inhibit bacterial growth (e.g. erythromycin)"},
  {id:"ch25-drugs-action-c3", front:"Distinguish antiseptics from disinfectants.", back:"<b>Antiseptics</b> are safe on living tissue; <b>disinfectants</b> are applied to inanimate objects and are too harsh for living tissue"},
  {id:"ch25-drugs-action-c4", front:"What are tranquilizers used for?", back:"Relieving <b>stress, anxiety, and mental disorders</b>; also used as a component of sleeping pills"}
],
"ch25-food-cleansing": [
  {id:"ch25-food-cleansing-c1", front:"Why is saccharin useful for diabetics?", back:"It is <b>non-caloric</b>, excreted unchanged from the body, and does not affect insulin/sugar metabolism, while still tasting sweet"},
  {id:"ch25-food-cleansing-c2", front:"Why don't soaps work well in hard water?", back:"They form an insoluble <b>scum (precipitate) with Ca²⁺ and Mg²⁺ ions</b>, reducing cleansing action"},
  {id:"ch25-food-cleansing-c3", front:"What is a micelle?", back:"A spherical cluster of soap/detergent molecules with <b>hydrophobic tails inward</b> (trapping oil/dirt) and <b>hydrophilic heads outward</b> (facing water)"},
  {id:"ch25-food-cleansing-c4", front:"Give an example of a cationic detergent.", back:"<b>Cetyltrimethylammonium bromide</b> (a quaternary ammonium salt)"}
],
"ch26-gas-laws": [
  {id:"ch26-gas-laws-c1", front:"State Boyle's Law.", back:"At constant temperature, the volume of a fixed mass of gas is <b>inversely proportional to pressure</b> (\\( PV = \\text{constant} \\))"},
  {id:"ch26-gas-laws-c2", front:"State Charles's Law.", back:"At constant pressure, the volume of a fixed mass of gas is <b>directly proportional to its absolute (Kelvin) temperature</b>"},
  {id:"ch26-gas-laws-c3", front:"What does the ideal gas equation state?", back:"\\( PV = nRT \\), relating pressure, volume, moles, and absolute temperature of an ideal gas"},
  {id:"ch26-gas-laws-c4", front:"What is London dispersion force?", back:"A weak <b>van der Waals force</b> from instantaneous dipole–induced dipole interactions; present in all molecules, including non-polar ones"}
],
"ch26-kinetic-real-gases": [
  {id:"ch26-kinetic-real-gases-c1", front:"What does kinetic theory say about average KE and temperature?", back:"Average kinetic energy of gas molecules is <b>directly proportional to absolute temperature</b>"},
  {id:"ch26-kinetic-real-gases-c2", front:"Why do real gases deviate from ideal behavior?", back:"Because real molecules have <b>finite volume</b> and experience <b>intermolecular attractive forces</b>, unlike the ideal gas assumptions"},
  {id:"ch26-kinetic-real-gases-c3", front:"Write the van der Waals equation for one mole of gas.", back:"\\( \\left(P + \\dfrac{a}{V^2}\\right)(V-b) = RT \\), where <b>a</b> corrects for attraction and <b>b</b> for molecular volume"},
  {id:"ch26-kinetic-real-gases-c4", front:"What is the compressibility factor Z?", back:"\\( Z = \\dfrac{PV}{nRT} \\); Z = 1 for an ideal gas, <b>Z ≠ 1 indicates deviation</b> from ideal behavior"}
],
"ch26-liquid-state": [
  {id:"ch26-liquid-state-c1", front:"What is vapour pressure?", back:"The pressure exerted by vapour in <b>equilibrium</b> with its liquid at a given temperature; it increases with temperature"},
  {id:"ch26-liquid-state-c2", front:"Define surface tension.", back:"Force acting <b>per unit length</b> along the liquid surface that tends to <b>minimize surface area</b>"},
  {id:"ch26-liquid-state-c3", front:"Define viscosity.", back:"A measure of a liquid's <b>resistance to flow</b>, due to internal friction between moving layers"},
  {id:"ch26-liquid-state-c4", front:"At what condition does a liquid boil?", back:"When its <b>vapour pressure equals the external (atmospheric) pressure</b>"}
],
"ch21-crystal-lattices": [
  {id:"ch21-crystal-lattices-c1", front:"What is the defining feature of a crystalline solid?", back:"Long-range <b>order</b> — a regular, repeating three-dimensional arrangement of particles."},
  {id:"ch21-crystal-lattices-c2", front:"What is a unit cell?", back:"The smallest <b>repeating unit</b> of a crystal lattice that, when repeated in 3D, generates the whole lattice."},
  {id:"ch21-crystal-lattices-c3", front:"How many crystal systems and Bravais lattices exist?", back:"<b>7</b> crystal systems and <b>14</b> Bravais lattices."},
  {id:"ch21-crystal-lattices-c4", front:"Name the six parameters that define a unit cell.", back:"Edge lengths <b>a, b, c</b> and interfacial angles <b>α, β, γ</b>."}
],
"ch21-close-packing": [
  {id:"ch21-close-packing-c1", front:"What is the coordination number in hcp and ccp structures?", back:"<b>12</b> in both hexagonal close-packed and cubic close-packed arrangements."},
  {id:"ch21-close-packing-c2", front:"What are the packing efficiencies of simple cubic, bcc, and ccp/hcp lattices?", back:"Simple cubic <b>52.4%</b>, bcc <b>68%</b>, ccp/hcp <b>74%</b>."},
  {id:"ch21-close-packing-c3", front:"What is the stacking sequence of ccp (fcc) close packing?", back:"<b>ABCABC...</b> repeating pattern."},
  {id:"ch21-close-packing-c4", front:"State the formula relating density to unit cell data.", back:"\\( d = \\dfrac{Z \\times M}{a^3 \\times N_A} \\), where <b>Z</b> is the number of atoms per unit cell."}
],
"ch21-defects-properties": [
  {id:"ch21-defects-properties-c1", front:"What is a Schottky defect?", back:"Equal numbers of <b>cations and anions</b> are missing from their lattice sites, lowering the crystal's density."},
  {id:"ch21-defects-properties-c2", front:"What is a Frenkel defect?", back:"A smaller ion (usually the cation) leaves its lattice site and occupies an <b>interstitial site</b>, seen in AgBr, ZnS."},
  {id:"ch21-defects-properties-c3", front:"Differentiate n-type and p-type semiconductors.", back:"n-type: doped with <b>group 15</b> element (extra electron); p-type: doped with <b>group 13</b> element (electron hole)."},
  {id:"ch21-defects-properties-c4", front:"How does band gap differ across conductors, semiconductors, and insulators?", back:"Conductors: <b>no gap</b> (overlapping bands); semiconductors: <b>small gap</b>; insulators: <b>large gap</b>."}
],
"ch22-adsorption": [
  {id:"ch22-adsorption-c1", front:"Distinguish physisorption from chemisorption based on enthalpy.", back:"Physisorption: low enthalpy (<b>20-40 kJ/mol</b>, van der Waals forces); Chemisorption: high enthalpy (<b>80-240 kJ/mol</b>, chemical bond formation)."},
  {id:"ch22-adsorption-c2", front:"State the Freundlich adsorption isotherm equation.", back:"\\( \\dfrac{x}{m} = k P^{1/n} \\), where <b>x/m</b> is mass adsorbed per gram of adsorbent."},
  {id:"ch22-adsorption-c3", front:"How does temperature affect physisorption?", back:"Physisorption <b>decreases</b> with increasing temperature (exothermic process, Le Chatelier)."},
  {id:"ch22-adsorption-c4", front:"Name two factors that increase the extent of adsorption of a gas on a solid.", back:"Increase in <b>surface area</b> of adsorbent and increase in <b>pressure</b> of the gas."}
],
"ch22-catalysis": [
  {id:"ch22-catalysis-c1", front:"What is the difference between homogeneous and heterogeneous catalysis?", back:"Homogeneous: catalyst is in the <b>same phase</b> as reactants; Heterogeneous: catalyst is in a <b>different phase</b>."},
  {id:"ch22-catalysis-c2", front:"What is autocatalysis?", back:"A reaction in which <b>one of the products</b> formed acts as a catalyst for the same reaction."},
  {id:"ch22-catalysis-c3", front:"Why are enzymes highly efficient and specific catalysts?", back:"Their <b>active site</b> has a shape complementary to a specific substrate (lock-and-key model)."},
  {id:"ch22-catalysis-c4", front:"How does a catalyst increase reaction rate?", back:"By providing an alternative pathway with <b>lower activation energy</b>, without changing \\( \\Delta G \\) or the equilibrium constant."}
],
"ch22-colloids": [
  {id:"ch22-colloids-c1", front:"What causes the Tyndall effect in colloids?", back:"<b>Scattering of light</b> by colloidal particles, whose size is comparable to the wavelength of visible light."},
  {id:"ch22-colloids-c2", front:"What is Brownian motion and what causes it?", back:"The continuous zig-zag motion of colloidal particles, caused by <b>unequal collisions</b> with molecules of the dispersion medium."},
  {id:"ch22-colloids-c3", front:"State the Hardy-Schulze rule.", back:"Greater the <b>charge/valency</b> of the oppositely charged coagulating ion, greater its coagulating power."},
  {id:"ch22-colloids-c4", front:"What does a low gold number indicate about a protective colloid?", back:"A <b>lower gold number</b> means greater protective power (less of it is needed to protect the gold sol)."}
],
"ch23-occurrence-concentration": [
  {id:"ch23-occurrence-concentration-c1", front:"Differentiate between a mineral and an ore.", back:"All minerals containing a metal are not economically viable; a mineral from which a metal can be <b>extracted profitably</b> is called an ore."},
  {id:"ch23-occurrence-concentration-c2", front:"What is gangue?", back:"The unwanted <b>earthy/rocky impurities</b> associated with an ore."},
  {id:"ch23-occurrence-concentration-c3", front:"What principle underlies froth flotation?", back:"Differences in <b>wettability</b> — sulphide ore particles are preferentially wetted by oil/pine oil and float with froth, while gangue is wetted by water and sinks."},
  {id:"ch23-occurrence-concentration-c4", front:"Name the concentration method used for bauxite ore.", back:"<b>Leaching</b> (chemical concentration) — bauxite is dissolved in hot concentrated NaOH (Bayer's process) leaving gangue undissolved."}
],
"ch23-extraction-reduction": [
  {id:"ch23-extraction-reduction-c1", front:"What does the Ellingham diagram plot?", back:"<b>ΔG° of formation of metal oxides</b> (per mole of O2) against <b>temperature</b>."},
  {id:"ch23-extraction-reduction-c2", front:"How do you decide which metal reduces another metal's oxide using the Ellingham diagram?", back:"The metal whose oxide formation line lies <b>lower</b> (more negative ΔG°) at a given temperature can reduce the oxide of the metal whose line lies above it."},
  {id:"ch23-extraction-reduction-c3", front:"What is the thermite reaction used for?", back:"Reduction of <b>Fe2O3 by aluminium</b> (highly exothermic), used to weld railway tracks."},
  {id:"ch23-extraction-reduction-c4", front:"Why can't carbon reduce oxides of Na, Mg, Al, Ca easily?", back:"These metals have a <b>greater affinity for oxygen</b> than carbon at practically attainable temperatures, so they are extracted by <b>electrolytic reduction</b> instead."}
],
"ch23-refining": [
  {id:"ch23-refining-c1", front:"In electrolytic refining, which electrode is impure metal placed at?", back:"Impure metal is the <b>anode</b>; pure metal deposits at the cathode; less reactive impurities fall as <b>anode mud</b>."},
  {id:"ch23-refining-c2", front:"What principle underlies zone refining?", back:"Impurities are <b>more soluble in the molten (liquid) state</b> than the solid state, so a moving molten zone sweeps impurities to one end."},
  {id:"ch23-refining-c3", front:"Describe the Mond process for nickel refining.", back:"Impure Ni + CO → volatile <b>Ni(CO)4</b> (~330 K), which is decomposed at ~450-470 K to give <b>pure nickel</b>."},
  {id:"ch23-refining-c4", front:"What is the van Arkel method used for?", back:"Refining metals like <b>Ti and Zr</b> by converting them to a volatile iodide, which decomposes on a hot filament to deposit pure metal."}
],
"ch1-measurement": [
  {id:"ch1-measurement-c1", front:"Physical vs chemical property?", back:"<b>Physical</b>: observed without changing identity (density, colour). <b>Chemical</b>: only shown when the substance reacts (flammability)."},
  {id:"ch1-measurement-c2", front:"Extensive vs intensive property?", back:"<b>Extensive</b> scales with amount (mass, volume). <b>Intensive</b> does not (density, temperature)."},
  {id:"ch1-measurement-c3", front:"Are trailing zeros after a decimal point significant?", back:"<b>Yes</b> — e.g. 4.20 has 3 significant figures."},
  {id:"ch1-measurement-c4", front:"Precision vs accuracy?", back:"<b>Precision</b> = readings agree with each other. <b>Accuracy</b> = readings agree with the true value."}
],
"ch13-iupac-nomenclature": [
  {id:"ch13-iupac-nomenclature-c1", front:"IUPAC suffix for -COOH?", back:"<b>-oic acid</b> (e.g. ethanoic acid)."},
  {id:"ch13-iupac-nomenclature-c2", front:"IUPAC suffix for an aldehyde (-CHO)?", back:"<b>-al</b> — and its carbon is always numbered C1."},
  {id:"ch13-iupac-nomenclature-c3", front:"How are multiple locants of the same substituent punctuated?", back:"Separated by <b>commas</b> (2,3-dimethyl...), with a hyphen before the substituent name."},
  {id:"ch13-iupac-nomenclature-c4", front:"Rule for choosing the parent chain when a principal group is present?", back:"The <b>longest chain that still contains the principal characteristic group</b> — not simply the longest chain overall."}
],
"ch18-hormones": [
  {id:"ch18-hormones-c1", front:"Why is the pituitary called the 'master gland'?", back:"It releases trophic hormones (TSH, ACTH, FSH, LH) that control most <b>other</b> endocrine glands."},
  {id:"ch18-hormones-c2", front:"Insulin vs glucagon effect on blood glucose?", back:"Insulin <b>lowers</b> it; glucagon <b>raises</b> it — an antagonistic pair."},
  {id:"ch18-hormones-c3", front:"How do steroid hormones act on target cells?", back:"They diffuse through the membrane and bind an <b>intracellular receptor</b> that regulates gene expression directly."},
  {id:"ch18-hormones-c4", front:"Childhood vs adult thyroxine deficiency?", back:"<b>Cretinism</b> in childhood (stunted growth, mental retardation); <b>myxoedema</b> in adults."}
],
"bio1-what-living-biodiversity": [
  {id:"bio1-what-living-biodiversity-c1", front:"What is the single defining property of all living organisms?", back:"<b>Consciousness</b> — the ability to sense the surroundings and respond to stimuli."},
  {id:"bio1-what-living-biodiversity-c2", front:"Is reproduction a defining feature of ALL living organisms?", back:"<b>No.</b> Sterile worker bees, mules, and infertile human couples are alive but cannot reproduce."},
  {id:"bio1-what-living-biodiversity-c3", front:"What is metabolism?", back:"The sum total of all <b>chemical reactions</b> occurring in an organism's body."},
  {id:"bio1-what-living-biodiversity-c4", front:"Why is metabolism alone not sufficient to define \"living\"?", back:"Isolated metabolic reactions can be carried out <b>outside the body</b> in a cell-free system (in vitro), which is not \"alive\"."},
  {id:"bio1-what-living-biodiversity-c5", front:"How does growth in a living organism differ from growth in a non-living object (e.g. a mountain)?", back:"Living organisms grow from <b>inside</b> (cell division/increase in cell number); non-living objects grow by <b>external</b> addition of material."},
  {id:"bio1-what-living-biodiversity-c6", front:"Why does every species need one scientifically accepted name?", back:"So that a species can be identified <b>correctly, uniquely, and consistently worldwide</b> — this is the purpose of nomenclature."}
],
"bio1-need-classification-taxonomy-systematics": [
  {id:"bio1-need-classification-taxonomy-systematics-c1", front:"Define taxonomy.", back:"The branch of biology dealing with <b>characterisation, identification, classification, and nomenclature</b> of organisms."},
  {id:"bio1-need-classification-taxonomy-systematics-c2", front:"Define systematics.", back:"The study of the kinds and diversity of organisms and the <b>evolutionary relationships</b> among them."},
  {id:"bio1-need-classification-taxonomy-systematics-c3", front:"Define classification (in taxonomy).", back:"The process of arranging organisms into <b>groups/categories</b> based on similarities and differences."},
  {id:"bio1-need-classification-taxonomy-systematics-c4", front:"Define identification (in taxonomy).", back:"Determining the <b>correct name and category</b> to which an organism belongs."}
],
"bio1-binomial-nomenclature": [
  {id:"bio1-binomial-nomenclature-c1", front:"Who gave the system of binomial nomenclature?", back:"<b>Carolus Linnaeus</b>."},
  {id:"bio1-binomial-nomenclature-c2", front:"What are the two parts of a binomial name?", back:"The <b>genus name</b> (first) and the <b>specific epithet</b> (second)."},
  {id:"bio1-binomial-nomenclature-c3", front:"In Mangifera indica, which part is the genus and which is the species epithet?", back:"<b>Mangifera</b> = genus; <b>indica</b> = specific epithet."},
  {id:"bio1-binomial-nomenclature-c4", front:"What is the capitalisation rule for a binomial name?", back:"The genus name starts with a <b>capital letter</b>; the specific epithet starts with a <b>small letter</b>."},
  {id:"bio1-binomial-nomenclature-c5", front:"How must a binomial name be written when printed vs. handwritten?", back:"<b>Italicised</b> when printed; <b>underlined separately</b> when handwritten."},
  {id:"bio1-binomial-nomenclature-c6", front:"Which code governs the nomenclature of plants?", back:"<b>ICBN</b> (International Code of Botanical Nomenclature, now ICN)."},
  {id:"bio1-binomial-nomenclature-c7", front:"Which code governs the nomenclature of animals?", back:"<b>ICZN</b> (International Code of Zoological Nomenclature)."}
],
"bio1-taxonomic-categories-hierarchy": [
  {id:"bio1-taxonomic-categories-hierarchy-c1", front:"Define a taxon.", back:"A <b>unit/rank</b> of classification, e.g. species, genus, family."},
  {id:"bio1-taxonomic-categories-hierarchy-c2", front:"List the taxonomic hierarchy from Kingdom down to Species.", back:"<b>Kingdom → Phylum/Division → Class → Order → Family → Genus → Species</b>."},
  {id:"bio1-taxonomic-categories-hierarchy-c3", front:"Which taxonomic rank is used for plants in place of \"Phylum\"?", back:"<b>Division</b>."},
  {id:"bio1-taxonomic-categories-hierarchy-c4", front:"Define species (taxonomically).", back:"A group of individuals with fundamental similarities that can <b>interbreed to produce fertile offspring</b>."},
  {id:"bio1-taxonomic-categories-hierarchy-c5", front:"How is a genus defined?", back:"A group of <b>related species</b> that resemble each other more than species of other genera."},
  {id:"bio1-taxonomic-categories-hierarchy-c6", front:"How is a family defined (taxonomically)?", back:"A group of related <b>genera</b> with still fewer similarities than genus and species share."},
  {id:"bio1-taxonomic-categories-hierarchy-c7", front:"As you move from Species up to Kingdom, what happens to the number of common characters shared?", back:"It <b>decreases</b> — higher categories share fewer characters."}
],
"bio1-taxonomic-aids": [
  {id:"bio1-taxonomic-aids-c1", front:"Define a herbarium.", back:"A store of plant specimens <b>collected, dried, pressed, and preserved</b> on sheets, used for taxonomic study."},
  {id:"bio1-taxonomic-aids-c2", front:"What information must a herbarium sheet label carry?", back:"Date and place of collection, English/local/vernacular name, family, and the <b>collector's name</b>."},
  {id:"bio1-taxonomic-aids-c3", front:"What is a botanical garden used for?", back:"Growing <b>living plants</b> for identification and reference; each plant is labelled with its scientific name and family."},
  {id:"bio1-taxonomic-aids-c4", front:"What is a taxonomic key used for?", back:"<b>Identification</b> of plants/animals based on their similarities and dissimilarities."},
  {id:"bio1-taxonomic-aids-c5", front:"What is a \"couplet\" in a taxonomic key?", back:"A pair of <b>contrasting characters/statements</b>; each statement in it is called a \"lead.\""},
  {id:"bio1-taxonomic-aids-c6", front:"What is a museum (as a taxonomic aid)?", back:"A place where <b>preserved plant/animal specimens</b> are kept for study, e.g. in formalin, or as dry/mounted specimens and skeletons."},
  {id:"bio1-taxonomic-aids-c7", front:"What is a flora?", back:"A book giving the actual <b>account of habitat and distribution</b> of plants of a given area."},
  {id:"bio1-taxonomic-aids-c8", front:"What is a monograph (taxonomic aid)?", back:"A publication containing information on <b>any one taxon</b> in complete detail."},
  {id:"bio1-taxonomic-aids-c9", front:"What is a catalogue (taxonomic aid)?", back:"A record giving the <b>correct name</b> and <b>geographical distribution</b> of a species."}
],
"phy1-physical-quantities-units": [
  {id:"phy1-physical-quantities-units-c1", front:"What is a base (fundamental) physical quantity?", back:"A quantity that is <b>independent</b> of other quantities and not defined in terms of them."},
  {id:"phy1-physical-quantities-units-c2", front:"What is a derived physical quantity?", back:"A quantity whose unit is expressed using base units, e.g. <b>speed = length/time</b>."},
  {id:"phy1-physical-quantities-units-c3", front:"How many SI base units are there?", back:"<b>Seven</b>."},
  {id:"phy1-physical-quantities-units-c4", front:"Name the seven SI base quantities with their SI units.", back:"Length (<b>metre</b>), mass (<b>kilogram</b>), time (<b>second</b>), electric current (<b>ampere</b>), temperature (<b>kelvin</b>), amount of substance (<b>mole</b>), luminous intensity (<b>candela</b>)."},
  {id:"phy1-physical-quantities-units-c5", front:"What are the two SI supplementary units?", back:"<b>Radian</b> (plane angle) and <b>steradian</b> (solid angle)."},
  {id:"phy1-physical-quantities-units-c6", front:"Give the SI prefixes for 10⁻⁹, 10⁻⁶, 10³, 10⁶, and 10⁹.", back:"<b>nano</b> (10⁻⁹), <b>micro</b> (10⁻⁶), <b>kilo</b> (10³), <b>mega</b> (10⁶), <b>giga</b> (10⁹)."}
],
"phy1-measuring-length-mass-time": [
  {id:"phy1-measuring-length-mass-time-c1", front:"What method is used to measure the distance of a nearby star?", back:"The <b>parallax method</b>."},
  {id:"phy1-measuring-length-mass-time-c2", front:"Define parallax angle.", back:"The angle subtended at the star by the <b>baseline</b> — the line joining the two points of observation."},
  {id:"phy1-measuring-length-mass-time-c3", front:"Define 1 Astronomical Unit (AU).", back:"The average distance from the <b>Earth to the Sun</b> ≈ 1.496 × 10¹¹ m."},
  {id:"phy1-measuring-length-mass-time-c4", front:"Define 1 light year.", back:"The distance light travels in vacuum in <b>1 year</b> ≈ 9.46 × 10¹⁵ m."},
  {id:"phy1-measuring-length-mass-time-c5", front:"Define 1 parsec.", back:"The distance at which 1 AU subtends an angle of <b>1 arcsecond</b> ≈ 3.08 × 10¹⁶ m."}
],
"phy1-errors": [
  {id:"phy1-errors-c1", front:"Distinguish accuracy from precision.", back:"<b>Accuracy</b> = closeness to the true value; <b>precision</b> = closeness among repeated measurements of the same quantity."},
  {id:"phy1-errors-c2", front:"Name the three types of measurement error.", back:"<b>Systematic</b>, <b>random</b>, and <b>gross</b> errors."},
  {id:"phy1-errors-c3", front:"Name the three sources of systematic error.", back:"<b>Instrumental</b> errors, imperfect <b>experimental technique/procedure</b>, and <b>personal</b> (observer) errors."},
  {id:"phy1-errors-c4", front:"What causes random errors?", back:"Irregular, unpredictable variations in <b>experimental conditions</b> (e.g. temperature fluctuations)."},
  {id:"phy1-errors-c5", front:"What is the least count of an instrument?", back:"The <b>smallest measurement</b> it can accurately read; error from this limit is the least count error."},
  {id:"phy1-errors-c6", front:"How is mean absolute error calculated?", back:"The <b>average</b> of the absolute values of the deviations of individual readings from the mean."},
  {id:"phy1-errors-c7", front:"If Z = A + B or Z = A − B, how do the absolute errors combine?", back:"<b>ΔZ = ΔA + ΔB</b> — absolute errors always add, even for a difference."},
  {id:"phy1-errors-c8", front:"If Z = AB or Z = A/B, how do the errors combine?", back:"<b>ΔZ/Z = ΔA/A + ΔB/B</b> — relative (percentage) errors add."},
  {id:"phy1-errors-c9", front:"If Z = Aⁿ, how does the error propagate?", back:"<b>ΔZ/Z = n(ΔA/A)</b> — the relative error is multiplied by the power."}
],
"phy1-significant-figures": [
  {id:"phy1-significant-figures-c1", front:"Define significant figures.", back:"The reliably known digits in a measurement, <b>plus the first uncertain (estimated) digit</b>."},
  {id:"phy1-significant-figures-c2", front:"Are all non-zero digits significant?", back:"<b>Yes</b>, always."},
  {id:"phy1-significant-figures-c3", front:"Are zeros between two non-zero digits (\"captive zeros\") significant?", back:"<b>Yes</b> — captive zeros are always significant."},
  {id:"phy1-significant-figures-c4", front:"Are leading zeros before the first non-zero digit significant?", back:"<b>No</b> — they only fix the position of the decimal point."},
  {id:"phy1-significant-figures-c5", front:"Are trailing zeros after a decimal point significant?", back:"<b>Yes</b>, always."},
  {id:"phy1-significant-figures-c6", front:"How do you remove the ambiguity of trailing zeros in a number like 4500 (no decimal point)?", back:"Write it in <b>scientific notation</b>: 4.5×10³ (2 sig figs) vs 4.500×10³ (4 sig figs)."},
  {id:"phy1-significant-figures-c7", front:"In addition/subtraction, to how many decimal places should the result be rounded?", back:"To match the term with the <b>least number of decimal places</b>."},
  {id:"phy1-significant-figures-c8", front:"In multiplication/division, how many significant figures should the result have?", back:"Equal to the operand with the <b>least significant figures</b>."}
],
"phy1-dimensions": [
  {id:"phy1-dimensions-c1", front:"What are the dimensions of a physical quantity?", back:"The <b>powers</b> to which base quantities (M, L, T, etc.) must be raised to represent it."},
  {id:"phy1-dimensions-c2", front:"What is a dimensional formula?", back:"An expression showing the powers of base quantities that represent a derived quantity, e.g. force = <b>[M L T⁻²]</b>."},
  {id:"phy1-dimensions-c3", front:"What is the dimensional formula of force?", back:"<b>[M L T⁻²]</b>."},
  {id:"phy1-dimensions-c4", front:"What is the dimensional formula of work/energy?", back:"<b>[M L² T⁻²]</b>."},
  {id:"phy1-dimensions-c5", front:"What is the dimensional formula of pressure?", back:"<b>[M L⁻¹ T⁻²]</b>."},
  {id:"phy1-dimensions-c7", front:"Are angle and strain dimensionless?", back:"<b>Yes</b> — both are ratios of like quantities, so their dimensional formula is [M⁰L⁰T⁰]."},
  {id:"phy1-dimensions-c8", front:"State the principle of homogeneity of dimensions.", back:"Every term on both sides of a correct physical equation must have the <b>same dimensions</b>."}
],
"phy1-dimensional-analysis": [
  {id:"phy1-dimensional-analysis-c1", front:"Name the three main uses of dimensional analysis.", back:"<b>Checking</b> the dimensional consistency of an equation, <b>deriving</b> a relation between quantities, and <b>converting units</b> between systems."},
  {id:"phy1-dimensional-analysis-c2", front:"Name the main limitations of dimensional analysis.", back:"It cannot determine <b>dimensionless constants</b>, cannot be used if a quantity depends on <b>more than 3</b> independent quantities, and cannot tell a <b>scalar from a vector</b> with the same dimensions."}
,
  {id:"phy1-dimensional-analysis-c5", front:"State the principle of homogeneity of dimensions.", back:"Only quantities with the <b>same dimensions</b> can be added or subtracted, and both sides of a valid physical equation must have <b>identical dimensions</b>."},
  {id:"phy1-dimensional-analysis-c6", front:"What are the dimensions of force?", back:"Force has dimensions <b>[M L T⁻²]</b>, derived from mass times acceleration."}],
"phy2-frame-of-reference": [
  {id:"phy2-frame-of-reference-c1", front:"What is a frame of reference?", back:"A <b>coordinate system with a clock</b>, relative to which the position and motion of an object are described."},
  {id:"phy2-frame-of-reference-c2", front:"What is an inertial frame of reference?", back:"A frame that is <b>at rest or moving at constant velocity</b> — Newton's first law holds in it."},
  {id:"phy2-frame-of-reference-c3", front:"What is a non-inertial frame of reference?", back:"An <b>accelerating</b> frame, in which Newton's first law does not hold without introducing pseudo-forces."}
,
  {id:"phy2-frame-of-reference-c5", front:"What is a frame of reference?", back:"A coordinate system with a clock, attached to an <b>observer</b>, used to specify the <b>position and time</b> of an event."}],
"phy2-motion-1d": [
  {id:"phy2-motion-1d-c1", front:"Distinguish distance from displacement.", back:"<b>Distance</b> = total path length covered (scalar). <b>Displacement</b> = shortest straight-line change in position (vector)."},
  {id:"phy2-motion-1d-c2", front:"Can displacement be zero while distance travelled is non-zero?", back:"<b>Yes</b> — e.g. returning to the exact starting point after moving around."},
  {id:"phy2-motion-1d-c3", front:"Distinguish speed from velocity.", back:"<b>Speed</b> = distance/time (scalar). <b>Velocity</b> = displacement/time (vector)."},
  {id:"phy2-motion-1d-c4", front:"How does average speed compare to the magnitude of average velocity?", back:"Average speed is <b>always ≥</b> |average velocity| — equal only for straight-line motion in one direction."}
],
"phy2-kinematic-equations": [
  {id:"phy2-kinematic-equations-c1", front:"State the first equation of motion.", back:"<b>v = u + at</b>."},
  {id:"phy2-kinematic-equations-c2", front:"State the second equation of motion.", back:"<b>s = ut + ½at²</b>."},
  {id:"phy2-kinematic-equations-c3", front:"State the third equation of motion.", back:"<b>v² = u² + 2as</b>."},
  {id:"phy2-kinematic-equations-c4", front:"Under what condition do the SUVAT equations apply?", back:"Only for motion with <b>constant (uniform) acceleration</b>."}
],
"phy2-graphical-analysis": [
  {id:"phy2-graphical-analysis-c1", front:"What does the slope of a position-time graph represent?", back:"<b>Velocity</b>."},
  {id:"phy2-graphical-analysis-c2", front:"What does the slope of a velocity-time graph represent?", back:"<b>Acceleration</b>."},
  {id:"phy2-graphical-analysis-c3", front:"What does the area under a velocity-time graph represent?", back:"<b>Displacement</b>."},
  {id:"phy2-graphical-analysis-c4", front:"What does a horizontal line on a velocity-time graph represent?", back:"Motion at <b>constant velocity</b> (zero acceleration)."},
  {id:"phy2-graphical-analysis-c5", front:"What does a straight line with non-zero slope on a position-time graph represent?", back:"Motion at <b>constant (uniform) velocity</b>."}
],
"phy2-motion-2d": [
  {id:"phy2-motion-2d-c1", front:"What is a position vector?", back:"A vector from the <b>origin</b> to a particle's location, giving its distance and direction."},
  {id:"phy2-motion-2d-c2", front:"How is average velocity defined for motion in a plane?", back:"<b>Total displacement ÷ total time taken</b> (a vector)."},
  {id:"phy2-motion-2d-c3", front:"How is average acceleration defined for motion in a plane?", back:"<b>Change in velocity ÷ time taken</b> (a vector)."}
,
  {id:"phy2-motion-2d-c5", front:"What is the trajectory of a projectile launched at an angle to the horizontal?", back:"A <b>parabola</b>, resulting from constant horizontal velocity combined with uniformly accelerated vertical motion due to <b>gravity</b>."}],
"phy2-projectile-motion": [
  {id:"phy2-projectile-motion-c1", front:"What is projectile motion?", back:"Motion of an object under <b>gravity alone</b> after launch, following a <b>parabolic</b> path."},
  {id:"phy2-projectile-motion-c2", front:"What happens to the horizontal velocity component during projectile motion?", back:"It stays <b>constant</b> throughout (no horizontal force, ignoring air resistance)."},
  {id:"phy2-projectile-motion-c3", front:"What governs the vertical velocity component during projectile motion?", back:"Constant <b>downward acceleration g</b>."},
  {id:"phy2-projectile-motion-c4", front:"For launch speed u at angle θ, what is the time of flight?", back:"<b>T = 2u sinθ / g</b>."},
  {id:"phy2-projectile-motion-c5", front:"For launch speed u at angle θ, what is the maximum height?", back:"<b>H = u²sin²θ / 2g</b>."},
  {id:"phy2-projectile-motion-c6", front:"For launch speed u at angle θ, what is the horizontal range?", back:"<b>R = u²sin2θ / g</b>."},
  {id:"phy2-projectile-motion-c7", front:"At what launch angle is the horizontal range maximum?", back:"<b>45°</b>."}
],
"phy2-relative-velocity": [
  {id:"phy2-relative-velocity-c1", front:"Define the relative velocity of A with respect to B.", back:"<b>v(A/B) = v(A) − v(B)</b>."},
  {id:"phy2-relative-velocity-c2", front:"Two objects move toward each other at speeds v₁ and v₂ — what is their relative speed of approach?", back:"<b>v₁ + v₂</b>."},
  {id:"phy2-relative-velocity-c3", front:"Two objects move in the same direction at speeds v₁ and v₂ — what is their relative speed?", back:"<b>|v₁ − v₂|</b>."}
,
  {id:"phy2-relative-velocity-c5", front:"How is the relative velocity of object A with respect to B defined?", back:"v_AB = <b>v_A − v_B</b>, the velocity of A as measured by an observer moving with B."}],
"phy2-circular-motion": [
  {id:"phy2-circular-motion-c1", front:"Define angular velocity.", back:"The rate of change of angular displacement with time: <b>ω = dθ/dt</b>."},
  {id:"phy2-circular-motion-c2", front:"Define angular acceleration.", back:"The rate of change of angular velocity with time: <b>α = dω/dt</b>."},
  {id:"phy2-circular-motion-c3", front:"How are linear speed v and angular speed ω related, for radius r?", back:"<b>v = rω</b>."},
  {id:"phy2-circular-motion-c4", front:"What is the direction of centripetal acceleration in uniform circular motion?", back:"Always directed <b>toward the centre</b> of the circle."}
],
"phy3-newtons-first-law": [
  {id:"phy3-newtons-first-law-c1", front:"State Newton's first law of motion.", back:"A body stays at rest or in uniform straight-line motion <b>unless acted on by a net external force</b>."},
  {id:"phy3-newtons-first-law-c2", front:"Define inertia.", back:"A body's natural tendency to <b>resist a change</b> in its state of rest or motion."},
  {id:"phy3-newtons-first-law-c3", front:"What determines the inertia of a body?", back:"Its <b>mass</b> — greater mass means greater inertia."}
,
  {id:"phy3-newtons-first-law-c5", front:"What is inertia?", back:"The natural tendency of a body to resist any change in its state of <b>rest or uniform motion</b>; mass is the quantitative measure of inertia."}],
"phy3-newtons-second-law": [
  {id:"phy3-newtons-second-law-c1", front:"State Newton's second law in terms of momentum.", back:"The <b>rate of change of momentum</b> equals the net applied force, in the direction of that force: F = dp/dt."},
  {id:"phy3-newtons-second-law-c2", front:"State Newton's second law in its common form.", back:"<b>F = ma</b> (net force = mass × acceleration), for constant mass."},
  {id:"phy3-newtons-second-law-c3", front:"Define momentum.", back:"The product of a body's mass and velocity, <b>p = mv</b> — a vector."}
,
  {id:"phy3-newtons-second-law-c5", front:"State Newton's Second Law in terms of momentum.", back:"The rate of change of <b>momentum</b> of a body is directly proportional to the applied force and occurs in the direction of the force: F = <b>dp/dt</b>."}],
"phy3-newtons-third-law": [
  {id:"phy3-newtons-third-law-c1", front:"State Newton's third law of motion.", back:"For every action there is an <b>equal and opposite reaction</b> — the forces two bodies exert on each other are equal and opposite."},
  {id:"phy3-newtons-third-law-c2", front:"Do action-reaction force pairs act on the same body or two different bodies?", back:"<b>Two different bodies</b> — that's why they don't cancel each other out."}
,
  {id:"phy3-newtons-third-law-c5", front:"State Newton's Third Law of Motion.", back:"For every action there is an equal and opposite <b>reaction</b>; action and reaction forces act on <b>different bodies</b> and occur simultaneously."},
  {id:"phy3-newtons-third-law-c6", front:"Why don't action-reaction pairs cancel out?", back:"Because they act on <b>two different bodies</b>, not the same body, so they cannot produce a net zero force on either object individually."}],
"phy3-friction": [
  {id:"phy3-friction-c1", front:"Define static friction.", back:"The friction force that resists the <b>start</b> of relative motion between two surfaces in contact."},
  {id:"phy3-friction-c2", front:"Define kinetic friction.", back:"The friction force that opposes <b>relative sliding</b> between two surfaces already in contact."},
  {id:"phy3-friction-c3", front:"How does maximum static friction compare to kinetic friction?", back:"Maximum static friction is generally <b>greater than or equal to</b> kinetic friction."},
  {id:"phy3-friction-c4", front:"What is the formula relating friction force to normal force?", back:"<b>f = μN</b>, where μ is the coefficient of friction."},
  {id:"phy3-friction-c5", front:"Does friction depend on the surface area of contact?", back:"<b>No</b> — only on the normal force and the nature of the surfaces."}
],
"phy3-impulse-momentum": [
  {id:"phy3-impulse-momentum-c1", front:"Define impulse.", back:"Force × the time it acts, <b>J = FΔt</b>; equals the change in momentum."},
  {id:"phy3-impulse-momentum-c2", front:"State the impulse-momentum theorem.", back:"<b>Impulse = change in momentum</b> (J = Δp)."},
  {id:"phy3-impulse-momentum-c3", front:"What does the area under a force-time graph represent?", back:"<b>Impulse</b>."},
  {id:"phy3-impulse-momentum-c4", front:"State the law of conservation of linear momentum.", back:"With no net external force, the <b>total momentum</b> of an isolated system stays constant."}
],
"phy3-circular-dynamics": [
  {id:"phy3-circular-dynamics-c1", front:"What provides the centripetal force in circular motion?", back:"Whichever <b>real force</b> (tension, gravity, friction, normal force…) acts as the net inward force."},
  {id:"phy3-circular-dynamics-c2", front:"What is the formula for centripetal force?", back:"<b>F = mv²/r</b> (equivalently F = mω²r)."},
  {id:"phy3-circular-dynamics-c3", front:"Is centripetal force a separate type of force?", back:"<b>No</b> — it's a role played by an existing real force, not a new force."}
,
  {id:"phy3-circular-dynamics-c5", front:"What provides the centripetal force for a car turning on a banked road?", back:"A component of the <b>normal reaction</b> and friction together provide the centripetal force; at the optimum banking angle, friction is not required: tanθ = v²/(rg)."}],
"phy4-work-done": [
  {id:"phy4-work-done-c1", front:"Define work done by a constant force.", back:"<b>W = Fd cosθ</b>, where θ is the angle between the force and the displacement."},
  {id:"phy4-work-done-c2", front:"What is the SI unit of work/energy?", back:"<b>Joule (J)</b>."},
  {id:"phy4-work-done-c3", front:"When is the work done by a force zero?", back:"When the force is <b>perpendicular</b> to the displacement (θ = 90°), or the displacement is zero."},
  {id:"phy4-work-done-c4", front:"Can work done by a force be negative?", back:"<b>Yes</b> — when the force has a component opposite to the displacement (θ > 90°)."}
],
"phy4-kinetic-energy": [
  {id:"phy4-kinetic-energy-c1", front:"Define kinetic energy.", back:"The energy a body has due to its motion: <b>KE = ½mv²</b>."},
  {id:"phy4-kinetic-energy-c2", front:"Is kinetic energy a scalar or a vector?", back:"A <b>scalar</b> — always positive."},
  {id:"phy4-kinetic-energy-c3", front:"How is KE related to momentum p and mass m?", back:"<b>KE = p²/2m</b>."}
,
  {id:"phy4-kinetic-energy-c5", front:"How does kinetic energy depend on velocity?", back:"KE = <b>½mv²</b>, so kinetic energy is directly proportional to mass and to the <b>square of velocity</b>."}],
"phy4-work-energy-theorem": [
  {id:"phy4-work-energy-theorem-c1", front:"State the work-energy theorem.", back:"The <b>net work</b> done on a body equals its <b>change in kinetic energy</b> (W = ΔKE)."},
  {id:"phy4-work-energy-theorem-c2", front:"Define instantaneous power.", back:"The rate of doing work at an instant: <b>P = F·v</b> (force dot velocity)."}
,
  {id:"phy4-work-energy-theorem-c5", front:"State the Work-Energy Theorem.", back:"The <b>net work</b> done on a body equals the change in its <b>kinetic energy</b>: W_net = ΔKE = KE_f − KE_i."},
  {id:"phy4-work-energy-theorem-c6", front:"Does the work-energy theorem apply to variable forces?", back:"Yes — it holds for both <b>constant and variable forces</b>, since work is computed as W = ∫F·dx regardless of how force changes."}],
"phy4-potential-energy": [
  {id:"phy4-potential-energy-c1", front:"Define potential energy.", back:"The energy a body has due to its <b>position or configuration</b>."},
  {id:"phy4-potential-energy-c2", front:"What is the formula for gravitational PE near Earth's surface?", back:"<b>PE = mgh</b>, h = height above a chosen reference level."},
  {id:"phy4-potential-energy-c3", front:"Is potential energy an absolute or a relative quantity?", back:"<b>Relative</b> — it depends on the chosen reference level."}
,
  {id:"phy4-potential-energy-c5", front:"How is gravitational potential energy near Earth's surface defined?", back:"U = <b>mgh</b>, the energy stored due to an object's position at height h above a reference level, arising from work done against gravity."}],
"phy4-conservation-energy": [
  {id:"phy4-conservation-energy-c1", front:"State the law of conservation of mechanical energy.", back:"Without non-conservative forces (like friction), the total mechanical energy (<b>KE + PE</b>) of a system stays constant."},
  {id:"phy4-conservation-energy-c2", front:"Distinguish conservative from non-conservative forces.", back:"<b>Conservative</b> (gravity, spring force): work is path-independent, fully recoverable. <b>Non-conservative</b> (friction): dissipates energy as heat, path-dependent."},
  {id:"phy4-conservation-energy-c3", front:"With friction present, how is the energy conservation equation modified?", back:"Initial energy = final mechanical energy + <b>energy lost to friction/heat</b> — energy overall is still conserved."}
,
  {id:"phy4-conservation-energy-c5", front:"State the law of conservation of mechanical energy.", back:"For a system under only <b>conservative forces</b>, the total mechanical energy (KE + PE) remains <b>constant</b>."}],
"phy4-vertical-circular-motion": [
  {id:"phy4-vertical-circular-motion-c1", front:"For a body on a string in vertical circular motion, what is the minimum speed at the top of the loop?", back:"<b>v(min) = √(gr)</b> — weight alone supplies the centripetal force."},
  {id:"phy4-vertical-circular-motion-c2", front:"At the lowest point of vertical circular motion on a string, what supplies the net centripetal force?", back:"<b>Tension minus weight</b>: T − mg = mv²/r."}
,
  {id:"phy4-vertical-circular-motion-c5", front:"What is the minimum speed at the top of a vertical circle for a body on a string?", back:"v_min = <b>√(gr)</b>, the speed at which gravity alone supplies the necessary centripetal force (tension = 0)."},
  {id:"phy4-vertical-circular-motion-c6", front:"How does tension vary between the top and bottom of a vertical circular loop?", back:"Tension is <b>maximum at the bottom</b> and <b>minimum at the top</b>, differing by 6mg for a body of mass m moving with minimum speed at the top (using energy conservation)."}],
"phy4-power": [
  {id:"phy4-power-c1", front:"Define average power.", back:"Total work done divided by total time taken: <b>P(avg) = W/t</b>."},
  {id:"phy4-power-c2", front:"What is the SI unit of power?", back:"<b>Watt (W)</b> = joule/second."},
  {id:"phy4-power-c3", front:"What is the formula for instantaneous power in terms of force and velocity?", back:"<b>P = F·v</b> (dot product)."}
,
  {id:"phy4-power-c5", front:"How is instantaneous power related to force and velocity?", back:"P = <b>F·v</b>, the dot product of the applied force and the instantaneous velocity of the object."}],
"phy4-collisions": [
  {id:"phy4-collisions-c1", front:"Define an elastic collision.", back:"Both <b>momentum and kinetic energy</b> are conserved."},
  {id:"phy4-collisions-c2", front:"Define an inelastic collision.", back:"<b>Momentum</b> is conserved but <b>kinetic energy is not</b> (some is lost to heat/sound)."},
  {id:"phy4-collisions-c3", front:"What is a perfectly inelastic collision?", back:"The two bodies <b>stick together</b> and move with a common velocity after impact."},
  {id:"phy4-collisions-c4", front:"Define the coefficient of restitution (e).", back:"The ratio of <b>relative velocity of separation</b> to <b>relative velocity of approach</b>."},
  {id:"phy4-collisions-c5", front:"What is e for a perfectly elastic collision?", back:"<b>e = 1</b>."},
  {id:"phy4-collisions-c6", front:"What is e for a perfectly inelastic collision?", back:"<b>e = 0</b>."}
],
"phy5-centre-of-mass": [
  {id:"phy5-centre-of-mass-c1", front:"Define centre of mass.", back:"The point where a system's <b>entire mass can be considered concentrated</b> for analysing translational motion."},
  {id:"phy5-centre-of-mass-c2", front:"For two point masses m₁, m₂ at positions x₁, x₂, what is the x-coordinate of the centre of mass?", back:"<b>x(cm) = (m₁x₁ + m₂x₂)/(m₁+m₂)</b>."},
  {id:"phy5-centre-of-mass-c3", front:"For a symmetric, uniform body, where does the centre of mass lie?", back:"At its <b>geometric centre</b>."}
,
  {id:"phy5-centre-of-mass-c5", front:"How is the centre of mass of a two-particle system defined?", back:"x_cm = (m₁x₁ + m₂x₂)/(m₁+m₂) — a <b>mass-weighted average position</b> that moves as if all external force acts there."}],
"phy5-moment-of-inertia": [
  {id:"phy5-moment-of-inertia-c1", front:"Define moment of inertia.", back:"A body's resistance to change in rotational motion about an axis: <b>I = Σmr²</b>."},
  {id:"phy5-moment-of-inertia-c2", front:"What is the moment of inertia of a point mass m at distance r from the axis?", back:"<b>I = mr²</b>."},
  {id:"phy5-moment-of-inertia-c3", front:"Moment of inertia of a uniform ring (mass M, radius R) about its central axis?", back:"<b>I = MR²</b>."},
  {id:"phy5-moment-of-inertia-c4", front:"Moment of inertia of a uniform disc (mass M, radius R) about its central axis?", back:"<b>I = ½MR²</b>."},
  {id:"phy5-moment-of-inertia-c5", front:"Moment of inertia of a uniform solid sphere (mass M, radius R) about a diameter?", back:"<b>I = (2/5)MR²</b>."},
  {id:"phy5-moment-of-inertia-c6", front:"Moment of inertia of a uniform rod (mass M, length L) about a perpendicular axis through its centre?", back:"<b>I = ML²/12</b>."}
],
"phy5-parallel-perpendicular-theorems": [
  {id:"phy5-parallel-perpendicular-theorems-c1", front:"State the parallel axis theorem.", back:"<b>I = I(cm) + Md²</b>, where d is the distance from the axis through the centre of mass."},
  {id:"phy5-parallel-perpendicular-theorems-c2", front:"State the perpendicular axis theorem (for a lamina).", back:"<b>I(z) = I(x) + I(y)</b>, for perpendicular in-plane axes x, y meeting the out-of-plane axis z at the same point."}
,
  {id:"phy5-parallel-perpendicular-theorems-c5", front:"State the Parallel Axis Theorem.", back:"I = I_cm + <b>Md²</b>, where I_cm is the moment of inertia about an axis through the centre of mass and d is the perpendicular distance to the parallel axis."},
  {id:"phy5-parallel-perpendicular-theorems-c6", front:"State the Perpendicular Axis Theorem.", back:"For a <b>planar lamina</b>, I_z = I_x + I_y, where z is perpendicular to the plane and x, y are two perpendicular axes in the plane, all intersecting at one point."}],
"phy5-torque": [
  {id:"phy5-torque-c1", front:"Define torque.", back:"The rotational analogue of force: <b>τ = r × F</b>."},
  {id:"phy5-torque-c2", front:"State Newton's second law for rotational motion.", back:"<b>τ = Iα</b> (net torque = moment of inertia × angular acceleration)."},
  {id:"phy5-torque-c3", front:"What is the condition for rotational equilibrium?", back:"The <b>net torque</b> about any axis must be zero."}
,
  {id:"phy5-torque-c5", front:"How is torque defined mathematically?", back:"τ = <b>r × F</b>, the cross product of the position vector and force; its magnitude is rF sinθ."}],
"phy5-angular-momentum": [
  {id:"phy5-angular-momentum-c1", front:"Define angular momentum.", back:"<b>L = r × p</b> (or L = Iω for a rigid body)."},
  {id:"phy5-angular-momentum-c2", front:"How are torque and angular momentum related?", back:"<b>τ = dL/dt</b> — net torque is the rate of change of angular momentum."},
  {id:"phy5-angular-momentum-c3", front:"State the law of conservation of angular momentum.", back:"With <b>no external torque</b>, a system's angular momentum stays constant."}
,
  {id:"phy5-angular-momentum-c5", front:"State the law of conservation of angular momentum.", back:"When <b>no external torque</b> acts on a system, its total angular momentum L = Iω remains <b>constant</b>."}],
"phy5-rolling-motion": [
  {id:"phy5-rolling-motion-c1", front:"What is the condition for pure rolling (rolling without slipping)?", back:"<b>v(centre) = ωR</b>."},
  {id:"phy5-rolling-motion-c2", front:"What is the velocity of the point of contact in pure rolling?", back:"<b>Zero</b> — instantaneously at rest relative to the ground."},
  {id:"phy5-rolling-motion-c3", front:"What is the total kinetic energy of a rolling body?", back:"<b>KE = ½mv² + ½Iω²</b> (translational + rotational)."}
,
  {id:"phy5-rolling-motion-c5", front:"What is the condition for pure rolling without slipping?", back:"The velocity of the point of contact with the surface is zero, i.e., <b>v = ωR</b>, linking translational and rotational speeds."}],
"phy6-universal-gravitation": [
  {id:"phy6-universal-gravitation-c1", front:"State Newton's law of universal gravitation.", back:"<b>F = Gm₁m₂/r²</b> — an attractive force along the line joining the two masses."},
  {id:"phy6-universal-gravitation-c2", front:"What is the approximate value of the universal gravitational constant G?", back:"<b>G ≈ 6.674 × 10⁻¹¹ N·m²/kg²</b> — the same everywhere in the universe."},
  {id:"phy6-universal-gravitation-c3", front:"Is gravitational force ever repulsive?", back:"<b>No</b> — gravitational force is always attractive."}
,
  {id:"phy6-universal-gravitation-c5", front:"State Newton's Law of Universal Gravitation.", back:"Every particle attracts every other particle with a force F = <b>Gm₁m₂/r²</b>, directed along the line joining them, where G is the universal gravitational constant."}],
"phy6-acceleration-gravity": [
  {id:"phy6-acceleration-gravity-c1", front:"What is \"g\"?", back:"The <b>acceleration</b> produced in a freely falling body due to Earth's gravity."},
  {id:"phy6-acceleration-gravity-c2", front:"Distinguish g from G.", back:"<b>g</b> = acceleration due to gravity (varies with location, ≈9.8 m/s² on Earth). <b>G</b> = universal gravitational constant (same everywhere)."},
  {id:"phy6-acceleration-gravity-c3", front:"How does g vary with height above Earth's surface?", back:"It <b>decreases</b> with height: g(h) = g/(1+h/R)²."},
  {id:"phy6-acceleration-gravity-c4", front:"How does g vary with depth below Earth's surface?", back:"It <b>decreases</b> with depth: g(d) = g(1−d/R), reaching zero at the centre."},
  {id:"phy6-acceleration-gravity-c5", front:"How does g vary with latitude on Earth?", back:"<b>Minimum at the equator, maximum at the poles</b>, due to Earth's rotation and shape."}
],
"phy6-gravitational-field-potential": [
  {id:"phy6-gravitational-field-potential-c1", front:"Define gravitational field.", back:"The gravitational force per unit mass at a point: <b>g = F/m</b>."},
  {id:"phy6-gravitational-field-potential-c2", front:"Define gravitational potential.", back:"Work done per unit mass to bring a test mass from <b>infinity</b> to that point."},
  {id:"phy6-gravitational-field-potential-c3", front:"Why is gravitational potential energy taken as negative?", back:"Because gravity is <b>attractive</b> and PE is defined as zero at infinite separation, so PE at any finite separation is negative."},
  {id:"phy6-gravitational-field-potential-c4", front:"What is the gravitational PE between two masses separated by distance r?", back:"<b>U = −Gm₁m₂/r</b>."}
],
"phy6-keplers-laws": [
  {id:"phy6-keplers-laws-c1", front:"State Kepler's first law (law of orbits).", back:"Every planet moves in an <b>elliptical orbit</b> with the Sun at one focus."},
  {id:"phy6-keplers-laws-c2", front:"State Kepler's second law (law of areas).", back:"The line joining a planet to the Sun sweeps out <b>equal areas in equal times</b>."},
  {id:"phy6-keplers-laws-c3", front:"State Kepler's third law (law of periods).", back:"<b>T² ∝ r³</b> — orbital period squared is proportional to the semi-major axis cubed."}
,
  {id:"phy6-keplers-laws-c5", front:"State Kepler's Third Law.", back:"The square of a planet's orbital period is proportional to the cube of the semi-major axis of its orbit: <b>T² ∝ a³</b>."}],
"phy6-escape-velocity": [
  {id:"phy6-escape-velocity-c1", front:"Define escape velocity.", back:"The minimum speed for an object to <b>escape a planet's gravity</b> without further propulsion, reaching infinity with zero KE."},
  {id:"phy6-escape-velocity-c2", front:"What is the formula for escape velocity from a planet of mass M and radius R?", back:"<b>v(escape) = √(2GM/R)</b>."},
  {id:"phy6-escape-velocity-c3", front:"Does escape velocity depend on the mass of the escaping object?", back:"<b>No</b> — independent of the escaping object's own mass."}
,
  {id:"phy6-escape-velocity-c5", front:"What is the formula for escape velocity from a planet's surface?", back:"v_e = <b>√(2GM/R)</b>, the minimum speed needed for an object to escape the planet's gravitational field without further propulsion."}],
"phy6-satellites": [
  {id:"phy6-satellites-c1", front:"What provides the centripetal force for a satellite in orbit?", back:"The planet's <b>gravitational force</b>."},
  {id:"phy6-satellites-c2", front:"What is the orbital velocity of a satellite at orbital radius r?", back:"<b>v(orbital) = √(GM/r)</b>."},
  {id:"phy6-satellites-c3", front:"What is a geostationary satellite?", back:"A satellite in the equatorial plane with the <b>same period as Earth's rotation (24 h)</b>, appearing stationary from the ground."},
  {id:"phy6-satellites-c4", front:"What is the time period of a satellite in terms of orbital radius r?", back:"<b>T = 2π√(r³/GM)</b>."}
],
"phy7-stress-strain": [
  {id:"phy7-stress-strain-c1", front:"Define stress.", back:"Restoring force per unit area within a deformed body: <b>stress = F/A</b>."},
  {id:"phy7-stress-strain-c2", front:"Define strain.", back:"The <b>fractional change</b> in a body's dimension under stress."},
  {id:"phy7-stress-strain-c3", front:"Distinguish tensile/compressive stress from shear stress.", back:"<b>Tensile/compressive</b>: force perpendicular to the area. <b>Shear</b>: force parallel/tangential to the area."},
  {id:"phy7-stress-strain-c4", front:"State Hooke's law.", back:"Within the elastic limit, <b>stress is directly proportional to strain</b>."}
],
"phy7-elastic-moduli": [
  {id:"phy7-elastic-moduli-c1", front:"Define Young's modulus.", back:"Ratio of longitudinal stress to longitudinal strain: <b>Y = (F/A)/(ΔL/L)</b>."},
  {id:"phy7-elastic-moduli-c2", front:"Define bulk modulus.", back:"Ratio of pressure (volumetric stress) to volumetric strain: <b>K = −ΔP/(ΔV/V)</b>."},
  {id:"phy7-elastic-moduli-c3", front:"Define shear modulus (modulus of rigidity).", back:"Ratio of <b>shearing stress</b> to shearing strain."},
  {id:"phy7-elastic-moduli-c4", front:"Which have the highest bulk modulus — solids, liquids, or gases?", back:"<b>Solids > liquids > gases</b> (gases are most compressible)."}
],
"phy7-fluid-pressure": [
  {id:"phy7-fluid-pressure-c1", front:"Define pressure in a fluid.", back:"Force exerted per unit area: <b>P = F/A</b>."},
  {id:"phy7-fluid-pressure-c2", front:"State Pascal's law.", back:"Pressure applied at any point in an enclosed, incompressible fluid is <b>transmitted equally</b> in all directions."},
  {id:"phy7-fluid-pressure-c3", front:"How does pressure vary with depth in a fluid?", back:"It increases linearly with depth: <b>P = P₀ + ρgh</b>."},
  {id:"phy7-fluid-pressure-c4", front:"What is atmospheric pressure at sea level, approximately?", back:"<b>≈1.013×10⁵ Pa (1 atm)</b>."}
],
"phy7-viscosity": [
  {id:"phy7-viscosity-c1", front:"Define viscosity.", back:"A fluid's <b>internal resistance</b> to relative motion between its layers."},
  {id:"phy7-viscosity-c2", front:"State Stokes' law.", back:"Viscous drag on a small sphere moving through a fluid: <b>F = 6πηrv</b>."},
  {id:"phy7-viscosity-c3", front:"Distinguish streamline (laminar) flow from turbulent flow.", back:"<b>Streamline</b>: smooth, orderly, non-mixing paths. <b>Turbulent</b>: chaotic, mixing flow, typically at high velocity."},
  {id:"phy7-viscosity-c4", front:"Define terminal velocity.", back:"The <b>constant maximum velocity</b> reached by an object falling through a viscous fluid, once viscous drag balances the net driving force."}
],
"phy7-bernoullis": [
  {id:"phy7-bernoullis-c1", front:"State Bernoulli's principle.", back:"For steady, non-viscous, incompressible flow, <b>pressure + kinetic + potential energy per unit volume is constant</b> along a streamline."},
  {id:"phy7-bernoullis-c2", front:"What is the mathematical form of Bernoulli's equation?", back:"<b>P + ½ρv² + ρgh = constant</b>."},
  {id:"phy7-bernoullis-c3", front:"What does Bernoulli's principle imply about pressure and flow speed?", back:"Where fluid speed is <b>higher</b>, pressure is <b>lower</b>, and vice versa."}
,
  {id:"phy7-bernoullis-c5", front:"State Bernoulli's theorem.", back:"For steady, non-viscous, incompressible flow, <b>P + ½ρv² + ρgh</b> remains constant along a streamline — total energy per unit volume is conserved."}],
"phy7-surface-tension": [
  {id:"phy7-surface-tension-c1", front:"Define surface tension.", back:"Force per unit length along a liquid's surface, tending to <b>minimize surface area</b>."},
  {id:"phy7-surface-tension-c2", front:"What is the excess pressure inside a liquid drop?", back:"<b>ΔP = 2σ/r</b> (σ = surface tension, r = radius)."},
  {id:"phy7-surface-tension-c3", front:"What is the excess pressure inside a soap bubble?", back:"<b>ΔP = 4σ/r</b> — double a drop's, since a bubble has two surfaces."},
  {id:"phy7-surface-tension-c4", front:"What causes capillary rise?", back:"<b>Surface tension</b> together with adhesion between the liquid and the tube wall."}
],
"phy8-zeroth-law": [
  {id:"phy8-zeroth-law-c1", front:"State the zeroth law of thermodynamics.", back:"If two systems are each in <b>thermal equilibrium</b> with a third, they are in equilibrium with each other."},
  {id:"phy8-zeroth-law-c2", front:"What physical quantity does the zeroth law let us define?", back:"<b>Temperature</b>."}
,
  {id:"phy8-zeroth-law-c5", front:"Why is the Zeroth Law important?", back:"It establishes <b>temperature</b> as a well-defined physical quantity and provides the basis for using a <b>thermometer</b> to compare thermal states of systems."},
  {id:"phy8-zeroth-law-c6", front:"Give an example illustrating the Zeroth Law.", back:"If a <b>thermometer</b> (system C) reads the same temperature for two separate objects A and B, then A and B are in thermal equilibrium with each other."}],
"phy8-first-law": [
  {id:"phy8-first-law-c1", front:"State the first law of thermodynamics.", back:"<b>Q = ΔU + W</b> — heat supplied equals the change in internal energy plus work done by the system."},
  {id:"phy8-first-law-c2", front:"The first law of thermodynamics is a statement of which conservation principle?", back:"<b>Conservation of energy</b>."},
  {id:"phy8-first-law-c3", front:"Define internal energy.", back:"The sum of the <b>kinetic and potential energies</b> of all molecules in a system."},
  {id:"phy8-first-law-c4", front:"Is internal energy a state function, or path-dependent like heat and work?", back:"Internal energy is a <b>state function</b> (depends only on the state); heat and work are <b>path-dependent</b>."}
],
"phy8-thermodynamic-processes": [
  {id:"phy8-thermodynamic-processes-c1", front:"Define an isothermal process.", back:"Occurs at <b>constant temperature</b> (ΔT = 0)."},
  {id:"phy8-thermodynamic-processes-c2", front:"Define an adiabatic process.", back:"No heat enters or leaves the system: <b>Q = 0</b>."},
  {id:"phy8-thermodynamic-processes-c3", front:"Define an isobaric process.", back:"Occurs at <b>constant pressure</b>."},
  {id:"phy8-thermodynamic-processes-c4", front:"Define an isochoric (isovolumetric) process.", back:"Occurs at <b>constant volume</b> — no work is done (W = 0)."}
],
"phy8-pv-diagrams": [
  {id:"phy8-pv-diagrams-c1", front:"What does the area under a P-V curve represent?", back:"The <b>work done</b> by/on the gas during that process."},
  {id:"phy8-pv-diagrams-c2", front:"Over one complete cycle, what is the net change in internal energy?", back:"<b>Zero</b> — internal energy is a state function and returns to its initial value."},
  {id:"phy8-pv-diagrams-c3", front:"What does the area enclosed by a cyclic process on a P-V diagram represent?", back:"The <b>net work done</b> over the cycle."}
,
  {id:"phy8-pv-diagrams-c5", front:"What does the area enclosed by a cyclic process on a P-V diagram represent?", back:"The <b>net work done</b> by the system in one complete cycle; clockwise cycles give positive net work (as in heat engines)."}],
"phy8-specific-heat": [
  {id:"phy8-specific-heat-c1", front:"Define specific heat capacity.", back:"Heat required to raise the temperature of <b>unit mass</b> of a substance by 1°C."},
  {id:"phy8-specific-heat-c2", front:"Define molar heat capacity.", back:"Heat required to raise the temperature of <b>one mole</b> of a substance by 1°C."},
  {id:"phy8-specific-heat-c3", front:"Why is Cp greater than Cv for a gas?", back:"At constant pressure, extra heat also does <b>work</b> as the gas expands, beyond just raising internal energy."},
  {id:"phy8-specific-heat-c4", front:"What is the relation between Cp and Cv for an ideal gas?", back:"<b>Cp − Cv = R</b> (Mayer's relation)."}
],
"phy8-second-law": [
  {id:"phy8-second-law-c1", front:"State the second law of thermodynamics (Kelvin-Planck statement).", back:"No heat engine can convert <b>all</b> absorbed heat into work — some heat must always be rejected."},
  {id:"phy8-second-law-c2", front:"What does the second law say about the direction of heat flow?", back:"Heat flows spontaneously only from a <b>hotter to a colder</b> body, never the reverse without external work."}
,
  {id:"phy8-second-law-c5", front:"State the Kelvin-Planck statement of the Second Law of Thermodynamics.", back:"No process is possible whose sole result is the <b>absorption of heat</b> from a reservoir and its <b>complete conversion into work</b>."},
  {id:"phy8-second-law-c6", front:"State the Clausius statement of the Second Law.", back:"No process is possible whose sole result is the transfer of heat from a <b>colder to a hotter body</b> without external work being done."}],
"phy8-heat-engines": [
  {id:"phy8-heat-engines-c1", front:"Define the efficiency of a heat engine.", back:"<b>η = W/Q₁ = 1 − Q₂/Q₁</b> (Q₁ = heat absorbed, Q₂ = heat rejected)."},
  {id:"phy8-heat-engines-c2", front:"What is a Carnot engine?", back:"An <b>ideal, reversible</b> heat engine giving the maximum possible efficiency between two temperatures."},
  {id:"phy8-heat-engines-c3", front:"What is the efficiency of a Carnot engine in terms of temperature?", back:"<b>η = 1 − T₂/T₁</b> (T in kelvin)."}
,
  {id:"phy8-heat-engines-c5", front:"What is the efficiency of a Carnot engine?", back:"η = 1 − <b>T₂/T₁</b>, depending only on the temperatures of the source (T₁) and sink (T₂) in Kelvin — the maximum possible efficiency between those temperatures."}],
"phy8-entropy": [
  {id:"phy8-entropy-c1", front:"Define entropy.", back:"A measure of the <b>disorder/randomness</b> of a system."},
  {id:"phy8-entropy-c2", front:"What does the second law say about the entropy of an isolated system?", back:"It <b>never decreases</b> — stays constant (reversible) or increases (irreversible)."}
,
  {id:"phy8-entropy-c5", front:"What does entropy measure?", back:"Entropy is a measure of the <b>disorder or randomness</b> of a system; it is a state function used to quantify the direction of natural (irreversible) processes."},
  {id:"phy8-entropy-c6", front:"How does entropy behave in an irreversible process for an isolated system?", back:"The total entropy of an isolated system <b>always increases</b> in an irreversible process, reaching a maximum at equilibrium."}],
"phy9-kinetic-theory-assumptions": [
  {id:"phy9-kinetic-theory-assumptions-c1", front:"What does kinetic theory assume about the size of gas molecules?", back:"They're treated as <b>point masses</b> — negligible size compared to intermolecular distances."},
  {id:"phy9-kinetic-theory-assumptions-c2", front:"What does kinetic theory assume about intermolecular forces?", back:"Except during collisions, molecules exert <b>no force</b> on each other."},
  {id:"phy9-kinetic-theory-assumptions-c3", front:"What does kinetic theory assume about molecular collisions?", back:"All collisions (between molecules, and with walls) are <b>perfectly elastic</b>."}
,
  {id:"phy9-kinetic-theory-assumptions-c5", front:"What assumption does kinetic theory make about molecular collisions?", back:"Collisions between molecules, and with the walls, are perfectly <b>elastic</b>, conserving kinetic energy and momentum."}],
"phy9-ideal-gas-equation": [
  {id:"phy9-ideal-gas-equation-c1", front:"State the ideal gas equation.", back:"<b>PV = nRT</b>."},
  {id:"phy9-ideal-gas-equation-c2", front:"State Boyle's law.", back:"At constant temperature, <b>PV = constant</b>."},
  {id:"phy9-ideal-gas-equation-c3", front:"State Charles's law.", back:"At constant pressure, <b>V/T = constant</b>."}
,
  {id:"phy9-ideal-gas-equation-c5", front:"State the ideal gas equation.", back:"<b>PV = nRT</b>, relating pressure, volume, number of moles, and absolute temperature via the universal gas constant R."}],
"phy9-degrees-freedom": [
  {id:"phy9-degrees-freedom-c1", front:"Define degrees of freedom of a gas molecule.", back:"The number of <b>independent ways</b> a molecule can possess/absorb energy."},
  {id:"phy9-degrees-freedom-c2", front:"How many degrees of freedom does a monoatomic gas molecule have?", back:"<b>3</b> (all translational)."},
  {id:"phy9-degrees-freedom-c3", front:"How many degrees of freedom does a diatomic gas molecule have (ignoring vibration)?", back:"<b>5</b> (3 translational + 2 rotational)."},
  {id:"phy9-degrees-freedom-c4", front:"State the law of equipartition of energy.", back:"Each degree of freedom contributes an average energy of <b>½kT</b> per molecule."}
],
"phy9-mean-free-path": [
  {id:"phy9-mean-free-path-c1", front:"Define mean free path.", back:"The <b>average distance</b> a molecule travels between successive collisions."},
  {id:"phy9-mean-free-path-c2", front:"How does mean free path depend on number density (n) and molecular diameter (d)?", back:"It's <b>inversely proportional</b> to n·d² — decreases as either increases."}
,
  {id:"phy9-mean-free-path-c5", front:"What is mean free path?", back:"The <b>average distance</b> a gas molecule travels between two successive collisions with other molecules."},
  {id:"phy9-mean-free-path-c6", front:"How does mean free path depend on molecular density and diameter?", back:"λ = 1/(√2 n π d²), so mean free path is <b>inversely proportional</b> to number density (n) and to the <b>square of molecular diameter</b> (d)."}],
"phy9-molecular-speeds": [
  {id:"phy9-molecular-speeds-c1", front:"Define rms speed of gas molecules.", back:"<b>v(rms) = √(3RT/M)</b> — square root of the mean of the squared speeds."},
  {id:"phy9-molecular-speeds-c2", front:"Rank rms, average, and most probable molecular speed by magnitude.", back:"<b>v(rms) > v(average) > v(most probable)</b>."},
  {id:"phy9-molecular-speeds-c3", front:"How does rms speed depend on temperature and molar mass?", back:"Directly proportional to <b>√T</b>, inversely proportional to <b>√M</b>."}
,
  {id:"phy9-molecular-speeds-c5", front:"How is the RMS speed of gas molecules related to temperature?", back:"v_rms = <b>√(3RT/M)</b>, so RMS speed increases with the square root of absolute temperature and decreases with molar mass M."}],
"phy10-SHM": [
  {id:"phy10-SHM-c1", front:"Define simple harmonic motion.", back:"Periodic motion where the restoring force is <b>directly proportional to displacement</b> and directed opposite to it."},
  {id:"phy10-SHM-c2", front:"What is the displacement equation for SHM?", back:"<b>x = A sin(ωt + φ)</b>."},
  {id:"phy10-SHM-c3", front:"What is the relation between angular frequency ω and period T?", back:"<b>ω = 2π/T</b>."},
  {id:"phy10-SHM-c4", front:"What is the acceleration in SHM in terms of displacement?", back:"<b>a = −ω²x</b> — proportional to displacement, directed toward equilibrium."}
],
"phy10-shm-energy": [
  {id:"phy10-shm-energy-c1", front:"What is the kinetic energy in SHM, at displacement x?", back:"<b>KE = ½mω²(A²−x²)</b>."},
  {id:"phy10-shm-energy-c2", front:"What is the potential energy in SHM, at displacement x?", back:"<b>PE = ½mω²x²</b>."},
  {id:"phy10-shm-energy-c3", front:"What is the total energy in SHM, and how does it vary with time?", back:"<b>E = ½mω²A²</b> — constant, independent of time or position."}
,
  {id:"phy10-shm-energy-c5", front:"How does the total mechanical energy of a particle in SHM vary with time?", back:"It remains <b>constant</b>, equal to <b>½mω²A²</b>, as kinetic and potential energy continuously interconvert."}],
"phy10-wave-motion": [
  {id:"phy10-wave-motion-c1", front:"Define a mechanical wave.", back:"A disturbance that transfers <b>energy</b> through a medium without net transfer of matter."},
  {id:"phy10-wave-motion-c2", front:"Distinguish transverse from longitudinal waves.", back:"<b>Transverse</b>: particle vibration perpendicular to propagation. <b>Longitudinal</b>: vibration parallel to propagation."},
  {id:"phy10-wave-motion-c3", front:"What is the relation between wave speed v, frequency f, and wavelength λ?", back:"<b>v = fλ</b>."}
,
  {id:"phy10-wave-motion-c5", front:"What is the relationship between wave speed, frequency, and wavelength?", back:"Wave speed <b>v = νλ</b>, the product of <b>frequency (ν)</b> and <b>wavelength (λ)</b>."}],
"phy10-superposition-waves": [
  {id:"phy10-superposition-waves-c1", front:"State the principle of superposition of waves.", back:"The resultant displacement where waves overlap is the <b>vector sum</b> of each wave's individual displacement."},
  {id:"phy10-superposition-waves-c2", front:"What is the condition for constructive interference?", back:"Path difference = <b>nλ</b> (whole number of wavelengths)."},
  {id:"phy10-superposition-waves-c3", front:"What is the condition for destructive interference?", back:"Path difference = <b>(n+½)λ</b> (odd multiple of half-wavelength)."},
  {id:"phy10-superposition-waves-c4", front:"What are beats?", back:"Periodic variation in loudness heard when <b>two waves of slightly different frequencies</b> superpose."}
],
"phy10-doppler-effect": [
  {id:"phy10-doppler-effect-c1", front:"Define the Doppler effect.", back:"The apparent change in <b>frequency</b> of a wave due to relative motion between source and observer."},
  {id:"phy10-doppler-effect-c2", front:"Does apparent frequency increase or decrease as the source approaches the observer?", back:"<b>Increase</b>."}
,
  {id:"phy10-doppler-effect-c5", front:"What is the Doppler effect in sound?", back:"The apparent change in <b>frequency</b> of a wave due to <b>relative motion</b> between the source and the observer."},
  {id:"phy10-doppler-effect-c6", front:"What happens to the apparent frequency when a source moves toward a stationary observer?", back:"The apparent frequency <b>increases</b> because the wavelength in front of the source gets <b>compressed</b>."}],
"phy11-electric-charges": [
  {id:"phy11-electric-charges-c1", front:"Name the three fundamental properties of electric charge.", back:"<b>Quantization, conservation, and additivity</b>."},
  {id:"phy11-electric-charges-c2", front:"State Coulomb's law.", back:"<b>F = kq₁q₂/r²</b>, along the line joining the two charges (k = 1/4πε₀)."},
  {id:"phy11-electric-charges-c3", front:"Is Coulomb's force always attractive?", back:"<b>No</b> — attractive for opposite charges, repulsive for like charges."},
  {id:"phy11-electric-charges-c4", front:"What is the value of Coulomb's constant k in vacuum?", back:"<b>k ≈ 9×10⁹ N·m²/C²</b>."}
],
"phy11-electric-field": [
  {id:"phy11-electric-field-c1", front:"Define electric field intensity.", back:"Force per unit positive test charge at a point: <b>E = F/q</b>."},
  {id:"phy11-electric-field-c2", front:"What is the electric field due to a point charge q at distance r?", back:"<b>E = kq/r²</b>."},
  {id:"phy11-electric-field-c3", front:"What is the SI unit of electric field?", back:"<b>N/C</b> (equivalently V/m)."}
,
  {id:"phy11-electric-field-c5", front:"What is the SI unit of electric field?", back:"<b>Newton per coulomb (N/C)</b>, equivalent to <b>volt per metre (V/m)</b>."}],
"phy11-electric-dipole": [
  {id:"phy11-electric-dipole-c1", front:"Define an electric dipole.", back:"A pair of <b>equal and opposite charges</b> separated by a small distance."},
  {id:"phy11-electric-dipole-c2", front:"Define dipole moment.", back:"<b>p = q × 2a</b>, directed from the negative to the positive charge."},
  {id:"phy11-electric-dipole-c3", front:"What is the electric field on a dipole's axial line, far away (r≫a)?", back:"<b>E(axial) = 2kp/r³</b>."},
  {id:"phy11-electric-dipole-c4", front:"What is the torque on a dipole in a uniform electric field?", back:"<b>τ = pE sinθ</b> (θ = angle between p and E)."}
],
"phy11-gauss-law": [
  {id:"phy11-gauss-law-c1", front:"Define electric flux.", back:"A measure of field lines through a surface: <b>Φ = E·A</b>."},
  {id:"phy11-gauss-law-c2", front:"State Gauss's law.", back:"<b>Φ = q(enclosed)/ε₀</b> — total flux through a closed surface depends only on the enclosed charge."}
,
  {id:"phy11-gauss-law-c5", front:"State Gauss's Law.", back:"The total electric flux through a closed surface equals <b>1/ε₀</b> times the <b>net charge enclosed</b>: Φ = q/ε₀."},
  {id:"phy11-gauss-law-c6", front:"Why is Gauss's Law useful for finding fields of symmetric charge distributions?", back:"It lets us choose a <b>Gaussian surface</b> matching the charge's <b>symmetry</b>, making the flux integral simple to evaluate."}],
"phy11-electric-potential": [
  {id:"phy11-electric-potential-c1", front:"Define electric potential at a point.", back:"Work done per unit positive charge in bringing it from <b>infinity</b> to that point."},
  {id:"phy11-electric-potential-c2", front:"What is the electric potential due to a point charge q at distance r?", back:"<b>V = kq/r</b>."},
  {id:"phy11-electric-potential-c3", front:"How are electric field and potential related?", back:"<b>E = −dV/dr</b> — field is the negative gradient of potential."},
  {id:"phy11-electric-potential-c4", front:"What is the relation between potential energy and potential for a charge q?", back:"<b>U = qV</b>."}
],
"phy11-capacitors": [
  {id:"phy11-capacitors-c1", front:"Define capacitance.", back:"<b>C = Q/V</b> — charge stored per unit potential."},
  {id:"phy11-capacitors-c2", front:"What is the SI unit of capacitance?", back:"<b>Farad (F)</b>."},
  {id:"phy11-capacitors-c3", front:"What is the capacitance of a parallel plate capacitor (vacuum)?", back:"<b>C = ε₀A/d</b>."},
  {id:"phy11-capacitors-c4", front:"How do capacitances combine in series vs parallel?", back:"<b>Series</b>: 1/C(eq) = 1/C₁+1/C₂+…. <b>Parallel</b>: C(eq) = C₁+C₂+…."}
],
"phy12-drift-velocity": [
  {id:"phy12-drift-velocity-c1", front:"Define drift velocity.", back:"The <b>average velocity</b> gained by free electrons in a conductor due to an applied field."},
  {id:"phy12-drift-velocity-c2", front:"What is the relation between current I and drift velocity v(d)?", back:"<b>I = nAqv(d)</b> (n = carrier density, A = cross-section, q = charge)."},
  {id:"phy12-drift-velocity-c3", front:"Define current density.", back:"Current per unit cross-sectional area: <b>J = I/A</b>."}
,
  {id:"phy12-drift-velocity-c5", front:"How is current related to drift velocity?", back:"Current <b>I = nqvdA</b>, where <b>n</b> is charge carrier density, <b>vd</b> is drift velocity, and A is cross-sectional area."}],
"phy12-ohms-law": [
  {id:"phy12-ohms-law-c1", front:"State Ohm's law.", back:"At constant temperature, <b>V = IR</b> — current is directly proportional to voltage."},
  {id:"phy12-ohms-law-c2", front:"Distinguish ohmic from non-ohmic conductors.", back:"<b>Ohmic</b>: V-I graph is a straight line through the origin. <b>Non-ohmic</b>: V-I graph is non-linear."}
,
  {id:"phy12-ohms-law-c5", front:"State Ohm's Law.", back:"At constant temperature, the current through a conductor is <b>directly proportional</b> to the <b>potential difference</b> across it: V = IR."},
  {id:"phy12-ohms-law-c6", front:"What does a non-linear V-I graph indicate about a device?", back:"The device is <b>non-ohmic</b> — its <b>resistance varies</b> with current or voltage, e.g., a diode."}],
"phy12-resistance": [
  {id:"phy12-resistance-c1", front:"Define electrical resistance.", back:"<b>R = V/I</b> — opposition to current flow."},
  {id:"phy12-resistance-c2", front:"What is the formula for resistance in terms of resistivity?", back:"<b>R = ρL/A</b>."},
  {id:"phy12-resistance-c3", front:"How does a metal's resistance vary with temperature?", back:"It <b>increases</b> with temperature."},
  {id:"phy12-resistance-c4", front:"How does a semiconductor's resistance vary with temperature?", back:"It <b>decreases</b> with temperature."}
],
"phy12-electrical-power": [
  {id:"phy12-electrical-power-c1", front:"What is the formula for electrical power in terms of V and I?", back:"<b>P = VI</b>."},
  {id:"phy12-electrical-power-c2", front:"What are the alternate forms of the electrical power formula using R?", back:"<b>P = I²R = V²/R</b>."}
,
  {id:"phy12-electrical-power-c5", front:"Write the formula for electrical power dissipated in a resistor.", back:"P = <b>I²R</b> = VI = <b>V²/R</b>, the rate of electrical energy converted to heat."},
  {id:"phy12-electrical-power-c6", front:"State Joule's Law of heating.", back:"Heat produced <b>H = I²Rt</b>, proportional to the <b>square of current</b>, resistance, and time."}],
"phy12-kirchhoffs-laws": [
  {id:"phy12-kirchhoffs-laws-c1", front:"State Kirchhoff's current law (junction rule).", back:"The algebraic sum of currents at a junction is <b>zero</b> (current in = current out)."},
  {id:"phy12-kirchhoffs-laws-c2", front:"State Kirchhoff's voltage law (loop rule).", back:"The algebraic sum of potential differences around any <b>closed loop</b> is zero."},
  {id:"phy12-kirchhoffs-laws-c3", front:"Which conservation principle does each Kirchhoff's law express?", back:"Current law: <b>conservation of charge</b>. Voltage law: <b>conservation of energy</b>."}
,
  {id:"phy12-kirchhoffs-laws-c5", front:"State Kirchhoff's Voltage Law (KVL).", back:"The algebraic sum of potential differences around any <b>closed loop</b> in a circuit is <b>zero</b>."}],
"phy12-wheatstone-bridge": [
  {id:"phy12-wheatstone-bridge-c1", front:"What is the balanced condition of a Wheatstone bridge (resistances P, Q, R, S)?", back:"<b>P/Q = R/S</b> — no current flows through the galvanometer."},
  {id:"phy12-wheatstone-bridge-c2", front:"What is a Wheatstone bridge used to measure?", back:"An <b>unknown resistance</b>, balanced against three known resistances."}
,
  {id:"phy12-wheatstone-bridge-c5", front:"What is the balance condition of a Wheatstone bridge?", back:"The bridge is balanced when <b>P/Q = R/S</b>, making the <b>galvanometer</b> current zero."},
  {id:"phy12-wheatstone-bridge-c6", front:"What quantity does a meter bridge experimentally determine?", back:"It determines an <b>unknown resistance</b> by finding the <b>null (balance) point</b> on a uniform wire."}],
"phy13-biot-savart-law": [
  {id:"phy13-biot-savart-law-c1", front:"State the Biot-Savart law.", back:"<b>dB = (μ₀/4π)(I dl × r̂)/r²</b> — magnetic field due to a current element."},
  {id:"phy13-biot-savart-law-c2", front:"What is the magnetic field at the centre of a circular current loop (radius R, current I)?", back:"<b>B = μ₀I/2R</b>."}
,
  {id:"phy13-biot-savart-law-c5", front:"State the Biot-Savart Law.", back:"The magnetic field due to a current element is dB = (μ₀/4π)(I dl × r̂)/r², proportional to <b>current</b> and inversely to <b>r²</b>."},
  {id:"phy13-biot-savart-law-c6", front:"What is the direction of dB given by the Biot-Savart Law?", back:"Perpendicular to both the <b>current element</b> and the <b>displacement vector</b>, given by the <b>right-hand rule</b>."}],
"phy13-amperes-law": [
  {id:"phy13-amperes-law-c1", front:"State Ampere's circuital law.", back:"<b>∮B·dl = μ₀I(enclosed)</b>."},
  {id:"phy13-amperes-law-c2", front:"What is the magnetic field due to a long straight current-carrying wire at distance r?", back:"<b>B = μ₀I/2πr</b>."}
,
  {id:"phy13-amperes-law-c5", front:"State Ampere's Circuital Law.", back:"The line integral of magnetic field around a closed loop equals <b>μ₀</b> times the <b>current enclosed</b>: ∮B·dl = μ₀I."},
  {id:"phy13-amperes-law-c6", front:"What is the magnetic field inside a long solenoid using Ampere's Law?", back:"B = <b>μ₀nI</b>, where <b>n</b> is the number of turns per unit length and I is the current."}],
"phy13-force-moving-charge": [
  {id:"phy13-force-moving-charge-c1", front:"What is the Lorentz force on a moving charge in a magnetic field?", back:"<b>F = qv × B</b>."},
  {id:"phy13-force-moving-charge-c2", front:"What gives the direction of magnetic force on a positive charge?", back:"The <b>right-hand rule</b> — F is perpendicular to both v and B."},
  {id:"phy13-force-moving-charge-c3", front:"Does the magnetic force do work on a moving charge?", back:"<b>No</b> — it's always perpendicular to velocity, so it only changes direction, not speed."}
,
  {id:"phy13-force-moving-charge-c5", front:"Write the expression for the Lorentz force on a moving charge.", back:"F = q(<b>E</b> + <b>v × B</b>), the combined force from electric and magnetic fields."}],
"phy13-force-current-conductor": [
  {id:"phy13-force-current-conductor-c1", front:"What is the force on a current-carrying conductor of length L in a magnetic field B?", back:"<b>F = IL × B</b>."},
  {id:"phy13-force-current-conductor-c2", front:"What is the force per unit length between two parallel current-carrying wires?", back:"<b>F/L = μ₀I₁I₂/2πd</b>."},
  {id:"phy13-force-current-conductor-c3", front:"Do two parallel wires with current in the same direction attract or repel?", back:"<b>Attract</b>."}
,
  {id:"phy13-force-current-conductor-c5", front:"What is the force on a current-carrying conductor in a magnetic field?", back:"F = <b>IL × B</b>, maximum when the conductor is <b>perpendicular</b> to the field."}],
"phy13-galvanometer": [
  {id:"phy13-galvanometer-c1", front:"What is the working principle of a moving coil galvanometer?", back:"A current-carrying coil in a magnetic field feels a <b>torque</b>, deflecting proportionally to the current."},
  {id:"phy13-galvanometer-c2", front:"How is a galvanometer converted into an ammeter?", back:"By connecting a <b>low resistance (shunt) in parallel</b>."},
  {id:"phy13-galvanometer-c3", front:"How is a galvanometer converted into a voltmeter?", back:"By connecting a <b>high resistance in series</b>."}
,
  {id:"phy13-galvanometer-c5", front:"How is a galvanometer converted into an ammeter?", back:"By connecting a <b>low-resistance shunt</b> in <b>parallel</b> with it to bypass most of the current."}],
"phy13-magnetic-dipole": [
  {id:"phy13-magnetic-dipole-c1", front:"Define the magnetic dipole moment of a current loop.", back:"<b>m = IA</b> (current × loop area), direction by the right-hand rule."},
  {id:"phy13-magnetic-dipole-c2", front:"What is the torque on a magnetic dipole in a uniform field?", back:"<b>τ = m × B</b>."}
,
  {id:"phy13-magnetic-dipole-c5", front:"What is the magnetic dipole moment of a current loop?", back:"m = <b>IA</b>, the product of current and loop area, directed by the <b>right-hand rule</b>."},
  {id:"phy13-magnetic-dipole-c6", front:"What is the torque on a magnetic dipole in a uniform magnetic field?", back:"τ = <b>m × B</b>, tending to align the dipole moment with the field."}],
"phy13-magnetic-materials": [
  {id:"phy13-magnetic-materials-c1", front:"Define magnetic susceptibility.", back:"A measure of how easily a material <b>gets magnetized</b> in an external field."},
  {id:"phy13-magnetic-materials-c2", front:"Distinguish diamagnetic, paramagnetic, and ferromagnetic materials.", back:"<b>Diamagnetic</b>: weakly repelled. <b>Paramagnetic</b>: weakly attracted. <b>Ferromagnetic</b>: strongly attracted, can retain magnetization."}
,
  {id:"phy13-magnetic-materials-c5", front:"What distinguishes ferromagnetic materials from paramagnetic materials?", back:"Ferromagnetic materials show <b>strong, permanent magnetization</b> due to domain alignment, unlike the <b>weak, temporary</b> magnetization of paramagnetics."},
  {id:"phy13-magnetic-materials-c6", front:"What happens to a ferromagnetic material above its Curie temperature?", back:"It loses its ferromagnetism and becomes <b>paramagnetic</b> as thermal agitation disrupts domain alignment."}],
"phy14-faradays-law": [
  {id:"phy14-faradays-law-c1", front:"State Faraday's first law of electromagnetic induction.", back:"A changing <b>magnetic flux</b> through a circuit induces an emf in it."},
  {id:"phy14-faradays-law-c2", front:"State Faraday's second law (quantitative).", back:"<b>ε = −dΦ/dt</b> — induced emf equals the negative rate of change of flux."}
,
  {id:"phy14-faradays-law-c5", front:"State Faraday's Law of Electromagnetic Induction.", back:"The induced EMF equals the negative rate of change of <b>magnetic flux</b>: ε = −dΦ/dt."},
  {id:"phy14-faradays-law-c6", front:"What factors can change magnetic flux to induce an EMF?", back:"A change in <b>field strength</b>, <b>area</b> of the loop, or the <b>angle</b> between B and the area vector."}],
"phy14-lenzs-law": [
  {id:"phy14-lenzs-law-c1", front:"State Lenz's law.", back:"Induced current flows in a direction that <b>opposes the change</b> in flux that produced it."},
  {id:"phy14-lenzs-law-c2", front:"What conservation principle does Lenz's law's negative sign reflect?", back:"<b>Conservation of energy</b>."}
,
  {id:"phy14-lenzs-law-c5", front:"State Lenz's Law.", back:"The induced current flows in a direction that <b>opposes the change</b> in magnetic flux that produced it."},
  {id:"phy14-lenzs-law-c6", front:"How does Lenz's Law relate to conservation of energy?", back:"The opposing induced current means work must be done against it, ensuring energy is <b>conserved</b>, not created."}],
"phy14-motional-emf": [
  {id:"phy14-motional-emf-c1", front:"Define motional emf.", back:"The emf induced in a conductor moving through a magnetic field: <b>ε = Bvl</b>."},
  {id:"phy14-motional-emf-c2", front:"What causes motional emf at the microscopic level?", back:"The <b>Lorentz force</b> on free charges in the moving conductor, separating charge."}
,
  {id:"phy14-motional-emf-c5", front:"Write the formula for motional EMF of a rod moving in a magnetic field.", back:"ε = <b>Bvl</b>, where B is field strength, v is velocity, and l is the rod's length."},
  {id:"phy14-motional-emf-c6", front:"What is the origin of motional EMF at the microscopic level?", back:"The <b>magnetic force (qv×B)</b> on free charges in the moving conductor pushes them, creating a <b>charge separation</b>."}],
"phy14-self-inductance": [
  {id:"phy14-self-inductance-c1", front:"Define self-inductance.", back:"A coil's opposition to a change in its own current: <b>ε = −L(dI/dt)</b>."},
  {id:"phy14-self-inductance-c2", front:"What is the self-inductance of a long solenoid (N turns, length l, area A)?", back:"<b>L = μ₀N²A/l</b>."},
  {id:"phy14-self-inductance-c3", front:"What is the SI unit of inductance?", back:"<b>Henry (H)</b>."}
,
  {id:"phy14-self-inductance-c5", front:"Define self-inductance of a coil.", back:"The property by which a coil opposes a change in its own current, given by <b>L = NΦ/I</b>, measured in <b>henry</b>."}],
"phy14-mutual-inductance": [
  {id:"phy14-mutual-inductance-c1", front:"Define mutual inductance.", back:"A changing current in one coil induces an emf in a nearby coil: <b>ε₂ = −M(dI₁/dt)</b>."},
  {id:"phy14-mutual-inductance-c2", front:"What is the SI unit of mutual inductance?", back:"<b>Henry (H)</b>."}
,
  {id:"phy14-mutual-inductance-c5", front:"Define mutual inductance between two coils.", back:"The EMF induced in one coil due to <b>rate of change of current</b> in the neighboring coil: ε₂ = −M(dI₁/dt)."},
  {id:"phy14-mutual-inductance-c6", front:"How does the number of turns affect mutual inductance?", back:"Mutual inductance M is proportional to the product of the <b>number of turns</b> in both coils, N₁N₂."}],
"phy22-ac-circuits": [
  {id:"phy22-ac-circuits-c1", front:"What is the standard form of AC voltage/current?", back:"<b>V = V₀sin(ωt)</b> — sinusoidal oscillation."},
  {id:"phy22-ac-circuits-c2", front:"What is the relation between rms and peak value for sinusoidal AC?", back:"<b>rms = peak/√2</b>."},
  {id:"phy22-ac-circuits-c3", front:"What is the reactance of a pure inductor in an AC circuit?", back:"<b>X(L) = ωL</b>."},
  {id:"phy22-ac-circuits-c4", front:"What is the reactance of a pure capacitor in an AC circuit?", back:"<b>X(C) = 1/ωC</b>."}
],
"phy22-lcr-circuits": [
  {id:"phy22-lcr-circuits-c1", front:"What is the impedance of a series LCR circuit?", back:"<b>Z = √(R² + (X(L)−X(C))²)</b>."},
  {id:"phy22-lcr-circuits-c2", front:"What is the resonance condition for a series LCR circuit?", back:"<b>X(L) = X(C)</b>, i.e. ω = 1/√(LC) — impedance is minimum, current maximum."},
  {id:"phy22-lcr-circuits-c3", front:"At resonance in a series LCR circuit, what is the phase relation between V and I?", back:"They're <b>in phase</b> (phase difference = 0)."}
,
  {id:"phy22-lcr-circuits-c5", front:"What is the condition for resonance in a series LCR circuit?", back:"Resonance occurs when <b>inductive reactance equals capacitive reactance</b> (X_L = X_C), giving minimum impedance (Z = R) and maximum current at resonant frequency ω₀ = 1/√(LC)."}],
"phy22-transformers": [
  {id:"phy22-transformers-c1", front:"What is a transformer's working principle?", back:"<b>Mutual induction</b> — a changing primary current induces emf in the secondary via shared flux."},
  {id:"phy22-transformers-c2", front:"What is the relation between turns ratio and voltage ratio in an ideal transformer?", back:"<b>V(s)/V(p) = N(s)/N(p)</b>."},
  {id:"phy22-transformers-c3", front:"Distinguish a step-up from a step-down transformer.", back:"<b>Step-up</b>: secondary turns > primary (voltage increases). <b>Step-down</b>: secondary turns < primary (voltage decreases)."}
,
  {id:"phy22-transformers-c5", front:"What is the turns ratio relation in an ideal transformer?", back:"V_s/V_p = N_s/N_p = I_p/I_s, where <b>N_s and N_p</b> are secondary and primary turns; a <b>step-up</b> transformer has N_s > N_p."}],
"phy15-displacement-current": [
  {id:"phy15-displacement-current-c1", front:"What problem did Maxwell's displacement current solve?", back:"An inconsistency in Ampere's law for a <b>charging capacitor</b>, where there's a changing E field but no conduction current between the plates."},
  {id:"phy15-displacement-current-c2", front:"Define displacement current.", back:"A current-like term from a <b>changing electric field</b>: I(d) = ε₀(dΦ(E)/dt)."}
,
  {id:"phy15-displacement-current-c5", front:"What is displacement current?", back:"A current-like term, Id = ε₀(dΦE/dt), arising from a <b>changing electric flux</b>, introduced by Maxwell to fix Ampere's Law."},
  {id:"phy15-displacement-current-c6", front:"Why did Maxwell introduce displacement current?", back:"To make Ampere's Circuital Law <b>consistent</b> with charge conservation, especially in a <b>charging capacitor</b> circuit."}],
"phy15-em-spectrum": [
  {id:"phy15-em-spectrum-c1", front:"List the EM spectrum in order of increasing wavelength, starting from gamma rays.", back:"<b>Gamma rays, X-rays, ultraviolet, visible, infrared, microwaves, radio waves</b>."},
  {id:"phy15-em-spectrum-c2", front:"Which part of the EM spectrum has the highest frequency/energy?", back:"<b>Gamma rays</b>."},
  {id:"phy15-em-spectrum-c3", front:"Which part of the EM spectrum has the longest wavelength?", back:"<b>Radio waves</b>."}
,
  {id:"phy15-em-spectrum-c5", front:"Arrange the electromagnetic spectrum in order of increasing wavelength starting from gamma rays.", back:"<b>Gamma rays, X-rays, UV, visible, infrared, microwaves, radio waves</b> — increasing wavelength, decreasing frequency."}],
"phy15-em-wave-properties": [
  {id:"phy15-em-wave-properties-c1", front:"Are electromagnetic waves transverse or longitudinal?", back:"<b>Transverse</b> — E and B fields oscillate perpendicular to each other and to propagation."},
  {id:"phy15-em-wave-properties-c2", front:"What is the speed of EM waves in vacuum?", back:"<b>c ≈ 3×10⁸ m/s</b>."},
  {id:"phy15-em-wave-properties-c3", front:"Do EM waves need a medium to travel?", back:"<b>No</b> — they can travel through vacuum."}
,
  {id:"phy15-em-wave-properties-c5", front:"How are the electric and magnetic field vectors oriented in an electromagnetic wave?", back:"<b>E</b> and <b>B</b> are mutually perpendicular to each other and to the <b>direction of propagation</b>."}],
"phy16-reflection": [
  {id:"phy16-reflection-c1", front:"State the laws of reflection.", back:"<b>Angle of incidence = angle of reflection</b>; incident ray, reflected ray, and normal lie in the same plane."},
  {id:"phy16-reflection-c2", front:"State the mirror formula.", back:"<b>1/v + 1/u = 1/f</b>."},
  {id:"phy16-reflection-c3", front:"What is the relation between focal length and radius of curvature for a spherical mirror?", back:"<b>f = R/2</b>."},
  {id:"phy16-reflection-c4", front:"What type of image does a plane mirror always form?", back:"<b>Virtual, erect</b>, and the same size as the object."}
],
"phy16-refraction": [
  {id:"phy16-refraction-c1", front:"Define refractive index.", back:"<b>n = c/v</b> — ratio of light's speed in vacuum to its speed in the medium."},
  {id:"phy16-refraction-c2", front:"State Snell's law.", back:"<b>n₁sinθ₁ = n₂sinθ₂</b>."},
  {id:"phy16-refraction-c3", front:"What is total internal reflection?", back:"Light going from a denser to rarer medium, hitting the boundary <b>beyond the critical angle</b>, is fully reflected back."},
  {id:"phy16-refraction-c4", front:"Define critical angle.", back:"The angle of incidence (in the denser medium) for which the <b>refraction angle is 90°</b>."}
],
"phy16-thin-lens": [
  {id:"phy16-thin-lens-c1", front:"State the lens formula.", back:"<b>1/v − 1/u = 1/f</b>."},
  {id:"phy16-thin-lens-c2", front:"Define the power of a lens.", back:"<b>P = 1/f</b> (f in metres), in dioptres (D)."},
  {id:"phy16-thin-lens-c3", front:"What sign of focal length does a convex lens have vs a concave lens?", back:"<b>Convex</b>: positive f. <b>Concave</b>: negative f."},
  {id:"phy16-thin-lens-c4", front:"How do the powers of two thin lenses in contact combine?", back:"They <b>add</b>: P = P₁ + P₂."}
],
"phy16-prism": [
  {id:"phy16-prism-c1", front:"Define the angle of deviation in a prism.", back:"The angle between the <b>incident ray and the emergent ray</b>."},
  {id:"phy16-prism-c2", front:"What is the condition for minimum deviation in a prism?", back:"The <b>angle of incidence equals the angle of emergence</b> (symmetric passage)."},
  {id:"phy16-prism-c3", front:"State the prism formula relating n, prism angle A, and minimum deviation δm.", back:"<b>n = sin((A+δm)/2) / sin(A/2)</b>."}
,
  {id:"phy16-prism-c5", front:"What causes dispersion of white light in a prism?", back:"Different <b>wavelengths</b> refract by different amounts because the prism's <b>refractive index varies with wavelength</b>."}],
"phy16-optical-instruments": [
  {id:"phy16-optical-instruments-c1", front:"What is the near point of a normal human eye?", back:"About <b>25 cm</b>."},
  {id:"phy16-optical-instruments-c2", front:"Define the eye's power of accommodation.", back:"Its ability to <b>adjust focal length</b> (via the lens) to focus at different distances."},
  {id:"phy16-optical-instruments-c3", front:"What is the magnifying power of a simple microscope?", back:"<b>M = 1 + D/f</b> (D = 25 cm)."},
  {id:"phy16-optical-instruments-c4", front:"What is myopia, and how is it corrected?", back:"Image focuses <b>in front of</b> the retina; corrected with a <b>concave (diverging)</b> lens."},
  {id:"phy16-optical-instruments-c5", front:"What is hypermetropia, and how is it corrected?", back:"Image focuses <b>behind</b> the retina; corrected with a <b>convex (converging)</b> lens."}
],
"phy16-wave-optics": [
  {id:"phy16-wave-optics-c1", front:"Define a wavefront.", back:"The locus of points <b>in the same phase</b> of vibration at a given instant."},
  {id:"phy16-wave-optics-c2", front:"State Huygens' principle.", back:"Every point on a wavefront acts as a source of <b>secondary wavelets</b>; the new wavefront is their envelope."},
  {id:"phy16-wave-optics-c3", front:"What shape is the wavefront from a point source in an isotropic medium?", back:"<b>Spherical</b>."}
,
  {id:"phy16-wave-optics-c5", front:"State Huygens' Principle.", back:"Every point on a wavefront acts as a source of <b>secondary wavelets</b>, and their envelope gives the <b>new wavefront</b>."}],
"phy16-interference": [
  {id:"phy16-interference-c1", front:"What condition must two light sources meet to show sustained interference?", back:"They must be <b>coherent</b> (constant phase difference), same frequency."},
  {id:"phy16-interference-c2", front:"In Young's double slit experiment, what is the fringe width formula?", back:"<b>β = λD/d</b>."},
  {id:"phy16-interference-c3", front:"What is the condition for a bright fringe in YDSE?", back:"Path difference = <b>nλ</b>."},
  {id:"phy16-interference-c4", front:"What is the condition for a dark fringe in YDSE?", back:"Path difference = <b>(n+½)λ</b>."}
],
"phy16-diffraction": [
  {id:"phy16-diffraction-c1", front:"Define diffraction.", back:"The <b>bending/spreading</b> of waves around obstacles or through apertures comparable to the wavelength."},
  {id:"phy16-diffraction-c2", front:"How does diffraction differ from interference, by source?", back:"<b>Interference</b>: two separate coherent sources. <b>Diffraction</b>: wavelets from the same wavefront/single source."},
  {id:"phy16-diffraction-c3", front:"What is the condition for the first minimum in single-slit diffraction?", back:"<b>a sinθ = λ</b> (a = slit width)."}
,
  {id:"phy16-diffraction-c5", front:"What condition produces the first minimum in single-slit diffraction?", back:"When <b>a sinθ = λ</b>, where a is the slit width, causing destructive interference."}],
"phy16-polarization": [
  {id:"phy16-polarization-c1", front:"Define polarized light.", back:"Light whose electric field vibrations are restricted to a <b>single plane</b>."},
  {id:"phy16-polarization-c2", front:"State Malus's law.", back:"<b>I = I₀cos²θ</b> — intensity after an analyzer, θ between polarizer and analyzer axes."},
  {id:"phy16-polarization-c3", front:"Define Brewster's angle.", back:"The incidence angle at which reflected light is <b>completely polarized</b>: tanθ(B) = n."},
  {id:"phy16-polarization-c4", front:"Does polarization prove light is a transverse wave?", back:"<b>Yes</b> — only transverse waves can be polarized."}
],
"phy17-photoelectric-effect": [
  {id:"phy17-photoelectric-effect-c1", front:"Define the photoelectric effect.", back:"Emission of electrons from a metal surface when light of <b>sufficient frequency</b> falls on it."},
  {id:"phy17-photoelectric-effect-c2", front:"State Einstein's photoelectric equation.", back:"<b>KE(max) = hν − φ</b> (φ = work function)."},
  {id:"phy17-photoelectric-effect-c3", front:"Define work function.", back:"The <b>minimum energy</b> needed to eject an electron from a metal surface."},
  {id:"phy17-photoelectric-effect-c4", front:"Define threshold frequency.", back:"The minimum frequency below which <b>no photoelectric emission</b> occurs, regardless of intensity."},
  {id:"phy17-photoelectric-effect-c5", front:"Does increasing intensity below the threshold frequency cause emission?", back:"<b>No</b> — emission depends on frequency, not intensity."},
  {id:"phy17-photoelectric-effect-c6", front:"How does stopping potential relate to the maximum kinetic energy of photoelectrons?", back:"<b>eV(stop) = KE(max)</b>."}
],
"phy17-de-broglie": [
  {id:"phy17-de-broglie-c1", front:"State de Broglie's hypothesis.", back:"Every moving particle has an associated wavelength: <b>λ = h/p</b>."},
  {id:"phy17-de-broglie-c2", front:"What is the de Broglie wavelength formula in terms of mass and velocity?", back:"<b>λ = h/(mv)</b>."},
  {id:"phy17-de-broglie-c3", front:"Why don't we observe the wave nature of everyday objects?", back:"Their de Broglie wavelength is <b>negligibly small</b> due to their large momentum."}
,
  {id:"phy17-de-broglie-c5", front:"Write the de Broglie wavelength formula.", back:"λ = <b>h/p</b> = h/(mv), relating a particle's <b>wavelength</b> to its <b>momentum</b>."}],
"phy17-davisson-germer": [
  {id:"phy17-davisson-germer-c1", front:"What did the Davisson-Germer experiment demonstrate?", back:"<b>Diffraction of electrons</b> by a crystal, confirming the wave nature of matter."},
  {id:"phy17-davisson-germer-c2", front:"What pattern, analogous to X-ray diffraction, did the experiment observe?", back:"Intensity <b>maxima at specific scattering angles</b>, matching the de Broglie wavelength prediction."}
,
  {id:"phy17-davisson-germer-c5", front:"What did the Davisson-Germer experiment demonstrate?", back:"It confirmed the <b>wave nature of electrons</b> by observing <b>diffraction</b> patterns from a nickel crystal."},
  {id:"phy17-davisson-germer-c6", front:"What phenomenon in the Davisson-Germer experiment matched de Broglie's prediction?", back:"The <b>intensity peak</b> of scattered electrons at a specific angle matched the wavelength predicted by <b>λ = h/p</b>."}],
"phy18-rutherford-model": [
  {id:"phy18-rutherford-model-c1", front:"What did Rutherford's alpha-scattering experiment reveal about atomic structure?", back:"Most of an atom's mass and positive charge is in a tiny <b>central nucleus</b>, with electrons orbiting at a distance."},
  {id:"phy18-rutherford-model-c2", front:"What was the major limitation of Rutherford's model?", back:"It couldn't explain why orbiting electrons <b>don't spiral into the nucleus</b> and radiate away their energy."}
,
  {id:"phy18-rutherford-model-c5", front:"What did Rutherford's alpha-scattering experiment reveal about atomic structure?", back:"Most of the atom's mass and <b>positive charge</b> is concentrated in a tiny, dense <b>nucleus</b>."},
  {id:"phy18-rutherford-model-c6", front:"What was the major drawback of Rutherford's nuclear model?", back:"It couldn't explain atomic <b>stability</b>, since accelerating electrons should radiate energy and <b>spiral into the nucleus</b>."}],
"phy18-bohr-model": [
  {id:"phy18-bohr-model-c1", front:"State Bohr's postulate about electron orbits.", back:"Electrons revolve in certain <b>stable, discrete orbits</b> without radiating energy."},
  {id:"phy18-bohr-model-c2", front:"State Bohr's quantization condition for angular momentum.", back:"<b>L = nh/2π</b> (n = 1, 2, 3, …)."},
  {id:"phy18-bohr-model-c3", front:"State Bohr's postulate about emission/absorption of radiation.", back:"A photon is emitted/absorbed only when an electron jumps orbits: <b>hν = E(final) − E(initial)</b>."},
  {id:"phy18-bohr-model-c4", front:"What is the energy of the nth orbit of a hydrogen atom?", back:"<b>E(n) = −13.6/n² eV</b>."}
],
"phy18-hydrogen-spectrum": [
  {id:"phy18-hydrogen-spectrum-c1", front:"What produces the different spectral series of hydrogen?", back:"Electron <b>transitions between energy levels</b> — each series ends at a particular lower level."},
  {id:"phy18-hydrogen-spectrum-c2", front:"Which hydrogen spectral series lies in the visible region?", back:"The <b>Balmer series</b>."},
  {id:"phy18-hydrogen-spectrum-c3", front:"Which hydrogen spectral series has transitions ending at n=1?", back:"The <b>Lyman series</b> (ultraviolet)."}
,
  {id:"phy18-hydrogen-spectrum-c5", front:"Write the Rydberg formula for hydrogen spectral lines.", back:"1/λ = R(1/n₁² − 1/n₂²), where <b>R</b> is the Rydberg constant and n₁, n₂ are <b>energy level</b> integers."}],
"phy18-nuclear-structure": [
  {id:"phy18-nuclear-structure-c1", front:"What are the constituents of an atomic nucleus?", back:"<b>Protons and neutrons</b> (nucleons)."},
  {id:"phy18-nuclear-structure-c2", front:"What does mass number (A) represent?", back:"The total number of <b>nucleons</b> (protons + neutrons)."},
  {id:"phy18-nuclear-structure-c3", front:"What does atomic number (Z) represent?", back:"The number of <b>protons</b>."},
  {id:"phy18-nuclear-structure-c4", front:"What are isotopes?", back:"Atoms of the same element (same Z) with <b>different numbers of neutrons</b>."},
  {id:"phy18-nuclear-structure-c5", front:"What is the approximate formula for nuclear radius in terms of A?", back:"<b>R = R₀A^(1/3)</b> (R₀ ≈ 1.2 fm)."}
],
"phy18-binding-energy": [
  {id:"phy18-binding-energy-c1", front:"Define binding energy of a nucleus.", back:"Energy needed to <b>completely separate</b> a nucleus into individual protons and neutrons."},
  {id:"phy18-binding-energy-c2", front:"What does binding energy per nucleon indicate?", back:"The <b>stability</b> of a nucleus — higher means more stable."},
  {id:"phy18-binding-energy-c3", front:"Around which mass number is binding energy per nucleon maximum?", back:"<b>A ≈ 56</b> (iron region)."},
  {id:"phy18-binding-energy-c4", front:"Why does nuclear fusion release energy for light nuclei?", back:"Combining light nuclei <b>increases binding energy per nucleon</b>, releasing the difference."},
  {id:"phy18-binding-energy-c5", front:"Why does nuclear fission release energy for heavy nuclei?", back:"Splitting heavy nuclei <b>increases binding energy per nucleon</b>, releasing the difference."}
],
"phy18-radioactivity": [
  {id:"phy18-radioactivity-c1", front:"Define radioactivity.", back:"Spontaneous emission of radiation from an <b>unstable nucleus</b>."},
  {id:"phy18-radioactivity-c2", front:"What happens to mass number and atomic number in alpha decay?", back:"Mass number <b>−4</b>, atomic number <b>−2</b> (emits a helium nucleus)."},
  {id:"phy18-radioactivity-c3", front:"What happens to mass number and atomic number in beta-minus decay?", back:"Mass number <b>unchanged</b>, atomic number <b>+1</b> (a neutron becomes a proton)."},
  {id:"phy18-radioactivity-c4", front:"State the law of radioactive decay.", back:"<b>N = N₀e^(−λt)</b> — exponential decay."},
  {id:"phy18-radioactivity-c5", front:"Define half-life.", back:"The time for <b>half</b> of a radioactive sample to decay."}
],
"phy18-nuclear-reactions": [
  {id:"phy18-nuclear-reactions-c1", front:"What quantities are conserved in a nuclear reaction?", back:"<b>Mass number, atomic number, charge, momentum, and total mass-energy</b>."},
  {id:"phy18-nuclear-reactions-c2", front:"Define the Q-value of a nuclear reaction.", back:"Energy released/absorbed: <b>Q = (mass of reactants − mass of products) × c²</b>."},
  {id:"phy18-nuclear-reactions-c3", front:"Distinguish nuclear fission from fusion.", back:"<b>Fission</b>: a heavy nucleus splits. <b>Fusion</b>: light nuclei combine."}
,
  {id:"phy18-nuclear-reactions-c5", front:"What is the difference between nuclear fission and fusion?", back:"<b>Fission</b> splits a heavy nucleus into lighter nuclei releasing energy; <b>fusion</b> combines light nuclei into a heavier one, releasing even more energy per unit mass but requiring extremely high temperature and pressure."}],
"phy19-semiconductors": [
  {id:"phy19-semiconductors-c1", front:"Distinguish conductors, semiconductors, and insulators by band gap.", back:"<b>Conductors</b>: no/overlapping gap. <b>Semiconductors</b>: small gap (~1 eV). <b>Insulators</b>: large gap (>3 eV)."},
  {id:"phy19-semiconductors-c2", front:"Distinguish intrinsic from extrinsic semiconductors.", back:"<b>Intrinsic</b>: pure. <b>Extrinsic</b>: doped with impurities to raise conductivity."},
  {id:"phy19-semiconductors-c3", front:"What is an n-type semiconductor?", back:"Doped with a <b>pentavalent</b> impurity — excess electrons are the majority carriers."},
  {id:"phy19-semiconductors-c4", front:"What is a p-type semiconductor?", back:"Doped with a <b>trivalent</b> impurity — excess holes are the majority carriers."}
],
"phy19-pn-junction": [
  {id:"phy19-pn-junction-c1", front:"What forms at a p-n junction?", back:"A <b>depletion region</b> — depleted of free carriers, with an internal electric field."},
  {id:"phy19-pn-junction-c2", front:"What is the approximate barrier potential of a silicon p-n junction?", back:"<b>≈0.7 V</b>."},
  {id:"phy19-pn-junction-c3", front:"What happens to the depletion region under forward vs reverse bias?", back:"<b>Forward bias</b>: narrows. <b>Reverse bias</b>: widens."}
,
  {id:"phy19-pn-junction-c5", front:"What causes the depletion region to form at a p-n junction?", back:"Diffusion of majority carriers (electrons from n-side, holes from p-side) across the junction leaves behind immobile <b>ionized dopant atoms</b>, creating a region depleted of free charge carriers and an internal <b>electric field/potential barrier</b>."}],
"phy19-diode-rectifier": [
  {id:"phy19-diode-rectifier-c1", front:"What is a diode's basic function?", back:"Allows current <b>one way</b> (forward bias), blocks it the other way (reverse bias)."},
  {id:"phy19-diode-rectifier-c2", front:"What is a half-wave rectifier?", back:"A circuit using <b>one diode</b> to pass only half of each AC cycle."},
  {id:"phy19-diode-rectifier-c3", front:"What is a full-wave rectifier?", back:"A circuit converting <b>both halves</b> of the AC cycle into DC output."}
,
  {id:"phy19-diode-rectifier-c5", front:"Why is a p-n junction diode used as a rectifier?", back:"It conducts current only when <b>forward biased</b> (low resistance) and blocks current when <b>reverse biased</b> (high resistance), converting AC into pulsating DC."}],
"phy19-special-diodes": [
  {id:"phy19-special-diodes-c1", front:"What does an LED do?", back:"Emits <b>light</b> when forward biased, as electrons and holes recombine."},
  {id:"phy19-special-diodes-c2", front:"What does a photodiode do?", back:"Generates <b>current when light falls</b> on its junction (reverse biased) — detects light."},
  {id:"phy19-special-diodes-c3", front:"What does a solar cell do?", back:"Converts <b>light directly into electrical energy</b> via the photovoltaic effect, with no external bias."}
,
  {id:"phy19-special-diodes-c5", front:"How does a photodiode operate?", back:"It is operated in <b>reverse bias</b>; incident light generates electron-hole pairs near the junction, and the reverse saturation current increases <b>linearly with light intensity</b>, allowing light detection."}],
"phy19-zener-diode": [
  {id:"phy19-zener-diode-c1", front:"What is a Zener diode designed to do?", back:"Operate in <b>reverse breakdown at a fixed voltage</b>, for voltage regulation."},
  {id:"phy19-zener-diode-c2", front:"What is Zener breakdown?", back:"Breakdown at a heavily-doped junction where a strong field <b>pulls electrons directly out of covalent bonds</b>."}
,
  {id:"phy19-zener-diode-c5", front:"What is Zener breakdown?", back:"In a heavily doped p-n junction under reverse bias, a strong electric field breaks covalent bonds directly, producing a large current at a fixed <b>Zener voltage</b> without damaging the diode."},
  {id:"phy19-zener-diode-c6", front:"How does a Zener diode regulate voltage?", back:"Once reverse voltage reaches the <b>breakdown voltage</b>, the Zener diode maintains a nearly constant output voltage across it despite changes in input voltage or load current, by adjusting the current through itself."}],
"phy19-transistor": [
  {id:"phy19-transistor-c1", front:"Name the three terminals of a bipolar junction transistor.", back:"<b>Emitter, base, and collector</b>."},
  {id:"phy19-transistor-c2", front:"In active operation, how are the emitter-base and collector-base junctions biased?", back:"<b>Emitter-base</b>: forward biased. <b>Collector-base</b>: reverse biased."},
  {id:"phy19-transistor-c3", front:"What is a transistor's key amplifying property?", back:"A small change in <b>base current</b> produces a large change in collector current."}
,
  {id:"phy19-transistor-c5", front:"What biasing condition allows a transistor to work as an amplifier?", back:"The <b>emitter-base junction</b> is forward biased and the <b>collector-base junction</b> is reverse biased, so the transistor operates in the active region."}],
"phy19-logic-gates": [
  {id:"phy19-logic-gates-c1", front:"What does an AND gate output?", back:"<b>1</b> only when all inputs are 1."},
  {id:"phy19-logic-gates-c2", front:"What does an OR gate output?", back:"<b>1</b> if at least one input is 1."},
  {id:"phy19-logic-gates-c3", front:"What does a NOT gate (inverter) output?", back:"The <b>opposite</b> of its single input."},
  {id:"phy19-logic-gates-c4", front:"Which two gates are called \"universal gates\"?", back:"<b>NAND and NOR</b> — any gate can be built from either alone."}
],
"phy20-vernier-caliper": [
  {id:"phy20-vernier-caliper-c1", front:"What is a vernier caliper used to measure?", back:"Length, diameter, or depth of small objects, more precisely than a plain scale."},
  {id:"phy20-vernier-caliper-c2", front:"What is the formula for the least count of a vernier caliper?", back:"<b>LC = (1 main scale division) / (number of vernier divisions)</b>."},
  {id:"phy20-vernier-caliper-c3", front:"What is zero error, and how is it corrected?", back:"A non-zero reading with jaws fully closed; <b>subtracted (with sign) from every reading</b>."}
,
  {id:"phy20-vernier-caliper-c5", front:"How is the least count of a vernier caliper calculated?", back:"Least count = <b>1 main scale division − 1 vernier scale division</b>, typically 0.01 cm for a standard vernier caliper."}],
"phy20-Micrometer": [
  {id:"phy20-Micrometer-c1", front:"What is a screw gauge used to measure?", back:"Very small lengths (wire diameter, sheet thickness) more precisely than a vernier caliper."},
  {id:"phy20-Micrometer-c2", front:"What is the formula for the least count of a screw gauge?", back:"<b>LC = pitch / (number of circular scale divisions)</b>."},
  {id:"phy20-Micrometer-c3", front:"Define the pitch of a screw gauge.", back:"The distance the screw <b>advances per one full rotation</b>."}
,
  {id:"phy20-Micrometer-c5", front:"How is the least count of a screw gauge calculated?", back:"Least count = <b>pitch / number of divisions on circular scale</b>; e.g., pitch 1 mm with 100 divisions gives least count 0.01 mm."}],
"phy20-common-experiments": [
  {id:"phy20-common-experiments-c1", front:"Which has the smaller least count: a vernier caliper or a screw gauge?", back:"A <b>screw gauge</b> — typically finer than a vernier caliper."},
  {id:"phy20-common-experiments-c2", front:"What is backlash error in a screw gauge, and how is it avoided?", back:"Error from <b>thread slack</b>; avoided by always rotating the screw in the <b>same direction</b> while taking a reading."}
,
  {id:"phy20-common-experiments-c5", front:"What is the purpose of a meter bridge experiment?", back:"To determine an <b>unknown resistance</b> using the principle of a <b>Wheatstone bridge</b>, by finding the balancing (null-deflection) point on a uniform wire."},
  {id:"phy20-common-experiments-c6", front:"How is the focal length of a concave mirror found using the u-v method?", back:"By measuring object distance <b>u</b> and image distance <b>v</b> for a sharp image and applying the mirror formula <b>1/v + 1/u = 1/f</b>."}],
"ch1-atomic-theory": [
  {id:"ch1-atomic-theory-c1", front:"What are the three main sub-atomic particles?", back:"<b>Protons, neutrons, and electrons</b>."},
  {id:"ch1-atomic-theory-c2", front:"Define isotopes.", back:"Atoms of the same element (same protons) with <b>different numbers of neutrons</b>."},
  {id:"ch1-atomic-theory-c3", front:"Define atomic mass unit (u).", back:"<b>1/12th the mass</b> of a carbon-12 atom."},
  {id:"ch1-atomic-theory-c4", front:"What is average atomic mass?", back:"The <b>weighted average</b> of the masses of an element's naturally occurring isotopes."}
],
"ch1-mole-concept": [
  {id:"ch1-mole-concept-c1", front:"Define a mole.", back:"The amount of substance containing <b>Avogadro's number</b> of particles — as many as atoms in 12 g of carbon-12."},
  {id:"ch1-mole-concept-c2", front:"What is Avogadro's number?", back:"<b>6.022 × 10²³</b>."},
  {id:"ch1-mole-concept-c3", front:"What is the formula relating moles, mass, and molar mass?", back:"<b>n = mass / molar mass</b>."},
  {id:"ch1-mole-concept-c4", front:"What is the molar volume of an ideal gas at STP?", back:"<b>22.7 L/mol</b> at STP (273.15 K, 1 bar), per current NCERT convention — the older value 22.4 L/mol used 1 atm instead of 1 bar."}
],
"ch1-percentage-composition": [
  {id:"ch1-percentage-composition-c1", front:"Define empirical formula.", back:"The <b>simplest whole-number ratio</b> of atoms of each element in a compound."},
  {id:"ch1-percentage-composition-c2", front:"Define molecular formula.", back:"The <b>actual number</b> of atoms of each element in one molecule."},
  {id:"ch1-percentage-composition-c3", front:"How is molecular formula related to empirical formula?", back:"<b>Molecular formula = (empirical formula) × n</b>, n = molecular mass / empirical formula mass."}
,
  {id:"ch1-percentage-composition-c5", front:"What is percentage composition of a compound?", back:"The <b>percentage by mass</b> of each element in a compound, calculated as (mass of element in 1 mole of compound / molar mass) × <b>100</b>."}],
"ch1-stoichiometry": [
  {id:"ch1-stoichiometry-c1", front:"Define a limiting reagent.", back:"The reactant <b>completely consumed first</b>, limiting the amount of product formed."},
  {id:"ch1-stoichiometry-c2", front:"Define theoretical yield.", back:"The <b>maximum</b> product possible, from stoichiometric calculation."},
  {id:"ch1-stoichiometry-c3", front:"Define percentage yield.", back:"<b>(Actual yield / theoretical yield) × 100</b>."}
,
  {id:"ch1-stoichiometry-c5", front:"What does stoichiometry allow us to calculate in a chemical reaction?", back:"It allows calculation of the <b>quantitative relationships</b> between reactants and products using <b>balanced chemical equations</b> and mole ratios."}],
"ch1-concentration-terms": [
  {id:"ch1-concentration-terms-c1", front:"Define molarity.", back:"Moles of solute per <b>litre of solution</b> (mol/L)."},
  {id:"ch1-concentration-terms-c2", front:"Define molality.", back:"Moles of solute per <b>kilogram of solvent</b> (mol/kg)."},
  {id:"ch1-concentration-terms-c3", front:"Define mole fraction.", back:"Moles of a component divided by the <b>total moles</b> of the mixture."},
  {id:"ch1-concentration-terms-c4", front:"Does molarity change with temperature?", back:"<b>Yes</b> — volume changes with temperature; molality doesn't, since it's mass-based."}
],
"ch1-equivalent-concept": [
  {id:"ch1-equivalent-concept-c1", front:"Define equivalent weight.", back:"<b>Molar mass ÷ n-factor</b> (valency factor)."},
  {id:"ch1-equivalent-concept-c2", front:"Define normality.", back:"Gram-equivalents of solute per <b>litre of solution</b>."},
  {id:"ch1-equivalent-concept-c3", front:"State the law of chemical equivalence.", back:"In a reaction, the <b>equivalents of all reactants and products are equal</b>."}
,
  {id:"ch1-equivalent-concept-c5", front:"How is the equivalent weight of an acid calculated?", back:"Equivalent weight of an acid = <b>Molar mass</b> / <b>basicity</b> (number of replaceable H⁺ ions per molecule)."}],
"ch2-em-radiation": [
  {id:"ch2-em-radiation-c1", front:"What is the relation between a photon's energy and frequency?", back:"<b>E = hν</b>."},
  {id:"ch2-em-radiation-c2", front:"What is the relation between frequency, wavelength, and speed of light?", back:"<b>c = νλ</b>."},
  {id:"ch2-em-radiation-c3", front:"What is the approximate value of Planck's constant?", back:"<b>h ≈ 6.626 × 10⁻³⁴ J·s</b>."}
,
  {id:"ch2-em-radiation-c5", front:"How are frequency and wavelength of electromagnetic radiation related?", back:"c = <b>νλ</b>, where c is the speed of light (3×10⁸ m/s); frequency and wavelength are <b>inversely proportional</b>."}],
"ch2-photoelectric": [
  {id:"ch2-photoelectric-c1", front:"State Einstein's photoelectric equation.", back:"<b>hν = φ + KE(max)</b> (φ = work function)."},
  {id:"ch2-photoelectric-c2", front:"Define threshold frequency.", back:"The minimum frequency needed to <b>just eject an electron</b> (KE = 0)."}
,
  {id:"ch2-photoelectric-c5", front:"What is the work function in the photoelectric effect?", back:"It is the minimum energy (<b>W₀ = hν₀</b>) needed to eject an electron from a metal surface, where ν₀ is the <b>threshold frequency</b>."},
  {id:"ch2-photoelectric-c6", front:"How does increasing light intensity affect the photoelectric effect above threshold frequency?", back:"Increasing intensity increases the <b>number of photoelectrons</b> ejected per second but does not change their <b>maximum kinetic energy</b>, which depends only on frequency."}],
"ch2-bohr": [
  {id:"ch2-bohr-c1", front:"State Bohr's quantization condition for angular momentum.", back:"<b>mvr = nh/2π</b>."},
  {id:"ch2-bohr-c2", front:"What is the radius of the nth Bohr orbit in a hydrogen-like atom?", back:"<b>r(n) = 0.529 Å × (n²/Z)</b>."},
  {id:"ch2-bohr-c3", front:"What is the energy of the nth orbit in a hydrogen-like atom?", back:"<b>E(n) = −13.6 (Z²/n²) eV</b>."}
,
  {id:"ch2-bohr-c5", front:"What is the formula for the radius of the nth Bohr orbit?", back:"r_n = <b>0.529 × n²/Z</b> Å, where n is the principal quantum number and Z is the atomic number."}],
"ch2-hydrogen-spectrum": [
  {id:"ch2-hydrogen-spectrum-c1", front:"State the Rydberg formula for hydrogen spectral lines.", back:"<b>1/λ = R(1/n₁² − 1/n₂²)</b>."},
  {id:"ch2-hydrogen-spectrum-c2", front:"Which hydrogen series corresponds to transitions ending at n=1?", back:"<b>Lyman series</b> (UV)."},
  {id:"ch2-hydrogen-spectrum-c3", front:"Which hydrogen series corresponds to transitions ending at n=2?", back:"<b>Balmer series</b> (visible)."}
,
  {id:"ch2-hydrogen-spectrum-c5", front:"Which series of the hydrogen spectrum lies in the visible region?", back:"The <b>Balmer series</b>, corresponding to transitions from higher energy levels down to <b>n=2</b>."}],
"ch2-dual-nature": [
  {id:"ch2-dual-nature-c1", front:"State de Broglie's equation.", back:"<b>λ = h/mv</b>."},
  {id:"ch2-dual-nature-c2", front:"State Heisenberg's uncertainty principle.", back:"Position and momentum <b>can't both be known exactly</b> at once: Δx·Δp ≥ h/4π."}
,
  {id:"ch2-dual-nature-c5", front:"What is the de Broglie wavelength equation?", back:"λ = <b>h/mv</b>, relating a particle's wavelength to Planck's constant (h) and its momentum (mv), showing matter has wave-like properties."},
  {id:"ch2-dual-nature-c6", front:"What experiment confirmed the wave nature of electrons?", back:"The <b>Davisson-Germer experiment</b> showed electron diffraction patterns, confirming that electrons exhibit <b>wave-like behavior</b>."}],
"ch2-quantum-model": [
  {id:"ch2-quantum-model-c1", front:"Define an orbital.", back:"A 3D region around the nucleus where the <b>probability of finding an electron</b> is maximum."},
  {id:"ch2-quantum-model-c2", front:"What does the principal quantum number (n) determine?", back:"The <b>size and energy</b> of the shell."},
  {id:"ch2-quantum-model-c3", front:"What does the azimuthal quantum number (l) determine?", back:"The <b>shape</b> of the subshell."},
  {id:"ch2-quantum-model-c4", front:"What does the magnetic quantum number (m) determine?", back:"The <b>orientation</b> of the orbital in space."},
  {id:"ch2-quantum-model-c5", front:"What does the spin quantum number (s) represent?", back:"The <b>spin</b> of the electron (+½ or −½)."}
],
"ch2-orbital-shapes": [
  {id:"ch2-orbital-shapes-c1", front:"What is the shape of an s-orbital?", back:"<b>Spherical</b>."},
  {id:"ch2-orbital-shapes-c2", front:"What is the shape of a p-orbital?", back:"<b>Dumbbell-shaped</b> (two lobes)."},
  {id:"ch2-orbital-shapes-c3", front:"How many orbitals are in a d-subshell?", back:"<b>5</b>."}
,
  {id:"ch2-orbital-shapes-c5", front:"What is the shape of a p-orbital?", back:"A p-orbital has a <b>dumb-bell shape</b> with two lobes on either side of the nucleus separated by a <b>nodal plane</b> of zero electron density."}],
"ch2-electronic-config": [
  {id:"ch2-electronic-config-c1", front:"State the Pauli exclusion principle.", back:"No two electrons can share the <b>same set of all four</b> quantum numbers."},
  {id:"ch2-electronic-config-c2", front:"State Hund's rule of maximum multiplicity.", back:"Degenerate orbitals are filled <b>singly (parallel spin) before pairing</b>."},
  {id:"ch2-electronic-config-c3", front:"State the Aufbau principle.", back:"Orbitals fill in order of <b>increasing energy</b>."},
  {id:"ch2-electronic-config-c4", front:"Why do Cr and Cu show exceptional configurations?", back:"<b>Half-filled/fully-filled d-subshells</b> (d⁵, d¹⁰) are extra stable, pulling an electron from 4s."}
],
"ch3-periodic-law": [
  {id:"ch3-periodic-law-c1", front:"State the modern periodic law.", back:"Properties of elements are a <b>periodic function of atomic number</b>."},
  {id:"ch3-periodic-law-c2", front:"What determines which block (s, p, d, f) an element belongs to?", back:"The <b>subshell being filled last</b>."}
,
  {id:"ch3-periodic-law-c5", front:"State the Modern Periodic Law.", back:"Properties of elements are a <b>periodic function</b> of their <b>atomic number</b>, not atomic mass."},
  {id:"ch3-periodic-law-c6", front:"How does atomic radius vary across a period and down a group?", back:"Atomic radius generally <b>decreases across a period</b> (increasing nuclear charge) and <b>increases down a group</b> (additional electron shells)."}],
"ch3-periodic-trends": [
  {id:"ch3-periodic-trends-c1", front:"How does atomic radius vary across a period and down a group?", back:"<b>Decreases</b> across a period; <b>increases</b> down a group."},
  {id:"ch3-periodic-trends-c2", front:"How does ionization energy vary across a period and down a group?", back:"<b>Increases</b> across a period; <b>decreases</b> down a group."},
  {id:"ch3-periodic-trends-c3", front:"How does electronegativity vary across a period and down a group?", back:"<b>Increases</b> across a period; <b>decreases</b> down a group."},
  {id:"ch3-periodic-trends-c4", front:"Define electron gain enthalpy.", back:"The <b>energy change</b> when an electron is added to a neutral gaseous atom."}
],
"ch3-s-block": [
  {id:"ch3-s-block-c1", front:"Which groups make up the s-block?", back:"<b>Group 1 (alkali metals)</b> and <b>Group 2 (alkaline earth metals)</b>."},
  {id:"ch3-s-block-c2", front:"How does alkali metal reactivity change down the group?", back:"<b>Increases</b> down the group."},
  {id:"ch3-s-block-c3", front:"What flame colour does sodium give?", back:"<b>Yellow</b>."}
],
"ch3-p-block": [
  {id:"ch3-p-block-c1", front:"Which groups make up the p-block?", back:"<b>Groups 13 to 18</b>."},
  {id:"ch3-p-block-c2", front:"What is the inert pair effect?", back:"The reluctance of the <b>outermost s-electron pair</b> to take part in bonding, common in heavier p-block elements."},
  {id:"ch3-p-block-c3", front:"Why do first elements of p-block groups behave anomalously?", back:"Their <b>small size and no d-orbitals</b> for bonding, unlike heavier group members."}
,
  {id:"ch3-p-block-c5", front:"What is the general electronic configuration of p-block elements?", back:"ns² np^(1-6), where the last electron enters the <b>p-subshell</b> of the outermost shell."}],
"ch4-ionic": [
  {id:"ch4-ionic-c1", front:"Define lattice energy.", back:"Energy released when <b>gaseous ions combine</b> to form one mole of ionic solid."},
  {id:"ch4-ionic-c2", front:"What does Fajan's rule predict?", back:"When an ionic compound gains <b>more covalent character</b> — small, highly-charged cation and large, polarizable anion."},
  {id:"ch4-ionic-c3", front:"What is the Born-Haber cycle used for?", back:"Calculating <b>lattice energy indirectly</b> via other known thermodynamic quantities."}
,
  {id:"ch4-ionic-c5", front:"What factors favor the formation of an ionic bond?", back:"Low <b>ionization enthalpy</b> of the metal, high <b>electron gain enthalpy</b> of the nonmetal, and high <b>lattice enthalpy</b> of the resulting compound."}],
"ch4-covalent": [
  {id:"ch4-covalent-c1", front:"Define formal charge.", back:"The charge an atom would have if bonding electrons were <b>shared equally</b>."},
  {id:"ch4-covalent-c2", front:"What is resonance?", back:"A molecule's true structure is a <b>hybrid of two or more valid Lewis structures</b>."},
  {id:"ch4-covalent-c3", front:"What increases a molecule's dipole moment?", back:"Greater <b>electronegativity difference</b> and an <b>asymmetric</b> geometry."}
,
  {id:"ch4-covalent-c5", front:"What is a covalent bond?", back:"A chemical bond formed by the <b>mutual sharing of electron pairs</b> between two atoms to achieve a stable noble gas configuration."}],
"ch4-vsepr": [
  {id:"ch4-vsepr-c1", front:"What is the basic principle of VSEPR theory?", back:"Electron pairs around a central atom arrange to <b>minimize repulsion</b>, fixing molecular shape."},
  {id:"ch4-vsepr-c2", front:"What shape does 4 bonding pairs, 0 lone pairs give?", back:"<b>Tetrahedral</b>."},
  {id:"ch4-vsepr-c3", front:"What shape does 3 bonding pairs + 1 lone pair give?", back:"<b>Trigonal pyramidal</b> (e.g. NH₃)."},
  {id:"ch4-vsepr-c4", front:"What shape does 2 bonding pairs + 2 lone pairs give?", back:"<b>Bent/angular</b> (e.g. H₂O)."}
],
"ch4-hybridization": [
  {id:"ch4-hybridization-c1", front:"What geometry does sp³ hybridization give?", back:"<b>Tetrahedral</b>."},
  {id:"ch4-hybridization-c2", front:"What geometry does sp² hybridization give?", back:"<b>Trigonal planar</b>."},
  {id:"ch4-hybridization-c3", front:"What geometry does sp hybridization give?", back:"<b>Linear</b>."},
  {id:"ch4-hybridization-c4", front:"What hybridization does a trigonal bipyramidal (5 pair) centre have?", back:"<b>sp³d</b>."}
],
"ch4-mot": [
  {id:"ch4-mot-c1", front:"What is bond order in molecular orbital theory?", back:"<b>½(bonding electrons − antibonding electrons)</b>."},
  {id:"ch4-mot-c2", front:"Why is O₂ paramagnetic according to MOT?", back:"It has <b>two unpaired electrons</b> in its π* antibonding orbitals."}
,
  {id:"ch4-mot-c5", front:"What is bond order according to Molecular Orbital Theory?", back:"Bond order = <b>½(Nb − Na)</b>, where Nb is the number of bonding electrons and Na is the number of antibonding electrons."},
  {id:"ch4-mot-c6", front:"Why is the O2 molecule paramagnetic according to MOT?", back:"Because it has <b>two unpaired electrons</b> in its degenerate <b>π*2p antibonding orbitals</b>, which Lewis structures fail to explain."}],
"ch4-hbond": [
  {id:"ch4-hbond-c1", front:"Define hydrogen bonding.", back:"A weak attraction between H (bonded to N/O/F) and a <b>lone pair</b> on another electronegative atom."},
  {id:"ch4-hbond-c2", front:"Distinguish intermolecular from intramolecular hydrogen bonding.", back:"<b>Intermolecular</b>: between separate molecules. <b>Intramolecular</b>: within the same molecule."},
  {id:"ch4-hbond-c3", front:"Why does ice float on water?", back:"Hydrogen bonding gives ice an <b>open, less dense</b> crystal structure than liquid water."}
,
  {id:"ch4-hbond-c5", front:"What conditions are necessary for hydrogen bond formation?", back:"A hydrogen atom must be bonded to a small, highly <b>electronegative atom</b> (F, O, or N), creating a partial positive charge that attracts a lone pair on a nearby electronegative atom."}],
"ch5-first-law": [
  {id:"ch5-first-law-c1", front:"State the first law of thermodynamics.", back:"<b>ΔU = q + w</b>."},
  {id:"ch5-first-law-c2", front:"What is the sign convention for work done ON a system?", back:"<b>Positive</b> — it increases internal energy."}
,
  {id:"ch5-first-law-c5", front:"State the mathematical form of the First Law of Thermodynamics.", back:"ΔU = q + w, where ΔU is change in <b>internal energy</b>, q is <b>heat</b> absorbed, and w is <b>work</b> done on the system — energy is conserved."},
  {id:"ch5-first-law-c6", front:"What is internal energy a function of?", back:"Internal energy (U) is a <b>state function</b>, depending only on the initial and final states of the system, not the path taken."}],
"ch5-enthalpy": [
  {id:"ch5-enthalpy-c1", front:"Define enthalpy.", back:"<b>H = U + PV</b> — total heat content at constant pressure."},
  {id:"ch5-enthalpy-c2", front:"State Hess's law.", back:"Total enthalpy change for a reaction is the <b>same regardless of the path/steps</b> taken."},
  {id:"ch5-enthalpy-c3", front:"What is the relation between ΔH and ΔU at constant pressure?", back:"<b>ΔH = ΔU + Δn(g)RT</b>."}
,
  {id:"ch5-enthalpy-c5", front:"How is enthalpy (H) related to internal energy?", back:"H = U + <b>PV</b>, and at constant pressure, ΔH = ΔU + <b>PΔV</b>, representing heat exchanged at constant pressure."}],
"ch5-entropy": [
  {id:"ch5-entropy-c1", front:"Define entropy.", back:"A measure of a system's <b>disorder/randomness</b>."},
  {id:"ch5-entropy-c2", front:"State the second law of thermodynamics.", back:"The <b>entropy of the universe</b> always increases for a spontaneous process."}
,
  {id:"ch5-entropy-c5", front:"What does entropy measure?", back:"Entropy (S) measures the degree of <b>randomness or disorder</b> of a system; it is a <b>state function</b>."},
  {id:"ch5-entropy-c6", front:"State the Second Law of Thermodynamics.", back:"The <b>total entropy</b> of the system plus surroundings (universe) always <b>increases</b> in a spontaneous process."}],
"ch5-gibbs": [
  {id:"ch5-gibbs-c1", front:"State the Gibbs free energy equation.", back:"<b>ΔG = ΔH − TΔS</b>."},
  {id:"ch5-gibbs-c2", front:"For what value of ΔG is a process spontaneous?", back:"<b>ΔG < 0</b>."},
  {id:"ch5-gibbs-c3", front:"Which combination of ΔH and ΔS gives spontaneity at ALL temperatures?", back:"<b>ΔH negative and ΔS positive</b>."}
,
  {id:"ch5-gibbs-c5", front:"What is the Gibbs free energy criterion for spontaneity?", back:"ΔG = ΔH − TΔS; a process is spontaneous at constant temperature and pressure when <b>ΔG < 0</b>."}],
"ch5-thermochem": [
  {id:"ch5-thermochem-c1", front:"Define bond enthalpy.", back:"Energy required to break <b>one mole of a bond</b> in the gaseous state."},
  {id:"ch5-thermochem-c2", front:"What does calorimetry measure?", back:"The <b>heat absorbed or released</b> in a physical/chemical process."},
  {id:"ch5-thermochem-c3", front:"Define enthalpy of combustion.", back:"Enthalpy change when <b>one mole is completely burnt</b> in excess oxygen."}
,
  {id:"ch5-thermochem-c5", front:"What is Hess's Law of constant heat summation?", back:"The total <b>enthalpy change</b> for a reaction is the same whether it occurs in <b>one step or multiple steps</b>, since enthalpy is a state function."}],
"ch6-chemical-eq": [
  {id:"ch6-chemical-eq-c1", front:"State the law of mass action.", back:"Reaction rate is proportional to the <b>product of active masses</b> (concentrations) of reactants."},
  {id:"ch6-chemical-eq-c2", front:"Define the equilibrium constant Kc.", back:"Ratio of <b>product to reactant concentrations</b> (each to its stoichiometric power) at equilibrium."},
  {id:"ch6-chemical-eq-c3", front:"How does the reaction quotient Q compare to K to predict direction?", back:"<b>Q<K</b>: forward. <b>Q>K</b>: backward. <b>Q=K</b>: at equilibrium."},
  {id:"ch6-chemical-eq-c4", front:"What is the relation between Kp and Kc for a gas-phase reaction?", back:"<b>Kp = Kc(RT)^Δn</b>."}
],
"ch6-le-chatelier": [
  {id:"ch6-le-chatelier-c1", front:"State Le Chatelier's principle.", back:"A disturbed equilibrium <b>shifts to oppose</b> the disturbance."},
  {id:"ch6-le-chatelier-c2", front:"How does increasing pressure affect a gas equilibrium?", back:"Shifts toward the side with <b>fewer moles of gas</b>."},
  {id:"ch6-le-chatelier-c3", front:"How does a catalyst affect the position of equilibrium?", back:"<b>No effect</b> on position — it only speeds up reaching equilibrium."}
,
  {id:"ch6-le-chatelier-c5", front:"State Le Chatelier's Principle.", back:"If a system at equilibrium is subjected to a change in <b>concentration, pressure, or temperature</b>, the equilibrium shifts to <b>counteract</b> that change."}],
"ch6-ionic-eq": [
  {id:"ch6-ionic-eq-c1", front:"Define a strong electrolyte.", back:"Ionizes <b>almost completely</b> in solution."},
  {id:"ch6-ionic-eq-c2", front:"Define a weak electrolyte.", back:"Ionizes only <b>partially</b> in solution."},
  {id:"ch6-ionic-eq-c3", front:"State Ostwald's dilution law.", back:"Degree of dissociation of a weak electrolyte <b>increases on dilution</b>: α ≈ √(Ka/C)."}
,
  {id:"ch6-ionic-eq-c5", front:"What is the common ion effect?", back:"The <b>suppression of ionization</b> of a weak electrolyte when a strong electrolyte with a common ion is added to the solution, per Le Chatelier's principle."}],
"ch6-acids-bases": [
  {id:"ch6-acids-bases-c1", front:"Define an Arrhenius acid and base.", back:"<b>Acid</b>: releases H⁺ in water. <b>Base</b>: releases OH⁻ in water."},
  {id:"ch6-acids-bases-c2", front:"Define a Brønsted-Lowry acid and base.", back:"<b>Acid</b>: proton donor. <b>Base</b>: proton acceptor."},
  {id:"ch6-acids-bases-c3", front:"Define a Lewis acid and base.", back:"<b>Acid</b>: electron pair acceptor. <b>Base</b>: electron pair donor."},
  {id:"ch6-acids-bases-c4", front:"What is a conjugate acid-base pair?", back:"Two species differing by <b>a single proton</b> (e.g. NH₄⁺/NH₃)."}
],
"ch6-ph-buffer": [
  {id:"ch6-ph-buffer-c1", front:"Define pH.", back:"<b>pH = −log[H⁺]</b>."},
  {id:"ch6-ph-buffer-c2", front:"What is the relation between pH and pOH at 25°C?", back:"<b>pH + pOH = 14</b>."},
  {id:"ch6-ph-buffer-c3", front:"State the Henderson-Hasselbalch equation.", back:"<b>pH = pKa + log([salt]/[acid])</b>."},
  {id:"ch6-ph-buffer-c4", front:"What is a buffer solution?", back:"A solution that <b>resists pH change</b> on adding small amounts of acid or base."},
  {id:"ch6-ph-buffer-c5", front:"What is salt hydrolysis?", back:"A salt's ions <b>reacting with water</b>, giving an acidic or basic solution."}
],
"ch6-ksp": [
  {id:"ch6-ksp-c1", front:"Define solubility product (Ksp).", back:"The <b>equilibrium constant</b> for dissolution of a sparingly soluble ionic compound."},
  {id:"ch6-ksp-c2", front:"What is the common ion effect?", back:"<b>Decreased solubility</b> of a salt when a common ion is already present in solution."},
  {id:"ch6-ksp-c3", front:"What is the condition for precipitation to occur?", back:"The <b>ionic product exceeds Ksp</b>."}
,
  {id:"ch6-ksp-c5", front:"What does the solubility product (Ksp) indicate about precipitation?", back:"If the <b>ionic product</b> exceeds Ksp, precipitation occurs; if it is less than Ksp, the solution remains <b>unsaturated</b> with no precipitate."}],
"ch7-redox": [
  {id:"ch7-redox-c1", front:"Define oxidation (electron-transfer sense).", back:"<b>Loss of electrons</b> (oxidation number increases)."},
  {id:"ch7-redox-c2", front:"Define reduction (electron-transfer sense).", back:"<b>Gain of electrons</b> (oxidation number decreases)."},
  {id:"ch7-redox-c3", front:"What is an oxidizing agent?", back:"A substance that <b>gets reduced</b>, causing oxidation of another substance."},
  {id:"ch7-redox-c4", front:"What is a reducing agent?", back:"A substance that <b>gets oxidized</b>, causing reduction of another substance."}
],
"ch7-cells": [
  {id:"ch7-cells-c1", front:"What is a galvanic (voltaic) cell?", back:"Converts <b>chemical energy to electrical energy</b> via a spontaneous redox reaction."},
  {id:"ch7-cells-c2", front:"What is the purpose of a salt bridge?", back:"Maintains <b>electrical neutrality</b> by allowing ion flow between half-cells."},
  {id:"ch7-cells-c3", front:"What is the relation between ΔG and cell potential E?", back:"<b>ΔG = −nFE</b>."},
  {id:"ch7-cells-c4", front:"In a galvanic cell, which is the anode and which is the cathode?", back:"<b>Anode</b> = oxidation (negative). <b>Cathode</b> = reduction (positive)."}
],
"ch7-electrode-potential": [
  {id:"ch7-electrode-potential-c1", front:"What is the standard hydrogen electrode (SHE) potential defined as?", back:"<b>0 V</b> — the reference electrode."},
  {id:"ch7-electrode-potential-c2", front:"What does the electrochemical series rank?", back:"<b>Standard reduction potentials</b> of different half-cells."},
  {id:"ch7-electrode-potential-c3", front:"Is standard electrode potential (E°) intensive or extensive?", back:"<b>Intensive</b> — independent of the amount of substance."}
,
  {id:"ch7-electrode-potential-c5", front:"What is the standard hydrogen electrode (SHE) potential defined as?", back:"The SHE is assigned a standard reduction potential of exactly <b>0.00 V</b> and serves as the reference for all other <b>standard electrode potentials</b>."}],
"ch7-nernst": [
  {id:"ch7-nernst-c1", front:"State the Nernst equation (25°C, log form).", back:"<b>E = E° − (0.059/n)log Q</b>."},
  {id:"ch7-nernst-c2", front:"What is a concentration cell?", back:"A galvanic cell with the <b>same electrode material</b> but different ion concentrations in each half-cell."},
  {id:"ch7-nernst-c3", front:"At equilibrium, what is the cell potential E?", back:"<b>Zero</b>."}
,
  {id:"ch7-nernst-c5", front:"Write the Nernst equation for a general electrode reaction.", back:"E = E° − (<b>RT/nF</b>) ln Q, relating electrode potential to the standard potential and the <b>reaction quotient (Q)</b> at non-standard conditions."}],
"ch7-conductance": [
  {id:"ch7-conductance-c1", front:"Define molar conductivity.", back:"Conductivity of a solution <b>divided by molar concentration</b>."},
  {id:"ch7-conductance-c2", front:"State Kohlrausch's law of independent migration of ions.", back:"At infinite dilution, <b>each ion contributes independently</b> to total molar conductivity."},
  {id:"ch7-conductance-c3", front:"How does molar conductivity with dilution differ for strong vs weak electrolytes?", back:"Both increase, but a <b>weak electrolyte's rises much more sharply</b> (rising dissociation)."}
,
  {id:"ch7-conductance-c5", front:"State Kohlrausch's Law of independent migration of ions.", back:"At infinite dilution, the <b>molar conductivity</b> of an electrolyte equals the sum of the individual contributions of its <b>cation and anion</b>, each migrating independently."}],
"ch7-electrolysis": [
  {id:"ch7-electrolysis-c1", front:"Define electrolysis.", back:"Using <b>electrical energy</b> to drive a non-spontaneous redox reaction."},
  {id:"ch7-electrolysis-c2", front:"State Faraday's first law of electrolysis.", back:"Mass deposited is <b>directly proportional to the charge</b> passed."},
  {id:"ch7-electrolysis-c3", front:"State Faraday's second law of electrolysis.", back:"For the same charge, mass deposited is <b>proportional to equivalent weight</b>."}
,
  {id:"ch7-electrolysis-c5", front:"State Faraday's First Law of Electrolysis.", back:"The mass of substance deposited or liberated at an electrode is <b>directly proportional</b> to the quantity of <b>charge</b> passed through the electrolyte."}],
"ch7-batteries": [
  {id:"ch7-batteries-c1", front:"Distinguish a primary cell from a secondary cell.", back:"<b>Primary</b>: non-rechargeable. <b>Secondary</b>: rechargeable."},
  {id:"ch7-batteries-c2", front:"What is a fuel cell?", back:"Generates electricity from a <b>continuous supply of fuel and oxidant</b>, without recharging."}
,
  {id:"ch7-batteries-c5", front:"What is the electrolyte and electrode composition of a lead storage battery?", back:"It uses <b>sulfuric acid (H2SO4)</b> as electrolyte, with <b>Pb</b> as anode and <b>PbO2</b> as cathode, both converting to PbSO4 during discharge."},
  {id:"ch7-batteries-c6", front:"What distinguishes a fuel cell from a regular battery?", back:"A fuel cell continuously converts the <b>chemical energy of a fuel</b> (e.g., H2 and O2) directly into electrical energy, as long as reactants are supplied, without needing recharging."}],
"ch7-corrosion": [
  {id:"ch7-corrosion-c1", front:"Define corrosion.", back:"<b>Gradual electrochemical degradation</b> of a metal by its environment."},
  {id:"ch7-corrosion-c2", front:"What is the electrochemical mechanism of rusting?", back:"Iron acts as an <b>anode</b>; with moisture and oxygen present, an electrochemical cell forms on the surface."},
  {id:"ch7-corrosion-c3", front:"Name one method to prevent corrosion.", back:"<b>Galvanization</b> (zinc coating), painting, or a sacrificial anode."}
,
  {id:"ch7-corrosion-c5", front:"What is corrosion, using rusting of iron as an example?", back:"Corrosion is the <b>electrochemical oxidation</b> of metals by environmental agents (O2, moisture); rusting forms <b>hydrated iron(III) oxide (Fe2O3·xH2O)</b>."}],
"ch8-rate-of-reaction": [
  {id:"ch8-rate-of-reaction-c1", front:"Define average rate of a reaction.", back:"<b>Change in concentration ÷ time interval</b>."},
  {id:"ch8-rate-of-reaction-c2", front:"Define instantaneous rate of a reaction.", back:"The rate at one instant — the <b>slope</b> of the concentration-time curve there."}
,
  {id:"ch8-rate-of-reaction-c5", front:"How is the average rate of a reaction expressed?", back:"Average rate = <b>Δ[concentration]/Δt</b>, the change in concentration of a reactant or product over a time interval."},
  {id:"ch8-rate-of-reaction-c6", front:"What is the instantaneous rate of a reaction?", back:"The rate at a <b>particular moment</b>, obtained as the limit of the average rate as the time interval approaches <b>zero</b> (slope of the concentration-time curve)."}],
"ch8-rate-law": [
  {id:"ch8-rate-law-c1", front:"What is a rate law?", back:"An equation expressing rate in terms of <b>reactant concentrations raised to specific powers</b>."},
  {id:"ch8-rate-law-c2", front:"What determines the units of the rate constant k?", back:"The <b>overall order</b> of the reaction."}
,
  {id:"ch8-rate-law-c5", front:"What is a rate law?", back:"An experimentally determined expression relating the <b>rate of reaction</b> to the <b>concentrations of reactants</b> raised to appropriate powers, e.g. Rate = k[A]^m[B]^n."},
  {id:"ch8-rate-law-c6", front:"What does the rate constant (k) depend on?", back:"It depends on <b>temperature</b> and the nature of reactants/catalyst, but is <b>independent of concentration</b>."}],
"ch8-order-molecularity": [
  {id:"ch8-order-molecularity-c1", front:"Distinguish order of reaction from molecularity.", back:"<b>Order</b>: experimental, from the rate law (can be fractional/zero). <b>Molecularity</b>: theoretical, molecules colliding in one elementary step (always a whole number)."},
  {id:"ch8-order-molecularity-c2", front:"What is a pseudo-first-order reaction?", back:"A higher-order reaction that <b>behaves as first order</b> because one reactant is in large excess."},
  {id:"ch8-order-molecularity-c3", front:"What is a zero-order reaction?", back:"Rate is <b>independent of reactant concentration</b>."}
,
  {id:"ch8-order-molecularity-c5", front:"How does order of reaction differ from molecularity?", back:"<b>Order</b> is experimentally determined from the rate law and can be zero or fractional, while <b>molecularity</b> is the number of species colliding in an elementary step and is always a whole number."}],
"ch8-integrated-rate": [
  {id:"ch8-integrated-rate-c1", front:"What is the integrated rate equation for a first-order reaction?", back:"<b>ln[A] = ln[A]₀ − kt</b>."},
  {id:"ch8-integrated-rate-c2", front:"What is the integrated rate equation for a zero-order reaction?", back:"<b>[A] = [A]₀ − kt</b>."},
  {id:"ch8-integrated-rate-c3", front:"For a first-order reaction, which plot gives a straight line?", back:"<b>ln[A] vs time</b>."}
,
  {id:"ch8-integrated-rate-c5", front:"What is the integrated rate equation for a first-order reaction?", back:"k = (2.303/t) log([A]₀/[A]), showing that <b>k</b> has units of <b>time⁻¹</b> for first-order reactions."}],
"ch8-half-life": [
  {id:"ch8-half-life-c1", front:"Define half-life of a reaction.", back:"Time for a reactant's concentration to fall to <b>half</b> its initial value."},
  {id:"ch8-half-life-c2", front:"What is the half-life formula for a first-order reaction?", back:"<b>t(½) = 0.693/k</b> — independent of initial concentration."},
  {id:"ch8-half-life-c3", front:"Does zero-order half-life depend on initial concentration?", back:"<b>Yes</b> — t(½) = [A]₀/2k, directly proportional to it."}
,
  {id:"ch8-half-life-c5", front:"How does the half-life of a first-order reaction depend on initial concentration?", back:"The half-life t½ = <b>0.693/k</b> is independent of initial concentration, depending only on the <b>rate constant</b>."}],
"ch8-arrhenius": [
  {id:"ch8-arrhenius-c1", front:"State the Arrhenius equation.", back:"<b>k = Ae^(−Ea/RT)</b>."},
  {id:"ch8-arrhenius-c2", front:"Define activation energy.", back:"The <b>minimum energy</b> reactants need to react on collision."},
  {id:"ch8-arrhenius-c3", front:"How does increasing temperature affect the rate constant k?", back:"It <b>increases k</b>."}
,
  {id:"ch8-arrhenius-c5", front:"Write the Arrhenius equation and explain Ea.", back:"k = <b>Ae^(-Ea/RT)</b>, where Ea is the <b>activation energy</b>, the minimum extra energy needed for reactant molecules to react."}],
"ch8-factors": [
  {id:"ch8-factors-c1", front:"Name the main factors affecting reaction rate.", back:"<b>Concentration, temperature, surface area, catalyst</b>, and (for some) pressure or light."},
  {id:"ch8-factors-c2", front:"How does increasing temperature generally affect reaction rate?", back:"<b>Increases it</b> — more molecules exceed Ea, and collisions are more frequent."}
,
  {id:"ch8-factors-c5", front:"How does increasing temperature typically affect reaction rate?", back:"Rate generally increases because a greater fraction of molecules acquire energy exceeding the <b>activation energy</b>, per the <b>Arrhenius equation</b>."},
  {id:"ch8-factors-c6", front:"Why does increasing reactant concentration increase reaction rate?", back:"Higher concentration increases the <b>frequency of effective collisions</b> between reacting molecules per unit time."}],
"ch8-catalysis": [
  {id:"ch8-catalysis-c1", front:"Distinguish homogeneous from heterogeneous catalysis.", back:"<b>Homogeneous</b>: catalyst same phase as reactants. <b>Heterogeneous</b>: different phase."},
  {id:"ch8-catalysis-c2", front:"How does a catalyst increase reaction rate?", back:"By providing an <b>alternate pathway with lower activation energy</b>."},
  {id:"ch8-catalysis-c3", front:"What is shape-selective catalysis (e.g. in zeolites)?", back:"Catalysis where the catalyst's <b>pore shape/size restricts</b> which molecules can react."}
,
  {id:"ch8-catalysis-c5", front:"How does a catalyst increase reaction rate?", back:"A catalyst provides an <b>alternate pathway</b> with lower <b>activation energy</b>, without itself being consumed in the reaction."}],
"ch9-types-solutions": [
  {id:"ch9-types-solutions-c1", front:"State Henry's law.", back:"<b>p = K(H)·x</b> — partial pressure of a gas is proportional to its mole fraction in solution."},
  {id:"ch9-types-solutions-c2", front:"Does gas solubility in a liquid increase or decrease with temperature?", back:"<b>Decreases</b> with increasing temperature."}
,
  {id:"ch9-types-solutions-c5", front:"What are the possible types of solutions based on physical state?", back:"Solutions can form from combinations of <b>solid, liquid, and gas</b> solutes and solvents, e.g., solid-in-liquid (sugar in water), gas-in-liquid (soda)."},
  {id:"ch9-types-solutions-c6", front:"What does it mean for a solution to be saturated?", back:"A solution in which <b>no more solute can dissolve</b> at a given temperature, being in dynamic equilibrium with undissolved solute."}],
"ch9-concentration": [
  {id:"ch9-concentration-c1", front:"Define mass percentage.", back:"<b>(Mass of solute / mass of solution) × 100</b>."},
  {id:"ch9-concentration-c2", front:"Which stays temperature-independent — molality or molarity?", back:"<b>Molality</b> (mass-based); molarity is volume-based and varies with temperature."}
,
  {id:"ch9-concentration-c5", front:"Define molality and how it differs from molarity.", back:"Molality is <b>moles of solute per kg of solvent</b>, unlike molarity (moles per litre of solution); molality is <b>temperature-independent</b> since mass doesn't change with temperature."},
  {id:"ch9-concentration-c6", front:"What is mole fraction?", back:"Mole fraction = <b>moles of a component / total moles of all components</b> in solution; mole fractions of all components sum to <b>1</b>."}],
"ch9-raoults-law": [
  {id:"ch9-raoults-law-c1", front:"State Raoult's law for a solution of volatile liquids.", back:"<b>p(i) = x(i)·p°(i)</b> for each component."},
  {id:"ch9-raoults-law-c2", front:"What is an ideal solution?", back:"Obeys Raoult's law throughout, with <b>ΔH(mixing) = 0 and ΔV(mixing) = 0</b>."},
  {id:"ch9-raoults-law-c3", front:"What is an azeotrope?", back:"A mixture that boils at a <b>constant temperature/composition</b>, unable to be separated by simple distillation."}
,
  {id:"ch9-raoults-law-c5", front:"State Raoult's Law for a solution of volatile liquids.", back:"The <b>partial vapor pressure</b> of each component is proportional to its <b>mole fraction</b> in solution: p_i = x_i × p_i°."}],
"ch9-colligative": [
  {id:"ch9-colligative-c1", front:"What is the formula for boiling point elevation?", back:"<b>ΔTb = Kb·m</b>."},
  {id:"ch9-colligative-c2", front:"What is the formula for freezing point depression?", back:"<b>ΔTf = Kf·m</b>."},
  {id:"ch9-colligative-c3", front:"What causes colligative properties?", back:"Dissolved solute particles <b>lower the solvent's vapour pressure</b>, depending only on particle number."}
,
  {id:"ch9-colligative-c5", front:"What are colligative properties?", back:"Properties that depend only on the <b>number of solute particles</b> in solution, not their identity — e.g., relative lowering of vapor pressure, boiling point elevation, freezing point depression, and osmotic pressure."}],
"ch9-osmotic-pressure": [
  {id:"ch9-osmotic-pressure-c1", front:"Define osmosis.", back:"Spontaneous solvent flow through a <b>semipermeable membrane</b>, toward higher solute concentration."},
  {id:"ch9-osmotic-pressure-c2", front:"State the van't Hoff equation for osmotic pressure.", back:"<b>π = CRT</b>."},
  {id:"ch9-osmotic-pressure-c3", front:"What is reverse osmosis?", back:"Applying pressure <b>greater than osmotic pressure</b> to force solvent from concentrated to dilute solution."}
,
  {id:"ch9-osmotic-pressure-c5", front:"Write the van't Hoff equation for osmotic pressure of a dilute solution.", back:"π = <b>CRT</b>, where π is osmotic pressure, C is molar concentration, R is the gas constant, and T is temperature — analogous to the ideal gas equation."}],
"ch9-vant-hoff": [
  {id:"ch9-vant-hoff-c1", front:"What is the van't Hoff factor (i)?", back:"Ratio of the <b>observed</b> colligative property to the theoretically calculated value."},
  {id:"ch9-vant-hoff-c2", front:"What value of i indicates dissociation into ions?", back:"<b>i > 1</b>."},
  {id:"ch9-vant-hoff-c3", front:"What value of i indicates association (e.g. dimerization)?", back:"<b>i < 1</b>."}
,
  {id:"ch9-vant-hoff-c5", front:"What does the van't Hoff factor (i) indicate?", back:"It indicates the extent of <b>dissociation or association</b> of solute particles; i > 1 for dissociation (e.g., NaCl) and i < 1 for association (e.g., dimerization of acetic acid)."}],
"ch10-group13": [
  {id:"ch10-group13-c1", front:"Which two elements does Group 13 chemistry mainly focus on?", back:"<b>Boron and aluminium</b>."},
  {id:"ch10-group13-c2", front:"What is unusual about the bonding in diborane (B₂H₆)?", back:"It has <b>3-centre-2-electron (\"banana\") bonds</b>."},
  {id:"ch10-group13-c3", front:"What is the Hall-Héroult process used for?", back:"<b>Extracting aluminium</b> by electrolysis of alumina dissolved in molten cryolite (Na₃AlF₆)."}
],
"ch10-group14": [
  {id:"ch10-group14-c1", front:"Name the main allotropes of carbon.", back:"<b>Diamond, graphite, and fullerenes</b> (also graphene)."},
  {id:"ch10-group14-c2", front:"What structural feature makes silicates and silicones important?", back:"Repeating <b>Si-O-Si</b> networks/chains."}
],
"ch10-group15": [
  {id:"ch10-group15-c1", front:"What is the shape of the ammonia (NH₃) molecule?", back:"<b>Trigonal pyramidal</b>."},
  {id:"ch10-group15-c2", front:"What is nitric acid's key industrial preparation method?", back:"The <b>Ostwald process</b> (catalytic oxidation of ammonia)."},
  {id:"ch10-group15-c3", front:"Name an important oxoacid of phosphorus.", back:"<b>Phosphoric acid (H₃PO₄)</b>."}
,
  {id:"ch10-group15-c5", front:"Why does NH3 act as a stronger base than PH3?", back:"Because <b>N</b> is smaller and more electronegative than <b>P</b>, its lone pair is more available for donation, giving NH3 much greater <b>base strength</b>."}],
"ch10-group16": [
  {id:"ch10-group16-c1", front:"What is notable about ozone's structure?", back:"A <b>bent, resonance-stabilized</b> structure with equal O-O bond lengths."},
  {id:"ch10-group16-c2", front:"What is the Contact process used for?", back:"Industrial manufacture of <b>sulfuric acid</b> via catalytic oxidation of SO₂."}
,
  {id:"ch10-group16-c5", front:"Why do melting/boiling points of Group 16 elements not increase smoothly down the group?", back:"Although <b>van der Waals forces</b> strengthen with atomic size, differences in <b>allotropic structure</b> (e.g. S8 rings vs Se chains) cause irregular trends."},
  {id:"ch10-group16-c6", front:"What is the catenation tendency trend in Group 16?", back:"<b>Sulfur</b> shows the greatest tendency to catenate among Group 16 elements, forming chains and rings like <b>S8</b>, due to strong S–S bonds."}],
"ch10-group17": [
  {id:"ch10-group17-c1", front:"Does HX acidity increase or decrease down the group (HF to HI)?", back:"<b>Increases</b> — HI is the strongest."},
  {id:"ch10-group17-c2", front:"What is an interhalogen compound?", back:"A compound formed between <b>two different halogens</b> (e.g. ClF, IF₅)."}
,
  {id:"ch10-group17-c5", front:"Why is fluorine's electron gain enthalpy less negative than chlorine's?", back:"Fluorine's very <b>small atomic size</b> causes strong <b>electron-electron repulsion</b> in its compact 2p orbital, reducing the energy released on adding an electron."},
  {id:"ch10-group17-c6", front:"What is the oxidizing power trend among the halogens?", back:"Oxidizing power decreases down the group: <b>F2 > Cl2 > Br2 > I2</b>, with fluorine being the strongest oxidizing agent."}],
"ch10-group18": [
  {id:"ch10-group18-c1", front:"Why are noble gases generally unreactive?", back:"A <b>complete, stable outer shell</b> (octet)."},
  {id:"ch10-group18-c2", front:"Which noble gas is known to form stable compounds with fluorine?", back:"<b>Xenon</b> (e.g. XeF₂, XeF₄, XeF₆)."}
,
  {id:"ch10-group18-c5", front:"Why are noble gases chemically inert?", back:"They have a completely filled <b>ns2np6</b> valence configuration (1s2 for He), giving exceptional <b>stability</b> and little tendency to gain, lose, or share electrons."},
  {id:"ch10-group18-c6", front:"What was the first noble gas compound synthesized, and by whom?", back:"<b>XePtF6</b>, prepared by <b>Neil Bartlett</b> in 1962 by reacting xenon with platinum hexafluoride."}],
"ch10-oxoacids": [
  {id:"ch10-oxoacids-c1", front:"How does oxoacid strength vary with the number of oxygen atoms on the central atom?", back:"<b>Increases</b> with more oxygen atoms."},
  {id:"ch10-oxoacids-c2", front:"How does oxoacid strength vary with the electronegativity of the central atom?", back:"<b>Higher electronegativity increases acid strength</b>."}
,
  {id:"ch10-oxoacids-c5", front:"What structural feature is common to nearly all phosphorus oxoacids?", back:"They contain at least one <b>P=O bond</b> and one <b>P–OH bond</b>; any P–H bonds present are non-ionizable and do not contribute to acidity."},
  {id:"ch10-oxoacids-c6", front:"Name the oxoacids of chlorine in increasing order of oxidation state.", back:"<b>Hypochlorous acid (HOCl, +1)</b>, chlorous acid (+3), chloric acid (+5), and <b>perchloric acid (+7)</b>."}],
"ch11-transition-elements": [
  {id:"ch11-transition-elements-c1", front:"How are transition elements defined?", back:"Elements with a <b>partially filled d-orbital</b> in the ground state or common oxidation state."},
  {id:"ch11-transition-elements-c2", front:"Which block of the periodic table do transition elements belong to?", back:"The <b>d-block</b>."}
,
  {id:"ch11-transition-elements-c5", front:"Why do transition elements show variable oxidation states?", back:"Because both <b>(n-1)d</b> and <b>ns</b> electrons have comparable energies and can participate in bonding, allowing multiple oxidation states."},
  {id:"ch11-transition-elements-c6", front:"Why are transition metal ions often colored?", back:"Due to <b>d-d transitions</b>, where electrons absorb visible light to jump between crystal-field-split <b>d orbitals</b> in the presence of ligands."}],
"ch11-properties": [
  {id:"ch11-properties-c1", front:"Why do transition metals show variable oxidation states?", back:"Because the <b>(n-1)d and ns electrons</b> have similar energies and can both be involved in bonding."},
  {id:"ch11-properties-c2", front:"Why are transition metal compounds often colored?", back:"Due to <b>d-d electronic transitions</b> within the incompletely filled d-orbitals."},
  {id:"ch11-properties-c3", front:"Why do transition metals show catalytic activity?", back:"Due to their <b>variable oxidation states and ability to form intermediates</b>."},
  {id:"ch11-properties-c4", front:"Why do transition metals form many complex compounds?", back:"Due to their <b>small size, high charge, and availability of vacant d-orbitals</b> to accept electron pairs."},
  {id:"ch11-properties-c5", front:"Why do many transition metal ions show paramagnetism?", back:"Due to the presence of <b>unpaired electrons</b> in d-orbitals."}
],
"ch11-compounds": [
  {id:"ch11-compounds-c1", front:"What is the color and use of KMnO₄ as an oxidizing agent?", back:"<b>Potassium permanganate</b>, a strong oxidizing agent, purple in color."},
  {id:"ch11-compounds-c2", front:"What is the color and use of K₂Cr₂O₇ as an oxidizing agent?", back:"<b>Potassium dichromate</b>, a strong oxidizing agent, orange in color."}
,
  {id:"ch11-compounds-c5", front:"What is KMnO4 commonly used for?", back:"<b>Potassium permanganate</b> is a strong <b>oxidizing agent</b> used in volumetric (redox titration) analysis and water treatment."},
  {id:"ch11-compounds-c6", front:"What is the oxidation state of chromium in K2Cr2O7?", back:"Chromium is in the <b>+6</b> oxidation state in <b>potassium dichromate</b>, a strong oxidizing agent in acidic medium."}],
"ch11-lanthanoids": [
  {id:"ch11-lanthanoids-c1", front:"Which elements are called lanthanoids?", back:"The <b>14 elements from Ce to Lu</b> following lanthanum, with filling of the 4f orbital."},
  {id:"ch11-lanthanoids-c2", front:"What is the lanthanoid contraction?", back:"The <b>steady decrease in atomic/ionic radii</b> across the lanthanoid series due to poor shielding by 4f electrons."},
  {id:"ch11-lanthanoids-c3", front:"What is the common oxidation state of lanthanoids?", back:"<b>+3</b>."}
,
  {id:"ch11-lanthanoids-c5", front:"What is lanthanoid contraction and why does it occur?", back:"The steady decrease in atomic/ionic radii across the <b>lanthanoid series</b>, caused by poor shielding by <b>4f electrons</b>, which increases effective nuclear charge."}],
"ch11-actinoids": [
  {id:"ch11-actinoids-c1", front:"Which elements are called actinoids?", back:"The <b>14 elements from Th to Lr</b> following actinium, with filling of the 5f orbital."},
  {id:"ch11-actinoids-c2", front:"How do actinoids differ from lanthanoids in oxidation states?", back:"Actinoids show a <b>greater range of oxidation states</b> than lanthanoids."}
,
  {id:"ch11-actinoids-c5", front:"How do actinoids differ from lanthanoids in oxidation-state behavior?", back:"Actinoids show a much wider range of <b>oxidation states</b> (e.g. +3 to +7) than lanthanoids, due to comparable energies of <b>5f, 6d, and 7s</b> orbitals."},
  {id:"ch11-actinoids-c6", front:"Why are all actinoids radioactive?", back:"All actinoids have <b>unstable nuclei</b> due to their high atomic number and neutron-proton imbalance, making them naturally <b>radioactive</b>."}],
"ch12-werners-theory": [
  {id:"ch12-werners-theory-c1", front:"What is primary valency in Werner's theory?", back:"The <b>oxidation state</b> of the metal, satisfied by negative ions."},
  {id:"ch12-werners-theory-c2", front:"What is secondary valency in Werner's theory?", back:"The <b>coordination number</b>, satisfied by ligands directly bonded to the metal."}
,
  {id:"ch12-werners-theory-c5", front:"According to Werner's theory, what is the difference between primary and secondary valence?", back:"<b>Primary valence</b> corresponds to the metal's oxidation state (ionizable), while <b>secondary valence</b> corresponds to its coordination number (satisfied by ligands, non-ionizable)."},
  {id:"ch12-werners-theory-c6", front:"What did Werner propose about the spatial arrangement of secondary valences?", back:"Secondary valences point in fixed directions in space, giving definite <b>geometries</b> such as octahedral, tetrahedral, or square planar."}],
"ch12-nomenclature": [
  {id:"ch12-nomenclature-c1", front:"In naming a coordination compound, which is named first, the cation or anion?", back:"The <b>cation</b> is named first, then the anion."},
  {id:"ch12-nomenclature-c2", front:"In what order are ligands named within a complex ion?", back:"In <b>alphabetical order</b>, regardless of charge."},
  {id:"ch12-nomenclature-c3", front:"What suffix is used for a complex anion?", back:"<b>-ate</b> (e.g. ferrate)."}
,
  {id:"ch12-nomenclature-c5", front:"In IUPAC naming, in what order are ligands named within a complex ion?", back:"Ligands are named in <b>alphabetical order</b> regardless of charge or number, before naming the <b>central metal atom</b>."}],
"ch12-isomerism": [
  {id:"ch12-isomerism-c1", front:"What is geometrical isomerism in coordination compounds?", back:"Isomerism due to <b>different spatial arrangement of ligands</b> (e.g. cis/trans)."},
  {id:"ch12-isomerism-c2", front:"What is optical isomerism in coordination compounds?", back:"Isomerism where two forms are <b>non-superimposable mirror images</b> of each other."},
  {id:"ch12-isomerism-c3", front:"What is ionization isomerism?", back:"Isomers that give <b>different ions in solution</b> due to interchange of ligand and counter ion."}
,
  {id:"ch12-isomerism-c5", front:"What is ionization isomerism in coordination compounds?", back:"Isomers that give <b>different ions</b> in solution due to interchange of a ligand and the counter ion, e.g. [Co(NH3)5Br]SO4 vs [Co(NH3)5SO4]Br."}],
"ch12-bonding-theories": [
  {id:"ch12-bonding-theories-c1", front:"According to valence bond theory, what determines the geometry of a complex?", back:"The <b>type of hybridization</b> of the metal orbitals."},
  {id:"ch12-bonding-theories-c2", front:"What does crystal field theory treat ligands as?", back:"<b>Point charges</b> that create an electric field around the metal ion."}
,
  {id:"ch12-bonding-theories-c5", front:"According to Valence Bond Theory, which hybridizations give octahedral geometry?", back:"<b>d2sp3</b> (inner orbital complex) or <b>sp3d2</b> (outer orbital complex) hybridization gives an <b>octahedral</b> geometry."},
  {id:"ch12-bonding-theories-c6", front:"What distinguishes inner orbital and outer orbital complexes in VBT?", back:"<b>Inner orbital complexes</b> use (n-1)d orbitals and are typically low spin; <b>outer orbital complexes</b> use nd orbitals and are typically high spin."}],
"ch12-crystal-field-theory": [
  {id:"ch12-crystal-field-theory-c1", front:"What happens to d-orbitals in an octahedral crystal field?", back:"They split into <b>lower energy t2g and higher energy eg</b> sets."},
  {id:"ch12-crystal-field-theory-c2", front:"What is a strong field (low spin) ligand?", back:"A ligand causing <b>large splitting</b>, favoring electron pairing in lower orbitals (e.g. CN⁻, CO)."},
  {id:"ch12-crystal-field-theory-c3", front:"What is a weak field (high spin) ligand?", back:"A ligand causing <b>small splitting</b>, favoring maximum unpaired electrons (e.g. F⁻, Cl⁻)."},
  {id:"ch12-crystal-field-theory-c4", front:"What is crystal field splitting energy (Δ)?", back:"The <b>energy gap</b> between the split d-orbital sets."}
],
"ch12-stability": [
  {id:"ch12-stability-c1", front:"What does a higher stability constant of a complex indicate?", back:"<b>Greater stability</b> of the complex ion."},
  {id:"ch12-stability-c2", front:"What is the chelate effect?", back:"<b>Chelating ligands</b> (forming rings with the metal) give more stable complexes than similar non-chelating ligands."}
,
  {id:"ch12-stability-c5", front:"What is the chelate effect?", back:"Complexes with <b>chelating (polydentate) ligands</b> are more stable than analogous complexes with monodentate ligands, mainly due to favorable <b>entropy</b> effects."},
  {id:"ch12-stability-c6", front:"How is the stability constant (Kf) related to complex stability?", back:"A larger <b>stability constant (Kf)</b> indicates a more stable complex, reflecting a greater equilibrium tendency to form the complex over dissociated ions."}],
"ch12-applications": [
  {id:"ch12-applications-c1", front:"What role does a coordination compound play in chlorophyll?", back:"Chlorophyll is a <b>magnesium complex</b> essential for photosynthesis."},
  {id:"ch12-applications-c2", front:"What coordination compound is used in treating lead poisoning?", back:"<b>EDTA</b> (as a chelating agent)."}
,
  {id:"ch12-applications-c5", front:"How are coordination compounds used in the extraction of silver and gold?", back:"Ores are treated with <b>cyanide ion</b> to form soluble complexes like [Ag(CN)2]⁻ and [Au(CN)2]⁻, which are later reduced to the free metal."},
  {id:"ch12-applications-c6", front:"What role does EDTA play as a coordination compound in medicine?", back:"<b>EDTA</b>, a hexadentate ligand, treats <b>heavy metal poisoning</b> by chelating toxic metal ions like lead into stable, water-soluble complexes for excretion."}],
"ch13-hybridization": [
  {id:"ch13-hybridization-c1", front:"What hybridization does a carbon with four single bonds have?", back:"<b>sp³</b>."},
  {id:"ch13-hybridization-c2", front:"What hybridization does a carbon with a double bond have?", back:"<b>sp²</b>."},
  {id:"ch13-hybridization-c3", front:"What hybridization does a carbon with a triple bond have?", back:"<b>sp</b>."}
,
  {id:"ch13-hybridization-c5", front:"What hybridization does the carbon in a triple bond (alkyne) show?", back:"<b>sp hybridization</b>, giving a linear geometry with bond angle <b>180°</b> and two mutually perpendicular pi bonds."}],
"ch13-structural-isomerism": [
  {id:"ch13-structural-isomerism-c1", front:"What is chain isomerism?", back:"Isomers differing in the <b>arrangement of the carbon skeleton</b>."},
  {id:"ch13-structural-isomerism-c2", front:"What is position isomerism?", back:"Isomers differing in the <b>position of a substituent/functional group</b> on the same carbon skeleton."},
  {id:"ch13-structural-isomerism-c3", front:"What is functional isomerism?", back:"Isomers with the <b>same molecular formula but different functional groups</b>."},
  {id:"ch13-structural-isomerism-c4", front:"What is metamerism?", back:"Isomerism due to <b>different alkyl groups on either side of a functional group</b> (e.g. ethers, amines)."}
],
"ch13-stereoisomerism": [
  {id:"ch13-stereoisomerism-c1", front:"What is stereoisomerism?", back:"Isomers with the <b>same structural formula but different spatial arrangement</b> of atoms."},
  {id:"ch13-stereoisomerism-c2", front:"What causes geometrical (cis-trans) isomerism in alkenes?", back:"<b>Restricted rotation around the C=C double bond</b>."},
  {id:"ch13-stereoisomerism-c3", front:"What is required for a carbon to be a chiral center?", back:"It must be attached to <b>four different groups</b>."}
,
  {id:"ch13-stereoisomerism-c5", front:"What is the difference between geometrical and optical isomerism?", back:"<b>Geometrical isomerism</b> arises from restricted rotation (e.g. around C=C), while <b>optical isomerism</b> arises from a molecule's non-superimposable mirror images (<b>chirality</b>)."}],
"ch13-electronic-effects": [
  {id:"ch13-electronic-effects-c1", front:"What is the inductive effect?", back:"The <b>permanent displacement of sigma electrons</b> along a chain due to an electronegative/electropositive atom or group."},
  {id:"ch13-electronic-effects-c2", front:"What is the electromeric effect?", back:"A <b>temporary shift of pi electrons</b> in a multiple bond when attacked by a reagent."},
  {id:"ch13-electronic-effects-c3", front:"What is resonance in organic molecules?", back:"Delocalization of electrons represented by <b>two or more structures differing only in electron position</b>."}
,
  {id:"ch13-electronic-effects-c5", front:"What is the difference between the inductive and resonance effects?", back:"The <b>inductive effect</b> is permanent displacement of sigma electrons along a chain due to electronegativity, while the <b>resonance effect</b> is delocalization of pi electrons/lone pairs through conjugation."}],
"ch13-reactive-intermediates": [
  {id:"ch13-reactive-intermediates-c1", front:"What is a carbocation?", back:"A carbon species with a <b>positive charge and only six electrons</b> around it."},
  {id:"ch13-reactive-intermediates-c2", front:"What is the stability order of carbocations?", back:"<b>Tertiary > secondary > primary</b>."},
  {id:"ch13-reactive-intermediates-c3", front:"What is a carbanion?", back:"A carbon species with a <b>negative charge and a lone pair</b> of electrons."},
  {id:"ch13-reactive-intermediates-c4", front:"What is a free radical?", back:"A species with an <b>unpaired electron</b>, formed by homolytic bond cleavage."}
],
"ch13-reaction-types": [
  {id:"ch13-reaction-types-c1", front:"What is a substitution reaction?", back:"A reaction where <b>one atom/group is replaced by another</b>."},
  {id:"ch13-reaction-types-c2", front:"What is an addition reaction?", back:"A reaction where <b>atoms/groups add across a multiple bond</b>."},
  {id:"ch13-reaction-types-c3", front:"What is an elimination reaction?", back:"A reaction where <b>atoms/groups are removed to form a multiple bond</b>."}
,
  {id:"ch13-reaction-types-c5", front:"What is a nucleophilic substitution reaction?", back:"A reaction where a <b>nucleophile</b> replaces a leaving group on an electrophilic carbon, occurring via <b>SN1</b> or <b>SN2</b> mechanisms."}],
"ch14-alkanes": [
  {id:"ch14-alkanes-c1", front:"What is the general formula for alkanes?", back:"<b>CₙH₂ₙ₊₂</b>."},
  {id:"ch14-alkanes-c2", front:"What type of reaction do alkanes mainly undergo?", back:"<b>Free radical substitution</b> (e.g. halogenation)."},
  {id:"ch14-alkanes-c3", front:"What is Wurtz reaction used to prepare?", back:"It couples two alkyl halides with sodium to give a <b>higher alkane</b>."}
,
  {id:"ch14-alkanes-c5", front:"What is the general formula of alkanes and their characteristic reaction type?", back:"Alkanes have general formula <b>CnH2n+2</b> and undergo <b>free radical substitution</b> reactions such as halogenation, since they are saturated."}],
"ch14-alkenes": [
  {id:"ch14-alkenes-c1", front:"What is the general formula for alkenes?", back:"<b>CₙH₂ₙ</b>."},
  {id:"ch14-alkenes-c2", front:"What rule predicts the major product of HX addition to an unsymmetrical alkene?", back:"<b>Markovnikov's rule</b>: H adds to the carbon with more hydrogens already."},
  {id:"ch14-alkenes-c3", front:"What is the anti-Markovnikov addition of HBr called?", back:"The <b>Kharasch (peroxide) effect</b>."}
,
  {id:"ch14-alkenes-c5", front:"What is Markovnikov's rule?", back:"In addition of HX to an unsymmetrical alkene, <b>H</b> adds to the carbon already bearing more hydrogens, while <b>X</b> adds to the more substituted carbon."}],
"ch14-alkynes": [
  {id:"ch14-alkynes-c1", front:"What is the general formula for alkynes?", back:"<b>CₙH₂ₙ₋₂</b>."},
  {id:"ch14-alkynes-c2", front:"Why is terminal alkyne (like ethyne) slightly acidic?", back:"Its <b>sp-hybridized C-H bond</b> has more s-character, holding electrons closer to carbon."},
  {id:"ch14-alkynes-c3", front:"What test distinguishes terminal alkynes?", back:"They give a <b>precipitate with ammoniacal AgNO₃ or Cu₂Cl₂</b>."}
,
  {id:"ch14-alkynes-c5", front:"Why are terminal alkynes more acidic than alkanes or alkenes?", back:"Greater <b>s-character (50%)</b> in the sp hybrid orbital of the ≡C–H carbon holds bonding electrons closer, allowing terminal alkynes to form <b>acetylide salts</b> with strong bases."}],
"ch14-benzene": [
  {id:"ch14-benzene-c1", front:"What is the hybridization of carbon atoms in benzene?", back:"<b>sp²</b>, all carbons in one plane."},
  {id:"ch14-benzene-c2", front:"What type of reaction does benzene characteristically undergo?", back:"<b>Electrophilic substitution</b> (due to its stable delocalized pi system)."},
  {id:"ch14-benzene-c3", front:"What condition defines aromaticity (Hückel's rule)?", back:"A <b>planar, cyclic, fully conjugated</b> ring with <b>(4n+2) pi electrons</b>."}
,
  {id:"ch14-benzene-c5", front:"What explains benzene's extra stability compared to a hypothetical cyclohexatriene?", back:"Its six pi electrons are <b>delocalized</b> over the ring, described as a <b>resonance hybrid</b> of Kekulé structures, giving <b>resonance stabilization energy</b>."}],
"ch14-directive-effects": [
  {id:"ch14-directive-effects-c1", front:"Where do ortho/para-directing groups send an incoming electrophile on benzene?", back:"To the <b>ortho and para positions</b> (e.g. -OH, -NH₂, -CH₃, halogens)."},
  {id:"ch14-directive-effects-c2", front:"Where do meta-directing groups send an incoming electrophile on benzene?", back:"To the <b>meta position</b> (e.g. -NO₂, -CN, -COOH)."},
  {id:"ch14-directive-effects-c3", front:"Are halogens on benzene activating or deactivating, and o,p- or m-directing?", back:"<b>Deactivating but ortho/para-directing</b>."}
,
  {id:"ch14-directive-effects-c5", front:"What are ortho/para directing groups in electrophilic aromatic substitution?", back:"Electron-donating groups like <b>-OH, -NH2, -CH3</b> direct incoming electrophiles to the <b>ortho and para</b> positions by resonance-stabilizing the intermediate carbocation."}],
"ch15-alkyl-halides": [
  {id:"ch15-alkyl-halides-c1", front:"What is the general formula/structure of an alkyl halide?", back:"An alkane with <b>one hydrogen replaced by a halogen</b> (R-X)."},
  {id:"ch15-alkyl-halides-c2", front:"What common method converts an alcohol to an alkyl halide?", back:"Reaction with <b>HX, PX₃, or SOCl₂</b>."}
,
  {id:"ch15-alkyl-halides-c5", front:"What is the reactivity order of alkyl halides towards SN2 reactions?", back:"<b>Methyl > primary > secondary > tertiary</b> halides, due to decreasing accessibility of the carbon to nucleophilic attack (steric hindrance)."},
  {id:"ch15-alkyl-halides-c6", front:"How are alkyl halides commonly prepared from alcohols?", back:"By reaction with <b>HX</b>, <b>PCl5</b>, <b>PCl3</b>, or <b>SOCl2</b> (Darzen's process, preferred since it gives only gaseous byproducts)."}],
"ch15-sn1-sn2-reactions": [
  {id:"ch15-sn1-sn2-reactions-c1", front:"What is the mechanism/rate law of an SN1 reaction?", back:"<b>Two-step, via a carbocation</b>; rate depends only on substrate concentration."},
  {id:"ch15-sn1-sn2-reactions-c2", front:"What is the mechanism/rate law of an SN2 reaction?", back:"<b>One-step, backside attack</b>; rate depends on both substrate and nucleophile concentration."},
  {id:"ch15-sn1-sn2-reactions-c3", front:"Which substrate favors SN1: primary or tertiary alkyl halide?", back:"<b>Tertiary</b> (more stable carbocation)."},
  {id:"ch15-sn1-sn2-reactions-c4", front:"What stereochemical outcome does SN2 give at the reacting carbon?", back:"<b>Inversion of configuration</b> (Walden inversion)."}
],
"ch15-elimination-reactions": [
  {id:"ch15-elimination-reactions-c1", front:"What does an alkyl halide give on elimination with alcoholic KOH?", back:"An <b>alkene</b> (dehydrohalogenation)."},
  {id:"ch15-elimination-reactions-c2", front:"What is Saytzeff's rule?", back:"The <b>more substituted (more stable) alkene</b> is the major elimination product."},
  {id:"ch15-elimination-reactions-c3", front:"Alcoholic KOH favors elimination; what does aqueous KOH favor with an alkyl halide?", back:"<b>Substitution</b> (to give an alcohol)."}
,
  {id:"ch15-elimination-reactions-c5", front:"What is the key mechanistic difference between E1 and E2 reactions?", back:"<b>E1</b> proceeds via a <b>carbocation intermediate</b> in two steps (favored by tertiary substrates), while <b>E2</b> is a <b>concerted one-step</b> mechanism needing anti-periplanar geometry."}],
"ch15-haloarenes": [
  {id:"ch15-haloarenes-c1", front:"Why are haloarenes (aryl halides) less reactive to nucleophilic substitution than alkyl halides?", back:"The <b>C-X bond has partial double bond character</b> due to resonance with the ring, and is shorter/stronger."},
  {id:"ch15-haloarenes-c2", front:"What effect do halogens have on further electrophilic substitution of the benzene ring?", back:"They are <b>deactivating but ortho/para-directing</b>."}
,
  {id:"ch15-haloarenes-c5", front:"Why are haloarenes less reactive than haloalkanes towards nucleophilic substitution?", back:"The <b>C–X bond</b> gains partial <b>double bond character</b> from resonance with the ring, and the halogen lone pair is delocalized, strengthening and shortening the bond."},
  {id:"ch15-haloarenes-c6", front:"What is the product of the Wurtz-Fittig reaction?", back:"Coupling of an <b>aryl halide</b> and an <b>alkyl halide</b> with sodium metal in dry ether gives an <b>alkylbenzene</b>."}],
"ch15-polyhalogen-compounds": [
  {id:"ch15-polyhalogen-compounds-c1", front:"What is chloroform used for?", back:"Once used as an <b>anesthetic</b>; now mainly an industrial solvent."},
  {id:"ch15-polyhalogen-compounds-c2", front:"What is DDT?", back:"A <b>polyhalogen insecticide/pesticide</b> (dichlorodiphenyltrichloroethane)."},
  {id:"ch15-polyhalogen-compounds-c3", front:"Why are CFCs (freons) environmentally concerning?", back:"They cause <b>depletion of the ozone layer</b>."}
,
  {id:"ch15-polyhalogen-compounds-c5", front:"Why are CFCs (chlorofluorocarbons) environmentally harmful?", back:"CFCs are highly stable and drift to the <b>stratosphere</b>, where UV radiation releases <b>chlorine free radicals</b> that catalytically destroy the <b>ozone layer</b>."}],
"ch16-alcohols": [
  {id:"ch16-alcohols-c1", front:"What functional group defines an alcohol?", back:"The <b>-OH (hydroxyl) group</b> attached to an sp³ carbon."},
  {id:"ch16-alcohols-c2", front:"Why do alcohols have higher boiling points than alkanes of similar mass?", back:"Due to <b>intermolecular hydrogen bonding</b>."},
  {id:"ch16-alcohols-c3", front:"What test distinguishes primary, secondary, and tertiary alcohols?", back:"The <b>Lucas test</b> (HCl + ZnCl₂) — reaction speed increases 1° < 2° < 3°."}
,
  {id:"ch16-alcohols-c5", front:"How does the Lucas test distinguish primary, secondary, and tertiary alcohols?", back:"With <b>Lucas reagent</b> (conc. HCl + ZnCl2), <b>tertiary alcohols</b> give immediate turbidity, <b>secondary</b> react in a few minutes, and <b>primary</b> show no reaction at room temperature."}],
"ch16-phenols": [
  {id:"ch16-phenols-c1", front:"What functional group defines a phenol?", back:"An <b>-OH group directly attached to a benzene ring</b>."},
  {id:"ch16-phenols-c2", front:"Why is phenol more acidic than an alcohol?", back:"The <b>phenoxide ion is stabilized by resonance</b> with the ring."},
  {id:"ch16-phenols-c3", front:"What test is used to detect phenols?", back:"They give a <b>color with neutral FeCl₃</b>."}
,
  {id:"ch16-phenols-c5", front:"Why is phenol more acidic than an alcohol like ethanol?", back:"The <b>phenoxide ion</b> formed after loss of H⁺ is stabilized by <b>resonance delocalization</b> into the aromatic ring, unlike a simple alkoxide ion."}],
"ch16-ethers": [
  {id:"ch16-ethers-c1", front:"What functional group defines an ether?", back:"An <b>oxygen atom connected to two alkyl/aryl groups</b> (R-O-R')."},
  {id:"ch16-ethers-c2", front:"How are ethers generally prepared from alcohols?", back:"By the <b>Williamson synthesis</b> (alkyl halide + sodium alkoxide)."}
,
  {id:"ch16-ethers-c5", front:"How does the Williamson synthesis prepare ethers?", back:"An <b>alkyl halide</b> reacts with a <b>sodium alkoxide</b> via an <b>SN2</b> mechanism to form an ether and sodium halide."},
  {id:"ch16-ethers-c6", front:"What happens when ethers react with excess HI on heating?", back:"The ether cleaves via <b>SN1/SN2</b> mechanism to give an <b>alcohol</b> and an <b>alkyl iodide</b>; with excess HI, both fragments are converted to alkyl iodides."}],
"ch16-aldehydes-ketones": [
  {id:"ch16-aldehydes-ketones-c1", front:"What functional group defines an aldehyde?", back:"A <b>-CHO group</b> (carbonyl carbon bonded to at least one H)."},
  {id:"ch16-aldehydes-ketones-c2", front:"What functional group defines a ketone?", back:"A <b>carbonyl group bonded to two carbon atoms</b> (R-CO-R')."},
  {id:"ch16-aldehydes-ketones-c3", front:"What test distinguishes aldehydes from ketones using Tollens' reagent?", back:"Aldehydes give a <b>silver mirror</b>; ketones do not react."},
  {id:"ch16-aldehydes-ketones-c4", front:"What test distinguishes aldehydes from ketones using Fehling's solution?", back:"Aldehydes give a <b>brick-red precipitate</b> of Cu₂O; ketones do not react."}
],
"ch16-carboxylic-acids": [
  {id:"ch16-carboxylic-acids-c1", front:"What functional group defines a carboxylic acid?", back:"The <b>-COOH group</b>."},
  {id:"ch16-carboxylic-acids-c2", front:"Why are carboxylic acids more acidic than alcohols/phenols?", back:"The <b>carboxylate ion is stabilized by resonance</b> over two oxygens."}
,
  {id:"ch16-carboxylic-acids-c5", front:"Why are carboxylic acids more acidic than phenols and alcohols?", back:"The <b>carboxylate ion</b> is stabilized by resonance, with the negative charge delocalized equally over <b>two oxygen atoms</b>, making it more stable than a phenoxide ion."},
  {id:"ch16-carboxylic-acids-c6", front:"What is the Hell-Volhard-Zelinsky (HVZ) reaction?", back:"Carboxylic acids with an <b>alpha-hydrogen</b> react with <b>Cl2/Br2</b> in presence of red phosphorus to give <b>alpha-halogenated carboxylic acids</b>."}],
"ch17-amines-classification": [
  {id:"ch17-amines-classification-c1", front:"How are amines classified as 1°, 2°, or 3°?", back:"By the <b>number of alkyl/aryl groups on nitrogen</b> (one, two, or three)."}
,
  {id:"ch17-amines-classification-c5", front:"How are amines classified based on hydrogen atoms replaced on ammonia?", back:"As <b>primary (1°)</b>, <b>secondary (2°)</b>, or <b>tertiary (3°)</b> amines, depending on whether one, two, or three H atoms of NH3 are replaced by alkyl/aryl groups."},
  {id:"ch17-amines-classification-c6", front:"How does the Hinsberg test distinguish 1°, 2°, and 3° amines?", back:"With benzenesulfonyl chloride, <b>1° amines</b> form a salt soluble in alkali, <b>2° amines</b> form an insoluble precipitate, and <b>3° amines</b> do not react."},
  {id:"ch17-amines-classification-c7", front:"What is the structural difference between aliphatic and aromatic amines?", back:"In <b>aromatic amines</b> (e.g. aniline) the nitrogen lone pair conjugates with the benzene ring, while in <b>aliphatic amines</b> the lone pair stays localized on nitrogen."}],
"ch17-amines-preparation": [
  {id:"ch17-amines-preparation-c1", front:"What reaction converts an alkyl halide to an amine?", back:"<b>Ammonolysis</b> (reaction with ammonia)."},
  {id:"ch17-amines-preparation-c2", front:"What does Gabriel phthalimide synthesis produce?", back:"<b>Pure primary amines</b>, free from 2° and 3° amine contamination."}
,
  {id:"ch17-amines-preparation-c5", front:"How is aniline prepared by reduction of nitrobenzene?", back:"Nitrobenzene is reduced with <b>Sn/HCl</b> (or Fe/HCl, H2/Ni), then treated with <b>NaOH</b> to liberate free aniline."},
  {id:"ch17-amines-preparation-c6", front:"What is the Gabriel phthalimide synthesis used for?", back:"It prepares pure <b>primary amines</b> by reacting potassium phthalimide with an alkyl halide, followed by <b>hydrolysis</b>."}],
"ch17-amines-properties": [
  {id:"ch17-amines-properties-c1", front:"Why are amines basic in nature?", back:"The <b>lone pair on nitrogen</b> can accept a proton."},
  {id:"ch17-amines-properties-c2", front:"Why do amines have a characteristic fishy smell?", back:"This is a <b>general physical property</b> of most amines (used as a qualitative identifier)."}
,
  {id:"ch17-amines-properties-c5", front:"Why do amines have lower boiling points than alcohols of similar molecular mass?", back:"<b>N–H...N hydrogen bonding</b> in amines is weaker than <b>O–H...O hydrogen bonding</b> in alcohols, since nitrogen is less electronegative than oxygen."},
  {id:"ch17-amines-properties-c6", front:"What is the carbylamine reaction, and what does it test for?", back:"A primary amine reacts with <b>chloroform and alcoholic KOH</b> to form a foul-smelling <b>isocyanide (carbylamine)</b>, a specific test for primary amines."}],
"ch17-basicity-amines": [
  {id:"ch17-basicity-amines-c1", front:"Why is aniline (an aromatic amine) less basic than a simple alkyl amine?", back:"The <b>lone pair on nitrogen is delocalized into the ring</b>, making it less available."},
  {id:"ch17-basicity-amines-c2", front:"What effect does an electron-donating group on the ring have on aniline's basicity?", back:"It <b>increases</b> basicity."}
,
  {id:"ch17-basicity-amines-c5", front:"Why is aniline a much weaker base than methylamine?", back:"In aniline, the nitrogen <b>lone pair</b> is delocalized into the <b>benzene ring</b> by resonance, making it far less available for protonation than in methylamine."},
  {id:"ch17-basicity-amines-c6", front:"What factors determine amine basicity in aqueous solution?", back:"Basicity in water depends on a balance of <b>+I effect (electron donation)</b>, <b>steric hindrance</b>, and <b>solvation/H-bonding</b> of the resulting ammonium cation."}],
"ch17-diazonium-salts": [
  {id:"ch17-diazonium-salts-c1", front:"How are diazonium salts prepared?", back:"By treating a <b>primary aromatic amine with HNO₂ (NaNO₂/HCl) at 0-5°C</b> (diazotization)."},
  {id:"ch17-diazonium-salts-c2", front:"Why must diazonium salt preparation be carried out at low temperature?", back:"Because the <b>diazonium salt decomposes above 5°C</b>."}
,
  {id:"ch17-diazonium-salts-c5", front:"How are diazonium salts prepared?", back:"A <b>primary aromatic amine</b> is treated with <b>NaNO2/HCl</b> at <b>0–5°C</b> (diazotization) to form an arenediazonium salt."},
  {id:"ch17-diazonium-salts-c6", front:"What is the Sandmeyer reaction?", back:"A diazonium salt reacts with <b>Cu2Cl2/HCl</b> or <b>Cu2Br2/HBr</b> to replace the diazonium group with <b>Cl or Br</b>, used to synthesize aryl halides."}],
"ch17-coupling-reactions": [
  {id:"ch17-coupling-reactions-c1", front:"What is the azo coupling reaction used to make?", back:"<b>Azo dyes</b> (colored compounds with an -N=N- linkage)."}
,
  {id:"ch17-coupling-reactions-c5", front:"What is an azo coupling reaction?", back:"The reaction of a <b>diazonium salt</b> with an activated aromatic ring (like phenol or aniline) to form a colored <b>azo compound (–N=N–)</b>."},
  {id:"ch17-coupling-reactions-c6", front:"Why are azo compounds intensely colored?", back:"Extended <b>conjugation</b> between the <b>–N=N–</b> azo linkage and the aromatic rings allows absorption of visible light, making them useful as <b>dyes</b>."},
  {id:"ch17-coupling-reactions-c7", front:"At what position does azo coupling of a diazonium salt with phenol typically occur?", back:"Predominantly at the <b>para position</b> of phenol (ortho if para is blocked), since the –OH group activates those ring positions."}],
"ch18-carbohydrates": [
  {id:"ch18-carbohydrates-c1", front:"What is a monosaccharide?", back:"A <b>simple sugar that cannot be hydrolyzed further</b> (e.g. glucose, fructose)."},
  {id:"ch18-carbohydrates-c2", front:"What is glucose classified as based on its functional groups?", back:"An <b>aldohexose</b> (six-carbon sugar with an aldehyde group)."},
  {id:"ch18-carbohydrates-c3", front:"What is the difference between amylose and amylopectin in starch?", back:"<b>Amylose</b> is a linear chain; <b>amylopectin</b> is branched."}
,
  {id:"ch18-carbohydrates-c5", front:"What is the difference between a reducing and non-reducing sugar?", back:"A <b>reducing sugar</b> has a free aldehyde/ketone group that reduces Fehling's/Tollens' reagent (e.g. glucose); a <b>non-reducing sugar</b> like <b>sucrose</b> has no free anomeric OH available."}],
"ch18-proteins": [
  {id:"ch18-proteins-c1", front:"What monomer units make up proteins?", back:"<b>Amino acids</b>, linked by peptide bonds."},
  {id:"ch18-proteins-c2", front:"What is the primary structure of a protein?", back:"The <b>linear sequence of amino acids</b>."},
  {id:"ch18-proteins-c3", front:"What holds the secondary structure of a protein together?", back:"<b>Hydrogen bonds</b> (forming alpha helix or beta pleated sheet)."},
  {id:"ch18-proteins-c4", front:"What is denaturation of a protein?", back:"<b>Loss of secondary/tertiary structure</b> (and biological activity) due to heat, pH, etc., while the primary structure remains."}
],
"ch18-nucleic-acids": [
  {id:"ch18-nucleic-acids-c1", front:"What are the two types of nucleic acids?", back:"<b>DNA and RNA</b>."},
  {id:"ch18-nucleic-acids-c2", front:"What three components make up a nucleotide?", back:"A <b>nitrogenous base, a pentose sugar, and a phosphate group</b>."},
  {id:"ch18-nucleic-acids-c3", front:"What base pairs does DNA base-pairing follow?", back:"<b>Adenine-Thymine and Guanine-Cytosine</b>."}
,
  {id:"ch18-nucleic-acids-c5", front:"What are the base-pairing rules in DNA?", back:"<b>Adenine pairs with Thymine</b> (2 H-bonds) and <b>Guanine pairs with Cytosine</b> (3 H-bonds), per Watson-Crick base pairing."}],
"ch18-vitamins": [
  {id:"ch18-vitamins-c1", front:"What is the key difference between fat-soluble and water-soluble vitamins?", back:"<b>Fat-soluble</b> (A, D, E, K) are stored in the body; <b>water-soluble</b> (B, C) are mostly excreted, not stored."},
  {id:"ch18-vitamins-c2", front:"Deficiency of which vitamin causes scurvy?", back:"<b>Vitamin C</b>."}
,
  {id:"ch18-vitamins-c5", front:"What is the difference between fat-soluble and water-soluble vitamins?", back:"<b>Fat-soluble vitamins</b> (A, D, E, K) are stored in body fat, while <b>water-soluble vitamins</b> (B-complex, C) are not stored and must be consumed regularly."},
  {id:"ch18-vitamins-c6", front:"What disease results from vitamin C deficiency?", back:"<b>Scurvy</b>, marked by bleeding gums and poor wound healing, results from deficiency of <b>vitamin C (ascorbic acid)</b>."}],
"ch18-enzymes": [
  {id:"ch18-enzymes-c1", front:"What are enzymes made of?", back:"<b>Proteins</b> that act as biological catalysts."},
  {id:"ch18-enzymes-c2", front:"Why are enzymes highly specific to their substrate?", back:"Due to the <b>specific shape of their active site</b> (lock-and-key/induced fit)."}
,
  {id:"ch18-enzymes-c5", front:"What is the lock-and-key model of enzyme action?", back:"It proposes that an enzyme's <b>active site</b> has a specific shape fitting only a particular <b>substrate</b>, like a key fitting a lock, enabling catalysis."},
  {id:"ch18-enzymes-c6", front:"How does temperature affect enzyme activity?", back:"Activity increases with temperature up to an <b>optimum</b> (around 37°C in humans), beyond which the enzyme <b>denatures</b> and loses activity."}],
"ch19-qualitative-analysis": [
  {id:"ch19-qualitative-analysis-c1", front:"What does the Lassaigne's test detect?", back:"The presence of <b>nitrogen, sulphur, and halogens</b> in an organic compound."},
  {id:"ch19-qualitative-analysis-c2", front:"In Lassaigne's test, what does a blood-red color with FeCl₃ indicate?", back:"The presence of <b>both nitrogen and sulphur together</b> (ferric thiocyanate); nitrogen alone gives a <b>Prussian-blue</b> colour instead."}
,
  {id:"ch19-qualitative-analysis-c5", front:"What is the purpose of the dry heating test in salt analysis?", back:"It identifies volatile products or color changes (e.g., <b>NH3 gas</b>, <b>iodine vapors</b>) released on heating a salt, helping detect specific anions/cations before wet tests."},
  {id:"ch19-qualitative-analysis-c6", front:"Which reagent confirms the presence of chloride ion in salt analysis?", back:"Adding <b>AgNO3 solution</b> gives a <b>white precipitate</b> of AgCl that is soluble in ammonium hydroxide, confirming the chloride ion."}],
"ch19-volumetric-analysis": [
  {id:"ch19-volumetric-analysis-c1", front:"What is titration used to determine?", back:"The <b>unknown concentration of a solution</b> by reacting it with a solution of known concentration."},
  {id:"ch19-volumetric-analysis-c2", front:"What is an indicator used for in titration?", back:"To show the <b>end point</b> of the reaction by a color change."}
,
  {id:"ch19-volumetric-analysis-c5", front:"What is the equivalence point in a titration?", back:"It is the point at which moles of titrant added exactly react with moles of analyte present, i.e., stoichiometrically equal amounts of <b>acid</b> and <b>base</b> (or oxidant and reductant) have reacted."},
  {id:"ch19-volumetric-analysis-c6", front:"Which indicator is suitable for a strong acid–strong base titration and why?", back:"<b>Phenolphthalein</b> or <b>methyl orange</b> can be used since the pH changes sharply near pH 7, and both indicators change color within this steep region."}],
"ch20-chromatography": [
  {id:"ch20-chromatography-c1", front:"What is chromatography used for?", back:"<b>Separating components of a mixture</b> based on differential movement through a medium."},
  {id:"ch20-chromatography-c2", front:"What principle does column chromatography rely on?", back:"<b>Differential adsorption</b> of components on a stationary phase."}
,
  {id:"ch20-chromatography-c5", front:"What is the retardation factor (Rf) in TLC?", back:"Rf = distance traveled by <b>solute</b> / distance traveled by <b>solvent front</b>, used to identify and compare compounds on a TLC plate."},
  {id:"ch20-chromatography-c6", front:"On what principle does column chromatography separate compounds?", back:"It separates components based on differential <b>adsorption</b> onto a stationary phase (e.g., alumina/silica) as a <b>mobile phase (eluent)</b> passes through the column."}],
"ch20-crystallization": [
  {id:"ch20-crystallization-c1", front:"What is crystallization used for?", back:"<b>Purifying a solid</b> based on differences in solubility."}
,
  {id:"ch20-crystallization-c5", front:"What is the principle behind purification by crystallization?", back:"It relies on the difference in <b>solubility</b> of a compound and its impurities in a solvent at different <b>temperatures</b>, allowing pure crystals to separate on cooling a saturated solution."},
  {id:"ch20-crystallization-c6", front:"Why must the crystallization solvent dissolve the compound only on heating?", back:"So that on cooling, the solution becomes <b>supersaturated</b>, causing pure <b>crystals</b> to form while impurities remain in the <b>mother liquor</b>."},
  {id:"ch20-crystallization-c7", front:"What technique purifies compounds with very close solubilities?", back:"<b>Fractional crystallization</b>, which involves repeated crystallization steps to separate compounds of similar solubility based on small solubility differences."}],
"ch20-detection-elements": [
  {id:"ch20-detection-elements-c1", front:"How is carbon detected qualitatively in an organic compound?", back:"By heating with <b>CuO</b>; the CO₂ produced turns lime water milky."},
  {id:"ch20-detection-elements-c2", front:"How is hydrogen detected qualitatively in an organic compound?", back:"By heating with <b>CuO</b>; the water produced turns anhydrous CuSO₄ blue."}
,
  {id:"ch20-detection-elements-c5", front:"What is Lassaigne's test used for?", back:"It is a <b>sodium fusion</b> test that converts elements like nitrogen, sulfur, and halogens in an organic compound into <b>ionic (water-soluble)</b> forms (NaCN, Na2S, NaX) for detection."},
  {id:"ch20-detection-elements-c6", front:"How is nitrogen detected using the Lassaigne extract?", back:"The extract is boiled with <b>FeSO4</b>, then acidified with dilute H2SO4; a <b>Prussian blue</b> color confirms nitrogen via sodium ferrocyanide formation."}],
"ch20-distillation": [
  {id:"ch20-distillation-c1", front:"What does simple distillation separate?", back:"Liquids with <b>sufficiently different boiling points</b>."},
  {id:"ch20-distillation-c2", front:"When is steam distillation used?", back:"For <b>volatile substances immiscible with water</b> (e.g. essential oils)."},
  {id:"ch20-distillation-c3", front:"When is vacuum distillation used?", back:"For liquids that <b>decompose at their normal boiling point</b>."}
,
  {id:"ch20-distillation-c5", front:"When is steam distillation used?", back:"It purifies <b>volatile, water-immiscible, steam-volatile liquids</b> (e.g., essential oils) from non-volatile impurities at a temperature below their normal boiling point."}],
"math1-sets-basics": [
  {id:"math1-sets-basics-c1", front:"What is a set?", back:"A <b>well-defined collection of distinct objects</b>."},
  {id:"math1-sets-basics-c2", front:"What is the difference between roster form and set-builder form?", back:"<b>Roster form</b> lists all elements; <b>set-builder form</b> states a defining property."}
,
  {id:"math1-sets-basics-c5", front:"What is the roster (tabular) form of a set?", back:"Listing all elements of the set separated by commas within curly braces, e.g., <b>{1, 2, 3, 4}</b> for the set of first four natural numbers."},
  {id:"math1-sets-basics-c6", front:"What is the set-builder form of a set?", back:"Describing a set by a common property of its elements, e.g., <b>{x : x is a natural number and x < 5}</b>."}],
"math1-set-operations": [
  {id:"math1-set-operations-c1", front:"What is the union of two sets A and B?", back:"<b>A ∪ B</b>: all elements in A, in B, or in both."},
  {id:"math1-set-operations-c2", front:"What is the intersection of two sets A and B?", back:"<b>A ∩ B</b>: elements common to both A and B."},
  {id:"math1-set-operations-c3", front:"What is the difference A − B of two sets?", back:"Elements <b>in A but not in B</b>."}
,
  {id:"math1-set-operations-c5", front:"What is De Morgan's law for set complements?", back:"(A ∪ B)' = A' ∩ B' and (A ∩ B)' = A' ∪ B', i.e., <b>complement of union equals intersection of complements</b>, and vice versa."}],
"math1-relations-basics": [
  {id:"math1-relations-basics-c1", front:"What is the Cartesian product A × B?", back:"The set of <b>all ordered pairs (a, b)</b> with a ∈ A and b ∈ B."},
  {id:"math1-relations-basics-c2", front:"What is a relation from set A to set B?", back:"Any <b>subset of A × B</b>."}
,
  {id:"math1-relations-basics-c5", front:"What is a relation from set A to set B?", back:"A <b>subset of the Cartesian product A × B</b>, i.e., a set of ordered pairs (a,b) with a ∈ A, b ∈ B."},
  {id:"math1-relations-basics-c6", front:"What is the domain and range of a relation R from A to B?", back:"<b>Domain</b> = set of all first elements of ordered pairs in R; <b>Range</b> = set of all second elements of ordered pairs in R."}],
"math1-types-of-relations": [
  {id:"math1-types-of-relations-c1", front:"When is a relation R on set A called reflexive?", back:"When <b>(a, a) ∈ R for every a ∈ A</b>."},
  {id:"math1-types-of-relations-c2", front:"When is a relation R called symmetric?", back:"When <b>(a,b) ∈ R implies (b,a) ∈ R</b>."},
  {id:"math1-types-of-relations-c3", front:"When is a relation R called transitive?", back:"When <b>(a,b) ∈ R and (b,c) ∈ R implies (a,c) ∈ R</b>."}
,
  {id:"math1-types-of-relations-c5", front:"What makes a relation an equivalence relation?", back:"It must be <b>reflexive, symmetric, and transitive</b> simultaneously."}],
"math1-functions-basics": [
  {id:"math1-functions-basics-c1", front:"What is a function from set A to set B?", back:"A relation where <b>every element of A maps to exactly one element of B</b>."},
  {id:"math1-functions-basics-c2", front:"What is the domain of a function?", back:"The <b>set of all valid inputs</b> (values of x)."},
  {id:"math1-functions-basics-c3", front:"What is the range of a function?", back:"The <b>set of actual output values</b> the function takes."}
,
  {id:"math1-functions-basics-c5", front:"What condition must a relation satisfy to be called a function?", back:"Every element of the domain must map to <b>exactly one</b> element of the codomain (no element has two images)."}],
"math1-types-of-functions": [
  {id:"math1-types-of-functions-c1", front:"What is a one-one (injective) function?", back:"A function where <b>distinct inputs always give distinct outputs</b>."},
  {id:"math1-types-of-functions-c2", front:"What is an onto (surjective) function?", back:"A function where <b>every element of the codomain is the image of some element</b> of the domain."},
  {id:"math1-types-of-functions-c3", front:"What is a bijective function?", back:"A function that is <b>both one-one and onto</b>."}
,
  {id:"math1-types-of-functions-c5", front:"What is the difference between a one-one (injective) and onto (surjective) function?", back:"<b>One-one</b>: distinct inputs give distinct outputs; <b>onto</b>: every element of the codomain has a pre-image in the domain."}],
"math1-composition": [
  {id:"math1-composition-c1", front:"What is the composition (fog)(x) of two functions f and g?", back:"<b>f(g(x))</b> — apply g first, then f."},
  {id:"math1-composition-c2", front:"What does the identity function do?", back:"It <b>maps every element to itself</b>: f(x) = x."}
,
  {id:"math1-composition-c5", front:"How is the composition of functions (fog)(x) defined?", back:"<b>(fog)(x) = f(g(x))</b>, applying g first then f, defined when the range of g lies in the domain of f."},
  {id:"math1-composition-c6", front:"What is the condition for a function f to have an inverse f⁻¹?", back:"f must be <b>bijective</b> (one-one and onto); then f⁻¹of = fof⁻¹ = I (identity function)."}],
"math2-complex-basics": [
  {id:"math2-complex-basics-c1", front:"What is the value of i²?", back:"<b>i² = −1</b>."},
  {id:"math2-complex-basics-c2", front:"What is the standard form of a complex number?", back:"<b>a + bi</b>, where a is the real part and b is the imaginary part."}
,
  {id:"math2-complex-basics-c5", front:"How do you find the conjugate of a complex number z = a + ib?", back:"The conjugate is <b>z̄ = a - ib</b>, obtained by reversing the sign of the imaginary part."},
  {id:"math2-complex-basics-c6", front:"How do you divide two complex numbers z1/z2?", back:"Multiply numerator and denominator by the conjugate of z2: <b>z1/z2 = (z1·z̄2)/|z2|²</b>."}],
"math2-argand-diagram": [
  {id:"math2-argand-diagram-c1", front:"What is the Argand plane used for?", back:"<b>Representing a complex number a + bi as the point (a, b)</b> in a 2D plane."}
,
  {id:"math2-argand-diagram-c5", front:"How is a complex number z = a+ib represented on the Argand plane?", back:"As the point <b>(a, b)</b>, with the real part on the x-axis and imaginary part on the y-axis."},
  {id:"math2-argand-diagram-c6", front:"What does |z1 - z2| represent geometrically on the Argand plane?", back:"The <b>distance between the points</b> representing z1 and z2 in the plane."},
  {id:"math2-argand-diagram-c7", front:"What locus does |z - z0| = r represent on the Argand plane?", back:"A <b>circle</b> of radius r centered at the point z0."}],
"math2-modulus-argument": [
  {id:"math2-modulus-argument-c1", front:"What is the modulus of a complex number a + bi?", back:"<b>|z| = √(a² + b²)</b> — its distance from the origin."},
  {id:"math2-modulus-argument-c2", front:"What is the argument of a complex number?", back:"The <b>angle it makes with the positive real axis</b>."}
,
  {id:"math2-modulus-argument-c5", front:"What is the formula for the modulus of z = a + ib?", back:"<b>|z| = sqrt(a² + b²)</b>."},
  {id:"math2-modulus-argument-c6", front:"What is the polar form of a complex number z?", back:"<b>z = r(cos θ + i sin θ)</b>, where r = |z| is the modulus and θ = arg(z) is the argument."}],
"math2-de-moivres-theorem": [
  {id:"math2-de-moivres-theorem-c1", front:"What does De Moivre's theorem state?", back:"<b>(cosθ + i sinθ)ⁿ = cos(nθ) + i sin(nθ)</b> for integer n."}
,
  {id:"math2-de-moivres-theorem-c5", front:"State De Moivre's Theorem.", back:"For any integer n, <b>(cos θ + i sin θ)^n = cos(nθ) + i sin(nθ)</b>."},
  {id:"math2-de-moivres-theorem-c6", front:"How do you find the nth roots of a complex number using De Moivre's theorem?", back:"The n roots are <b>r^(1/n)[cos((θ+2kπ)/n) + i sin((θ+2kπ)/n)]</b> for k = 0,1,...,n-1."},
  {id:"math2-de-moivres-theorem-c7", front:"How is De Moivre's theorem used to expand cos 3θ in terms of cos θ?", back:"Using <b>(cos θ + i sin θ)^3 = cos 3θ + i sin 3θ</b> and comparing real parts gives cos 3θ = 4cos³θ - 3cos θ."}],
"math2-cube-roots-unity": [
  {id:"math2-cube-roots-unity-c1", front:"What equation defines the cube roots of unity?", back:"<b>x³ = 1</b>."},
  {id:"math2-cube-roots-unity-c2", front:"What is the sum of the three cube roots of unity (1, ω, ω²)?", back:"<b>0</b>."}
,
  {id:"math2-cube-roots-unity-c5", front:"What are the cube roots of unity?", back:"<b>1, ω, ω²</b>, where ω = (-1+i√3)/2, and each satisfies x³ = 1."},
  {id:"math2-cube-roots-unity-c6", front:"State the key property of ω used in JEE problems.", back:"<b>1 + ω + ω² = 0</b> and <b>ω³ = 1</b>."}],
"math2-quadratic-equations": [
  {id:"math2-quadratic-equations-c1", front:"What determines the nature of roots of a quadratic equation?", back:"The <b>discriminant, D = b² − 4ac</b>."},
  {id:"math2-quadratic-equations-c2", front:"What does a negative discriminant (D < 0) mean for the roots?", back:"The roots are <b>complex conjugates</b> (non-real)."}
,
  {id:"math2-quadratic-equations-c5", front:"When does a quadratic equation ax²+bx+c=0 (real coefficients) have complex roots?", back:"When the <b>discriminant D = b² - 4ac < 0</b>; the roots are then complex conjugates."},
  {id:"math2-quadratic-equations-c6", front:"What are the roots of ax²+bx+c=0 when D < 0?", back:"<b>x = (-b ± i√|D|)/(2a)</b>, a conjugate pair of complex numbers."}],
"math3-matrix-basics": [
  {id:"math3-matrix-basics-c1", front:"What is a matrix?", back:"A <b>rectangular arrangement of numbers</b> in rows and columns."},
  {id:"math3-matrix-basics-c2", front:"How is the order of a matrix described?", back:"As <b>m × n</b>, meaning m rows and n columns."}
,
  {id:"math3-matrix-basics-c5", front:"What is a symmetric matrix?", back:"A square matrix A such that <b>A = A^T</b> (transpose equals the matrix itself)."},
  {id:"math3-matrix-basics-c6", front:"What is a skew-symmetric matrix?", back:"A square matrix A such that <b>A^T = -A</b>; all diagonal elements must be zero."}],
"math3-matrix-algebra": [
  {id:"math3-matrix-algebra-c1", front:"What condition must hold to multiply matrix A by matrix B?", back:"The <b>number of columns of A must equal the number of rows of B</b>."},
  {id:"math3-matrix-algebra-c2", front:"Is matrix multiplication commutative in general (AB = BA)?", back:"<b>No</b>, matrix multiplication is generally not commutative."}
,
  {id:"math3-matrix-algebra-c5", front:"Under what condition can two matrices be multiplied?", back:"The <b>number of columns of the first matrix must equal the number of rows of the second</b>; product of (m×n) and (n×p) gives (m×p)."},
  {id:"math3-matrix-algebra-c6", front:"Is matrix multiplication commutative in general?", back:"<b>No</b>, in general AB ≠ BA, even when both products are defined."}],
"math3-determinants-evaluation": [
  {id:"math3-determinants-evaluation-c1", front:"What is the determinant of a 2×2 matrix [[a,b],[c,d]]?", back:"<b>ad − bc</b>."},
  {id:"math3-determinants-evaluation-c2", front:"How is the determinant of a 3×3 matrix evaluated?", back:"By <b>expansion along any row or column</b> using cofactors."}
,
  {id:"math3-determinants-evaluation-c5", front:"How do you evaluate the determinant of a 2x2 matrix [[a,b],[c,d]]?", back:"<b>det = ad - bc</b>."},
  {id:"math3-determinants-evaluation-c6", front:"How do you evaluate a 3x3 determinant by expansion along the first row?", back:"Expand as <b>a11·M11 - a12·M12 + a13·M13</b>, using cofactor expansion along that row."}],
"math3-minors-cofactors": [
  {id:"math3-minors-cofactors-c1", front:"What is the minor of an element in a matrix?", back:"The <b>determinant left after deleting that element's row and column</b>."},
  {id:"math3-minors-cofactors-c2", front:"What is the cofactor of an element?", back:"Its <b>minor multiplied by (−1)^(i+j)</b>, based on its position."}
,
  {id:"math3-minors-cofactors-c5", front:"What is the minor Mij of an element in a determinant?", back:"The <b>determinant of the submatrix</b> obtained by deleting the i-th row and j-th column."},
  {id:"math3-minors-cofactors-c6", front:"How is the cofactor Cij related to the minor Mij?", back:"<b>Cij = (-1)^(i+j) · Mij</b>."}],
"math3-adjoint-inverse": [
  {id:"math3-adjoint-inverse-c1", front:"What is the adjoint of a square matrix?", back:"The <b>transpose of its cofactor matrix</b>."},
  {id:"math3-adjoint-inverse-c2", front:"When does a square matrix have an inverse?", back:"When it is <b>non-singular</b> (determinant ≠ 0)."}
,
  {id:"math3-adjoint-inverse-c5", front:"How is the adjoint of a matrix A defined?", back:"adj(A) is the <b>transpose of the cofactor matrix</b> of A."},
  {id:"math3-adjoint-inverse-c6", front:"What is the formula for the inverse of a matrix A?", back:"<b>A⁻¹ = adj(A)/|A|</b>, provided |A| ≠ 0 (A is non-singular)."}],
"math3-linear-equations": [
  {id:"math3-linear-equations-c1", front:"What does Cramer's rule use to solve a linear system?", back:"<b>Ratios of determinants</b> formed from the coefficient and constant matrices."},
  {id:"math3-linear-equations-c2", front:"How does the matrix method solve AX = B?", back:"By computing <b>X = A⁻¹B</b>."}
,
  {id:"math3-linear-equations-c5", front:"State Cramer's Rule for solving a system of linear equations.", back:"For AX=B with |A|≠0, <b>xi = Di/D</b>, where D=|A| and Di is D with the i-th column replaced by B."},
  {id:"math3-linear-equations-c6", front:"How do you solve AX=B using the matrix inverse method?", back:"<b>X = A⁻¹B</b>, provided A is non-singular (|A| ≠ 0)."}],
"math3-properties-determinants": [
  {id:"math3-properties-determinants-c1", front:"What happens to a determinant's value if two rows are interchanged?", back:"Its <b>sign changes</b>."},
  {id:"math3-properties-determinants-c2", front:"What is the value of a determinant with two identical rows or columns?", back:"<b>Zero</b>."}
,
  {id:"math3-properties-determinants-c5", front:"What happens to a determinant's value if two rows (or columns) are identical?", back:"The determinant is <b>zero</b>."},
  {id:"math3-properties-determinants-c6", front:"What happens to a determinant if two rows (or columns) are interchanged?", back:"The <b>sign of the determinant changes</b> (its magnitude stays the same)."}],
"math4-fundamental-counting-principle": [
  {id:"math4-fundamental-counting-principle-c1", front:"What is the multiplication principle of counting?", back:"If one task can be done in m ways and another in n ways, both together can be done in <b>m × n</b> ways."},
  {id:"math4-fundamental-counting-principle-c2", front:"What is the addition principle of counting?", back:"If a task can be done in m ways OR n ways (not both), it can be done in <b>m + n</b> ways."}
,
  {id:"math4-fundamental-counting-principle-c5", front:"State the fundamental principle of counting (multiplication principle).", back:"If one task can be done in m ways and a second in n ways, both together can be done in <b>m × n</b> ways."},
  {id:"math4-fundamental-counting-principle-c6", front:"When do you use the addition principle instead of the multiplication principle?", back:"When events are <b>mutually exclusive alternatives</b> (either one or the other happens), add the number of ways: <b>m + n</b>."}],
"math4-permutations-basics": [
  {id:"math4-permutations-basics-c1", front:"What does nPr represent?", back:"The <b>number of ways to arrange r objects out of n</b> distinct objects, order matters."},
  {id:"math4-permutations-basics-c2", front:"What is the formula for nPr?", back:"<b>nPr = n!/(n−r)!</b>."}
,
  {id:"math4-permutations-basics-c5", front:"What is the formula for nPr?", back:"<b>nPr = n! / (n-r)!</b>, the number of arrangements of r items from n distinct items."},
  {id:"math4-permutations-basics-c6", front:"How many ways can n distinct objects be arranged in a row?", back:"<b>n!</b> ways (nPn = n!)."}],
"math4-permutations-with-repetition": [
  {id:"math4-permutations-with-repetition-c1", front:"How many arrangements of n objects are there if some objects are identical?", back:"<b>n!/(p!q!...)</b>, where p, q,... are the counts of each repeated type."}
,
  {id:"math4-permutations-with-repetition-c5", front:"How many arrangements are possible for n objects with repetitions allowed for r positions?", back:"<b>n^r</b>, since each of the r positions can independently be any of the n objects."},
  {id:"math4-permutations-with-repetition-c6", front:"How do you count permutations of n objects where some are identical (p, q, r of each kind)?", back:"<b>n! / (p! · q! · r!)</b>."},
  {id:"math4-permutations-with-repetition-c7", front:"How many distinct arrangements of the word 'MISSISSIPPI' are possible?", back:"Using <b>11!/(4!·4!·2!)</b> = 34650, accounting for repeated I's, S's, and P's."}],
"math4-circular-permutations": [
  {id:"math4-circular-permutations-c1", front:"How many ways can n distinct objects be arranged in a circle?", back:"<b>(n−1)!</b>."},
  {id:"math4-circular-permutations-c2", front:"How many circular arrangements are there if clockwise and anticlockwise are considered the same?", back:"<b>(n−1)!/2</b>."}
,
  {id:"math4-circular-permutations-c5", front:"How many ways can n distinct objects be arranged in a circle?", back:"<b>(n-1)!</b> ways, since rotations of the same arrangement are considered identical."},
  {id:"math4-circular-permutations-c6", front:"How does the count change for circular arrangements when clockwise and anticlockwise are considered the same (e.g., necklace)?", back:"<b>(n-1)!/2</b>, since each arrangement is counted twice (once for each direction)."}],
"math4-combinations-basics": [
  {id:"math4-combinations-basics-c1", front:"What does nCr represent?", back:"The <b>number of ways to choose r objects out of n</b>, order does not matter."},
  {id:"math4-combinations-basics-c2", front:"What is the formula for nCr?", back:"<b>nCr = n!/(r!(n−r)!)</b>."}
,
  {id:"math4-combinations-basics-c5", front:"What is the formula for nCr?", back:"<b>nCr = n! / [r!(n-r)!]</b>, the number of ways to select r items from n without regard to order."},
  {id:"math4-combinations-basics-c6", front:"State the relation between nCr and nC(n-r).", back:"<b>nCr = nC(n-r)</b>, choosing r items is equivalent to leaving out (n-r) items."}],
"math4-combinations-applications": [
  {id:"math4-combinations-applications-c1", front:"What is the relationship between nCr and nC(n−r)?", back:"<b>nCr = nC(n−r)</b>."}
,
  {id:"math4-combinations-applications-c5", front:"How many ways can a committee of r people be chosen from n people?", back:"<b>nCr</b> ways, since order of selection doesn't matter."},
  {id:"math4-combinations-applications-c6", front:"How do you count selections of r items from n that must include one particular item?", back:"Fix that item and choose the rest: <b>(n-1)C(r-1)</b> ways."},
  {id:"math4-combinations-applications-c7", front:"How many ways can n distinct items be distributed into groups of specified sizes r1, r2, ..., rk (r1+...+rk=n)?", back:"<b>n! / (r1! · r2! · ... · rk!)</b>."}],
"math4-derangements": [
  {id:"math4-derangements-c1", front:"What is a derangement?", back:"A <b>permutation where no element appears in its original position</b>."}
,
  {id:"math4-derangements-c5", front:"What is a derangement?", back:"A permutation of n objects in which <b>no object appears in its original (correct) position</b>."},
  {id:"math4-derangements-c6", front:"State the formula for the number of derangements D(n) of n objects.", back:"<b>D(n) = n! [1 - 1/1! + 1/2! - 1/3! + ... + (-1)^n/n!]</b>."},
  {id:"math4-derangements-c7", front:"What is the number of derangements of 4 objects?", back:"<b>D(4) = 9</b>, using D(4) = 4!(1 - 1 + 1/2 - 1/6 + 1/24) = 9."}],
"math5-binomial-expansion": [
  {id:"math5-binomial-expansion-c1", front:"What does the binomial theorem give the expansion of?", back:"<b>(x + y)ⁿ</b> as a sum of terms of the form nCr xⁿ⁻ʳyʳ."},
  {id:"math5-binomial-expansion-c2", front:"How many terms are in the expansion of (x + y)ⁿ?", back:"<b>(n + 1) terms</b>."}
,
  {id:"math5-binomial-expansion-c5", front:"State the Binomial Theorem for a positive integer n.", back:"For positive integer n, <b>(x+y)^n = sum_{r=0}^{n} nCr x^(n-r) y^r</b>, where nCr = n!/(r!(n-r)!)."},
  {id:"math5-binomial-expansion-c6", front:"How many terms are there in the expansion of (x+y)^n?", back:"<b>(n+1) terms</b>, since r ranges from 0 to n in the expansion."}],
"math5-general-term": [
  {id:"math5-general-term-c1", front:"What is the general term (Tᵣ₊₁) in the expansion of (x + y)ⁿ?", back:"<b>Tᵣ₊₁ = nCr xⁿ⁻ʳyʳ</b>."},
  {id:"math5-general-term-c2", front:"How many middle terms does (x + y)ⁿ have when n is odd?", back:"<b>Two middle terms</b>."}
,
  {id:"math5-general-term-c5", front:"What is the formula for the general term T(r+1) in the expansion of (x+y)^n?", back:"<b>T(r+1) = nCr x^(n-r) y^r</b>, giving the (r+1)th term of the expansion."},
  {id:"math5-general-term-c6", front:"How do you find the middle term(s) of (x+y)^n?", back:"If n is even, there is one middle term <b>T(n/2 + 1)</b>. If n is odd, there are two middle terms: <b>T((n+1)/2) and T((n+3)/2)</b>."}],
"math5-binomial-coefficients": [
  {id:"math5-binomial-coefficients-c1", front:"What is the symmetry property of binomial coefficients?", back:"<b>nCr = nC(n−r)</b>."},
  {id:"math5-binomial-coefficients-c2", front:"What is the sum of all binomial coefficients in the expansion of (1+x)ⁿ?", back:"<b>2ⁿ</b>."}
,
  {id:"math5-binomial-coefficients-c5", front:"What is the sum of all binomial coefficients in the expansion of (1+x)^n?", back:"Putting x=1 gives <b>nC0 + nC1 + ... + nCn = 2^n</b>."},
  {id:"math5-binomial-coefficients-c6", front:"What is the relation between nCr and nC(n-r)?", back:"<b>nCr = nC(n-r)</b>, since choosing r items is equivalent to leaving out (n-r) items."}],
"math5-applications": [
  {id:"math5-applications-c1", front:"What is the binomial approximation for (1+x)ⁿ when x is small?", back:"<b>(1+x)ⁿ ≈ 1 + nx</b>."}
,
  {id:"math5-applications-c5", front:"How is the Binomial Theorem used to approximate (1+x)^n for small x?", back:"For |x| << 1, <b>(1+x)^n ≈ 1 + nx</b>, ignoring higher powers of x."},
  {id:"math5-applications-c6", front:"Approximate (0.98)^5 using the binomial approximation.", back:"Write 0.98 = 1 - 0.02, so (1-0.02)^5 ≈ <b>1 - 5(0.02) = 0.9</b>."},
  {id:"math5-applications-c7", front:"Why does the binomial expansion give a quick estimate of sqrt(1+x) for small x?", back:"Since sqrt(1+x) = (1+x)^(1/2), using the first two terms of the binomial series gives <b>sqrt(1+x) ≈ 1 + x/2</b>."}],
"math5-multinomial-theorem": [
  {id:"math5-multinomial-theorem-c1", front:"What does the multinomial theorem generalize?", back:"The <b>binomial theorem, to expansions with more than two terms</b>, e.g. (x+y+z)ⁿ."}
,
  {id:"math5-multinomial-theorem-c5", front:"State the Multinomial Theorem for (x1+x2+...+xk)^n.", back:"<b>(x1+...+xk)^n = sum n!/(n1! n2! ... nk!) x1^n1 x2^n2 ... xk^nk</b>, summed over all non-negative n1+n2+...+nk = n."},
  {id:"math5-multinomial-theorem-c6", front:"How many distinct terms are there in the expansion of (x+y+z)^n?", back:"There are <b>(n+1)(n+2)/2</b> terms, corresponding to the number of non-negative integer solutions of a+b+c=n."},
  {id:"math5-multinomial-theorem-c7", front:"What is the coefficient of x^2 y z^2 in the expansion of (x+y+z)^5?", back:"Using the multinomial coefficient formula, the coefficient is <b>5!/(2!1!2!) = 30</b>."}],
"math6-AP": [
  {id:"math6-AP-c1", front:"What is the nth term of an arithmetic progression (AP)?", back:"<b>aₙ = a + (n−1)d</b>."},
  {id:"math6-AP-c2", front:"What is the sum of n terms of an AP?", back:"<b>Sₙ = n/2 [2a + (n−1)d]</b>."}
,
  {id:"math6-AP-c5", front:"What is the nth term formula for an Arithmetic Progression (AP)?", back:"<b>a_n = a + (n-1)d</b>, where a is the first term and d is the common difference."},
  {id:"math6-AP-c6", front:"What is the formula for the sum of the first n terms of an AP?", back:"<b>S_n = n/2 [2a + (n-1)d]</b>, which can also be written as n/2 (a + l), where l is the last term."}],
"math6-GP": [
  {id:"math6-GP-c1", front:"What is the nth term of a geometric progression (GP)?", back:"<b>aₙ = a·rⁿ⁻¹</b>."},
  {id:"math6-GP-c2", front:"What is the sum of n terms of a GP (r ≠ 1)?", back:"<b>Sₙ = a(rⁿ−1)/(r−1)</b>."}
,
  {id:"math6-GP-c5", front:"What is the nth term formula for a Geometric Progression (GP)?", back:"<b>a_n = a·r^(n-1)</b>, where a is the first term and r is the common ratio."},
  {id:"math6-GP-c6", front:"What is the sum of the first n terms of a GP (r ≠ 1)?", back:"<b>S_n = a(r^n - 1)/(r-1)</b>, equivalently a(1-r^n)/(1-r)."}],
"math6-HP": [
  {id:"math6-HP-c1", front:"What is a harmonic progression (HP)?", back:"A sequence whose <b>reciprocals form an arithmetic progression</b>."}
,
  {id:"math6-HP-c5", front:"What is a Harmonic Progression (HP)?", back:"A sequence whose reciprocals form an <b>Arithmetic Progression</b>, e.g. 1/a, 1/(a+d), 1/(a+2d), ..."},
  {id:"math6-HP-c6", front:"How do you find the nth term of an HP?", back:"Take reciprocals to form the corresponding AP, find its nth term a_n = a+(n-1)d, then the <b>nth term of the HP is 1/a_n</b>."},
  {id:"math6-HP-c7", front:"How do you find the Harmonic Mean (HM) of two positive numbers a and b?", back:"<b>HM = 2ab/(a+b)</b>, the reciprocal of the average of the reciprocals of a and b."}],
"math6-AGP": [
  {id:"math6-AGP-c1", front:"What is an arithmetico-geometric progression (AGP)?", back:"A sequence where <b>each term is the product of corresponding terms of an AP and a GP</b>."}
,
  {id:"math6-AGP-c5", front:"What is an Arithmetico-Geometric Progression (AGP)?", back:"A sequence formed by multiplying corresponding terms of an AP and a GP, e.g. <b>a, (a+d)r, (a+2d)r^2, ...</b>."},
  {id:"math6-AGP-c6", front:"What is the standard technique to sum an AGP?", back:"Multiply the sum S by the common ratio r, subtract term-by-term from S to get a <b>telescoping GP</b>, then solve the resulting equation for S."},
  {id:"math6-AGP-c7", front:"What is the sum to infinity of the AGP a, (a+d)r, (a+2d)r^2, ... for |r|<1?", back:"<b>S∞ = a/(1-r) + dr/(1-r)^2</b>."}],
"math6-am-gm-hm": [
  {id:"math6-am-gm-hm-c1", front:"What is the relationship among AM, GM, and HM of positive numbers?", back:"<b>AM ≥ GM ≥ HM</b>."}
,
  {id:"math6-am-gm-hm-c5", front:"State the AM-GM-HM inequality for positive real numbers.", back:"For positive reals, <b>AM ≥ GM ≥ HM</b>, with equality holding if and only if all the numbers are equal."},
  {id:"math6-am-gm-hm-c6", front:"What is the relation between the AM, GM, and HM of two positive numbers?", back:"<b>GM^2 = AM × HM</b>, i.e., GM is the geometric mean of the AM and HM."},
  {id:"math6-am-gm-hm-c7", front:"Using AM-GM, what is the minimum value of x + 1/x for x>0?", back:"By AM-GM, (x + 1/x)/2 ≥ sqrt(x · 1/x) = 1, so the <b>minimum value is 2</b>, attained at x=1."}],
"math6-infinite-gp": [
  {id:"math6-infinite-gp-c1", front:"When does an infinite GP converge (have a finite sum)?", back:"When <b>|r| < 1</b>."},
  {id:"math6-infinite-gp-c2", front:"What is the sum of an infinite GP with |r| < 1?", back:"<b>S = a/(1−r)</b>."}
,
  {id:"math6-infinite-gp-c5", front:"What is the condition for an infinite GP to have a finite (convergent) sum?", back:"The common ratio must satisfy <b>|r| < 1</b>."},
  {id:"math6-infinite-gp-c6", front:"What is the formula for the sum to infinity of a GP with first term a and ratio r (|r|<1)?", back:"<b>S∞ = a/(1-r)</b>."}],
"math6-method-differences": [
  {id:"math6-method-differences-c1", front:"What is the method of differences used for?", back:"<b>Finding the nth term/sum of a series</b> whose consecutive differences form a simpler known series."}
,
  {id:"math6-method-differences-c5", front:"When is the 'Method of Differences' used to sum a series?", back:"When the differences of successive terms of the series form an <b>AP or GP</b>, even though the original series is neither."},
  {id:"math6-method-differences-c6", front:"What is the core idea of the 'Vn method' for summing a series?", back:"Express the general term T_r as a difference <b>V_r - V_(r-1)</b> so that the sum telescopes to <b>ΣT_r = V_n - V_0</b>."},
  {id:"math6-method-differences-c7", front:"How is the series 1·2 + 2·3 + 3·4 + ... + n(n+1) summed using the Vn method?", back:"With T_r = r(r+1), take V_r = r(r+1)(r+2)/3 so T_r = V_r - V_(r-1); telescoping gives <b>S_n = n(n+1)(n+2)/3</b>."}],
"math6-special-series": [
  {id:"math6-special-series-c1", front:"What is the sum of the first n natural numbers?", back:"<b>n(n+1)/2</b>."},
  {id:"math6-special-series-c2", front:"What is the sum of the squares of the first n natural numbers?", back:"<b>n(n+1)(2n+1)/6</b>."}
,
  {id:"math6-special-series-c5", front:"What is the formula for the sum of squares of the first n natural numbers?", back:"<b>Σr^2 = n(n+1)(2n+1)/6</b>."},
  {id:"math6-special-series-c6", front:"What is the formula for the sum of cubes of the first n natural numbers?", back:"<b>Σr^3 = [n(n+1)/2]^2</b>, the square of the sum of the first n natural numbers."}],
"math7-limits-basics": [
  {id:"math7-limits-basics-c1", front:"When does the limit of a function at a point exist?", back:"When the <b>left-hand limit equals the right-hand limit</b>."},
  {id:"math7-limits-basics-c2", front:"What are the left-hand and right-hand limits?", back:"The value the function approaches from the <b>left (x→a⁻) and from the right (x→a⁺)</b>."}
,
  {id:"math7-limits-basics-c5", front:"What does it mean for lim(x→a) f(x) = L?", back:"As x approaches a from either side (without x ever equaling a), <b>f(x) gets arbitrarily close to L</b>; both the left-hand and right-hand limits equal L."},
  {id:"math7-limits-basics-c6", front:"When does the limit lim(x→a) f(x) fail to exist?", back:"When the <b>left-hand limit is not equal to the right-hand limit</b>, or f(x) is unbounded or oscillates near x=a."}],
"math7-standard-limits": [
  {id:"math7-standard-limits-c1", front:"What is the value of lim(x→0) sinx/x?", back:"<b>1</b>."},
  {id:"math7-standard-limits-c2", front:"What is the value of lim(x→0) (eˣ−1)/x?", back:"<b>1</b>."}
,
  {id:"math7-standard-limits-c5", front:"What is the standard limit lim(x→0) sin(x)/x?", back:"<b>lim(x→0) sin(x)/x = 1</b> (x measured in radians)."},
  {id:"math7-standard-limits-c6", front:"State L'Hopital's Rule.", back:"If lim f(x)/g(x) gives the 0/0 or ∞/∞ indeterminate form, then <b>lim f(x)/g(x) = lim f'(x)/g'(x)</b>, provided the right-hand limit exists."}],
"math7-continuity": [
  {id:"math7-continuity-c1", front:"What three conditions must hold for a function to be continuous at x = a?", back:"<b>f(a) is defined, the limit exists at a, and the limit equals f(a)</b>."},
  {id:"math7-continuity-c2", front:"What is a removable discontinuity?", back:"A point where the <b>limit exists but does not equal the function's value</b> (or the function is undefined there)."}
,
  {id:"math7-continuity-c5", front:"What are the three conditions for f(x) to be continuous at x=a?", back:"<b>f(a) must be defined, lim(x→a) f(x) must exist, and lim(x→a) f(x) = f(a)</b>."},
  {id:"math7-continuity-c6", front:"Give an example of a function with a removable discontinuity.", back:"f(x) = (x^2-1)/(x-1) is undefined at x=1, but lim(x→1) f(x) = 2; this is a <b>removable discontinuity</b> since defining f(1)=2 makes it continuous."}],
"math7-differentiability": [
  {id:"math7-differentiability-c1", front:"How is the derivative of f at a point defined?", back:"As the <b>limit of the difference quotient</b>: f'(x) = lim(h→0) [f(x+h)−f(x)]/h."},
  {id:"math7-differentiability-c2", front:"Does differentiability imply continuity?", back:"<b>Yes</b> — but continuity does not imply differentiability."}
,
  {id:"math7-differentiability-c5", front:"What is the relationship between differentiability and continuity?", back:"<b>Every differentiable function is continuous</b>, but a continuous function need not be differentiable, e.g. f(x)=|x| at x=0."},
  {id:"math7-differentiability-c6", front:"How is the derivative of f at x=a defined using limits?", back:"<b>f'(a) = lim(h→0) [f(a+h) - f(a)]/h</b>, provided this limit exists."}],
"math7-differentiation-rules": [
  {id:"math7-differentiation-rules-c1", front:"What is the product rule for differentiation?", back:"<b>(uv)' = u'v + uv'</b>."},
  {id:"math7-differentiation-rules-c2", front:"What is the quotient rule for differentiation?", back:"<b>(u/v)' = (u'v − uv')/v²</b>."},
  {id:"math7-differentiation-rules-c3", front:"What is the chain rule for differentiation?", back:"<b>dy/dx = (dy/du)·(du/dx)</b> for a composite function y = f(g(x))."}
,
  {id:"math7-differentiation-rules-c5", front:"State the quotient rule for differentiation.", back:"For differentiable u and v with v≠0, <b>d/dx[u/v] = (u'v - uv')/v^2</b>."}],
"math7-implicit-differentiation": [
  {id:"math7-implicit-differentiation-c1", front:"When is implicit differentiation used?", back:"When <b>y cannot easily be isolated as an explicit function of x</b> in the given equation."}
,
  {id:"math7-implicit-differentiation-c5", front:"How do you find dy/dx for the implicit equation x^2 + y^2 = 25?", back:"Differentiate both sides with respect to x: 2x + 2y(dy/dx) = 0, giving <b>dy/dx = -x/y</b>."},
  {id:"math7-implicit-differentiation-c6", front:"If x = a cos(t) and y = a sin(t), what is dy/dx?", back:"dy/dt = a cos(t) and dx/dt = -a sin(t), so <b>dy/dx = -cot(t)</b>."},
  {id:"math7-implicit-differentiation-c7", front:"What is the general formula for dy/dx when x=f(t) and y=g(t) are given parametrically?", back:"<b>dy/dx = (dy/dt)/(dx/dt) = g'(t)/f'(t)</b>, provided f'(t) ≠ 0."}],
"math7-higher-derivatives": [
  {id:"math7-higher-derivatives-c1", front:"What does the second derivative of a function represent?", back:"The <b>rate of change of the first derivative</b> (related to concavity)."}
,
  {id:"math7-higher-derivatives-c5", front:"What does the second derivative f''(x) represent geometrically?", back:"The <b>rate of change of the slope</b> of the curve; it indicates the concavity of the curve at that point."},
  {id:"math7-higher-derivatives-c6", front:"How do you find the second derivative of a curve given parametrically as x=f(t), y=g(t)?", back:"First compute dy/dx = (dy/dt)/(dx/dt), then <b>d^2y/dx^2 = [d/dt(dy/dx)] / (dx/dt)</b>."},
  {id:"math7-higher-derivatives-c7", front:"If y = e^x, what is the nth derivative y^(n)?", back:"<b>y^(n) = e^x</b> for every n, since e^x is unchanged by repeated differentiation."}],
"math7-mean-value-theorems": [
  {id:"math7-mean-value-theorems-c1", front:"What does Rolle's theorem state?", back:"If f is continuous on [a,b], differentiable on (a,b), and f(a) = f(b), then <b>f'(c) = 0 for some c in (a,b)</b>."},
  {id:"math7-mean-value-theorems-c2", front:"What does the Lagrange mean value theorem (LMVT) state?", back:"There exists c in (a,b) such that <b>f'(c) = [f(b)−f(a)]/(b−a)</b>."}
,
  {id:"math7-mean-value-theorems-c5", front:"State Rolle's Theorem.", back:"If f is continuous on [a,b], differentiable on (a,b), and f(a)=f(b), then <b>there exists c in (a,b) such that f'(c)=0</b>."},
  {id:"math7-mean-value-theorems-c6", front:"State Lagrange's Mean Value Theorem (LMVT).", back:"If f is continuous on [a,b] and differentiable on (a,b), then there exists c in (a,b) such that <b>f'(c) = [f(b)-f(a)]/(b-a)</b>."}],
"math7-applications-derivatives": [
  {id:"math7-applications-derivatives-c1", front:"How do you determine where a function is increasing using derivatives?", back:"The function is increasing where <b>f'(x) > 0</b>."},
  {id:"math7-applications-derivatives-c2", front:"What does the first derivative test check for maxima/minima?", back:"Whether <b>f'(x) changes sign from positive to negative (max) or negative to positive (min)</b> at a critical point."}
,
  {id:"math7-applications-derivatives-c5", front:"How do you determine if a function is increasing on an interval using derivatives?", back:"f is increasing on an interval where <b>f'(x) ≥ 0</b> throughout (strictly increasing if f'(x) > 0)."},
  {id:"math7-applications-derivatives-c6", front:"State the second derivative test for a critical point c where f'(c)=0.", back:"<b>f''(c) < 0 implies a local maximum; f''(c) > 0 implies a local minimum</b>; if f''(c)=0, the test is inconclusive."}],
"math7-curve-sketching": [
  {id:"math7-curve-sketching-c1", front:"What does the sign of the second derivative indicate about a curve's concavity?", back:"<b>f''(x) > 0 means concave up; f''(x) < 0 means concave down</b>."}
,
  {id:"math7-curve-sketching-c5", front:"How do you find points of inflection of a curve y=f(x)?", back:"Solve <b>f''(x) = 0</b> and verify that the concavity (sign of f'') actually changes across that point."},
  {id:"math7-curve-sketching-c6", front:"How do you locate a vertical asymptote of a rational function f(x)=p(x)/q(x)?", back:"Vertical asymptotes occur where <b>q(x) = 0 while p(x) ≠ 0</b> (the denominator vanishes but the numerator does not)."},
  {id:"math7-curve-sketching-c7", front:"How is concavity of a curve determined using the second derivative?", back:"The curve is <b>concave up where f''(x) > 0</b> and <b>concave down where f''(x) < 0</b>."}],
"math8-indefinite-integrals": [
  {id:"math8-indefinite-integrals-c1", front:"What is an indefinite integral?", back:"The <b>general antiderivative</b> of a function, written ∫f(x)dx = F(x) + C."},
  {id:"math8-indefinite-integrals-c2", front:"What is ∫xⁿ dx (n ≠ −1)?", back:"<b>xⁿ⁺¹/(n+1) + C</b>."}
,
  {id:"math8-indefinite-integrals-c5", front:"What is the power rule for indefinite integration of x^n (n ≠ -1)?", back:"<b>∫x^n dx = x^(n+1)/(n+1) + C</b>."},
  {id:"math8-indefinite-integrals-c6", front:"What is ∫(1/x) dx?", back:"<b>∫(1/x) dx = ln|x| + C</b>."}],
"math8-integration-techniques": [
  {id:"math8-integration-techniques-c1", front:"When is the substitution method used in integration?", back:"When the integral <b>simplifies by replacing a part of the expression with a new variable</b>."},
  {id:"math8-integration-techniques-c2", front:"What is the integration by parts formula?", back:"<b>∫u dv = uv − ∫v du</b>."}
,
  {id:"math8-integration-techniques-c5", front:"What is the formula for Integration by Parts?", back:"<b>∫u dv = uv - ∫v du</b>, choosing u using the ILATE priority order."},
  {id:"math8-integration-techniques-c6", front:"How do you integrate a proper rational function using partial fractions?", back:"Decompose the rational function into <b>simpler fractions with linear or irreducible quadratic denominators</b>, then integrate each term separately."}],
"math8-trigonometric-integration": [
  {id:"math8-trigonometric-integration-c1", front:"Why are power-reduction/product-to-sum identities used before integrating trig products?", back:"They <b>convert products of trig functions into sums</b> that are easier to integrate directly."}
,
  {id:"math8-trigonometric-integration-c5", front:"How do you integrate ∫sin^2(x) dx?", back:"Use sin^2(x) = (1-cos2x)/2 to get <b>∫sin^2(x) dx = x/2 - sin(2x)/4 + C</b>."},
  {id:"math8-trigonometric-integration-c6", front:"What substitution is used to integrate ∫dx/(a + b·cos x)?", back:"Use the <b>Weierstrass substitution t = tan(x/2)</b>, which converts sin x and cos x into rational functions of t."},
  {id:"math8-trigonometric-integration-c7", front:"What is ∫sec(x) dx?", back:"<b>∫sec(x) dx = ln|sec x + tan x| + C</b>."}],
"math8-definite-integrals": [
  {id:"math8-definite-integrals-c1", front:"What does the fundamental theorem of calculus state (evaluating a definite integral)?", back:"<b>∫ₐᵇ f(x)dx = F(b) − F(a)</b>, where F is an antiderivative of f."}
,
  {id:"math8-definite-integrals-c5", front:"State the Fundamental Theorem of Calculus for evaluating a definite integral.", back:"If F is an antiderivative of f, then <b>∫[a to b] f(x) dx = F(b) - F(a)</b>."},
  {id:"math8-definite-integrals-c6", front:"What is the property relating ∫[a to b] f(x) dx and ∫[a to b] f(a+b-x) dx?", back:"<b>∫[a to b] f(x) dx = ∫[a to b] f(a+b-x) dx</b>, a key symmetry property of definite integrals."},
  {id:"math8-definite-integrals-c7", front:"What is ∫[-a to a] f(x) dx if f is an odd function?", back:"<b>∫[-a to a] f(x) dx = 0</b>, since f(-x) = -f(x) for an odd function."}],
"math8-applications-integrals": [
  {id:"math8-applications-integrals-c1", front:"How is the area under a curve y = f(x) from a to b found?", back:"By the <b>definite integral ∫ₐᵇ f(x)dx</b>."},
  {id:"math8-applications-integrals-c2", front:"How is the area between two curves y = f(x) and y = g(x) found?", back:"By <b>∫ₐᵇ [f(x) − g(x)]dx</b> (upper curve minus lower curve)."}
,
  {id:"math8-applications-integrals-c5", front:"How do you find the area under a curve y=f(x) between x=a and x=b (above the x-axis)?", back:"Area = <b>∫[a to b] f(x) dx</b>."},
  {id:"math8-applications-integrals-c6", front:"How do you find the area between two curves y=f(x) and y=g(x) from x=a to x=b, where f(x) ≥ g(x)?", back:"Area = <b>∫[a to b] [f(x) - g(x)] dx</b>, integrating the difference of the upper and lower curves."}],
"math9-order-degree": [
  {id:"math9-order-degree-c1", front:"What is the order of a differential equation?", back:"The <b>order of the highest derivative</b> present in the equation."},
  {id:"math9-order-degree-c2", front:"What is the degree of a differential equation?", back:"The <b>power of the highest-order derivative</b>, when the equation is polynomial in derivatives."}
,
  {id:"math9-order-degree-c5", front:"What is the 'order' of a differential equation?", back:"The <b>order of the highest derivative</b> that appears in the differential equation."},
  {id:"math9-order-degree-c6", front:"What is the 'degree' of a differential equation?", back:"The <b>power of the highest order derivative</b>, once the equation is expressed as a polynomial in derivatives (free of radicals and fractions)."}],
"math9-formation-de": [
  {id:"math9-formation-de-c1", front:"How is a differential equation formed from a family of curves?", back:"By <b>differentiating the equation and eliminating the arbitrary constant(s)</b>."}
,
  {id:"math9-formation-de-c5", front:"How do you form a differential equation from a family of curves containing n arbitrary constants?", back:"<b>Differentiate the equation n times</b> and eliminate all n arbitrary constants to obtain the differential equation."},
  {id:"math9-formation-de-c6", front:"Form the differential equation for the family of lines y = mx, where m is an arbitrary constant.", back:"Differentiating gives dy/dx = m; substituting back yields <b>x(dy/dx) = y</b>."},
  {id:"math9-formation-de-c7", front:"How many arbitrary constants appear in the differential equation for circles of fixed radius but variable center?", back:"<b>Two arbitrary constants</b> (the center's coordinates), so the resulting differential equation is of second order."}],
"math9-variable-separable": [
  {id:"math9-variable-separable-c1", front:"What is the variable separable method used for?", back:"Solving equations that can be written as <b>f(y)dy = g(x)dx</b>, then integrating both sides."}
,
  {id:"math9-variable-separable-c5", front:"What is the general strategy for solving a variable separable differential equation dy/dx = f(x)g(y)?", back:"Separate the variables as <b>dy/g(y) = f(x) dx</b>, then integrate both sides."},
  {id:"math9-variable-separable-c6", front:"Solve the variable separable differential equation dy/dx = y.", back:"Separating gives dy/y = dx; integrating gives ln|y| = x + C, so <b>y = Ce^x</b>."},
  {id:"math9-variable-separable-c7", front:"Solve the differential equation dy/dx = -x/y.", back:"Separating gives y dy = -x dx; integrating both sides gives <b>x^2 + y^2 = C</b>, a family of circles."}],
"math9-homogeneous-de": [
  {id:"math9-homogeneous-de-c1", front:"What substitution is used to solve a homogeneous differential equation?", back:"<b>y = vx</b> (or x = vy)."}
,
  {id:"math9-homogeneous-de-c5", front:"What makes a differential equation dy/dx = f(x,y) 'homogeneous'?", back:"When f(x,y) can be expressed as a function of <b>y/x alone</b>, i.e., f(λx,λy) = f(x,y) for all λ."},
  {id:"math9-homogeneous-de-c6", front:"What substitution is used to solve a homogeneous differential equation?", back:"Substitute <b>y = vx</b> (so dy/dx = v + x dv/dx), which converts it into a variable separable equation in v and x."},
  {id:"math9-homogeneous-de-c7", front:"Solve the homogeneous differential equation dy/dx = (x+y)/x.", back:"Let y=vx: v + x dv/dx = 1+v gives x dv/dx = 1, so dv = dx/x; integrating gives <b>v = ln|x| + C, i.e. y = x(ln|x| + C)</b>."}],
"math9-linear-de": [
  {id:"math9-linear-de-c1", front:"What is the standard form of a linear differential equation in y?", back:"<b>dy/dx + Py = Q</b>, where P, Q are functions of x."}
,
  {id:"math9-linear-de-c5", front:"What is the standard form of a first-order linear differential equation?", back:"<b>dy/dx + P(x)y = Q(x)</b>, where P and Q are functions of x alone."},
  {id:"math9-linear-de-c6", front:"What is the Integrating Factor (IF) for the linear differential equation dy/dx + Py = Q?", back:"<b>IF = e^(∫P dx)</b>."},
  {id:"math9-linear-de-c7", front:"What is the general solution of a linear differential equation once the integrating factor is known?", back:"<b>y·(IF) = ∫Q·(IF) dx + C</b>."}],
"math9-applications-de": [
  {id:"math9-applications-de-c1", front:"What differential equation models exponential growth/decay?", back:"<b>dN/dt = kN</b> (k > 0 for growth, k < 0 for decay)."}
,
  {id:"math9-applications-de-c5", front:"How is a differential equation used to model exponential population growth?", back:"dP/dt = kP with k>0; solving gives <b>P(t) = P0 e^(kt)</b>, exponential growth."},
  {id:"math9-applications-de-c6", front:"How does Newton's Law of Cooling translate into a differential equation and its solution?", back:"dT/dt = -k(T - Ts) where Ts is the surrounding temperature; solving gives <b>T(t) = Ts + (T0 - Ts)e^(-kt)</b>."},
  {id:"math9-applications-de-c7", front:"How is radioactive decay modeled using a differential equation?", back:"dN/dt = -λN with decay constant λ>0; solving gives <b>N(t) = N0 e^(-λt)</b>."}],
"math10-straight-lines": [
  {id:"math10-straight-lines-c1", front:"What is the distance formula between two points (x₁,y₁) and (x₂,y₂)?", back:"<b>√[(x₂−x₁)² + (y₂−y₁)²]</b>."},
  {id:"math10-straight-lines-c2", front:"What is the slope-intercept form of a line?", back:"<b>y = mx + c</b>."}
,
  {id:"math10-straight-lines-c5", front:"What is the slope-point form of a line?", back:"The equation of a line through (x1,y1) with slope m is <b>y - y1 = m(x - x1)</b>."},
  {id:"math10-straight-lines-c6", front:"How do you find the distance between two parallel lines ax+by+c1=0 and ax+by+c2=0?", back:"Distance = <b>|c1 - c2| / sqrt(a^2 + b^2)</b>."}],
"math10-circles": [
  {id:"math10-circles-c1", front:"What is the standard equation of a circle with center (h,k) and radius r?", back:"<b>(x−h)² + (y−k)² = r²</b>."}
,
  {id:"math10-circles-c5", front:"What is the general equation of a circle?", back:"x^2 + y^2 + 2gx + 2fy + c = 0, with center <b>(-g, -f)</b> and radius <b>sqrt(g^2+f^2-c)</b>."},
  {id:"math10-circles-c6", front:"What is the equation of a circle with center (h,k) and radius r?", back:"<b>(x-h)^2 + (y-k)^2 = r^2</b>."},
  {id:"math10-circles-c7", front:"What is the condition for a line y = mx + c to be tangent to circle x^2+y^2=r^2?", back:"The line is tangent when <b>c^2 = r^2(1+m^2)</b>."}],
"math10-conic-general": [
  {id:"math10-conic-general-c1", front:"What determines which conic a general second-degree equation represents?", back:"The <b>discriminant condition on its coefficients</b> (relating to B² − 4AC for Ax²+Bxy+Cy²+...)."}
,
  {id:"math10-conic-general-c5", front:"What is the general second-degree equation representing a conic?", back:"<b>ax^2 + 2hxy + by^2 + 2gx + 2fy + c = 0</b>, representing different conics depending on the discriminant Δ = abc + 2fgh - af^2 - bg^2 - ch^2 being nonzero."},
  {id:"math10-conic-general-c6", front:"How do you identify the type of conic from ax^2+2hxy+by^2+...=0 using h^2 - ab?", back:"If <b>h^2 - ab < 0</b> it's an ellipse (or circle if a=b, h=0), if <b>h^2 - ab = 0</b> it's a parabola, if <b>h^2 - ab > 0</b> it's a hyperbola."},
  {id:"math10-conic-general-c7", front:"What is eccentricity in the unified focus-directrix definition of conics?", back:"The ratio of the distance from a point on the conic to the focus, over the distance to the directrix; <b>e<1 ellipse, e=1 parabola, e>1 hyperbola</b>."}],
"math10-parabola": [
  {id:"math10-parabola-c1", front:"What is the standard equation of a right-opening parabola with vertex at origin?", back:"<b>y² = 4ax</b>."}
,
  {id:"math10-parabola-c5", front:"What is the standard equation of a parabola opening rightward?", back:"<b>y^2 = 4ax</b>, with vertex at origin, focus at (a,0), and directrix x = -a."},
  {id:"math10-parabola-c6", front:"What is the length of the latus rectum of the parabola y^2=4ax?", back:"The latus rectum length is <b>4a</b>, the chord through the focus perpendicular to the axis."},
  {id:"math10-parabola-c7", front:"What is the equation of the tangent to y^2=4ax at point (at^2, 2at)?", back:"<b>ty = x + at^2</b>."}],
"math10-ellipse": [
  {id:"math10-ellipse-c1", front:"What is the standard equation of an ellipse centered at the origin (a > b)?", back:"<b>x²/a² + y²/b² = 1</b>."},
  {id:"math10-ellipse-c2", front:"What does eccentricity describe for an ellipse?", back:"How much it <b>deviates from a circle</b> (0 < e < 1)."}
,
  {id:"math10-ellipse-c5", front:"What is the standard equation of an ellipse with major axis along the x-axis?", back:"<b>x^2/a^2 + y^2/b^2 = 1</b> (a>b), with foci at (±ae, 0) where e = sqrt(1 - b^2/a^2)."},
  {id:"math10-ellipse-c6", front:"What is the relation between a, b, and eccentricity e of an ellipse?", back:"<b>b^2 = a^2(1 - e^2)</b>."}],
"math10-hyperbola": [
  {id:"math10-hyperbola-c1", front:"What is the standard equation of a horizontal hyperbola centered at the origin?", back:"<b>x²/a² − y²/b² = 1</b>."}
,
  {id:"math10-hyperbola-c5", front:"What is the standard equation of a hyperbola with transverse axis along the x-axis?", back:"<b>x^2/a^2 - y^2/b^2 = 1</b>, with foci at (±ae, 0) where e = sqrt(1 + b^2/a^2)."},
  {id:"math10-hyperbola-c6", front:"What are the equations of the asymptotes of x^2/a^2 - y^2/b^2 = 1?", back:"<b>y = ±(b/a)x</b>."},
  {id:"math10-hyperbola-c7", front:"What is the relation between a, b, and eccentricity e of a hyperbola?", back:"<b>b^2 = a^2(e^2 - 1)</b>."}],
"math10-tangent-normal-conics": [
  {id:"math10-tangent-normal-conics-c1", front:"What is the general rule for finding the equation of the tangent to a conic (T = 0)?", back:"<b>Replace x² with x·x₁, y² with y·y₁, and xy/x/y terms with their mixed forms</b> using the point of contact."}
,
  {id:"math10-tangent-normal-conics-c5", front:"What is the condition for line y=mx+c to be tangent to ellipse x^2/a^2+y^2/b^2=1?", back:"<b>c^2 = a^2m^2 + b^2</b>."},
  {id:"math10-tangent-normal-conics-c6", front:"What is the equation of the normal to the parabola y^2=4ax at (at^2, 2at)?", back:"<b>y + tx = 2at + at^3</b>."},
  {id:"math10-tangent-normal-conics-c7", front:"What is the condition for y=mx+c to be tangent to hyperbola x^2/a^2 - y^2/b^2=1?", back:"<b>c^2 = a^2m^2 - b^2</b>."}],
"math10-chord-contact": [
  {id:"math10-chord-contact-c1", front:"What is the chord of contact?", back:"The <b>line joining the two points of tangency</b> from an external point to a conic, given by T = 0."}
,
  {id:"math10-chord-contact-c5", front:"What is the equation of the chord of contact from an external point (x1,y1) to circle x^2+y^2=r^2?", back:"<b>xx1 + yy1 = r^2</b>, formed by joining the points of contact of tangents drawn from (x1,y1)."},
  {id:"math10-chord-contact-c6", front:"What is the polar of a point (x1,y1) with respect to the parabola y^2=4ax?", back:"<b>yy1 = 2a(x + x1)</b>."},
  {id:"math10-chord-contact-c7", front:"What is the pole-polar reciprocity relationship for conics?", back:"If the polar of point P passes through point Q, then the <b>polar of Q passes through P</b> (conjugate points property)."}],
"math11-3d-coordinates": [
  {id:"math11-3d-coordinates-c1", front:"What is the distance formula between two points in 3D space?", back:"<b>√[(x₂−x₁)² + (y₂−y₁)² + (z₂−z₁)²]</b>."}
,
  {id:"math11-3d-coordinates-c5", front:"What is the distance formula between two points in 3D?", back:"For P(x1,y1,z1) and Q(x2,y2,z2), distance = <b>sqrt((x2-x1)^2+(y2-y1)^2+(z2-z1)^2)</b>."},
  {id:"math11-3d-coordinates-c6", front:"What is the section formula for a point dividing a 3D segment internally in ratio m:n?", back:"<b>((mx2+nx1)/(m+n), (my2+ny1)/(m+n), (mz2+nz1)/(m+n))</b>."},
  {id:"math11-3d-coordinates-c7", front:"What are the coordinates of the midpoint of the segment joining (x1,y1,z1) and (x2,y2,z2)?", back:"<b>((x1+x2)/2, (y1+y2)/2, (z1+z2)/2)</b>."}],
"math11-direction-cosines": [
  {id:"math11-direction-cosines-c1", front:"What is the fundamental identity for direction cosines l, m, n of a line?", back:"<b>l² + m² + n² = 1</b>."}
,
  {id:"math11-direction-cosines-c5", front:"What is the relation between the direction cosines l, m, n of a line?", back:"<b>l^2 + m^2 + n^2 = 1</b>."},
  {id:"math11-direction-cosines-c6", front:"How do you convert direction ratios a,b,c to direction cosines?", back:"Divide each by sqrt(a^2+b^2+c^2): <b>l=a/sqrt(a^2+b^2+c^2), m=b/sqrt(a^2+b^2+c^2), n=c/sqrt(a^2+b^2+c^2)</b>."},
  {id:"math11-direction-cosines-c7", front:"What are the direction cosines of a line joining points (x1,y1,z1) and (x2,y2,z2)?", back:"<b>(x2-x1)/d, (y2-y1)/d, (z2-z1)/d</b>, where d is the distance between the two points."}],
"math11-line-in-space": [
  {id:"math11-line-in-space-c1", front:"What is the vector form of the equation of a line through a point with direction vector b?", back:"<b>r = a + λb</b>."}
,
  {id:"math11-line-in-space-c5", front:"What is the vector equation of a line through a point with position vector a and parallel to vector b?", back:"<b>r = a + λb</b>, where λ is a scalar parameter."},
  {id:"math11-line-in-space-c6", front:"What is the Cartesian equation of a line through (x1,y1,z1) with direction ratios a,b,c?", back:"<b>(x-x1)/a = (y-y1)/b = (z-z1)/c</b>."},
  {id:"math11-line-in-space-c7", front:"What is the vector equation of a line through two given points with position vectors a and b?", back:"<b>r = a + λ(b - a)</b>."}],
"math11-angle-between-lines": [
  {id:"math11-angle-between-lines-c1", front:"How is the angle between two lines in 3D found using direction ratios?", back:"Using <b>cosθ = |a₁a₂+b₁b₂+c₁c₂| / (√(a₁²+b₁²+c₁²)·√(a₂²+b₂²+c₂²))</b> — the modulus keeps θ acute, by convention."}
,
  {id:"math11-angle-between-lines-c5", front:"How do you find the angle between two lines with direction ratios a1,b1,c1 and a2,b2,c2?", back:"cos θ = <b>|a1a2+b1b2+c1c2| / (sqrt(a1^2+b1^2+c1^2) · sqrt(a2^2+b2^2+c2^2))</b>."},
  {id:"math11-angle-between-lines-c6", front:"What is the condition for two lines with direction ratios (a1,b1,c1) and (a2,b2,c2) to be perpendicular?", back:"<b>a1a2 + b1b2 + c1c2 = 0</b>."},
  {id:"math11-angle-between-lines-c7", front:"What is the condition for two lines with direction ratios (a1,b1,c1) and (a2,b2,c2) to be parallel?", back:"<b>a1/a2 = b1/b2 = c1/c2</b>."}],
"math11-coplanarity": [
  {id:"math11-coplanarity-c1", front:"What determinant condition tests if four points are coplanar?", back:"A <b>3×3 determinant formed from vectors between the points must equal zero</b>."}
,
  {id:"math11-coplanarity-c5", front:"What is the condition for two lines to be coplanar?", back:"For lines through (x1,y1,z1) and (x2,y2,z2) with direction ratios (a1,b1,c1) and (a2,b2,c2), they are coplanar if <b>the determinant |x2-x1 y2-y1 z2-z1; a1 b1 c1; a2 b2 c2| = 0</b>."},
  {id:"math11-coplanarity-c6", front:"How do you check if four points are coplanar?", back:"Form vectors from one point to the other three and check if their <b>scalar triple product equals zero</b>."},
  {id:"math11-coplanarity-c7", front:"What does coplanarity of two lines imply geometrically?", back:"The lines either <b>intersect or are parallel</b>, i.e., they lie in a common plane."}],
"math11-plane-equations": [
  {id:"math11-plane-equations-c1", front:"What is the general equation of a plane?", back:"<b>Ax + By + Cz + D = 0</b>."}
,
  {id:"math11-plane-equations-c5", front:"What is the vector equation of a plane at perpendicular distance d from the origin with unit normal n̂?", back:"<b>r · n̂ = d</b>."},
  {id:"math11-plane-equations-c6", front:"What is the Cartesian equation of a plane with normal direction ratios a,b,c passing through (x1,y1,z1)?", back:"<b>a(x-x1) + b(y-y1) + c(z-z1) = 0</b>."},
  {id:"math11-plane-equations-c7", front:"What is the equation of a plane through three non-collinear points with position vectors a, b, c?", back:"<b>(r - a) · [(b-a) × (c-a)] = 0</b>."}],
"math11-line-plane-relations": [
  {id:"math11-line-plane-relations-c1", front:"When is a line perpendicular to a plane?", back:"When the <b>line's direction vector is parallel to the plane's normal vector</b>."}
,
  {id:"math11-line-plane-relations-c5", front:"What is the condition for a line with direction ratios a,b,c to be parallel to the plane Ax+By+Cz+D=0?", back:"The line is parallel to the plane when <b>Aa + Bb + Cc = 0</b>."},
  {id:"math11-line-plane-relations-c6", front:"What is the condition for a line to be perpendicular to a plane?", back:"The line's direction ratios must be <b>proportional to the plane's normal</b>: a/A = b/B = c/C."},
  {id:"math11-line-plane-relations-c7", front:"How do you find the angle between a line and a plane?", back:"sin θ = <b>|Aa+Bb+Cc| / (sqrt(A^2+B^2+C^2)·sqrt(a^2+b^2+c^2))</b>, where (a,b,c) are the line's direction ratios and (A,B,C) the plane's normal."}],
"math11-skew-lines": [
  {id:"math11-skew-lines-c1", front:"What are skew lines?", back:"Lines that are <b>neither parallel nor intersecting</b> (in different planes)."}
,
  {id:"math11-skew-lines-c5", front:"What are skew lines?", back:"Lines that are <b>neither intersecting nor parallel</b> and do not lie in the same plane."},
  {id:"math11-skew-lines-c6", front:"What is the formula for the shortest distance between two skew lines r=a1+λb1 and r=a2+μb2?", back:"d = <b>|(a2-a1)·(b1×b2)| / |b1×b2|</b>."},
  {id:"math11-skew-lines-c7", front:"What is the shortest distance between two parallel lines r=a1+λb and r=a2+μb?", back:"d = <b>|(a2-a1)×b| / |b|</b>."}],
"math12-vectors-basics": [
  {id:"math12-vectors-basics-c1", front:"What distinguishes a vector from a scalar?", back:"A vector has <b>both magnitude and direction</b>; a scalar has only magnitude."},
  {id:"math12-vectors-basics-c2", front:"What is a unit vector?", back:"A vector with <b>magnitude 1</b>."}
,
  {id:"math12-vectors-basics-c5", front:"What is a unit vector?", back:"A vector with <b>magnitude 1</b>; the unit vector along a is â = <b>a/|a|</b>."},
  {id:"math12-vectors-basics-c6", front:"What is the position vector of a point?", back:"The vector <b>OP</b> from the origin O to the point P, representing its location in space."}],
"math12-vector-addition": [
  {id:"math12-vector-addition-c1", front:"What does the triangle law of vector addition state?", back:"If two vectors are represented as two sides of a triangle in order, their <b>sum is the third side</b> (closing the triangle)."}
,
  {id:"math12-vector-addition-c5", front:"State the triangle law of vector addition.", back:"If two vectors are represented by two sides of a triangle taken in order, their sum is given by the <b>third side taken in reverse order</b>: OA + AB = OB."},
  {id:"math12-vector-addition-c6", front:"State the parallelogram law of vector addition.", back:"If two vectors are represented by two adjacent sides of a parallelogram, their sum is given by the <b>diagonal through their common point</b>."},
  {id:"math12-vector-addition-c7", front:"How do you add vectors given in component form?", back:"Add corresponding components: if a=(a1,a2,a3) and b=(b1,b2,b3), then <b>a+b=(a1+b1, a2+b2, a3+b3)</b>."}],
"math12-scalar-product": [
  {id:"math12-scalar-product-c1", front:"What is the formula for the scalar (dot) product of vectors a and b?", back:"<b>a·b = |a||b|cosθ</b>."},
  {id:"math12-scalar-product-c2", front:"When is the dot product of two non-zero vectors zero?", back:"When the vectors are <b>perpendicular</b>."}
,
  {id:"math12-scalar-product-c5", front:"What is the formula for the scalar (dot) product of two vectors?", back:"<b>a · b = |a||b| cos θ</b>, where θ is the angle between them."},
  {id:"math12-scalar-product-c6", front:"How is the dot product used to find the angle between two vectors?", back:"cos θ = <b>(a · b) / (|a||b|)</b>, so θ = cos⁻¹((a·b)/(|a||b|))."}],
"math12-vector-product": [
  {id:"math12-vector-product-c1", front:"What is the magnitude of the vector (cross) product of a and b?", back:"<b>|a×b| = |a||b|sinθ</b>."},
  {id:"math12-vector-product-c2", front:"What rule gives the direction of a×b?", back:"The <b>right-hand rule</b>."}
,
  {id:"math12-vector-product-c5", front:"What is the formula for the vector (cross) product of two vectors?", back:"<b>a × b = |a||b| sin θ n̂</b>, where n̂ is the unit vector perpendicular to both a and b."},
  {id:"math12-vector-product-c6", front:"How do you find the area of a parallelogram formed by vectors a and b?", back:"Area = <b>|a × b|</b>, the magnitude of their cross product."}],
"math12-triple-products": [
  {id:"math12-triple-products-c1", front:"What does the scalar triple product a·(b×c) represent geometrically?", back:"Its <b>absolute value |a·(b×c)|</b> is the volume of the parallelepiped formed by the three vectors; the sign shows whether the triad is right- or left-handed."}
,
  {id:"math12-triple-products-c5", front:"What is the scalar triple product of vectors a, b, c?", back:"<b>a · (b × c)</b>, denoted [a b c], equal to the determinant of their components; it gives the volume of the parallelepiped formed by them."},
  {id:"math12-triple-products-c6", front:"What does a scalar triple product of zero indicate?", back:"The three vectors are <b>coplanar</b>."},
  {id:"math12-triple-products-c7", front:"How do you compute the volume of a parallelepiped using vectors?", back:"Volume = <b>|a · (b × c)|</b>, the absolute value of the scalar triple product of the coterminous edge vectors."}],
"math13-measures-central-tendency": [
  {id:"math13-measures-central-tendency-c1", front:"What is the mean of a data set?", back:"The <b>sum of all values divided by the number of values</b>."},
  {id:"math13-measures-central-tendency-c2", front:"What is the median of a data set?", back:"The <b>middle value</b> when data is arranged in order."}
,
  {id:"math13-measures-central-tendency-c5", front:"What is the formula for the mean of grouped data using the direct method?", back:"Mean = <b>Σ(fi·xi) / Σfi</b>, where fi is frequency and xi is the class mark."},
  {id:"math13-measures-central-tendency-c6", front:"How is the median of grouped data calculated?", back:"Median = <b>l + [(n/2 - cf)/f] × h</b>, where l is the lower limit of the median class, cf is the cumulative frequency before it, f is its frequency, and h is the class width."}],
"math13-measures-dispersion": [
  {id:"math13-measures-dispersion-c1", front:"What is the range of a data set?", back:"<b>Maximum value minus minimum value</b>."},
  {id:"math13-measures-dispersion-c2", front:"What is standard deviation a measure of?", back:"The <b>spread of data around the mean</b>."}
,
  {id:"math13-measures-dispersion-c5", front:"What is the formula for the variance of grouped data?", back:"Variance σ^2 = <b>Σfi(xi - x̄)^2 / Σfi</b>, where x̄ is the mean."},
  {id:"math13-measures-dispersion-c6", front:"What is the relationship between standard deviation and variance?", back:"Standard deviation is the <b>positive square root of variance</b>: σ = sqrt(σ^2)."}],
"math13-probability-basics": [
  {id:"math13-probability-basics-c1", front:"What is the sample space of a random experiment?", back:"The <b>set of all possible outcomes</b>."},
  {id:"math13-probability-basics-c2", front:"What is the classical formula for probability of an event E?", back:"<b>P(E) = (favorable outcomes)/(total outcomes)</b>."}
,
  {id:"math13-probability-basics-c5", front:"What is the formula for the probability of an event?", back:"P(E) = <b>n(E)/n(S)</b>, the ratio of favorable outcomes to total outcomes in the sample space."},
  {id:"math13-probability-basics-c6", front:"What is the range of values a probability can take?", back:"Probability always satisfies <b>0 ≤ P(E) ≤ 1</b>, with P(S) = 1 for the sample space and P(∅) = 0."}],
"math13-conditional-probability": [
  {id:"math13-conditional-probability-c1", front:"What is the formula for conditional probability P(A|B)?", back:"<b>P(A|B) = P(A∩B)/P(B)</b>, provided P(B) ≠ 0."}
,
  {id:"math13-conditional-probability-c5", front:"What is the formula for conditional probability P(A|B)?", back:"<b>P(A|B) = P(A∩B)/P(B)</b>, provided P(B) > 0."},
  {id:"math13-conditional-probability-c6", front:"State the multiplication rule of probability.", back:"<b>P(A∩B) = P(A)·P(B|A) = P(B)·P(A|B)</b>, used to find the probability of two events occurring together."},
  {id:"math13-conditional-probability-c7", front:"How do you check if two events A and B are independent using conditional probability?", back:"A and B are independent if <b>P(A|B) = P(A)</b> and <b>P(B|A) = P(B)</b>, equivalently P(A∩B) = P(A)P(B)."}],
"math13-bayes-theorem": [
  {id:"math13-bayes-theorem-c1", front:"What does Bayes' theorem let you calculate?", back:"The <b>probability of a cause given an observed effect</b>, using prior probabilities and conditional probabilities."}
,
  {id:"math13-bayes-theorem-c5", front:"State Bayes' Theorem.", back:"For events A1,...,An partitioning S and event E: <b>P(Ai|E) = [P(Ai)P(E|Ai)] / Σ P(Aj)P(E|Aj)</b>."},
  {id:"math13-bayes-theorem-c6", front:"What is the Law of Total Probability?", back:"If A1,...,An partition the sample space, then <b>P(E) = Σ P(Ai)·P(E|Ai)</b>."},
  {id:"math13-bayes-theorem-c7", front:"In Bayes' theorem, what do 'prior' and 'posterior' probabilities mean?", back:"The <b>prior</b> P(Ai) is the probability before observing evidence E; the <b>posterior</b> P(Ai|E) is the updated probability after observing E."}],
"math13-bernoulli-trials": [
  {id:"math13-bernoulli-trials-c1", front:"What is a Bernoulli trial?", back:"A <b>random experiment with exactly two outcomes</b> (success/failure), repeated independently."}
,
  {id:"math13-bernoulli-trials-c5", front:"What are the conditions for a sequence of trials to be Bernoulli trials?", back:"Trials must be <b>independent</b>, each have only <b>two outcomes</b> (success/failure), and have the <b>same probability p</b> of success each time."},
  {id:"math13-bernoulli-trials-c6", front:"State the binomial probability formula for exactly r successes in n Bernoulli trials.", back:"<b>P(X=r) = nCr · p^r · q^(n-r)</b>, where q = 1-p."},
  {id:"math13-bernoulli-trials-c7", front:"What is the probability of at least one success in n Bernoulli trials with success probability p?", back:"<b>P(at least one success) = 1 - q^n</b>, where q = 1-p is the failure probability."}],
"math13-random-variables": [
  {id:"math13-random-variables-c1", front:"What is a random variable?", back:"A <b>variable whose value depends on the outcome of a random experiment</b>."}
,
  {id:"math13-random-variables-c5", front:"What is a random variable?", back:"A <b>real-valued function defined on the sample space</b> of a random experiment, mapping each outcome to a number."},
  {id:"math13-random-variables-c6", front:"What is the formula for the mean (expectation) of a discrete random variable X?", back:"<b>E(X) = Σ xi·P(xi)</b>, summed over all values xi of X."},
  {id:"math13-random-variables-c7", front:"What is the formula for the variance of a discrete random variable X?", back:"<b>Var(X) = E(X²) - [E(X)]²</b>, where E(X²) = Σ xi²·P(xi)."}],
"math13-probability-distributions": [
  {id:"math13-probability-distributions-c1", front:"What does the binomial distribution model?", back:"The <b>number of successes in n independent Bernoulli trials</b>, each with success probability p."}
,
  {id:"math13-probability-distributions-c5", front:"What two conditions must a probability distribution of a discrete random variable satisfy?", back:"Each <b>0 ≤ pi ≤ 1</b> and <b>Σ pi = 1</b> over all values of the random variable."},
  {id:"math13-probability-distributions-c6", front:"What are the mean and variance of a Binomial distribution B(n,p)?", back:"Mean = <b>np</b> and Variance = <b>npq</b>, where q = 1-p."},
  {id:"math13-probability-distributions-c7", front:"How do you find the cumulative distribution from a probability distribution table?", back:"The cumulative probability at x is <b>F(x) = P(X ≤ x) = Σ P(xi) for all xi ≤ x</b>."}],
"math14-trig-identities": [
  {id:"math14-trig-identities-c1", front:"What is the fundamental trigonometric identity?", back:"<b>sin²θ + cos²θ = 1</b>."},
  {id:"math14-trig-identities-c2", front:"What is the formula for sin(A+B)?", back:"<b>sinA cosB + cosA sinB</b>."}
,
  {id:"math14-trig-identities-c5", front:"State the sum-to-product formula for sin A + sin B.", back:"<b>sin A + sin B = 2 sin((A+B)/2) cos((A-B)/2)</b>."},
  {id:"math14-trig-identities-c6", front:"State the double angle formula for cos 2x in terms of sin x only.", back:"<b>cos 2x = 1 - 2sin²x</b>."}],
"math14-trig-equations": [
  {id:"math14-trig-equations-c1", front:"What is the general solution of sinθ = sinα?", back:"<b>θ = nπ + (−1)ⁿα</b>, for integer n."}
,
  {id:"math14-trig-equations-c5", front:"What is the general solution of sin θ = sin α?", back:"<b>θ = nπ + (-1)^n α</b>, n ∈ Z."},
  {id:"math14-trig-equations-c6", front:"What is the general solution of cos θ = cos α?", back:"<b>θ = 2nπ ± α</b>, n ∈ Z."},
  {id:"math14-trig-equations-c7", front:"What is the general solution of tan θ = tan α?", back:"<b>θ = nπ + α</b>, n ∈ Z."}],
"math14-inverse-trig": [
  {id:"math14-inverse-trig-c1", front:"What is the principal value range of sin⁻¹x?", back:"<b>[−π/2, π/2]</b>."},
  {id:"math14-inverse-trig-c2", front:"What is the principal value range of cos⁻¹x?", back:"<b>[0, π]</b>."}
,
  {id:"math14-inverse-trig-c5", front:"What is the principal value range of sin⁻¹x?", back:"<b>[-π/2, π/2]</b>, for x ∈ [-1, 1]."},
  {id:"math14-inverse-trig-c6", front:"What is the identity relating sin⁻¹x and cos⁻¹x?", back:"<b>sin⁻¹x + cos⁻¹x = π/2</b>, for x ∈ [-1, 1]."}],
"math14-properties-triangles": [
  {id:"math14-properties-triangles-c1", front:"What is the sine rule for a triangle with sides a, b, c and opposite angles A, B, C?", back:"<b>a/sinA = b/sinB = c/sinC</b>."},
  {id:"math14-properties-triangles-c2", front:"What is the cosine rule for side a?", back:"<b>a² = b² + c² − 2bc·cosA</b>."}
,
  {id:"math14-properties-triangles-c5", front:"State the Sine Rule for a triangle.", back:"<b>a/sin A = b/sin B = c/sin C = 2R</b>, where R is the circumradius."},
  {id:"math14-properties-triangles-c6", front:"State the Cosine Rule for a triangle.", back:"<b>cos A = (b² + c² - a²)/(2bc)</b>, and similarly for angles B and C."}],
"bio5-root-system": [
  {id:"bio5-root-system-c1", front:"What are the two main functions of the root system?", back:"<b>Anchorage and absorption</b> of water and minerals."},
  {id:"bio5-root-system-c2", front:"What is the difference between a tap root and a fibrous root system?", back:"A <b>tap root</b> has one main root with branches; a <b>fibrous root</b> system has many similar-sized roots, no main root."}
,
  {id:"bio5-root-system-c5", front:"What is the modification of roots in Rhizophora (mangrove plants)?", back:"Rhizophora develops <b>pneumatophores</b>, negatively geotropic roots that grow vertically upward to help obtain oxygen for respiration."},
  {id:"bio5-root-system-c6", front:"Name the four regions of a typical root from tip to base.", back:"<b>Root cap</b>, region of <b>meristematic activity</b>, region of <b>elongation</b>, and region of <b>maturation</b> (with root hairs)."}],
"bio5-stem": [
  {id:"bio5-stem-c1", front:"What are the two main functions of the stem?", back:"<b>Support</b> (bearing leaves/flowers) and <b>transport</b> of water and nutrients."},
  {id:"bio5-stem-c2", front:"What is a modified underground stem that stores food, e.g. potato?", back:"A <b>tuber</b>."}
,
  {id:"bio5-stem-c5", front:"What is the function of tendrils formed by stems, e.g. in Cucurbita?", back:"Stem tendrils are slender, coiled structures that help the plant <b>climb</b> by clinging to a support."},
  {id:"bio5-stem-c6", front:"How do underground stems like potato differ from roots?", back:"Underground stems bear <b>nodes</b>, <b>internodes</b>, scaly leaves and axillary buds (e.g. <b>eyes</b> of potato), features roots never have."}],
"bio5-leaf": [
  {id:"bio5-leaf-c1", front:"What are the two main parts of a typical leaf?", back:"The <b>petiole (stalk) and lamina (blade)</b>."},
  {id:"bio5-leaf-c2", front:"What is the difference between reticulate and parallel venation?", back:"<b>Reticulate</b> venation forms a network (dicots); <b>parallel</b> venation runs in straight lines (monocots)."}
,
  {id:"bio5-leaf-c5", front:"Differentiate reticulate and parallel venation.", back:"In <b>reticulate venation</b> (dicots) veins form a network; in <b>parallel venation</b> (monocots) veins run parallel to each other."},
  {id:"bio5-leaf-c6", front:"What is phyllotaxy and name its three types.", back:"<b>Phyllotaxy</b> is the pattern of leaf arrangement on a stem: <b>alternate</b>, <b>opposite</b>, and <b>whorled</b>."}],
"bio5-inflorescence": [
  {id:"bio5-inflorescence-c1", front:"What is the difference between racemose and cymose inflorescence?", back:"In <b>racemose</b>, the main axis keeps growing and flowers are borne laterally; in <b>cymose</b>, the main axis ends in a flower and growth continues from lateral branches."}
,
  {id:"bio5-inflorescence-c5", front:"Define inflorescence.", back:"The arrangement of flowers on the <b>floral axis</b> of a plant, classified mainly as <b>racemose</b> or <b>cymose</b>."},
  {id:"bio5-inflorescence-c6", front:"What distinguishes racemose from cymose inflorescence?", back:"In <b>racemose</b> type the main axis keeps growing with flowers borne laterally in acropetal order; in <b>cymose</b> type the main axis ends in a flower, showing <b>basipetal</b> order."},
  {id:"bio5-inflorescence-c7", front:"Give an example of a special/mixed inflorescence found in Asteraceae.", back:"The <b>capitulum (head)</b>, e.g. in sunflower, where the axis is condensed into a flat receptacle bearing many sessile florets."}],
"bio5-flower": [
  {id:"bio5-flower-c1", front:"What are the four whorls of a typical flower, from outside in?", back:"<b>Calyx, corolla, androecium, gynoecium</b>."},
  {id:"bio5-flower-c2", front:"What is the difference between an actinomorphic and a zygomorphic flower?", back:"<b>Actinomorphic</b> flowers are radially symmetric; <b>zygomorphic</b> flowers are bilaterally symmetric."},
  {id:"bio5-flower-c3", front:"What is a hypogynous flower?", back:"A flower where the <b>ovary is superior</b> — other floral whorls are attached below it."}
,
  {id:"bio5-flower-c5", front:"What is aestivation? Name its types.", back:"<b>Aestivation</b> is the arrangement of sepals/petals in a floral bud relative to each other: <b>valvate</b>, <b>twisted</b>, <b>imbricate</b>, and <b>vexillary</b>."}],
"bio5-fruit": [
  {id:"bio5-fruit-c1", front:"What is the difference between a true fruit and a false fruit?", back:"A <b>true fruit</b> develops only from the ovary; a <b>false fruit</b> develops from the ovary plus other floral parts (e.g. apple)."},
  {id:"bio5-fruit-c2", front:"What is parthenocarpy?", back:"Development of <b>fruit without fertilisation</b> (usually seedless)."}
,
  {id:"bio5-fruit-c5", front:"What is a true fruit versus a false fruit?", back:"A <b>true fruit</b> develops only from the fertilized <b>ovary</b> (e.g. mango); a <b>false fruit</b> develops from other floral parts like the <b>thalamus</b> (e.g. apple, cashew)."},
  {id:"bio5-fruit-c6", front:"Define pericarp and its three layers.", back:"The <b>pericarp</b> is the fruit wall developed from the ovary wall, differentiated into <b>epicarp</b>, <b>mesocarp</b>, and <b>endocarp</b>."}],
"bio5-seed": [
  {id:"bio5-seed-c1", front:"What are the two main parts of a seed?", back:"The <b>seed coat and the embryo</b>."},
  {id:"bio5-seed-c2", front:"What is the difference between epigeal and hypogeal germination?", back:"In <b>epigeal</b> germination the cotyledons come above the soil; in <b>hypogeal</b> germination they stay below."}
,
  {id:"bio5-seed-c5", front:"What is the function of the micropyle in a seed?", back:"The <b>micropyle</b> is a small pore that allows entry of <b>oxygen and water</b> into the seed during germination."},
  {id:"bio5-seed-c6", front:"Differentiate albuminous and non-albuminous seeds.", back:"<b>Albuminous seeds</b> retain endosperm at maturity (e.g. wheat, maize); <b>non-albuminous seeds</b> consume the endosperm during embryo development (e.g. pea, gram)."}],
"bio5-semi-technical-description-families": [
  {id:"bio5-semi-technical-description-families-c1", front:"What does a floral formula represent?", back:"A <b>shorthand notation summarising the number and arrangement</b> of floral whorls (calyx, corolla, androecium, gynoecium)."}
,
  {id:"bio5-semi-technical-description-families-c5", front:"What is a floral formula used to represent?", back:"A <b>floral formula</b> uses symbols and numbers to represent the number of <b>sepals, petals, stamens and carpels</b>, their union and floral symmetry."},
  {id:"bio5-semi-technical-description-families-c6", front:"Name the family to which pea (Pisum sativum) belongs and its key floral character.", back:"Pea belongs to family <b>Fabaceae</b>, characterized by <b>papilionaceous</b> corolla with standard, wing, and keel petals and diadelphous stamens."},
  {id:"bio5-semi-technical-description-families-c7", front:"What is a distinguishing floral characteristic of family Solanaceae?", back:"Solanaceae flowers are typically <b>actinomorphic</b>, bisexual, with 5 fused sepals and petals, <b>epipetalous</b> stamens, and a bicarpellary syncarpous ovary placed obliquely."}],
"bio6-meristematic-tissue": [
  {id:"bio6-meristematic-tissue-c1", front:"What are the three types of meristem based on location?", back:"<b>Apical, lateral, and intercalary</b> meristem."},
  {id:"bio6-meristematic-tissue-c2", front:"What is a distinguishing feature of meristematic cells?", back:"They are <b>thin-walled, living cells that actively divide</b>."}
,
  {id:"bio6-meristematic-tissue-c5", front:"Classify meristems based on position in the plant body.", back:"<b>Apical meristem</b> (at root/shoot tips), <b>intercalary meristem</b> (between mature tissues, e.g. grass nodes), and <b>lateral meristem</b> (cambium, parallel to organ sides)."},
  {id:"bio6-meristematic-tissue-c6", front:"What are the three primary meristems derived from the apical meristem?", back:"<b>Protoderm</b> (gives rise to epidermis), <b>ground meristem</b> (gives ground tissue), and <b>procambium</b> (gives vascular tissue)."}],
"bio6-permanent-tissue": [
  {id:"bio6-permanent-tissue-c1", front:"What is the difference between simple and complex permanent tissue?", back:"<b>Simple</b> tissue has one cell type (e.g. parenchyma); <b>complex</b> tissue has more than one cell type working together (e.g. xylem, phloem)."},
  {id:"bio6-permanent-tissue-c2", front:"What are the three types of simple permanent tissue?", back:"<b>Parenchyma, collenchyma, and sclerenchyma</b>."}
,
  {id:"bio6-permanent-tissue-c5", front:"Differentiate parenchyma, collenchyma and sclerenchyma by cell wall.", back:"<b>Parenchyma</b> has thin cellulose walls; <b>collenchyma</b> has unevenly thickened pectin/cellulose walls for flexible support; <b>sclerenchyma</b> has thick lignified walls with no living protoplasm at maturity."},
  {id:"bio6-permanent-tissue-c6", front:"What are the two types of sclerenchyma cells?", back:"<b>Fibres</b> (long, narrow, tapering cells) and <b>sclereids</b> (short, irregular-shaped cells, e.g. in pear grit)."}],
"bio6-tissue-systems": [
  {id:"bio6-tissue-systems-c1", front:"What are the three tissue systems of a plant, classified by position?", back:"<b>Epidermal, vascular, and ground tissue system</b>."}
,
  {id:"bio6-tissue-systems-c5", front:"Name the three tissue systems of a plant based on Sachs' classification.", back:"<b>Epidermal tissue system</b>, <b>ground (fundamental) tissue system</b>, and <b>vascular tissue system</b>."},
  {id:"bio6-tissue-systems-c6", front:"What is the function of guard cells in the epidermal tissue system?", back:"<b>Guard cells</b> flank the stomatal pore and regulate <b>gaseous exchange and transpiration</b> by controlling stomatal opening and closing."},
  {id:"bio6-tissue-systems-c7", front:"What is a vascular bundle, and name its two conducting tissues?", back:"A <b>vascular bundle</b> is a strand of conducting tissue containing <b>xylem</b> (water/mineral transport) and <b>phloem</b> (food transport)."}],
"bio6-anatomy-dicot-monocot-roots": [
  {id:"bio6-anatomy-dicot-monocot-roots-c1", front:"How does the number of xylem bundles typically differ between dicot and monocot roots?", back:"<b>Dicot roots</b> have few (2-6) xylem bundles; <b>monocot roots</b> have many (more than 6)."},
  {id:"bio6-anatomy-dicot-monocot-roots-c2", front:"How does pith size typically compare between dicot and monocot roots?", back:"<b>Monocot roots</b> have a large, well-developed pith; <b>dicot roots</b> have little or no pith."}
,
  {id:"bio6-anatomy-dicot-monocot-roots-c5", front:"How does xylem arrangement differ between dicot and monocot roots?", back:"Dicot roots usually show <b>2-4 xylem arches</b> with a small pith; monocot roots are <b>polyarch</b> (many xylem groups) with a large, well-developed pith."},
  {id:"bio6-anatomy-dicot-monocot-roots-c6", front:"What is the pericycle's role in root anatomy?", back:"The <b>pericycle</b>, located just inside the endodermis, gives rise to <b>lateral roots</b> and contributes to secondary growth initiation."}],
"bio6-anatomy-dicot-monocot-stems": [
  {id:"bio6-anatomy-dicot-monocot-stems-c1", front:"How are vascular bundles arranged in dicot vs monocot stems?", back:"<b>Dicot stems</b> have bundles arranged in a ring; <b>monocot stems</b> have bundles scattered throughout."},
  {id:"bio6-anatomy-dicot-monocot-stems-c2", front:"Do monocot vascular bundles have cambium?", back:"<b>No</b> — monocot bundles are conjoint and closed (no cambium), so no secondary growth."}
,
  {id:"bio6-anatomy-dicot-monocot-stems-c5", front:"How is vascular bundle arrangement different in dicot vs monocot stems?", back:"Dicot stems have vascular bundles arranged in a <b>ring</b>, and are <b>conjoint, collateral, open</b> (with cambium); monocot stems have bundles <b>scattered</b> and are <b>closed</b> (no cambium)."},
  {id:"bio6-anatomy-dicot-monocot-stems-c6", front:"What is a bundle sheath in monocot stems?", back:"A layer of <b>sclerenchymatous cells</b> surrounding each scattered vascular bundle that provides mechanical support."}],
"bio6-anatomy-dicot-monocot-leaves": [
  {id:"bio6-anatomy-dicot-monocot-leaves-c1", front:"What is the difference between a dorsiventral and an isobilateral leaf?", back:"A <b>dorsiventral</b> leaf (dicot) has distinct upper/lower surfaces; an <b>isobilateral</b> leaf (monocot) looks the same on both surfaces."}
,
  {id:"bio6-anatomy-dicot-monocot-leaves-c5", front:"What is the key difference in mesophyll organization between dicot and monocot leaves?", back:"Dicot leaves show <b>dorsiventral</b> structure with differentiated <b>palisade and spongy parenchyma</b>; monocot leaves are <b>isobilateral</b> with undifferentiated mesophyll."},
  {id:"bio6-anatomy-dicot-monocot-leaves-c6", front:"What are bulliform cells and their function?", back:"Large, empty, thin-walled cells on the upper epidermis of monocot leaves (e.g. grasses) that help in <b>rolling/folding leaves</b> to reduce water loss during drought."},
  {id:"bio6-anatomy-dicot-monocot-leaves-c7", front:"Where are stomata typically located in dicot vs monocot leaves?", back:"In dicot leaves stomata are more numerous on the <b>lower (abaxial)</b> surface; in monocot leaves stomata are distributed <b>equally on both surfaces</b>."}],
"bio6-secondary-growth": [
  {id:"bio6-secondary-growth-c1", front:"What causes secondary growth in stems and roots?", back:"Activity of <b>secondary/lateral meristems</b> (vascular cambium and cork cambium)."},
  {id:"bio6-secondary-growth-c2", front:"What does secondary growth produce?", back:"<b>Increase in girth</b> — additional wood (secondary xylem) and bark."}
,
  {id:"bio6-secondary-growth-c5", front:"How is the cambial ring formed in dicot stems during secondary growth?", back:"The <b>intrafascicular cambium</b> (within vascular bundles) connects with newly formed <b>interfascicular cambium</b> to form a continuous <b>cambial ring</b>."},
  {id:"bio6-secondary-growth-c6", front:"Differentiate spring wood and autumn wood.", back:"<b>Spring wood (early wood)</b> has larger xylem vessels and is lighter, less dense; <b>autumn wood (late wood)</b> has smaller vessels and is darker, denser; together they form <b>annual rings</b>."}],
"bio7-animal-tissues-overview": [
  {id:"bio7-animal-tissues-overview-c1", front:"What are the four basic animal tissue types?", back:"<b>Epithelial, connective, muscular, and nervous</b> tissue."}
,
  {id:"bio7-animal-tissues-overview-c5", front:"Name the four basic types of animal tissues.", back:"<b>Epithelial</b>, <b>connective</b>, <b>muscular</b>, and <b>nervous</b> tissue."},
  {id:"bio7-animal-tissues-overview-c6", front:"What defines a tissue?", back:"A <b>tissue</b> is a group of similar cells, along with intercellular substances, that work together to perform a specific function."},
  {id:"bio7-animal-tissues-overview-c7", front:"Which tissue type covers body surfaces and lines internal cavities?", back:"<b>Epithelial tissue</b>, which forms a continuous protective sheet over the body and lines internal cavities and organs."}],
"bio7-epithelial-tissue": [
  {id:"bio7-epithelial-tissue-c1", front:"What is the main function of epithelial tissue?", back:"<b>Protection and secretion</b> (lining/covering surfaces)."},
  {id:"bio7-epithelial-tissue-c2", front:"What is the difference between simple and stratified epithelium?", back:"<b>Simple</b> epithelium is one cell layer thick; <b>stratified</b> epithelium has multiple layers."}
,
  {id:"bio7-epithelial-tissue-c5", front:"Differentiate simple and compound epithelium.", back:"<b>Simple epithelium</b> is a single layer of cells involved in absorption/secretion; <b>compound epithelium</b> has multiple cell layers and mainly provides <b>protection</b> (e.g. skin)."},
  {id:"bio7-epithelial-tissue-c6", front:"What is the function of ciliated columnar epithelium?", back:"It lines the <b>fallopian tubes and bronchioles</b>; its cilia beat to move mucus, particles, or the ovum in a specific direction."}],
"bio7-connective-tissue": [
  {id:"bio7-connective-tissue-c1", front:"What is the main function of connective tissue?", back:"<b>Binding and supporting</b> other tissues and organs."},
  {id:"bio7-connective-tissue-c2", front:"Name three types of connective tissue.", back:"<b>Areolar tissue, adipose tissue, and bone</b>."}
,
  {id:"bio7-connective-tissue-c5", front:"Name the three main categories of connective tissue.", back:"<b>Loose connective tissue</b> (e.g. areolar), <b>dense connective tissue</b> (e.g. tendons, ligaments), and <b>specialized connective tissue</b> (cartilage, bone, blood)."},
  {id:"bio7-connective-tissue-c6", front:"Differentiate tendons and ligaments.", back:"<b>Tendons</b> connect muscle to bone and are made of parallel <b>collagen fibres</b>; <b>ligaments</b> connect bone to bone and are more <b>elastic</b>."}],
"bio7-muscular-nervous-tissue": [
  {id:"bio7-muscular-nervous-tissue-c1", front:"What are the three types of muscle tissue?", back:"<b>Skeletal (striated), smooth, and cardiac</b> muscle."},
  {id:"bio7-muscular-nervous-tissue-c2", front:"What is the basic functional unit of nervous tissue?", back:"The <b>neuron</b>."}
,
  {id:"bio7-muscular-nervous-tissue-c5", front:"Differentiate striated, unstriated and cardiac muscle.", back:"<b>Striated (skeletal) muscle</b> is voluntary with visible bands; <b>unstriated (smooth) muscle</b> is involuntary and spindle-shaped; <b>cardiac muscle</b> is involuntary, striated, with <b>intercalated discs</b>."},
  {id:"bio7-muscular-nervous-tissue-c6", front:"What is the basic structural and functional unit of nervous tissue?", back:"The <b>neuron</b>, comprising a cell body (cyton), dendrites, and an axon that conducts nerve impulses."}],
"bio7-frog-digestive-circulatory": [
  {id:"bio7-frog-digestive-circulatory-c1", front:"How many chambers does a frog's heart have?", back:"<b>Three</b> — two atria and one ventricle."}
,
  {id:"bio7-frog-digestive-circulatory-c5", front:"What type of circulatory system does a frog have, and how many heart chambers?", back:"Frogs have a <b>closed circulatory system</b> with a <b>three-chambered heart</b> (two atria, one ventricle)."},
  {id:"bio7-frog-digestive-circulatory-c6", front:"Name the parts of the frog's digestive tract from mouth to cloaca.", back:"<b>Buccal cavity → oesophagus → stomach → small intestine → large intestine → rectum → cloaca</b>."},
  {id:"bio7-frog-digestive-circulatory-c7", front:"What is the role of the frog's liver and gall bladder in digestion?", back:"The <b>liver</b> secretes <b>bile</b>, stored in the <b>gall bladder</b>, which helps emulsify fats for digestion in the small intestine."}],
"bio7-frog-respiratory-nervous-reproductive": [
  {id:"bio7-frog-respiratory-nervous-reproductive-c1", front:"What two modes of respiration does a frog use?", back:"<b>Cutaneous (through skin) and pulmonary (through lungs)</b> respiration."},
  {id:"bio7-frog-respiratory-nervous-reproductive-c2", front:"Is a frog monoecious or dioecious?", back:"<b>Dioecious</b> — sexes are separate."}
,
  {id:"bio7-frog-respiratory-nervous-reproductive-c5", front:"How does a frog respire in water versus on land?", back:"In water, a frog respires through its moist <b>skin (cutaneous respiration)</b>; on land, it uses <b>buccal cavity and lung (pulmonary) respiration</b>."},
  {id:"bio7-frog-respiratory-nervous-reproductive-c6", front:"Is fertilization in frogs internal or external, and where does it occur?", back:"Fertilization in frogs is <b>external</b>, occurring in <b>water</b> during amplexus, when the female releases eggs and the male releases sperm over them."}],
"bio8-cell-theory-basic-unit": [
  {id:"bio8-cell-theory-basic-unit-c1", front:"What does cell theory state?", back:"<b>All living organisms are composed of cells, and the cell is the basic unit of life</b>."},
  {id:"bio8-cell-theory-basic-unit-c2", front:"Who extended cell theory to state all cells arise from pre-existing cells?", back:"<b>Rudolf Virchow</b>."}
,
  {id:"bio8-cell-theory-basic-unit-c5", front:"State the three tenets of the modern cell theory.", back:"All living organisms are composed of <b>cells</b>; the cell is the basic <b>structural and functional unit</b> of life; all cells arise from <b>pre-existing cells</b> (Virchow)."},
  {id:"bio8-cell-theory-basic-unit-c6", front:"Who discovered the cell and in what material?", back:"<b>Robert Hooke</b> discovered cells in 1665 while examining a thin slice of <b>cork</b> under a microscope."}],
"bio8-prokaryotic-eukaryotic-cells": [
  {id:"bio8-prokaryotic-eukaryotic-cells-c1", front:"What is the defining difference between prokaryotic and eukaryotic cells?", back:"Eukaryotic cells have a <b>true, membrane-bound nucleus</b>; prokaryotic cells do not."}
,
  {id:"bio8-prokaryotic-eukaryotic-cells-c5", front:"What is a nucleoid?", back:"In prokaryotic cells, the <b>nucleoid</b> is an undefined nuclear region containing a single, circular, naked (non-histone bound) <b>DNA</b> molecule."},
  {id:"bio8-prokaryotic-eukaryotic-cells-c6", front:"Name two membrane-bound organelles absent in prokaryotic cells.", back:"Prokaryotes lack a true <b>nucleus (nuclear membrane)</b> and membrane-bound organelles such as <b>mitochondria and chloroplasts</b>."},
  {id:"bio8-prokaryotic-eukaryotic-cells-c7", front:"What are mesosomes in bacterial cells?", back:"<b>Mesosomes</b> are infoldings of the plasma membrane that aid in <b>cell wall formation, DNA replication, and respiration</b> in bacteria."}],
"bio8-cell-envelope": [
  {id:"bio8-cell-envelope-c1", front:"What model describes the structure of the plasma membrane?", back:"The <b>fluid mosaic model</b>."},
  {id:"bio8-cell-envelope-c2", front:"What is the main function of the cell wall?", back:"Providing <b>rigidity and protection</b> to the cell."}
,
  {id:"bio8-cell-envelope-c5", front:"What is the fluid mosaic model of the plasma membrane?", back:"Proposed by <b>Singer and Nicolson</b>, it describes the membrane as a mosaic of <b>proteins embedded in a fluid phospholipid bilayer</b>."},
  {id:"bio8-cell-envelope-c6", front:"What is the main chemical composition of the plant cell wall?", back:"Primarily <b>cellulose</b>, along with hemicellulose, pectin and proteins, providing shape and protection against osmotic lysis."}],
"bio8-endomembrane-system": [
  {id:"bio8-endomembrane-system-c1", front:"What is the difference between rough and smooth endoplasmic reticulum?", back:"<b>Rough ER</b> has ribosomes and makes proteins; <b>smooth ER</b> lacks ribosomes and makes lipids."},
  {id:"bio8-endomembrane-system-c2", front:"What is the main function of the Golgi apparatus?", back:"<b>Packaging and secretion</b> of materials from the ER."},
  {id:"bio8-endomembrane-system-c3", front:"What is the main function of a lysosome?", back:"<b>Intracellular digestion</b> using hydrolytic enzymes."}
,
  {id:"bio8-endomembrane-system-c5", front:"Name the organelles that constitute the endomembrane system.", back:"The <b>endoplasmic reticulum</b>, <b>Golgi apparatus</b>, <b>lysosomes</b>, and <b>vacuoles</b>, since their functions are structurally and functionally coordinated."}],
"bio8-mitochondria-plastids-other-organelles": [
  {id:"bio8-mitochondria-plastids-other-organelles-c1", front:"Why is the mitochondrion called the powerhouse of the cell?", back:"It is the site of <b>aerobic respiration and ATP production</b>."},
  {id:"bio8-mitochondria-plastids-other-organelles-c2", front:"What is the function of a chloroplast?", back:"The site of <b>photosynthesis</b>."},
  {id:"bio8-mitochondria-plastids-other-organelles-c3", front:"What is the main function of ribosomes?", back:"<b>Protein synthesis</b>."}
,
  {id:"bio8-mitochondria-plastids-other-organelles-c5", front:"Why is the mitochondrion called the 'powerhouse of the cell'?", back:"It is the site of <b>aerobic respiration</b>, producing most of the cell's <b>ATP</b>, and contains its own circular <b>DNA</b>."}],
"bio8-cytoskeleton-cell-appendages": [
  {id:"bio8-cytoskeleton-cell-appendages-c1", front:"What is the main function of the cytoskeleton?", back:"Providing <b>mechanical support, shape, and enabling movement</b> of cell components."},
  {id:"bio8-cytoskeleton-cell-appendages-c2", front:"What is the difference between cilia and flagella?", back:"<b>Cilia</b> are short and numerous; <b>flagella</b> are long and fewer — both aid movement."}
,
  {id:"bio8-cytoskeleton-cell-appendages-c5", front:"What are the three components of the cytoskeleton?", back:"<b>Microtubules</b>, <b>microfilaments</b>, and <b>intermediate filaments</b>, which provide mechanical support, motility, and shape."},
  {id:"bio8-cytoskeleton-cell-appendages-c6", front:"Differentiate cilia and flagella.", back:"<b>Cilia</b> are numerous, short, hair-like structures producing wave-like movement; <b>flagella</b> are longer, fewer in number, and produce whip-like movement for locomotion."}],
"bio8-nucleus": [
  {id:"bio8-nucleus-c1", front:"What separates the nucleus from the cytoplasm?", back:"The <b>nuclear envelope</b> (double membrane, with nuclear pores)."},
  {id:"bio8-nucleus-c2", front:"What is chromatin?", back:"The <b>DNA-protein complex</b> that condenses into chromosomes during cell division."}
,
  {id:"bio8-nucleus-c5", front:"Who discovered the nucleus and when?", back:"<b>Robert Brown</b> discovered the nucleus in 1831 as a spherical, dense structure within the cell."},
  {id:"bio8-nucleus-c6", front:"What passes through the nuclear pores?", back:"Nuclear pores allow the transport of <b>RNA and proteins</b> between the <b>nucleus and cytoplasm</b>."}],
"bio9-proteins": [
  {id:"bio9-proteins-c1", front:"What is the monomer unit of a protein?", back:"<b>Amino acids</b>."},
  {id:"bio9-proteins-c2", front:"What bond links amino acids together in a protein?", back:"The <b>peptide bond</b>."}
,
  {id:"bio9-proteins-c5", front:"What type of bond links amino acids in a protein?", back:"A <b>peptide bond</b>, formed between the carboxyl group (-COOH) of one amino acid and the amino group (-NH2) of another."},
  {id:"bio9-proteins-c6", front:"Differentiate primary and secondary structure of proteins.", back:"<b>Primary structure</b> is the linear sequence of amino acids; <b>secondary structure</b> refers to regular folding patterns like the <b>alpha helix</b> and <b>beta pleated sheet</b>."}],
"bio9-carbohydrates": [
  {id:"bio9-carbohydrates-c1", front:"What are the three classes of carbohydrates by size?", back:"<b>Monosaccharides, disaccharides, and polysaccharides</b>."},
  {id:"bio9-carbohydrates-c2", front:"What bond links sugar units together?", back:"The <b>glycosidic bond</b>."}
,
  {id:"bio9-carbohydrates-c5", front:"Classify carbohydrates based on their hydrolysis products.", back:"<b>Monosaccharides</b> (cannot be hydrolysed further, e.g. glucose), <b>oligosaccharides</b> (2-10 units, e.g. sucrose), and <b>polysaccharides</b> (many units, e.g. starch, cellulose)."},
  {id:"bio9-carbohydrates-c6", front:"What type of bond joins two glucose units in maltose?", back:"A <b>glycosidic bond</b>, formed between the -OH groups of two monosaccharides with the loss of water."}],
"bio9-lipids": [
  {id:"bio9-lipids-c1", front:"What two components make up a typical fat (triglyceride)?", back:"<b>Glycerol and fatty acids</b>."},
  {id:"bio9-lipids-c2", front:"What is the difference between saturated and unsaturated fatty acids?", back:"<b>Saturated</b> fatty acids have no double bonds; <b>unsaturated</b> ones have one or more C=C double bonds."}
,
  {id:"bio9-lipids-c5", front:"What distinguishes a saturated fatty acid from an unsaturated fatty acid?", back:"<b>Saturated fatty acids</b> have no double bonds between carbon atoms; <b>unsaturated fatty acids</b> have one or more <b>double bonds</b>."},
  {id:"bio9-lipids-c6", front:"What type of bond links glycerol to fatty acids in a triglyceride?", back:"An <b>ester bond</b>, formed by dehydration/condensation between the -OH group of glycerol and the -COOH group of a fatty acid."}],
"bio9-nucleic-acids": [
  {id:"bio9-nucleic-acids-c1", front:"What is the basic structural difference between DNA and RNA?", back:"<b>DNA</b> is usually double-stranded with deoxyribose sugar; <b>RNA</b> is usually single-stranded with ribose sugar."}
,
  {id:"bio9-nucleic-acids-c5", front:"What are the building blocks of a nucleic acid called?", back:"<b>Nucleotides</b>, each composed of a nitrogenous base, a pentose sugar, and a phosphate group."},
  {id:"bio9-nucleic-acids-c6", front:"Name the purine and pyrimidine bases found in DNA.", back:"Purines: <b>adenine and guanine</b>; pyrimidines: <b>cytosine and thymine</b> (uracil replaces thymine in RNA)."},
  {id:"bio9-nucleic-acids-c7", front:"What type of bond links adjacent nucleotides in a nucleic acid strand?", back:"A <b>phosphodiester bond</b>, connecting the 3' carbon of one sugar to the 5' phosphate of the next nucleotide."}],
"bio9-enzymes": [
  {id:"bio9-enzymes-c1", front:"What part of an enzyme binds the substrate?", back:"The <b>active site</b>."},
  {id:"bio9-enzymes-c2", front:"Name two factors that affect enzyme activity.", back:"<b>Temperature and pH</b>."}
,
  {id:"bio9-enzymes-c5", front:"What is the active site of an enzyme?", back:"A specific region of the enzyme where the <b>substrate</b> binds and the catalytic reaction occurs."},
  {id:"bio9-enzymes-c6", front:"Name the two models explaining enzyme-substrate binding.", back:"The <b>lock and key model</b> (rigid fit) and the <b>induced fit model</b> (enzyme changes shape upon substrate binding)."}],
"bio10-cell-cycle": [
  {id:"bio10-cell-cycle-c1", front:"What are the two main phases of the cell cycle?", back:"<b>Interphase and M phase (mitotic phase)</b>."},
  {id:"bio10-cell-cycle-c2", front:"What are the three sub-phases of interphase?", back:"<b>G1 (growth), S (DNA synthesis), and G2 (growth before division)</b>."}
,
  {id:"bio10-cell-cycle-c5", front:"What are the two main phases of the cell cycle?", back:"<b>Interphase</b> (preparatory phase) and <b>M phase</b> (mitotic/division phase)."},
  {id:"bio10-cell-cycle-c6", front:"What are the sub-phases of interphase?", back:"<b>G1</b> (Gap 1), <b>S</b> (Synthesis, DNA replication), and <b>G2</b> (Gap 2)."}],
"bio10-mitosis": [
  {id:"bio10-mitosis-c1", front:"What are the four main stages of mitosis, in order?", back:"<b>Prophase, metaphase, anaphase, telophase</b>."},
  {id:"bio10-mitosis-c2", front:"What is the result of mitosis?", back:"<b>Two genetically identical diploid daughter cells</b> from one parent cell."}
,
  {id:"bio10-mitosis-c5", front:"What is the significance of mitosis?", back:"It produces two genetically identical <b>diploid</b> daughter cells and is responsible for <b>growth</b> and repair/replacement of somatic cells."},
  {id:"bio10-mitosis-c6", front:"During which phase of mitosis do chromosomes align at the equatorial plate?", back:"<b>Metaphase</b>, when chromosomes align at the equatorial/metaphase plate held by <b>spindle fibers</b> attached at the kinetochore."}],
"bio10-meiosis": [
  {id:"bio10-meiosis-c1", front:"What is the result of meiosis?", back:"<b>Four haploid daughter cells</b>, each with half the chromosome number."},
  {id:"bio10-meiosis-c2", front:"What is the key difference between meiosis I and meiosis II?", back:"<b>Meiosis I</b> is reductional (halves chromosome number); <b>meiosis II</b> is equational (like mitosis)."}
,
  {id:"bio10-meiosis-c5", front:"What is synapsis?", back:"Pairing of <b>homologous chromosomes</b> during the zygotene sub-stage of prophase I, forming a <b>bivalent (tetrad)</b>."},
  {id:"bio10-meiosis-c6", front:"What is the significance of meiosis?", back:"It keeps the chromosome number constant across generations by reducing diploid to <b>haploid</b>, and generates <b>genetic variation</b> via crossing over and independent assortment."}],
"bio10-comparing-mitosis-meiosis": [
  {id:"bio10-comparing-mitosis-meiosis-c1", front:"In which division does crossing over occur: mitosis or meiosis?", back:"<b>Meiosis</b> (during prophase I)."}
,
  {id:"bio10-comparing-mitosis-meiosis-c5", front:"How many daughter cells are produced by mitosis versus meiosis?", back:"Mitosis produces two <b>diploid</b> daughter cells; meiosis produces four <b>haploid</b> daughter cells."},
  {id:"bio10-comparing-mitosis-meiosis-c6", front:"Which division involves crossing over, mitosis or meiosis?", back:"<b>Meiosis I</b>, specifically during the pachytene sub-stage of prophase I; crossing over does not occur in mitosis."},
  {id:"bio10-comparing-mitosis-meiosis-c7", front:"Compare the genetic identity of daughter cells produced by mitosis and meiosis.", back:"Mitosis gives <b>genetically identical</b> daughter cells; meiosis gives <b>genetically variable</b> daughter cells due to crossing over and independent assortment."}],
"bio11-photosynthesis-overview-site": [
  {id:"bio11-photosynthesis-overview-site-c1", front:"Where does photosynthesis take place in a plant cell?", back:"In the <b>chloroplast</b>."},
  {id:"bio11-photosynthesis-overview-site-c2", front:"What is the main photosynthetic pigment?", back:"<b>Chlorophyll a</b>."}
,
  {id:"bio11-photosynthesis-overview-site-c5", front:"Where do the light and dark reactions of photosynthesis occur?", back:"Light reactions occur in the <b>thylakoid membrane</b>; dark reactions (Calvin cycle) occur in the <b>stroma</b> of the chloroplast."},
  {id:"bio11-photosynthesis-overview-site-c6", front:"What two products of the light reaction are used in the dark reaction?", back:"<b>ATP</b> and <b>NADPH</b>, together called assimilatory power."}],
"bio11-light-reactions": [
  {id:"bio11-light-reactions-c1", front:"What two photosystems are involved in the light reactions?", back:"<b>Photosystem I (PSI) and Photosystem II (PSII)</b>."},
  {id:"bio11-light-reactions-c2", front:"What is released when water is split during the light reaction?", back:"<b>Oxygen</b> (along with electrons and protons)."}
,
  {id:"bio11-light-reactions-c5", front:"What is photolysis of water?", back:"Splitting of water molecules by <b>Photosystem II</b>, releasing O2, protons, and electrons; also known as the <b>Hill reaction</b>."},
  {id:"bio11-light-reactions-c6", front:"What is the difference between cyclic and non-cyclic photophosphorylation?", back:"<b>Cyclic</b> photophosphorylation involves only PSI and produces only ATP; <b>non-cyclic</b> involves both PSI and PSII and produces ATP, NADPH, and O2."}],
"bio11-chemiosmotic-hypothesis": [
  {id:"bio11-chemiosmotic-hypothesis-c1", front:"What drives ATP synthesis according to the chemiosmotic hypothesis?", back:"A <b>proton gradient across the thylakoid membrane</b>, dissipated through ATP synthase."}
,
  {id:"bio11-chemiosmotic-hypothesis-c5", front:"What does the chemiosmotic hypothesis explain?", back:"It explains ATP synthesis in chloroplasts through a <b>proton gradient</b> across the thylakoid membrane driving <b>ATP synthase</b>."},
  {id:"bio11-chemiosmotic-hypothesis-c6", front:"Where does the proton gradient build up during photophosphorylation?", back:"In the <b>thylakoid lumen</b>, due to splitting of water, electron transport pumping H+ across the membrane, and NADP reductase removing H+ from the stroma."},
  {id:"bio11-chemiosmotic-hypothesis-c7", front:"Which enzyme complex uses the proton gradient to synthesize ATP?", back:"<b>ATP synthase</b> (CF0-CF1 particle), located on the thylakoid membrane."}],
"bio11-calvin-cycle-biosynthetic-phase": [
  {id:"bio11-calvin-cycle-biosynthetic-phase-c1", front:"What are the three phases of the Calvin cycle?", back:"<b>Carboxylation, reduction, and regeneration</b>."},
  {id:"bio11-calvin-cycle-biosynthetic-phase-c2", front:"What enzyme fixes CO2 in the Calvin cycle?", back:"<b>RuBisCO</b>."}
,
  {id:"bio11-calvin-cycle-biosynthetic-phase-c5", front:"What are the three stages of the Calvin cycle?", back:"<b>Carboxylation</b>, <b>reduction</b>, and <b>regeneration</b> of RuBP."},
  {id:"bio11-calvin-cycle-biosynthetic-phase-c6", front:"How many ATP and NADPH are needed to synthesize one glucose molecule in the Calvin cycle?", back:"<b>18 ATP</b> and <b>12 NADPH</b>."}],
"bio11-c4-pathway-photorespiration": [
  {id:"bio11-c4-pathway-photorespiration-c1", front:"What is the first stable product of CO2 fixation in C3 vs C4 plants?", back:"<b>C3 plants</b>: PGA (3-carbon); <b>C4 plants</b>: OAA (4-carbon, oxaloacetic acid)."},
  {id:"bio11-c4-pathway-photorespiration-c2", front:"Why is photorespiration considered wasteful?", back:"It <b>consumes O2 and releases CO2 without producing ATP or sugar</b>."}
,
  {id:"bio11-c4-pathway-photorespiration-c5", front:"What is the first stable product of CO2 fixation in C4 plants?", back:"<b>Oxaloacetic acid (OAA)</b>, a 4-carbon compound formed via <b>PEP carboxylase</b> in mesophyll cells."},
  {id:"bio11-c4-pathway-photorespiration-c6", front:"Why does photorespiration not occur in C4 plants?", back:"<b>Bundle sheath cells</b> maintain a high CO2 concentration around RuBisCO, suppressing its <b>oxygenase activity</b>."}],
"bio11-factors-affecting-photosynthesis": [
  {id:"bio11-factors-affecting-photosynthesis-c1", front:"What does Blackman's law of limiting factors state?", back:"The <b>rate of a process is limited by whichever factor is in shortest supply</b>."}
,
  {id:"bio11-factors-affecting-photosynthesis-c5", front:"State the Law of Limiting Factors.", back:"When a process depends on several factors, its rate is limited by the factor nearest its <b>minimum value</b> (Blackman's law)."},
  {id:"bio11-factors-affecting-photosynthesis-c6", front:"How does light intensity affect the rate of photosynthesis?", back:"Rate increases with <b>light intensity</b> up to a point, then plateaus even with further increase because other factors become limiting."},
  {id:"bio11-factors-affecting-photosynthesis-c7", front:"How does temperature affect the rate of photosynthesis?", back:"Since the dark reactions are enzymatic, rate increases with <b>temperature</b> up to an optimum (25-35°C), then declines due to <b>enzyme denaturation</b>."}],
"bio12-respiration-basics-glycolysis": [
  {id:"bio12-respiration-basics-glycolysis-c1", front:"Where does glycolysis take place?", back:"In the <b>cytoplasm</b>."},
  {id:"bio12-respiration-basics-glycolysis-c2", front:"What is the end product of glycolysis?", back:"<b>Pyruvate</b> (pyruvic acid)."}
,
  {id:"bio12-respiration-basics-glycolysis-c5", front:"Where does glycolysis occur in the cell?", back:"In the <b>cytoplasm</b> (cytosol)."},
  {id:"bio12-respiration-basics-glycolysis-c6", front:"What is the end product of glycolysis and its net ATP/NADH yield?", back:"Two molecules of <b>pyruvate</b>, with a net gain of <b>2 ATP</b> and <b>2 NADH</b> per glucose."}],
"bio12-fermentation-anaerobic-respiration": [
  {id:"bio12-fermentation-anaerobic-respiration-c1", front:"What happens to pyruvate in the absence of oxygen (fermentation)?", back:"It is converted to <b>ethanol or lactic acid</b>."}
,
  {id:"bio12-fermentation-anaerobic-respiration-c5", front:"What are the end products of alcoholic fermentation?", back:"<b>Ethanol</b> and <b>CO2</b>, via pyruvic acid decarboxylase and alcohol dehydrogenase."},
  {id:"bio12-fermentation-anaerobic-respiration-c6", front:"What is the end product of lactic acid fermentation?", back:"<b>Lactic acid</b>, formed by reduction of pyruvate via lactate dehydrogenase, occurring in muscle cells and some bacteria."},
  {id:"bio12-fermentation-anaerobic-respiration-c7", front:"Why is fermentation energetically less efficient than aerobic respiration?", back:"It yields only <b>2 ATP</b> per glucose from glycolysis with incomplete oxidation, versus about <b>36-38 ATP</b> in aerobic respiration."}],
"bio12-krebs-cycle-tca-cycle": [
  {id:"bio12-krebs-cycle-tca-cycle-c1", front:"Where does the Krebs cycle occur?", back:"In the <b>mitochondrial matrix</b>."}
,
  {id:"bio12-krebs-cycle-tca-cycle-c5", front:"Where does the Krebs cycle occur?", back:"In the <b>mitochondrial matrix</b>."},
  {id:"bio12-krebs-cycle-tca-cycle-c6", front:"What is the direct ATP yield from one turn of the Krebs cycle?", back:"<b>1 ATP</b> (as GTP) via substrate-level phosphorylation, along with <b>3 NADH</b> and <b>1 FADH2</b>."},
  {id:"bio12-krebs-cycle-tca-cycle-c7", front:"Which molecule combines with acetyl CoA to start the Krebs cycle?", back:"<b>Oxaloacetic acid (OAA)</b> combines with acetyl CoA to form <b>citric acid</b>, a 6-carbon compound."}],
"bio12-etc-oxidative-phosphorylation": [
  {id:"bio12-etc-oxidative-phosphorylation-c1", front:"Where does the electron transport chain occur?", back:"On the <b>inner mitochondrial membrane</b>."},
  {id:"bio12-etc-oxidative-phosphorylation-c2", front:"What is the final electron acceptor of the electron transport chain?", back:"<b>Oxygen</b>."}
,
  {id:"bio12-etc-oxidative-phosphorylation-c5", front:"Where is the electron transport chain (ETC) located?", back:"On the <b>inner mitochondrial membrane</b>."},
  {id:"bio12-etc-oxidative-phosphorylation-c6", front:"Which complex is the terminal electron acceptor in the ETC and what does it produce?", back:"<b>Complex IV (cytochrome oxidase)</b> transfers electrons to O2, forming <b>H2O</b>."}],
"bio12-respiratory-balance-sheet-quotient": [
  {id:"bio12-respiratory-balance-sheet-quotient-c1", front:"How is respiratory quotient (RQ) calculated?", back:"<b>RQ = volume of CO2 evolved / volume of O2 consumed</b>."}
,
  {id:"bio12-respiratory-balance-sheet-quotient-c5", front:"What is the Respiratory Quotient (RQ)?", back:"RQ = volume of <b>CO2 evolved</b> / volume of <b>O2 consumed</b>."},
  {id:"bio12-respiratory-balance-sheet-quotient-c6", front:"What is the RQ value for carbohydrate respiration?", back:"RQ = <b>1</b>, since equal volumes of CO2 are released and O2 consumed."},
  {id:"bio12-respiratory-balance-sheet-quotient-c7", front:"What is the RQ for fat respiration, and why?", back:"RQ is less than 1 (about <b>0.7</b>) because fats contain less oxygen relative to carbon and hydrogen, requiring more O2 for complete oxidation."}],
"bio13-seed-germination-growth-phases": [
  {id:"bio13-seed-germination-growth-phases-c1", front:"What are the three phases of a typical plant growth curve?", back:"<b>Lag, log (exponential), and senescent (stationary/declining) phase</b>."}
,
  {id:"bio13-seed-germination-growth-phases-c5", front:"What are the three phases of the plant growth curve?", back:"<b>Lag phase</b>, <b>log (exponential) phase</b>, and <b>stationary phase</b>, together forming a sigmoid growth curve."},
  {id:"bio13-seed-germination-growth-phases-c6", front:"What is imbibition in seed germination?", back:"Absorption of <b>water</b> by the dry seed causing it to swell, soften the seed coat, and activate metabolism."},
  {id:"bio13-seed-germination-growth-phases-c7", front:"Define absolute and relative growth rate.", back:"<b>Absolute growth rate</b> is the total growth per unit time; <b>relative growth rate</b> is growth per unit time expressed on a common basis, such as initial size."}],
"bio13-differentiation-dedifferentiation-redifferentiation": [
  {id:"bio13-differentiation-dedifferentiation-redifferentiation-c1", front:"What is differentiation in plants?", back:"Cells derived from meristems <b>mature and take up a specific structure and function</b>."},
  {id:"bio13-differentiation-dedifferentiation-redifferentiation-c2", front:"What is dedifferentiation?", back:"<b>Differentiated cells regain the ability to divide</b> under certain conditions."}
,
  {id:"bio13-differentiation-dedifferentiation-redifferentiation-c5", front:"What is dedifferentiation?", back:"The process by which living <b>differentiated cells</b> regain the capacity to divide, e.g., parenchyma forming <b>interfascicular cambium</b>."},
  {id:"bio13-differentiation-dedifferentiation-redifferentiation-c6", front:"What is redifferentiation?", back:"Dedifferentiated cells that divide and then <b>mature</b> to perform specific functions again, e.g., cork cambium forming <b>cork</b>."}],
"bio13-sequence-development": [
  {id:"bio13-sequence-development-c1", front:"What is the order of events in plant development?", back:"<b>Growth → differentiation → development</b> (growth and differentiation together make up development)."}
,
  {id:"bio13-sequence-development-c5", front:"What is the correct sequence of developmental processes in a plant?", back:"<b>Growth</b> → <b>differentiation</b> → <b>dedifferentiation</b> → <b>redifferentiation</b>, giving rise to the mature plant body."},
  {id:"bio13-sequence-development-c6", front:"Define differentiation in plants.", back:"Cells derived from apical and cambial <b>meristems</b> undergo structural and functional changes to mature and perform specific roles."},
  {id:"bio13-sequence-development-c7", front:"What is meant by plant growth being \"open\" and \"indeterminate\"?", back:"Plants retain the capacity for <b>unlimited growth</b> throughout life due to persistent <b>meristems</b> that add new cells and organs continuously."}],
"bio13-auxins": [
  {id:"bio13-auxins-c1", front:"What is apical dominance and which hormone causes it?", back:"<b>Auxin</b> suppresses growth of lateral (axillary) buds while the apical bud grows."},
  {id:"bio13-auxins-c2", front:"What is the first auxin discovered, isolated from human urine?", back:"<b>IAA (indole-3-acetic acid)</b>."}
,
  {id:"bio13-auxins-c5", front:"Who isolated auxin, and from what source?", back:"<b>F.W. Went</b> isolated auxin from <b>coleoptile tips</b> of oat seedlings, building on earlier observations by the Darwins."},
  {id:"bio13-auxins-c6", front:"Name two physiological effects of auxins.", back:"Auxins promote <b>apical dominance</b> (suppressing lateral bud growth) and induce <b>rooting</b> in stem cuttings."}],
"bio13-gibberellins-cytokinins": [
  {id:"bio13-gibberellins-cytokinins-c1", front:"What effect do gibberellins have on stem growth?", back:"They cause <b>bolting</b> — rapid internode elongation."},
  {id:"bio13-gibberellins-cytokinins-c2", front:"What is the main function of cytokinins?", back:"Promoting <b>cell division</b>."}
,
  {id:"bio13-gibberellins-cytokinins-c5", front:"What is a key effect of gibberellins on genetically dwarf plants?", back:"Gibberellins cause <b>internode elongation</b> (bolting), making dwarf varieties like dwarf pea and maize grow to normal height."},
  {id:"bio13-gibberellins-cytokinins-c6", front:"What is the primary role of cytokinins?", back:"Cytokinins promote <b>cell division</b> (cytokinesis); first isolated as kinetin, and found naturally in <b>coconut milk</b>."}],
"bio13-ethylene-abscisic-acid": [
  {id:"bio13-ethylene-abscisic-acid-c1", front:"What is ethylene's main effect on fruit?", back:"It promotes <b>fruit ripening</b>."},
  {id:"bio13-ethylene-abscisic-acid-c2", front:"What is abscisic acid known as, and why?", back:"The <b>stress hormone</b> — it induces dormancy and stomatal closure under stress."}
,
  {id:"bio13-ethylene-abscisic-acid-c5", front:"What is the main commercial use of ethylene?", back:"Ethylene is used to hasten <b>fruit ripening</b>, e.g., in tomatoes and apples."},
  {id:"bio13-ethylene-abscisic-acid-c6", front:"Why is abscisic acid (ABA) called the \"stress hormone\"?", back:"ABA inhibits <b>seed germination</b> and growth, promotes <b>stomatal closure</b>, and helps plants withstand stresses like drought."}],
"bio14-respiratory-organs-across-animals": [
  {id:"bio14-respiratory-organs-across-animals-c1", front:"What respiratory organ do fish use?", back:"<b>Gills</b>."}
,
  {id:"bio14-respiratory-organs-across-animals-c5", front:"What respiratory organ do fish use for gas exchange?", back:"<b>Gills</b>, which extract dissolved oxygen from water."},
  {id:"bio14-respiratory-organs-across-animals-c6", front:"What respiratory structures do insects use?", back:"<b>Tracheal tubes</b>, which open to the exterior through <b>spiracles</b>."},
  {id:"bio14-respiratory-organs-across-animals-c7", front:"How do earthworms and frogs respire?", back:"Through their moist, vascularized <b>skin</b> (cutaneous respiration)."}],
"bio14-human-respiratory-system": [
  {id:"bio14-human-respiratory-system-c1", front:"What is the pathway of air from the nose to the alveoli?", back:"<b>Nostrils → pharynx → larynx → trachea → bronchi → bronchioles → alveoli</b>."}
,
  {id:"bio14-human-respiratory-system-c5", front:"Name the parts of the human respiratory tract from nostrils to lungs.", back:"<b>Nostrils</b> → nasal passage → pharynx → larynx → <b>trachea</b> → bronchi → bronchioles → <b>alveoli</b>."},
  {id:"bio14-human-respiratory-system-c6", front:"What is the site of gas exchange in the human lungs?", back:"The <b>alveoli</b>, thin-walled sac-like structures surrounded by an extensive network of blood capillaries."},
  {id:"bio14-human-respiratory-system-c7", front:"What is the function of the larynx?", back:"It houses the <b>vocal cords</b> and produces sound; it is also called the voice box."}],
"bio14-mechanism-breathing": [
  {id:"bio14-mechanism-breathing-c1", front:"What happens to the diaphragm during inspiration?", back:"It <b>contracts and flattens</b>, increasing thoracic volume."},
  {id:"bio14-mechanism-breathing-c2", front:"Is breathing driven by pressure differences?", back:"<b>Yes</b> — air moves from higher to lower pressure between atmosphere and lungs."}
,
  {id:"bio14-mechanism-breathing-c5", front:"Which muscles are primarily involved in normal inspiration?", back:"The <b>diaphragm</b> and <b>external intercostal muscles</b>, which contract to increase thoracic volume."},
  {id:"bio14-mechanism-breathing-c6", front:"What causes air to flow into the lungs during inspiration?", back:"Increased thoracic volume decreases intra-pulmonary pressure below atmospheric pressure, so air flows in, following <b>Boyle's law</b>."}],
"bio14-respiratory-volumes-capacities": [
  {id:"bio14-respiratory-volumes-capacities-c1", front:"What is tidal volume?", back:"The <b>volume of air breathed in/out in normal, quiet breathing</b> (~500 mL)."},
  {id:"bio14-respiratory-volumes-capacities-c2", front:"What is vital capacity?", back:"The <b>maximum volume of air that can be forcibly exhaled after maximum inspiration</b>."}
,
  {id:"bio14-respiratory-volumes-capacities-c5", front:"What is tidal volume?", back:"The volume of air inspired or expired during normal, quiet breathing, about <b>500 mL</b>."},
  {id:"bio14-respiratory-volumes-capacities-c6", front:"What is vital capacity?", back:"The maximum volume of air that can be exhaled after a forced inspiration; <b>VC = TV + IRV + ERV</b>."}],
"bio14-exchange-transport-gases": [
  {id:"bio14-exchange-transport-gases-c1", front:"What molecule transports most of the oxygen in blood?", back:"<b>Hemoglobin</b>."},
  {id:"bio14-exchange-transport-gases-c2", front:"How is most CO2 transported in blood?", back:"As <b>bicarbonate ions (HCO3⁻)</b>."}
,
  {id:"bio14-exchange-transport-gases-c5", front:"By what mechanism does gas exchange occur across the alveolar membrane?", back:"By <b>simple diffusion</b>, governed by the partial pressure gradients of O2 and CO2."},
  {id:"bio14-exchange-transport-gases-c6", front:"How is most CO2 transported in the blood?", back:"About <b>70% as bicarbonate</b> (HCO3-), 20-25% bound to hemoglobin as <b>carbamino-hemoglobin</b>, and the rest dissolved in plasma."}],
"bio14-regulation-respiration": [
  {id:"bio14-regulation-respiration-c1", front:"Which brain region contains the main respiratory rhythm centre?", back:"The <b>medulla oblongata</b>."}
,
  {id:"bio14-regulation-respiration-c5", front:"Which part of the brain is the primary respiratory rhythm center?", back:"The <b>medulla oblongata</b>, which controls the rhythm of breathing."},
  {id:"bio14-regulation-respiration-c6", front:"What is the role of the pneumotaxic center?", back:"Located in the <b>pons</b>, it can moderate the medullary respiratory center and reduce the duration of inspiration."},
  {id:"bio14-regulation-respiration-c7", front:"What is the main chemical stimulus that regulates respiratory rate?", back:"Increased <b>CO2 concentration</b> in blood, the most powerful stimulant detected by chemosensitive areas near the medulla."}],
"bio14-respiratory-disorders": [
  {id:"bio14-respiratory-disorders-c1", front:"What is asthma?", back:"<b>Difficulty in breathing</b> due to inflammation/constriction of bronchi and bronchioles."}
,
  {id:"bio14-respiratory-disorders-c5", front:"What is asthma?", back:"A disorder causing difficulty in breathing due to inflammation of the <b>bronchi and bronchioles</b>, producing wheezing."},
  {id:"bio14-respiratory-disorders-c6", front:"What is emphysema?", back:"A chronic disorder in which <b>alveolar walls are damaged</b>, decreasing respiratory surface area, often caused by <b>cigarette smoking</b>."},
  {id:"bio14-respiratory-disorders-c7", front:"What causes occupational respiratory disorders like silicosis?", back:"Long-term exposure to <b>dust particles</b> (e.g., silica dust in mining) causing inflammation and <b>fibrosis</b> of the lungs."}],
"bio15-blood-composition-groups": [
  {id:"bio15-blood-composition-groups-c1", front:"What are the two main components of blood?", back:"<b>Plasma (fluid) and blood cells (RBCs, WBCs, platelets)</b>."},
  {id:"bio15-blood-composition-groups-c2", front:"What determines the ABO blood group of a person?", back:"The <b>type of antigen (A and/or B) present on red blood cells</b>."}
,
  {id:"bio15-blood-composition-groups-c5", front:"What are the formed elements of blood?", back:"Blood contains three formed elements: <b>erythrocytes</b> (RBCs), <b>leukocytes</b> (WBCs), and <b>platelets</b> (thrombocytes), suspended in plasma."},
  {id:"bio15-blood-composition-groups-c6", front:"What determines the ABO blood group system?", back:"ABO blood groups are determined by <b>antigens A and B</b> on RBC surfaces and corresponding <b>antibodies</b> (anti-A, anti-B) in the plasma."}],
"bio15-blood-coagulation": [
  {id:"bio15-blood-coagulation-c1", front:"What is the final step of the blood clotting cascade?", back:"<b>Fibrinogen is converted to fibrin</b>, forming a clot mesh."}
,
  {id:"bio15-blood-coagulation-c5", front:"What is the role of thrombokinase (thromboplastin) in clotting?", back:"It converts inactive <b>prothrombin</b> into active <b>thrombin</b> in the presence of Ca2+, triggering the clotting cascade."},
  {id:"bio15-blood-coagulation-c6", front:"How does thrombin form a blood clot?", back:"Thrombin converts soluble <b>fibrinogen</b> into insoluble <b>fibrin</b> threads, which form a mesh trapping cells to form a clot."},
  {id:"bio15-blood-coagulation-c7", front:"What triggers the clotting cascade after an injury?", back:"Injury causes platelets to release clotting factors that, along with damaged tissue factors, lead to formation of <b>thromboplastin</b>, essential for clot formation."}],
"bio15-lymph": [
  {id:"bio15-lymph-c1", front:"What are the two main functions of lymph?", back:"<b>Draining excess tissue fluid back into blood, and fighting infection</b>."}
,
  {id:"bio15-lymph-c5", front:"How is lymph formed?", back:"Blood plasma passing from capillaries into intercellular spaces forms <b>interstitial fluid</b>; on entering lymphatic vessels this fluid is called <b>lymph</b>."},
  {id:"bio15-lymph-c6", front:"How does the composition of lymph differ from plasma?", back:"Lymph is colourless, similar to plasma but contains <b>less protein</b> and relatively more <b>lymphocytes</b>."},
  {id:"bio15-lymph-c7", front:"What are the functions of the lymphatic system?", back:"It drains excess interstitial fluid back into blood, transports <b>absorbed fats</b> from the intestine, and supports the <b>immune response</b>."}],
"bio15-human-heart-structure": [
  {id:"bio15-human-heart-structure-c1", front:"How many chambers does the human heart have?", back:"<b>Four</b> — two atria and two ventricles."},
  {id:"bio15-human-heart-structure-c2", front:"What is the function of heart valves?", back:"To <b>prevent backflow of blood</b> between chambers."}
,
  {id:"bio15-human-heart-structure-c5", front:"How many chambers does the human heart have?", back:"The human heart is <b>four-chambered</b>, with two upper <b>atria</b> and two lower <b>ventricles</b>."},
  {id:"bio15-human-heart-structure-c6", front:"Which valve separates the left atrium and left ventricle?", back:"The <b>bicuspid (mitral) valve</b> separates the left atrium from the left ventricle and ensures unidirectional blood flow."}],
"bio15-cardiac-cycle-output": [
  {id:"bio15-cardiac-cycle-output-c1", front:"What is the difference between systole and diastole?", back:"<b>Systole</b> is contraction of the heart; <b>diastole</b> is relaxation."},
  {id:"bio15-cardiac-cycle-output-c2", front:"How is cardiac output calculated?", back:"<b>Cardiac output = stroke volume × heart rate</b>."}
,
  {id:"bio15-cardiac-cycle-output-c5", front:"What is cardiac output?", back:"Cardiac output is the volume of blood pumped by each ventricle per minute, equal to <b>stroke volume × heart rate</b>, about 5 litres/min at rest."},
  {id:"bio15-cardiac-cycle-output-c6", front:"What are the main phases of the cardiac cycle?", back:"The cycle consists of <b>joint diastole</b>, <b>atrial systole</b>, and <b>ventricular systole</b>, repeating roughly 72 times per minute."}],
"bio15-electrocardiogram-ecg": [
  {id:"bio15-electrocardiogram-ecg-c1", front:"What does the P wave of an ECG represent?", back:"<b>Atrial depolarization</b> (contraction of the atria)."}
,
  {id:"bio15-electrocardiogram-ecg-c5", front:"What does the P wave of an ECG represent?", back:"The <b>P wave</b> represents <b>atrial depolarisation</b>, occurring just before atrial contraction."},
  {id:"bio15-electrocardiogram-ecg-c6", front:"What does the QRS complex of an ECG represent?", back:"The <b>QRS complex</b> represents <b>ventricular depolarisation</b>, which initiates ventricular contraction."},
  {id:"bio15-electrocardiogram-ecg-c7", front:"What does the T wave of an ECG indicate?", back:"The <b>T wave</b> represents <b>ventricular repolarisation</b>, marking the return of the ventricles to their relaxed state."}],
"bio15-regulation-cardiac-activity": [
  {id:"bio15-regulation-cardiac-activity-c1", front:"What is the pacemaker of the heart?", back:"The <b>SA (sino-atrial) node</b>."}
,
  {id:"bio15-regulation-cardiac-activity-c5", front:"What structure sets the rhythm of the heartbeat?", back:"The <b>sino-atrial node (SAN)</b>, in the wall of the right atrium, generates rhythmic impulses and is called the <b>pacemaker</b> of the heart."},
  {id:"bio15-regulation-cardiac-activity-c6", front:"How does the autonomic nervous system regulate heart rate?", back:"The <b>sympathetic nerves</b> increase heart rate and cardiac output, while the <b>parasympathetic (vagus) nerve</b> decreases them."},
  {id:"bio15-regulation-cardiac-activity-c7", front:"What role does the medulla oblongata play in cardiac regulation?", back:"A neural centre in the <b>medulla oblongata</b> moderates cardiac function by sending signals through sympathetic and parasympathetic nerves."}],
"bio15-disorders-circulatory-system": [
  {id:"bio15-disorders-circulatory-system-c1", front:"What is hypertension?", back:"<b>Persistently high blood pressure</b>."}
,
  {id:"bio15-disorders-circulatory-system-c5", front:"What is atherosclerosis?", back:"Atherosclerosis is the deposition of <b>fatty plaques (cholesterol)</b> on the inner walls of arteries, narrowing their lumen."},
  {id:"bio15-disorders-circulatory-system-c6", front:"What is angina pectoris?", back:"Angina is severe chest pain occurring when the <b>heart muscle</b> receives insufficient oxygen due to reduced blood flow, without permanent tissue damage."},
  {id:"bio15-disorders-circulatory-system-c7", front:"What is hypertension?", back:"Hypertension is persistently elevated <b>blood pressure</b> (above 140/90 mmHg), a major risk factor for heart disease and stroke."}],
"bio16-modes-nitrogenous-excretion": [
  {id:"bio16-modes-nitrogenous-excretion-c1", front:"What are the three main modes of nitrogenous excretion?", back:"<b>Ammonotelic (ammonia), ureotelic (urea), and uricotelic (uric acid)</b>."}
,
  {id:"bio16-modes-nitrogenous-excretion-c5", front:"What is ammonotelism?", back:"Excretion of nitrogenous waste mainly as <b>ammonia</b>; seen in many bony fishes and aquatic amphibians since ammonia is toxic and needs large amounts of water to be flushed out."},
  {id:"bio16-modes-nitrogenous-excretion-c6", front:"What is ureotelism?", back:"Excretion of nitrogenous waste as <b>urea</b>; ammonia is converted to less toxic urea in the liver, seen in mammals and marine fishes."},
  {id:"bio16-modes-nitrogenous-excretion-c7", front:"What is uricotelism, and which animals show it?", back:"Excretion of nitrogenous waste as semi-solid <b>uric acid</b>, a water-conserving adaptation seen in birds, reptiles, and insects."}],
"bio16-human-excretory-system-structure": [
  {id:"bio16-human-excretory-system-structure-c1", front:"What is the functional unit of the kidney?", back:"The <b>nephron</b>."}
,
  {id:"bio16-human-excretory-system-structure-c5", front:"What is the functional unit of the kidney?", back:"The <b>nephron</b> is the structural and functional unit of the kidney, consisting of a glomerulus and a renal tubule."},
  {id:"bio16-human-excretory-system-structure-c6", front:"What are the parts of the renal tubule of a nephron?", back:"The renal tubule consists of the <b>Bowman's capsule</b>, <b>proximal convoluted tubule (PCT)</b>, <b>loop of Henle</b>, and <b>distal convoluted tubule (DCT)</b>."},
  {id:"bio16-human-excretory-system-structure-c7", front:"What is the malpighian body of the kidney?", back:"It consists of the <b>glomerulus</b> (a tuft of capillaries) enclosed within the <b>Bowman's capsule</b>, located in the renal cortex."}],
"bio16-urine-formation": [
  {id:"bio16-urine-formation-c1", front:"What are the three steps of urine formation in a nephron?", back:"<b>Filtration, reabsorption, and secretion</b>."}
,
  {id:"bio16-urine-formation-c5", front:"What are the three main steps of urine formation?", back:"<b>Glomerular filtration</b>, <b>tubular reabsorption</b>, and <b>tubular secretion</b>."},
  {id:"bio16-urine-formation-c6", front:"What is glomerular filtration rate (GFR)?", back:"GFR is the volume of filtrate formed by the kidneys per minute, about <b>125 mL/minute</b> in a healthy adult."},
  {id:"bio16-urine-formation-c7", front:"What is reabsorbed at the proximal convoluted tubule (PCT)?", back:"The <b>PCT</b> reabsorbs almost all essential nutrients like <b>glucose and amino acids</b>, and about 70-80% of electrolytes and water."}],
"bio16-osmoregulation": [
  {id:"bio16-osmoregulation-c1", front:"What does ADH (antidiuretic hormone) do to urine output?", back:"It <b>increases water reabsorption</b>, reducing urine volume."}
,
  {id:"bio16-osmoregulation-c5", front:"What is the role of the loop of Henle in osmoregulation?", back:"Through the <b>counter-current mechanism</b>, the loop of Henle maintains high osmolarity in the medullary interstitium, enabling concentrated urine formation."},
  {id:"bio16-osmoregulation-c6", front:"What is the role of the DCT in osmoregulation?", back:"The <b>DCT</b> conditionally reabsorbs sodium and water, and helps maintain blood pH and Na+/K+ balance."},
  {id:"bio16-osmoregulation-c7", front:"How does the counter-current mechanism concentrate urine?", back:"Filtrate flows through the <b>loop of Henle</b> and blood flows through the <b>vasa recta</b> in opposite directions, maintaining the osmotic gradient needed to concentrate urine."}],
"bio16-hormonal-regulation-kidney-function": [
  {id:"bio16-hormonal-regulation-kidney-function-c1", front:"What is the RAAS system?", back:"The <b>renin-angiotensin-aldosterone system</b>, which regulates blood pressure and kidney filtration."}
,
  {id:"bio16-hormonal-regulation-kidney-function-c5", front:"What is the function of ADH (vasopressin) in the kidney?", back:"<b>ADH</b> increases the permeability of the distal tubule and collecting duct to water, promoting water reabsorption and reducing urine volume."},
  {id:"bio16-hormonal-regulation-kidney-function-c6", front:"What triggers renin release and what does it do?", back:"A fall in glomerular blood flow triggers <b>renin</b> release from juxtaglomerular cells, converting angiotensinogen to angiotensin II, which raises blood pressure and stimulates aldosterone release."},
  {id:"bio16-hormonal-regulation-kidney-function-c7", front:"What is the role of aldosterone in kidney function?", back:"<b>Aldosterone</b> acts on the DCT to promote reabsorption of <b>Na+ and water</b>, helping conserve sodium and regulate blood pressure."}],
"bio16-role-other-organs-excretion": [
  {id:"bio16-role-other-organs-excretion-c1", front:"What excretory role does skin play?", back:"Removing <b>water, salts, and some urea via sweat</b>."}
,
  {id:"bio16-role-other-organs-excretion-c5", front:"Besides the kidneys, which organs assist in excretion?", back:"The <b>lungs</b> (remove CO2), <b>liver</b> (excretes bile pigments), and <b>skin</b> (sweat glands remove water, salts and urea) all assist excretion."},
  {id:"bio16-role-other-organs-excretion-c6", front:"What do sweat glands excrete besides water?", back:"Sweat glands excrete water along with small amounts of <b>NaCl, urea, and lactic acid</b>, while also aiding thermoregulation."},
  {id:"bio16-role-other-organs-excretion-c7", front:"What role does the liver play in nitrogenous waste elimination?", back:"The liver converts toxic <b>ammonia</b> into less toxic <b>urea</b> via the ornithine cycle, and also excretes bile pigments like bilirubin."}],
"bio16-disorders-dialysis": [
  {id:"bio16-disorders-dialysis-c1", front:"What does dialysis do for a patient with kidney failure?", back:"It <b>artificially removes waste and excess fluid from the blood</b>, mimicking kidney function."}
,
  {id:"bio16-disorders-dialysis-c5", front:"What is uraemia?", back:"Uraemia is the accumulation of <b>urea</b> in the blood due to kidney malfunction, which can be life-threatening."},
  {id:"bio16-disorders-dialysis-c6", front:"What is haemodialysis?", back:"Blood is passed through a dialysing unit containing fluid similar to plasma (minus nitrogenous wastes), removing wastes by <b>diffusion</b> across a semi-permeable membrane; used in kidney failure."},
  {id:"bio16-disorders-dialysis-c7", front:"What are renal calculi?", back:"Renal calculi (kidney stones) are crystallised masses of <b>calcium oxalate or uric acid salts</b> formed within the kidney, causing pain and obstruction."}],
"bio17-types-movement": [
  {id:"bio17-types-movement-c1", front:"What are the three basic types of movement in the body?", back:"<b>Ciliary, flagellar, and muscular</b> movement."}
,
  {id:"bio17-types-movement-c5", front:"What are the three main types of movement in the human body?", back:"<b>Amoeboid</b>, <b>ciliary</b>, and <b>muscular</b> movement."},
  {id:"bio17-types-movement-c6", front:"Give an example of ciliary movement in the human body.", back:"Movement of ova through the <b>fallopian tubes</b> and clearance of dust particles in the trachea occur via <b>ciliary movement</b>."},
  {id:"bio17-types-movement-c7", front:"Where does amoeboid movement occur in the human body?", back:"Amoeboid movement, using <b>pseudopodia</b> formed by cytoplasmic streaming, is seen in <b>macrophages and leucocytes</b> in the blood."}],
"bio17-skeletal-muscle-structure": [
  {id:"bio17-skeletal-muscle-structure-c1", front:"What is a sarcomere?", back:"The <b>repeating contractile unit</b> of a skeletal muscle fiber, between two Z-lines."}
,
  {id:"bio17-skeletal-muscle-structure-c5", front:"What is a sarcomere?", back:"A sarcomere is the functional unit of a myofibril, the region between two successive <b>Z-lines</b>, containing overlapping actin and myosin filaments."},
  {id:"bio17-skeletal-muscle-structure-c6", front:"What are the two main types of myofilaments in a muscle fibre?", back:"<b>Actin</b> (thin filament) and <b>myosin</b> (thick filament), whose sliding relative to each other produces muscle contraction."},
  {id:"bio17-skeletal-muscle-structure-c7", front:"What is the sarcoplasmic reticulum?", back:"A membranous network surrounding myofibrils that stores and releases <b>Ca2+ ions</b>, which trigger muscle contraction."}],
"bio17-mechanism-muscle-contraction": [
  {id:"bio17-mechanism-muscle-contraction-c1", front:"What theory explains skeletal muscle contraction?", back:"The <b>sliding filament theory</b> — actin filaments slide over myosin filaments."},
  {id:"bio17-mechanism-muscle-contraction-c2", front:"What ion triggers muscle contraction after a nerve signal arrives?", back:"<b>Calcium ions (Ca²⁺)</b>."}
,
  {id:"bio17-mechanism-muscle-contraction-c5", front:"Which theory explains skeletal muscle contraction?", back:"The <b>sliding filament theory</b>: actin filaments slide over myosin filaments, shortening the sarcomere without any change in filament length."},
  {id:"bio17-mechanism-muscle-contraction-c6", front:"What role do calcium and troponin play in muscle contraction?", back:"Released Ca2+ binds to <b>troponin</b>, shifting tropomyosin to expose <b>myosin-binding sites</b> on actin, allowing cross-bridge formation."}],
"bio17-skeletal-system-functions": [
  {id:"bio17-skeletal-system-functions-c1", front:"Name two functions of the skeletal system.", back:"<b>Support/framework and protection of internal organs</b> (also acts as levers for movement)."}
,
  {id:"bio17-skeletal-system-functions-c5", front:"How many bones are in the adult human skeleton?", back:"The adult human skeleton has <b>206 bones</b>, divided into the axial and appendicular skeleton."},
  {id:"bio17-skeletal-system-functions-c6", front:"What bones make up the axial skeleton?", back:"The axial skeleton comprises the <b>skull, vertebral column, sternum, and ribs</b>, totalling 80 bones."},
  {id:"bio17-skeletal-system-functions-c7", front:"What are the main functions of the skeletal system?", back:"It provides <b>support and shape</b>, protects vital organs, enables <b>locomotion</b> via muscle attachment, and produces blood cells in <b>bone marrow</b>."}],
"bio17-joints": [
  {id:"bio17-joints-c1", front:"What type of joint is the shoulder, allowing movement in all directions?", back:"A <b>ball-and-socket joint</b>."}
,
  {id:"bio17-joints-c5", front:"What is a synovial joint?", back:"A joint with a fluid-filled <b>synovial cavity</b> that permits free movement between bones, e.g., the ball-and-socket joint of the hip."},
  {id:"bio17-joints-c6", front:"Give examples of a hinge joint and a pivot joint.", back:"The <b>knee/elbow</b> is a hinge joint (movement in one plane); the joint between the <b>atlas and axis</b> vertebrae is a pivot joint (allows rotation)."},
  {id:"bio17-joints-c7", front:"What is a fibrous (fixed) joint?", back:"A joint that permits no movement, where bones are joined by fibrous tissue, e.g., the <b>sutures</b> between skull bones."}],
"bio17-disorders-muscular-skeletal-system": [
  {id:"bio17-disorders-muscular-skeletal-system-c1", front:"What is arthritis?", back:"<b>Inflammation of a joint</b>."}
,
  {id:"bio17-disorders-muscular-skeletal-system-c5", front:"What is myasthenia gravis?", back:"An <b>autoimmune disorder</b> affecting neuromuscular junctions, causing progressive muscle weakness and fatigue."},
  {id:"bio17-disorders-muscular-skeletal-system-c6", front:"What is osteoporosis?", back:"A bone disorder marked by decreased bone mass and increased fracture risk, often due to reduced <b>estrogen</b> levels after menopause."},
  {id:"bio17-disorders-muscular-skeletal-system-c7", front:"What causes gout?", back:"Gout is inflammation of the joints caused by deposition of <b>uric acid crystals</b>."}],
"bio18-neuron-nerve-structure": [
  {id:"bio18-neuron-nerve-structure-c1", front:"What are the three main parts of a neuron?", back:"<b>Dendrites, cell body (soma), and axon</b>."}
,
  {id:"bio18-neuron-nerve-structure-c5", front:"What are the main parts of a neuron?", back:"The <b>cell body (cyton)</b>, <b>dendrites</b> that receive signals, and a single long <b>axon</b> that transmits signals."},
  {id:"bio18-neuron-nerve-structure-c6", front:"What is the function of the myelin sheath?", back:"Formed by <b>Schwann cells</b>, the myelin sheath insulates the axon and enables faster <b>saltatory conduction</b> of nerve impulses."},
  {id:"bio18-neuron-nerve-structure-c7", front:"What are nodes of Ranvier?", back:"Gaps in the <b>myelin sheath</b> along the axon where the axolemma is exposed, allowing the nerve impulse to jump between successive nodes."}],
"bio18-organisation-human-nervous-system": [
  {id:"bio18-organisation-human-nervous-system-c1", front:"What are the two main divisions of the human nervous system?", back:"The <b>central nervous system (CNS)</b> and the <b>peripheral nervous system (PNS)</b>."}
,
  {id:"bio18-organisation-human-nervous-system-c5", front:"What are the two main divisions of the human nervous system?", back:"The <b>central nervous system (CNS)</b> — brain and spinal cord — and the <b>peripheral nervous system (PNS)</b> — cranial and spinal nerves."},
  {id:"bio18-organisation-human-nervous-system-c6", front:"What are the subdivisions of the peripheral nervous system?", back:"The <b>somatic nervous system</b>, controlling voluntary actions, and the <b>autonomic nervous system</b>, controlling involuntary functions of visceral organs."},
  {id:"bio18-organisation-human-nervous-system-c7", front:"How do the sympathetic and parasympathetic divisions differ?", back:"The <b>sympathetic</b> division prepares the body for stress (\"fight or flight\"), while the <b>parasympathetic</b> division promotes relaxation (\"rest and digest\")."}],
"bio18-generation-nerve-impulse": [
  {id:"bio18-generation-nerve-impulse-c1", front:"What is the resting membrane potential of a neuron mainly due to?", back:"Unequal distribution of <b>Na⁺ and K⁺ ions</b> across the membrane (maintained by the Na⁺-K⁺ pump)."},
  {id:"bio18-generation-nerve-impulse-c2", front:"What causes the depolarization phase of an action potential?", back:"A <b>sudden influx of Na⁺ ions</b> into the neuron."}
,
  {id:"bio18-generation-nerve-impulse-c5", front:"What is resting membrane potential?", back:"The inside of a resting neuron's membrane is <b>negatively charged (about -70 mV)</b> relative to outside, maintained by the <b>Na+/K+ pump</b>."},
  {id:"bio18-generation-nerve-impulse-c6", front:"What causes depolarisation during an action potential?", back:"A stimulus increases membrane <b>Na+ permeability</b>, causing Na+ influx that makes the inside of the membrane positive, generating an <b>action potential</b>."}],
"bio18-conduction-nerve-impulse": [
  {id:"bio18-conduction-nerve-impulse-c1", front:"What is a synapse?", back:"The <b>junction between two neurons</b> where signal transmission occurs, usually via neurotransmitters."}
,
  {id:"bio18-conduction-nerve-impulse-c5", front:"How does a nerve impulse travel along an unmyelinated axon?", back:"It travels continuously as a wave of <b>depolarisation and repolarisation</b> along the entire length of the axon membrane."},
  {id:"bio18-conduction-nerve-impulse-c6", front:"What is saltatory conduction?", back:"In myelinated neurons, the impulse jumps from one <b>node of Ranvier</b> to the next, making conduction much faster than in unmyelinated fibres."},
  {id:"bio18-conduction-nerve-impulse-c7", front:"How is a nerve impulse transmitted across a chemical synapse?", back:"An impulse triggers release of <b>neurotransmitters</b> from synaptic vesicles into the synaptic cleft; these bind receptors on the postsynaptic membrane, generating a new impulse."}],
"bio19-endocrine-glands-hormones": [
  {id:"bio19-endocrine-glands-hormones-c1", front:"What makes a gland 'endocrine'?", back:"It <b>secretes hormones directly into the blood</b> (ductless)."}
,
  {id:"bio19-endocrine-glands-hormones-c5", front:"What is a hormone?", back:"A hormone is a chemical messenger secreted in trace amounts by <b>endocrine glands</b>, released directly into the blood, and acting on a distant <b>target organ</b>."},
  {id:"bio19-endocrine-glands-hormones-c6", front:"How do endocrine glands differ from exocrine glands?", back:"<b>Endocrine glands</b> are ductless and secrete hormones directly into blood; <b>exocrine glands</b> have ducts that carry secretions to a specific site."},
  {id:"bio19-endocrine-glands-hormones-c7", front:"Name the three chemical classes of hormones with an example each.", back:"<b>Peptide/protein</b> hormones (insulin), <b>steroid</b> hormones (cortisol), and <b>amino-acid derivatives</b> (thyroxine, adrenaline)."}],
"bio19-hypothalamus-pituitary": [
  {id:"bio19-hypothalamus-pituitary-c1", front:"What is the relationship between the hypothalamus and pituitary gland?", back:"The <b>hypothalamus releases hormones that control pituitary hormone secretion</b>."},
  {id:"bio19-hypothalamus-pituitary-c2", front:"Why is the pituitary called the 'master gland'?", back:"Its hormones <b>regulate the activity of many other endocrine glands</b>."}
,
  {id:"bio19-hypothalamus-pituitary-c5", front:"What is the functional link between hypothalamus and pituitary?", back:"The hypothalamus secretes <b>releasing</b> and <b>inhibitory hormones</b> that regulate secretion of pituitary hormones."},
  {id:"bio19-hypothalamus-pituitary-c6", front:"List the hormones secreted by the pars distalis of the anterior pituitary.", back:"<b>GH, PRL, TSH, ACTH, LH, FSH</b> — collectively called tropic hormones."}],
"bio19-pineal-thyroid-parathyroid": [
  {id:"bio19-pineal-thyroid-parathyroid-c1", front:"What hormone does the pineal gland secrete?", back:"<b>Melatonin</b> (regulates biological rhythms)."},
  {id:"bio19-pineal-thyroid-parathyroid-c2", front:"What does parathyroid hormone (PTH) regulate?", back:"<b>Calcium levels in the blood</b>."}
,
  {id:"bio19-pineal-thyroid-parathyroid-c5", front:"What hormone does the pineal gland secrete and what is its role?", back:"<b>Melatonin</b>, which regulates the body's day-night (<b>circadian</b>) rhythm and influences pigmentation and immunity."},
  {id:"bio19-pineal-thyroid-parathyroid-c6", front:"What is the function of parathyroid hormone (PTH)?", back:"PTH raises blood <b>Ca2+</b> levels by stimulating bone resorption, renal reabsorption of calcium, and intestinal absorption; it is <b>hypercalcemic</b>."}],
"bio19-adrenal-gland": [
  {id:"bio19-adrenal-gland-c1", front:"What are the two parts of the adrenal gland?", back:"The outer <b>cortex</b> (steroid hormones) and inner <b>medulla</b> (adrenaline/noradrenaline)."}
,
  {id:"bio19-adrenal-gland-c5", front:"What are the two regions of the adrenal gland and their embryonic origin?", back:"The outer <b>adrenal cortex</b> (mesodermal) and the inner <b>adrenal medulla</b> (neuroectodermal)."},
  {id:"bio19-adrenal-gland-c6", front:"Name the three types of corticoids secreted by the adrenal cortex.", back:"<b>Glucocorticoids</b> (cortisol), <b>mineralocorticoids</b> (aldosterone), and small amounts of <b>androgens</b>."},
  {id:"bio19-adrenal-gland-c7", front:"What is the role of adrenaline and noradrenaline?", back:"These <b>catecholamines</b> from the adrenal medulla increase heart rate, blood pressure, and glucose breakdown as part of the <b>fight or flight</b> response."}],
"bio19-pancreas-gonads": [
  {id:"bio19-pancreas-gonads-c1", front:"What two hormones regulating blood sugar does the pancreas secrete?", back:"<b>Insulin (lowers blood sugar) and glucagon (raises blood sugar)</b>."}
,
  {id:"bio19-pancreas-gonads-c5", front:"Which cells of the islets of Langerhans secrete insulin and glucagon?", back:"<b>Beta cells</b> secrete insulin; <b>alpha cells</b> secrete glucagon."},
  {id:"bio19-pancreas-gonads-c6", front:"What is the action of glucagon on blood glucose?", back:"Glucagon is <b>hyperglycemic</b> — it stimulates glycogenolysis in the liver, raising blood glucose levels."},
  {id:"bio19-pancreas-gonads-c7", front:"Which hormones are secreted by the testis and ovary respectively?", back:"The testis secretes <b>testosterone</b> (from Leydig cells); the ovary secretes <b>estrogen</b> and <b>progesterone</b>."}],
"bio19-mechanism-hormone-action": [
  {id:"bio19-mechanism-hormone-action-c1", front:"What must a hormone bind to on a target cell to have an effect?", back:"A specific <b>receptor</b>."}
,
  {id:"bio19-mechanism-hormone-action-c5", front:"Where are receptors for protein hormones typically located, and why?", back:"On the <b>cell membrane</b>, because protein hormones cannot cross the lipid bilayer; binding activates a second messenger like <b>cAMP</b>."},
  {id:"bio19-mechanism-hormone-action-c6", front:"How do steroid hormones act on target cells?", back:"Being lipophilic, they cross the membrane and bind <b>intracellular/nuclear receptors</b>, forming a hormone-receptor complex that regulates gene expression."},
  {id:"bio19-mechanism-hormone-action-c7", front:"What is a second messenger in hormone signaling? Give an example.", back:"A molecule that relays a hormone's signal inside the cell after receptor binding; e.g. <b>cAMP</b> or <b>Ca2+</b> ions."}],
"bio19-endocrine-disorders": [
  {id:"bio19-endocrine-disorders-c1", front:"What condition results from insulin deficiency or resistance?", back:"<b>Diabetes mellitus</b>."}
,
  {id:"bio19-endocrine-disorders-c5", front:"What causes goitre and what is its main sign?", back:"<b>Iodine deficiency</b> impairs thyroxine synthesis, causing enlargement of the <b>thyroid gland</b> (goitre)."},
  {id:"bio19-endocrine-disorders-c6", front:"What is dwarfism caused by?", back:"<b>Hyposecretion of growth hormone (GH)</b> during childhood, leading to stunted growth."},
  {id:"bio19-endocrine-disorders-c7", front:"What are the hallmark features of diabetes mellitus?", back:"Insufficient <b>insulin</b> action causes high blood glucose (<b>hyperglycemia</b>) and glucose in urine (<b>glycosuria</b>)."}],
"bio20-flower-pre-fertilisation": [
  {id:"bio20-flower-pre-fertilisation-c1", front:"Where do pollen grains develop in a flower?", back:"Inside the <b>anther</b> (in microsporangia)."}
,
  {id:"bio20-flower-pre-fertilisation-c5", front:"What are the parts of a typical angiosperm stamen?", back:"A <b>filament</b> and an <b>anther</b>, the anther bearing pollen sacs where microsporogenesis occurs."},
  {id:"bio20-flower-pre-fertilisation-c6", front:"Describe the structure of a mature pollen grain wall.", back:"A hard outer <b>exine</b> (made of sporopollenin, with germ pores) and a thin inner <b>intine</b> (made of cellulose and pectin)."},
  {id:"bio20-flower-pre-fertilisation-c7", front:"What is the megasporangium in flowering plants called?", back:"The <b>ovule</b>, which contains the megaspore mother cell that undergoes meiosis to form megaspores."}],
"bio20-pollination": [
  {id:"bio20-pollination-c1", front:"What is pollination?", back:"Transfer of <b>pollen grains from anther to stigma</b>."}
,
  {id:"bio20-pollination-c5", front:"Differentiate autogamy from geitonogamy.", back:"<b>Autogamy</b> is self-pollination within the same flower; <b>geitonogamy</b> is transfer of pollen to another flower on the same plant (genetically self-pollination)."},
  {id:"bio20-pollination-c6", front:"What is xenogamy?", back:"Transfer of pollen from the anther of one plant to the stigma of a genetically different plant — true <b>cross-pollination</b>."},
  {id:"bio20-pollination-c7", front:"Name two agents of pollination and a floral adaptation for each.", back:"<b>Insects</b> (bright, scented, nectar-rich flowers) and <b>wind</b> (light, non-sticky pollen with feathery stigma, as in grasses)."}],
"bio20-double-fertilisation": [
  {id:"bio20-double-fertilisation-c1", front:"What are the two fusion events in double fertilisation?", back:"<b>Syngamy</b> (male gamete + egg → zygote) and <b>triple fusion</b> (male gamete + two polar nuclei → endosperm)."}
,
  {id:"bio20-double-fertilisation-c5", front:"What is double fertilisation?", back:"One male gamete fuses with the <b>egg</b> to form a diploid <b>zygote</b>; the other fuses with the two <b>polar nuclei</b> to form the triploid <b>primary endosperm nucleus (PEN)</b>."},
  {id:"bio20-double-fertilisation-c6", front:"What is syngamy?", back:"The fusion of a male gamete with the egg cell to produce a diploid <b>zygote</b>."},
  {id:"bio20-double-fertilisation-c7", front:"What is triple fusion?", back:"Fusion of a male gamete with the two <b>polar nuclei</b> in the central cell, producing the triploid <b>PEN</b> that develops into <b>endosperm</b>."}],
"bio20-post-fertilisation-structures-events": [
  {id:"bio20-post-fertilisation-structures-events-c1", front:"What does the ovary develop into after fertilisation?", back:"The <b>fruit</b>."}
,
  {id:"bio20-post-fertilisation-structures-events-c5", front:"What does the ovule develop into after fertilisation?", back:"The ovule develops into the <b>seed</b>; its integuments become the <b>seed coat</b>."},
  {id:"bio20-post-fertilisation-structures-events-c6", front:"What does the ovary become after fertilisation?", back:"The ovary develops into the <b>fruit (pericarp)</b>, which may be fleshy or dry."},
  {id:"bio20-post-fertilisation-structures-events-c7", front:"What is a perisperm?", back:"The residual, persistent <b>nucellus</b> tissue found in some seeds (e.g. black pepper, beet), distinct from endosperm."}],
"bio20-apomixis-polyembryony": [
  {id:"bio20-apomixis-polyembryony-c1", front:"What is apomixis?", back:"A form of <b>asexual reproduction that produces seeds without fertilisation</b>."}
,
  {id:"bio20-apomixis-polyembryony-c5", front:"What is apomixis?", back:"A form of asexual reproduction that produces seeds <b>without fertilisation</b>, resulting in offspring genetically identical to the parent."},
  {id:"bio20-apomixis-polyembryony-c6", front:"What is polyembryony and where is it commonly seen?", back:"The occurrence of <b>more than one embryo</b> in a single seed, commonly seen in <b>Citrus</b> and mango due to nucellar embryos."},
  {id:"bio20-apomixis-polyembryony-c7", front:"Why is apomixis important for agriculture?", back:"It allows <b>hybrid seed</b> vigor to be maintained across generations without loss of hybrid traits through segregation, since seeds are produced clonally."}],
"bio21-male-reproductive-system": [
  {id:"bio21-male-reproductive-system-c1", front:"Where are sperm produced in the male reproductive system?", back:"In the <b>testes (seminiferous tubules)</b>."}
,
  {id:"bio21-male-reproductive-system-c5", front:"What is the function of the scrotum?", back:"It holds the testes outside the body and maintains a temperature about 2-2.5°C lower than body temperature, needed for <b>spermatogenesis</b>."},
  {id:"bio21-male-reproductive-system-c6", front:"Trace the path of sperm from the testis to the urethra.", back:"<b>Seminiferous tubules → rete testis → vasa efferentia → epididymis → vas deferens → ejaculatory duct → urethra</b>."},
  {id:"bio21-male-reproductive-system-c7", front:"Name the accessory glands of the male reproductive system and their secretion.", back:"<b>Seminal vesicles</b>, <b>prostate</b>, and <b>bulbourethral glands</b> secrete fluids that make up seminal plasma, nourishing and activating sperm."}],
"bio21-female-reproductive-system": [
  {id:"bio21-female-reproductive-system-c1", front:"Where does fertilisation normally occur in the female reproductive tract?", back:"In the <b>fallopian tube (oviduct)</b>."}
,
  {id:"bio21-female-reproductive-system-c5", front:"What are the parts of the fallopian tube (oviduct)?", back:"<b>Infundibulum</b> (with fimbriae, near the ovary), <b>ampulla</b> (site of fertilisation), and <b>isthmus</b> (joins the uterus)."},
  {id:"bio21-female-reproductive-system-c6", front:"Describe the three layers of the uterine wall.", back:"Outer <b>perimetrium</b>, middle muscular <b>myometrium</b>, and inner glandular <b>endometrium</b>, which undergoes cyclic changes."},
  {id:"bio21-female-reproductive-system-c7", front:"What is the function of the cervix?", back:"The <b>cervix</b> connects the uterus to the vagina, forming the <b>cervical canal</b> that allows sperm entry and menstrual flow."}],
"bio21-gametogenesis": [
  {id:"bio21-gametogenesis-c1", front:"What is gametogenesis?", back:"The process of <b>formation of gametes (sperm or egg)</b>."}
,
  {id:"bio21-gametogenesis-c5", front:"What is spermiogenesis?", back:"The transformation of <b>spermatids</b> into mature, motile <b>spermatozoa</b>."},
  {id:"bio21-gametogenesis-c6", front:"Outline the stages of oogenesis up to ovulation.", back:"Oogonia develop into a <b>primary oocyte</b> (arrested in prophase I); at ovulation it completes meiosis I to form a <b>secondary oocyte</b> plus the first polar body."},
  {id:"bio21-gametogenesis-c7", front:"What is spermiation?", back:"The release of mature <b>spermatozoa</b> from the <b>Sertoli cells</b> into the lumen of the seminiferous tubule."}],
"bio21-menstrual-cycle": [
  {id:"bio21-menstrual-cycle-c1", front:"What is the average length of the human menstrual cycle?", back:"<b>28 days</b>."},
  {id:"bio21-menstrual-cycle-c2", front:"What event marks the middle of the menstrual cycle?", back:"<b>Ovulation</b>."}
,
  {id:"bio21-menstrual-cycle-c5", front:"What triggers ovulation in the menstrual cycle?", back:"A surge of <b>LH (luteinising hormone)</b> around day 14, called the <b>LH surge</b>, triggers rupture of the Graafian follicle."},
  {id:"bio21-menstrual-cycle-c6", front:"What happens to the corpus luteum if fertilisation does not occur?", back:"The <b>corpus luteum</b> degenerates, causing a drop in <b>progesterone</b> that leads to shedding of the endometrium (menstruation)."}],
"bio21-fertilisation-implantation": [
  {id:"bio21-fertilisation-implantation-c1", front:"What is implantation?", back:"Attachment of the <b>blastocyst to the uterine wall (endometrium)</b>."}
,
  {id:"bio21-fertilisation-implantation-c5", front:"Where does fertilisation normally occur in the human female?", back:"In the <b>ampulla</b> of the fallopian tube (oviduct)."},
  {id:"bio21-fertilisation-implantation-c6", front:"What is capacitation?", back:"Physiological changes that sperm undergo in the female reproductive tract that enable them to <b>fertilise</b> the ovum."},
  {id:"bio21-fertilisation-implantation-c7", front:"What is implantation?", back:"The attachment of the <b>blastocyst</b> to the <b>endometrium</b> of the uterus, occurring about a week after fertilisation."}],
"bio21-pregnancy-embryonic-development": [
  {id:"bio21-pregnancy-embryonic-development-c1", front:"What is the average duration of human pregnancy?", back:"About <b>9 months (~40 weeks)</b>."}
,
  {id:"bio21-pregnancy-embryonic-development-c5", front:"What is the placenta and what is its function?", back:"A structural and functional connection between mother and fetus formed via <b>chorionic villi</b>, enabling exchange of nutrients, oxygen and waste, and secreting hormones like <b>hCG</b>, estrogen and progesterone."},
  {id:"bio21-pregnancy-embryonic-development-c6", front:"What is the role of hCG in early pregnancy?", back:"<b>Human Chorionic Gonadotropin</b>, secreted soon after implantation, maintains the <b>corpus luteum</b> so it continues producing progesterone."},
  {id:"bio21-pregnancy-embryonic-development-c7", front:"What is parturition and which hormone triggers it?", back:"<b>Parturition</b> is childbirth; it is induced by signals from the fully developed fetus and placenta and involves <b>oxytocin</b>, which causes strong uterine contractions."}],
"bio22-reproductive-sexual-health": [
  {id:"bio22-reproductive-sexual-health-c1", front:"What does reproductive health include beyond absence of disease?", back:"<b>Physical, emotional, behavioural, and social well-being</b> related to reproduction."}
,
  {id:"bio22-reproductive-sexual-health-c5", front:"What does the term 'Reproductive and Child Health Care (RCH)' refer to?", back:"Government programmes providing reproductive health education and services to achieve a <b>healthy reproductive life</b> and safe motherhood for individuals."},
  {id:"bio22-reproductive-sexual-health-c6", front:"Why is sex education important in schools, according to NCERT?", back:"It provides correct, age-appropriate information about <b>reproductive organs, safe practices, and STIs</b>, discouraging misconceptions from unreliable sources."},
  {id:"bio22-reproductive-sexual-health-c7", front:"What is the significance of awareness about puberty changes?", back:"It helps individuals understand <b>adolescence</b>, avoid <b>myths</b>, and make informed decisions about reproductive and sexual health."}],
"bio22-population-stabilisation": [
  {id:"bio22-population-stabilisation-c1", front:"Why is population stabilisation important for reproductive health policy?", back:"Rapid population growth <b>strains resources and reproductive healthcare capacity</b>."}
,
  {id:"bio22-population-stabilisation-c5", front:"Why did India need population stabilisation measures?", back:"Rapid population growth strained resources, prompting the government to promote the <b>small family norm</b>."},
  {id:"bio22-population-stabilisation-c6", front:"Name two measures adopted to encourage population control in India.", back:"Raising the <b>legal marriage age</b> (21 for males, 18 for females) and incentivising couples who adopt the <b>small family norm</b>."},
  {id:"bio22-population-stabilisation-c7", front:"What role does contraceptive awareness play in population stabilisation?", back:"Widespread knowledge and use of <b>contraceptive methods</b> helps couples space or limit births, slowing population growth."}],
"bio22-contraception": [
  {id:"bio22-contraception-c1", front:"What are the main categories of contraceptive methods?", back:"<b>Barrier, hormonal (oral pills), IUDs, and surgical (sterilisation)</b> methods."}
,
  {id:"bio22-contraception-c5", front:"Name the main categories of contraceptive methods.", back:"<b>Barrier methods</b>, <b>hormonal contraceptives (oral pills)</b>, <b>IUDs</b>, and <b>surgical methods (sterilisation)</b>."},
  {id:"bio22-contraception-c6", front:"How do oral contraceptive pills prevent pregnancy?", back:"They contain <b>progestogen</b>, or a progestogen-estrogen combination, that inhibits <b>ovulation</b> and alters the endometrium and cervical mucus."},
  {id:"bio22-contraception-c7", front:"What are the surgical methods of contraception called?", back:"<b>Vasectomy</b> in males (blocking the vas deferens) and <b>tubectomy</b> in females (blocking the fallopian tubes)."}],
"bio22-medical-termination-pregnancy-mtp": [
  {id:"bio22-medical-termination-pregnancy-mtp-c1", front:"What does MTP stand for?", back:"<b>Medical Termination of Pregnancy</b>."}
,
  {id:"bio22-medical-termination-pregnancy-mtp-c5", front:"What is Medical Termination of Pregnancy (MTP)?", back:"The intentional termination of pregnancy before <b>full term</b>, commonly known as induced abortion."},
  {id:"bio22-medical-termination-pregnancy-mtp-c6", front:"Up to what gestational period is MTP generally considered safest?", back:"MTP is relatively safe during the <b>first trimester (up to 12 weeks)</b>; second trimester termination carries higher risk."},
  {id:"bio22-medical-termination-pregnancy-mtp-c7", front:"Give a medical reason for legally permitting MTP.", back:"Cases where continuing pregnancy endangers the mother's life, the fetus has severe abnormalities, or pregnancy resulted from <b>rape or contraceptive failure</b>."}],
"bio22-sexually-transmitted-infections-stis": [
  {id:"bio22-sexually-transmitted-infections-stis-c1", front:"Give an example of an STI.", back:"<b>Gonorrhoea, syphilis, or HIV/AIDS</b>."}
,
  {id:"bio22-sexually-transmitted-infections-stis-c5", front:"Give examples of bacterial and viral STIs mentioned in NCERT.", back:"Bacterial: <b>gonorrhea, syphilis</b>; Viral: <b>genital herpes, HIV/AIDS, genital warts</b>."},
  {id:"bio22-sexually-transmitted-infections-stis-c6", front:"Why is early treatment of STIs important?", back:"Untreated STIs like <b>syphilis, gonorrhea, and HIV</b> can be passed to a fetus/newborn and can cause complications such as <b>infertility</b>."},
  {id:"bio22-sexually-transmitted-infections-stis-c7", front:"What is the single most effective way to reduce risk of STIs, per NCERT?", back:"Avoiding intercourse with unknown/multiple partners and using <b>barrier methods (condoms)</b> during coitus."}],
"bio22-infertility-assisted-reproductive-technologies": [
  {id:"bio22-infertility-assisted-reproductive-technologies-c1", front:"What does IVF stand for?", back:"<b>In Vitro Fertilisation</b> — fertilisation outside the body, then embryo transfer."}
,
  {id:"bio22-infertility-assisted-reproductive-technologies-c5", front:"What is infertility?", back:"The inability of a couple to conceive even after <b>two years</b> of unprotected, regular sexual intercourse."},
  {id:"bio22-infertility-assisted-reproductive-technologies-c6", front:"What is IVF and where does fertilisation occur in this technique?", back:"<b>In Vitro Fertilisation</b> — fertilisation of the ovum by sperm occurs outside the body, followed by embryo transfer to the fallopian tube (<b>ZIFT</b>) or uterus (<b>ET</b>)."},
  {id:"bio22-infertility-assisted-reproductive-technologies-c7", front:"What is GIFT?", back:"<b>Gamete Intra-Fallopian Transfer</b> — transfer of an ovum collected from a donor into the fallopian tube of another female who cannot produce her own ova."}],
"bio23-mendels-laws-inheritance": [
  {id:"bio23-mendels-laws-inheritance-c1", front:"What does Mendel's law of dominance state?", back:"In a heterozygote, one allele (<b>dominant</b>) masks the expression of the other (<b>recessive</b>)."},
  {id:"bio23-mendels-laws-inheritance-c2", front:"What does Mendel's law of independent assortment state?", back:"Genes for <b>different traits segregate independently</b> during gamete formation."}
,
  {id:"bio23-mendels-laws-inheritance-c5", front:"State Mendel's Law of Dominance.", back:"In a heterozygote, one allele (<b>dominant</b>) masks the expression of the other (<b>recessive</b>) allele; the dominant allele expresses in both homozygous and heterozygous conditions."},
  {id:"bio23-mendels-laws-inheritance-c6", front:"What is a test cross?", back:"Crossing an individual of unknown genotype with a <b>homozygous recessive</b> parent to determine whether the unknown is <b>homozygous</b> or <b>heterozygous</b> dominant."}],
"bio23-chromosomal-theory-inheritance": [
  {id:"bio23-chromosomal-theory-inheritance-c1", front:"What does the chromosomal theory of inheritance state?", back:"<b>Genes are located on chromosomes</b>, which are the physical carriers of heredity."}
,
  {id:"bio23-chromosomal-theory-inheritance-c5", front:"Who proposed the Chromosomal Theory of Inheritance?", back:"<b>Sutton and Boveri</b> (1902) proposed that chromosomes are the carriers of genetic material, since they showed parallel behaviour to Mendelian factors."},
  {id:"bio23-chromosomal-theory-inheritance-c6", front:"What experimental evidence did Morgan provide for the chromosomal theory?", back:"<b>Thomas Hunt Morgan's</b> work on <b>Drosophila melanogaster</b> and the white-eye mutation showed that the gene for eye colour is located on the <b>X chromosome</b>, confirming genes reside on chromosomes."},
  {id:"bio23-chromosomal-theory-inheritance-c7", front:"Why was Drosophila melanogaster a good model for Morgan's genetics experiments?", back:"It has a short life cycle, produces many offspring per mating, is easy to grow on synthetic medium, and has clearly distinguishable <b>hereditary characters</b> and giant salivary gland chromosomes."}],
"bio23-deviations-from-mendelism": [
  {id:"bio23-deviations-from-mendelism-c1", front:"What is incomplete dominance?", back:"When the <b>heterozygote shows an intermediate phenotype</b> between the two parents."},
  {id:"bio23-deviations-from-mendelism-c2", front:"What is codominance?", back:"When <b>both alleles are equally expressed</b> in the heterozygote (e.g. ABO blood group AB)."}
,
  {id:"bio23-deviations-from-mendelism-c5", front:"What is incomplete dominance? Give an example.", back:"A condition where the <b>heterozygote</b> phenotype is intermediate between both parents; e.g., <b>Mirabilis jalapa</b> (4 o'clock plant) flower colour, red x white gives pink."},
  {id:"bio23-deviations-from-mendelism-c6", front:"What is codominance? Give an example.", back:"Both alleles express fully and independently in the <b>heterozygote</b> with neither being dominant; seen in the <b>ABO blood group</b> system where alleles I^A and I^B are both expressed."}],
"bio23-sex-determination": [
  {id:"bio23-sex-determination-c1", front:"What determines the sex of a human offspring?", back:"Whether the <b>sperm carries an X or a Y chromosome</b> (XX = female, XY = male)."}
,
  {id:"bio23-sex-determination-c5", front:"What is the XO type of sex determination?", back:"Seen in insects like grasshoppers; females have <b>two X chromosomes (XX)</b> while males have a <b>single X chromosome</b> and no second sex chromosome."},
  {id:"bio23-sex-determination-c6", front:"How is sex determined in birds?", back:"Birds show the <b>ZW system</b>; males are <b>ZZ (homogametic)</b> and females are <b>ZW (heterogametic)</b>, opposite to the human XY system."},
  {id:"bio23-sex-determination-c7", front:"What determines maleness in humans?", back:"Presence of the <b>Y chromosome</b>, specifically the <b>SRY gene</b> (sex-determining region), which triggers testis development in the embryo."}],
"bio23-linkage-recombination": [
  {id:"bio23-linkage-recombination-c1", front:"What is genetic linkage?", back:"The tendency of <b>genes on the same chromosome to be inherited together</b>."}
,
  {id:"bio23-linkage-recombination-c5", front:"Define linkage.", back:"The tendency of genes located on the <b>same chromosome</b> to be inherited together and not assort independently, first demonstrated by <b>Morgan</b> in Drosophila."},
  {id:"bio23-linkage-recombination-c6", front:"What is recombination frequency and how does it relate to gene distance?", back:"It is the percentage of recombinant offspring produced by crossing over; genes located <b>farther apart</b> show higher recombination frequency, while tightly linked genes show low recombination frequency."},
  {id:"bio23-linkage-recombination-c7", front:"During which stage of meiosis does crossing over occur?", back:"Crossing over between non-sister chromatids of homologous chromosomes occurs during <b>pachytene</b> of prophase I, mediated by the enzyme complex <b>recombinase</b>."}],
"bio23-sex-linked-inheritance": [
  {id:"bio23-sex-linked-inheritance-c1", front:"Give an example of a sex-linked (X-linked) genetic condition.", back:"<b>Colour blindness or haemophilia</b>."}
,
  {id:"bio23-sex-linked-inheritance-c5", front:"Why do sex-linked recessive disorders like haemophilia appear more often in males?", back:"The genes are located on the <b>X chromosome</b>; males (XY) have only one X, so a single recessive allele is expressed (<b>hemizygous</b>), while females need two recessive alleles."},
  {id:"bio23-sex-linked-inheritance-c6", front:"What is haemophilia?", back:"An <b>X-linked recessive</b> disorder affecting a clotting factor protein (VIII or IX) involved in the <b>blood clotting</b> cascade, causing continuous bleeding from a minor cut."},
  {id:"bio23-sex-linked-inheritance-c7", front:"Describe the inheritance pattern of colour blindness.", back:"It is an <b>X-linked recessive</b> trait affecting red-green cone perception; a carrier mother (heterozygous) has a 50% chance of passing it to sons, who will be <b>colour blind</b>."}],
"bio23-genetic-disorders": [
  {id:"bio23-genetic-disorders-c1", front:"What causes Down syndrome?", back:"<b>Trisomy of chromosome 21</b> (an extra copy)."},
  {id:"bio23-genetic-disorders-c2", front:"What type of mutation causes sickle cell anaemia?", back:"A <b>point mutation</b> in the gene coding for haemoglobin."}
,
  {id:"bio23-genetic-disorders-c5", front:"What chromosomal abnormality causes Down's syndrome?", back:"<b>Trisomy of chromosome 21</b> — presence of an extra copy (3 copies) of chromosome 21, resulting in characteristic features like short stature and furrowed tongue."},
  {id:"bio23-genetic-disorders-c6", front:"What causes Klinefelter's syndrome?", back:"An extra <b>X chromosome</b> giving a karyotype of <b>44+XXY</b>, resulting in overall masculine development with feminine characters like gynaecomastia."}],
"bio24-search-genetic-material": [
  {id:"bio24-search-genetic-material-c1", front:"What did the Hershey-Chase experiment prove?", back:"That <b>DNA (not protein) is the genetic material</b>, using bacteriophages."}
,
  {id:"bio24-search-genetic-material-c5", front:"What did Griffith's transformation experiment demonstrate?", back:"That some '<b>transforming principle</b>' from heat-killed virulent (S-strain) Streptococcus pneumoniae could transfer virulence to live non-virulent (R-strain) bacteria."},
  {id:"bio24-search-genetic-material-c6", front:"What did Avery, MacLeod, and McCarty prove?", back:"That <b>DNA</b>, not protein or RNA, is the transforming principle, since only DNA-digesting enzymes (DNase) could stop the transformation."},
  {id:"bio24-search-genetic-material-c7", front:"How did the Hershey-Chase experiment confirm DNA as the genetic material?", back:"Using radioactively labelled <b>bacteriophages</b> (³²P for DNA, ³⁵S for protein), they showed only <b>DNA</b> entered bacterial cells and directed progeny phage formation."}],
"bio24-structure-nucleic-acids": [
  {id:"bio24-structure-nucleic-acids-c1", front:"Who proposed the double helix structure of DNA?", back:"<b>Watson and Crick</b>."},
  {id:"bio24-structure-nucleic-acids-c2", front:"How are the two strands of DNA oriented relative to each other?", back:"<b>Antiparallel</b>."}
,
  {id:"bio24-structure-nucleic-acids-c5", front:"According to Chargaff's rule, what is the relationship between purines and pyrimidines in DNA?", back:"The amount of <b>adenine equals thymine</b> and the amount of <b>guanine equals cytosine</b>; overall purines equal pyrimidines."},
  {id:"bio24-structure-nucleic-acids-c6", front:"What holds the two strands of the DNA double helix together?", back:"<b>Hydrogen bonds</b> between complementary base pairs (A=T with 2 bonds, G≡C with 3 bonds), with the strands running <b>antiparallel</b> to each other."}],
"bio24-packaging-dna": [
  {id:"bio24-packaging-dna-c1", front:"What is a nucleosome?", back:"<b>DNA wrapped around a core of histone proteins</b>."}
,
  {id:"bio24-packaging-dna-c5", front:"What is a nucleosome?", back:"The basic unit of chromatin packaging, consisting of DNA (~200 bp) wrapped around a <b>histone octamer</b> (2 each of H2A, H2B, H3, H4)."},
  {id:"bio24-packaging-dna-c6", front:"What is the role of histone H1 in chromatin packaging?", back:"It binds to the <b>linker DNA</b> between nucleosomes, helping condense the '<b>beads-on-a-string</b>' structure into higher-order chromatin fibres."},
  {id:"bio24-packaging-dna-c7", front:"Distinguish between euchromatin and heterochromatin.", back:"<b>Euchromatin</b> is loosely packed, stains lighter, and is transcriptionally active; <b>heterochromatin</b> is densely packed, stains darker, and is transcriptionally inactive."}],
"bio24-dna-replication": [
  {id:"bio24-dna-replication-c1", front:"What is the mechanism of DNA replication called?", back:"<b>Semiconservative</b> — each daughter DNA has one old and one new strand."},
  {id:"bio24-dna-replication-c2", front:"What enzyme synthesizes new DNA strands during replication?", back:"<b>DNA polymerase</b>."}
,
  {id:"bio24-dna-replication-c5", front:"What does semiconservative replication mean, and which experiment proved it?", back:"Each daughter DNA molecule retains <b>one parental strand</b> and one newly synthesised strand; proved by the <b>Meselson and Stahl</b> experiment using ¹⁵N-labelled E. coli."},
  {id:"bio24-dna-replication-c6", front:"Why is DNA replication continuous on one strand and discontinuous on the other?", back:"DNA polymerase synthesises only in the <b>5' to 3' direction</b>; the leading strand is made continuously while the lagging strand is made discontinuously as <b>Okazaki fragments</b>."}],
"bio24-transcription": [
  {id:"bio24-transcription-c1", front:"What is transcription?", back:"The process of <b>synthesizing RNA from a DNA template</b>."},
  {id:"bio24-transcription-c2", front:"What enzyme carries out transcription?", back:"<b>RNA polymerase</b>."}
,
  {id:"bio24-transcription-c5", front:"Which enzyme catalyses transcription in prokaryotes, and what is unique about it?", back:"<b>RNA polymerase</b> catalyses all types of RNA synthesis in bacteria; it requires no primer, unlike DNA polymerase."},
  {id:"bio24-transcription-c6", front:"What is the role of the promoter and terminator in transcription?", back:"The <b>promoter</b> defines the template strand, RNA polymerase binding site, and start point; the <b>terminator</b> defines the region where transcription stops."}],
"bio24-genetic-code-translation": [
  {id:"bio24-genetic-code-translation-c1", front:"How many nucleotides make up one codon?", back:"<b>Three</b>."},
  {id:"bio24-genetic-code-translation-c2", front:"What is the start codon?", back:"<b>AUG</b> (codes for methionine)."}
,
  {id:"bio24-genetic-code-translation-c5", front:"What are the key features of the genetic code?", back:"It is a <b>triplet code</b> of 64 codons, is largely <b>degenerate</b> (more than one codon per amino acid), unambiguous, and nearly <b>universal</b> across organisms."},
  {id:"bio24-genetic-code-translation-c6", front:"What is the significance of AUG in translation?", back:"AUG is the <b>start codon</b> and also codes for <b>methionine</b>; it signals the ribosome to begin protein synthesis."}],
"bio24-gene-regulation-genome-studies": [
  {id:"bio24-gene-regulation-genome-studies-c1", front:"What is the lac operon an example of?", back:"<b>Gene regulation</b> in bacteria — genes turned on/off together depending on lactose availability."}
,
  {id:"bio24-gene-regulation-genome-studies-c5", front:"What is the lac operon and how is it regulated?", back:"An <b>inducible operon</b> in E. coli with structural genes (z, y, a) for lactose metabolism; the repressor binds the operator and blocks transcription unless <b>lactose (inducer)</b> is present."},
  {id:"bio24-gene-regulation-genome-studies-c6", front:"What was the main goal of the Human Genome Project?", back:"To determine the complete <b>nucleotide sequence</b> of human DNA (~3 billion bp) and identify all approximately <b>20,000-25,000 genes</b> in the human genome."},
  {id:"bio24-gene-regulation-genome-studies-c7", front:"What is DNA fingerprinting used for and on what principle is it based?", back:"It identifies individuals based on differences in <b>repetitive DNA sequences (VNTRs)</b>; used in forensics and paternity testing, developed by <b>Alec Jeffreys</b>."}],
"bio25-origin-life": [
  {id:"bio25-origin-life-c1", front:"What theory suggests life originated from simple organic molecules in early Earth's oceans?", back:"The <b>Oparin-Haldane theory (primordial soup theory)</b>."}
,
  {id:"bio25-origin-life-c5", front:"What did the Miller-Urey experiment demonstrate?", back:"That <b>amino acids</b> and other simple organic compounds could form spontaneously from inorganic gases (CH4, NH3, H2, water vapour) under spark discharge simulating early Earth conditions."},
  {id:"bio25-origin-life-c6", front:"What is the panspermia theory of origin of life?", back:"The idea that <b>unicellular life or spores</b> arrived on Earth from outer space, transported on meteorites or cosmic dust."},
  {id:"bio25-origin-life-c7", front:"What is meant by chemical evolution of life?", back:"The theory, proposed by <b>Oparin and Haldane</b>, that the first form of life could have come from pre-existing non-living organic molecules, with life arising as a consequence of <b>chemical evolution</b>."}],
"bio25-evidence-evolution": [
  {id:"bio25-evidence-evolution-c1", front:"What is one major line of evidence for evolution?", back:"<b>Fossil evidence</b> showing a record of change over time."}
,
  {id:"bio25-evidence-evolution-c5", front:"What are homologous organs? Give an example.", back:"Structures with the <b>same basic structure/origin</b> but different functions, e.g., forelimbs of whale, bat, and human, indicating <b>divergent evolution</b>."},
  {id:"bio25-evidence-evolution-c6", front:"What are analogous organs? Give an example.", back:"Structures with <b>different origins</b> but similar functions due to similar habitats, e.g., wings of a butterfly and a bird, indicating <b>convergent evolution</b>."},
  {id:"bio25-evidence-evolution-c7", front:"How do fossils provide evidence for evolution?", back:"<b>Fossils</b> found in rock sediments of different ages show a chronological, gradual sequence of change, e.g., the evolution of <b>Equus (horse)</b> from Eohippus."}],
"bio25-darwinism-natural-selection": [
  {id:"bio25-darwinism-natural-selection-c1", front:"What is the core idea of Darwin's natural selection?", back:"Organisms <b>better adapted to their environment survive and reproduce more</b> ('survival of the fittest')."}
,
  {id:"bio25-darwinism-natural-selection-c5", front:"What is the core idea of Darwin's theory of natural selection?", back:"Organisms produce more offspring than can survive; those with <b>heritable variations</b> better suited to the environment survive and reproduce more (<b>survival of the fittest</b>)."},
  {id:"bio25-darwinism-natural-selection-c6", front:"What is industrial melanism, and how does it illustrate natural selection?", back:"In peppered moths (<b>Biston betularia</b>), dark-coloured moths increased in polluted, soot-covered areas because they were better camouflaged from predators than light-coloured moths."},
  {id:"bio25-darwinism-natural-selection-c7", front:"How did Lamarck's theory differ from Darwin's?", back:"Lamarck proposed <b>inheritance of acquired characters</b> (use and disuse of organs) as the mechanism of evolution, whereas Darwin proposed <b>natural selection</b> acting on existing heritable variation."}],
"bio25-modern-synthetic-theory-evolution": [
  {id:"bio25-modern-synthetic-theory-evolution-c1", front:"What does the modern synthetic theory of evolution add to Darwin's ideas?", back:"It incorporates <b>genetics and mutation</b> as sources of variation."}
,
  {id:"bio25-modern-synthetic-theory-evolution-c5", front:"What is the Hardy-Weinberg principle?", back:"In a large, randomly mating population with no evolutionary forces acting, allele and genotype frequencies remain <b>constant</b> across generations, described by p²+2pq+q²=1."},
  {id:"bio25-modern-synthetic-theory-evolution-c6", front:"What is genetic drift?", back:"Random change in <b>allele frequencies</b> in a small population due to chance events, which can lead to the founder effect when a small group establishes a new population."},
  {id:"bio25-modern-synthetic-theory-evolution-c7", front:"What factors can disturb Hardy-Weinberg equilibrium and cause evolution?", back:"<b>Mutation, gene migration/flow, genetic drift, genetic recombination</b>, and natural selection can all disturb allele frequencies and drive evolutionary change."}],
"bio25-species-speciation": [
  {id:"bio25-species-speciation-c1", front:"What commonly drives speciation?", back:"<b>Geographic isolation</b> of populations, leading to independent evolution."}
,
  {id:"bio25-species-speciation-c5", front:"What is allopatric speciation?", back:"Formation of new species when populations of the same species are separated by a <b>geographical barrier</b> that prevents gene flow, leading to independent evolution."},
  {id:"bio25-species-speciation-c6", front:"What is sympatric speciation?", back:"Formation of new species within the <b>same geographical area</b> without physical isolation, often through mechanisms like polyploidy or behavioural/reproductive isolation."},
  {id:"bio25-species-speciation-c7", front:"How does polyploidy contribute to speciation, especially in plants?", back:"A change in <b>chromosome number</b> (e.g., doubling) can instantly create reproductive isolation from the parent species, rapidly giving rise to a new species, a mechanism common in <b>plants</b>."}],
"bio25-human-evolution": [
  {id:"bio25-human-evolution-c1", front:"Where did Homo sapiens evolve, according to current evidence?", back:"In <b>Africa</b>."}
,
  {id:"bio25-human-evolution-c5", front:"What key features distinguish Homo habilis from earlier hominids?", back:"Homo habilis (~2 million years ago) had a <b>brain capacity of about 650-800 cc</b> and is believed to be the first species to use and make <b>stone tools</b>."},
  {id:"bio25-human-evolution-c6", front:"What are the key characteristics of Homo erectus?", back:"Lived about <b>1.5 million years ago</b>, had a brain capacity around <b>900 cc</b>; fossils include Java man, showing more advanced tool use than habilis."},
  {id:"bio25-human-evolution-c7", front:"What characterizes Neanderthal man in the human evolutionary lineage?", back:"<b>Homo neanderthalensis</b> (~100,000-40,000 years ago) had a brain size of about <b>1400 cc</b>, lived in Europe/Asia, used hides for clothing, and buried the dead."}],
"bio26-common-diseases-pathogens": [
  {id:"bio26-common-diseases-pathogens-c1", front:"What causes typhoid?", back:"The <b>bacterium Salmonella typhi</b>."},
  {id:"bio26-common-diseases-pathogens-c2", front:"What causes malaria?", back:"The <b>protozoan parasite Plasmodium</b>, transmitted by Anopheles mosquito."}
,
  {id:"bio26-common-diseases-pathogens-c5", front:"What pathogen causes typhoid, and how is it diagnosed?", back:"<b>Salmonella typhi</b> causes typhoid fever; diagnosed by the <b>Widal test</b>, which detects antibodies against the bacterium."},
  {id:"bio26-common-diseases-pathogens-c6", front:"Name the causative organism and vector for malaria, and what causes the chills?", back:"Caused by <b>Plasmodium</b> species, transmitted by the female <b>Anopheles</b> mosquito; chills/fever occur when infected RBCs rupture and release <b>merozoites</b> into the blood."}],
"bio26-immunity-immune-system": [
  {id:"bio26-immunity-immune-system-c1", front:"What is the difference between innate and acquired immunity?", back:"<b>Innate</b> immunity is non-specific and present from birth; <b>acquired</b> immunity is specific and develops after exposure."},
  {id:"bio26-immunity-immune-system-c2", front:"Which cells produce antibodies?", back:"<b>B lymphocytes (B cells)</b>."}
,
  {id:"bio26-immunity-immune-system-c5", front:"Differentiate between active and passive immunity.", back:"<b>Active immunity</b> is produced by the body's own immune system after exposure to antigen (slow but long-lasting); <b>passive immunity</b> involves directly providing ready-made antibodies (fast but short-lived)."},
  {id:"bio26-immunity-immune-system-c6", front:"What is the difference between humoral and cell-mediated immunity?", back:"<b>Humoral immunity (antibody-mediated)</b> is mediated by <b>B-lymphocytes</b> producing antibodies; <b>cell-mediated immunity</b> is carried out by <b>T-lymphocytes</b> that directly attack infected cells."}],
"bio26-aids": [
  {id:"bio26-aids-c1", front:"What virus causes AIDS?", back:"<b>HIV (human immunodeficiency virus)</b>, a retrovirus."}
,
  {id:"bio26-aids-c5", front:"Which virus causes AIDS and which cells does it primarily target?", back:"<b>HIV (Human Immunodeficiency Virus)</b>, a retrovirus, primarily infects and destroys <b>helper T-lymphocytes (TH)</b>."},
  {id:"bio26-aids-c6", front:"What is the ELISA test used for in relation to AIDS?", back:"<b>ELISA (Enzyme-Linked Immunosorbent Assay)</b> is used to detect the presence of HIV antibodies/antigens in blood, confirming HIV infection."},
  {id:"bio26-aids-c7", front:"How does HIV reduce a person's immunity, leading to AIDS?", back:"HIV progressively decreases the number of <b>helper T-cells</b>, crippling the body's immune system so that it succumbs to opportunistic infections, defining the AIDS condition."}],
"bio26-cancer": [
  {id:"bio26-cancer-c1", front:"What fundamentally characterizes cancer at the cellular level?", back:"<b>Uncontrolled cell division</b>."}
,
  {id:"bio26-cancer-c5", front:"What is metastasis?", back:"The property of <b>malignant (cancerous) cells</b> to migrate from their origin site and invade other tissues via blood/lymph, forming secondary tumours."},
  {id:"bio26-cancer-c6", front:"Differentiate between benign and malignant tumours.", back:"A <b>benign tumour</b> remains confined to its original location and doesn't spread; a <b>malignant tumour</b> is invasive, grows uncontrollably, and undergoes <b>metastasis</b>."},
  {id:"bio26-cancer-c7", front:"Name two techniques used to diagnose cancer.", back:"<b>Biopsy and histopathological studies</b> of tissue, along with imaging techniques like <b>radiography (X-rays), CT scan, and MRI</b>, are used for cancer detection."}],
"bio26-drug-alcohol-abuse": [
  {id:"bio26-drug-alcohol-abuse-c1", front:"What is addiction primarily driven by, biologically?", back:"Substances that <b>hijack the brain's reward pathway</b>."}
,
  {id:"bio26-drug-alcohol-abuse-c5", front:"What is the source plant of opioids like morphine and heroin?", back:"Opioids are obtained from the latex of the <b>poppy plant, Papaver somniferum</b>; they act as depressants and slow down body functions."},
  {id:"bio26-drug-alcohol-abuse-c6", front:"From which plant are cannabinoid drugs like marijuana/hashish obtained, and how do they act?", back:"From the plant <b>Cannabis sativa</b>; cannabinoids interact with <b>cannabinoid receptors</b> in the brain and affect the cardiovascular system."},
  {id:"bio26-drug-alcohol-abuse-c7", front:"What is drug dependence and what are withdrawal symptoms?", back:"<b>Drug dependence</b> is compulsive drug use where the body craves the substance; stopping the drug causes <b>withdrawal symptoms</b> like anxiety, shakiness, and nausea."}],
"bio27-microbes-household-products": [
  {id:"bio27-microbes-household-products-c1", front:"Which bacterium converts milk to curd?", back:"<b>Lactobacillus</b>."}
,
  {id:"bio27-microbes-household-products-c5", front:"What bacterium converts milk to curd, and what nutritional benefit does it confer?", back:"<b>Lactobacillus</b> (lactic acid bacteria) multiplies in milk and converts it to curd; it also improves the nutritional quality by increasing <b>vitamin B12</b>."},
  {id:"bio27-microbes-household-products-c6", front:"Which microorganism causes bread dough to rise, and why?", back:"<b>Saccharomyces cerevisiae</b> (baker's yeast) ferments sugars in the dough, producing <b>CO2</b> bubbles that make it rise (puff)."},
  {id:"bio27-microbes-household-products-c7", front:"Name the bacterium responsible for the large holes in Swiss cheese.", back:"<b>Propionibacterium sharmanii</b> produces large amounts of <b>CO2</b> gas during fermentation, creating the characteristic holes."}],
"bio27-microbes-industrial-production": [
  {id:"bio27-microbes-industrial-production-c1", front:"What is a bioreactor/fermenter used for?", back:"<b>Large-scale culturing of microbes</b> to produce useful products."}
,
  {id:"bio27-microbes-industrial-production-c5", front:"Which fungus is used commercially to produce citric acid?", back:"<b>Aspergillus niger</b> is used industrially to produce <b>citric acid</b> through fermentation."},
  {id:"bio27-microbes-industrial-production-c6", front:"Who discovered penicillin, and from which fungus?", back:"<b>Alexander Fleming</b> discovered <b>penicillin</b> from the fungus <b>Penicillium notatum</b>."},
  {id:"bio27-microbes-industrial-production-c7", front:"Name the yeast used to produce statins that lower blood cholesterol.", back:"<b>Monascus purpureus</b> is used to produce <b>statins</b>, which competitively inhibit the enzyme controlling cholesterol synthesis."}],
"bio27-microbes-sewage-treatment": [
  {id:"bio27-microbes-sewage-treatment-c1", front:"What role do aerobic bacteria play in sewage treatment (activated sludge)?", back:"They <b>break down organic matter</b> in the waste water."}
,
  {id:"bio27-microbes-sewage-treatment-c5", front:"What does BOD stand for, and what does it indicate about sewage water?", back:"<b>Biochemical Oxygen Demand</b> — the amount of oxygen microbes need to break down organic matter in a water sample; a higher BOD means greater pollution."},
  {id:"bio27-microbes-sewage-treatment-c6", front:"What happens during secondary (biological) treatment of sewage?", back:"Sewage flows into large <b>aeration tanks</b> where aerobic microbes consume the organic matter, significantly reducing the <b>BOD</b>."},
  {id:"bio27-microbes-sewage-treatment-c7", front:"What is activated sludge, and how is it reused?", back:"The bacterial floc that settles at the bottom of the aeration tank is called <b>activated sludge</b>; a small part is pumped back as inoculum for the secondary treatment."}],
"bio27-microbes-biogas-production": [
  {id:"bio27-microbes-biogas-production-c1", front:"What organisms produce biogas from waste?", back:"<b>Methanogenic bacteria (methanogens)</b>."}
,
  {id:"bio27-microbes-biogas-production-c5", front:"Which group of bacteria produce methane in biogas plants?", back:"<b>Methanogens</b> (e.g., <b>Methanobacterium</b>), anaerobic bacteria naturally found in the rumen of cattle, produce methane from digested cellulosic waste."},
  {id:"bio27-microbes-biogas-production-c6", front:"Why is cattle dung slurry particularly effective for generating gobar gas?", back:"The <b>rumen</b> of cattle harbors <b>methanogenic bacteria</b> that anaerobically digest cellulose, so their dung is rich in these organisms for biogas production."},
  {id:"bio27-microbes-biogas-production-c7", front:"What is the main combustible component of biogas?", back:"<b>Methane</b> gas, generated by anaerobic microbial degradation of organic matter, is the main combustible component of <b>biogas</b>."}],
"bio27-microbes-biocontrol-agents": [
  {id:"bio27-microbes-biocontrol-agents-c1", front:"Which bacterium is used as a natural biopesticide against insect larvae?", back:"<b>Bacillus thuringiensis (Bt)</b>."}
,
  {id:"bio27-microbes-biocontrol-agents-c5", front:"Which bacterium is used to control butterfly and moth caterpillars, and how is it applied?", back:"<b>Bacillus thuringiensis</b> (Bt) produces a toxin lethal to insect larvae; it is applied as a dried spore powder or engineered directly into crops like <b>Bt cotton</b>."},
  {id:"bio27-microbes-biocontrol-agents-c6", front:"Name the free-living fungus used as a biocontrol agent against several plant pathogens.", back:"<b>Trichoderma</b> species are free-living fungi in root ecosystems that act as effective biocontrol agents against many plant pathogens."},
  {id:"bio27-microbes-biocontrol-agents-c7", front:"Why are baculoviruses considered ideal biological control agents?", back:"<b>Baculoviruses</b> attack insects and arthropods and are mostly <b>species-specific</b>, giving narrow-spectrum insecticidal action with no harm to plants, mammals, or beneficial insects."}],
"bio27-microbes-biofertilizers": [
  {id:"bio27-microbes-biofertilizers-c1", front:"Which bacterium fixes nitrogen in the root nodules of legumes?", back:"<b>Rhizobium</b>."}
,
  {id:"bio27-microbes-biofertilizers-c5", front:"Which bacterium forms symbiotic root nodules with legumes and fixes atmospheric nitrogen?", back:"<b>Rhizobium</b> forms a symbiotic association with leguminous plant roots and fixes atmospheric <b>nitrogen</b> in root nodules."},
  {id:"bio27-microbes-biofertilizers-c6", front:"Name two free-living, nitrogen-fixing bacteria used as biofertilizers.", back:"<b>Azotobacter</b> and <b>Azospirillum</b> are free-living soil bacteria that fix atmospheric nitrogen."},
  {id:"bio27-microbes-biofertilizers-c7", front:"How does mycorrhiza benefit its host plant?", back:"<b>Mycorrhiza</b> (e.g., the fungus <b>Glomus</b>) forms a symbiotic association with roots that improves the plant's absorption of <b>phosphorus</b> from the soil."}],
"bio28-principles-genetic-engineering": [
  {id:"bio28-principles-genetic-engineering-c1", front:"What are the core steps of genetic engineering?", back:"<b>Cutting and joining DNA, introducing it into a host, and selecting/maintaining the changed cells</b>."}
,
  {id:"bio28-principles-genetic-engineering-c5", front:"What is genetic engineering?", back:"The technique of altering the chemistry of genetic material (DNA/RNA) to introduce it into a host organism and change the host's <b>phenotype</b>."},
  {id:"bio28-principles-genetic-engineering-c6", front:"Who first constructed recombinant DNA, and how?", back:"<b>Cohen and Boyer</b> (1972) linked an antibiotic-resistance gene from <b>Salmonella typhimurium</b> with the plasmid <b>pSC101</b> and introduced it into <b>E. coli</b>, creating the first recombinant DNA."},
  {id:"bio28-principles-genetic-engineering-c7", front:"What are the two core techniques central to genetic engineering?", back:"(1) <b>Recombinant DNA technology</b> to construct novel DNA, and (2) methods to transfer this DNA into a host and alter the host's <b>phenotype</b>."}],
"bio28-molecular-scissors-glue-enzymes": [
  {id:"bio28-molecular-scissors-glue-enzymes-c1", front:"What do restriction enzymes do?", back:"<b>Cut DNA at specific recognition sequences</b>."},
  {id:"bio28-molecular-scissors-glue-enzymes-c2", front:"What enzyme joins DNA fragments together?", back:"<b>DNA ligase</b>."}
,
  {id:"bio28-molecular-scissors-glue-enzymes-c5", front:"What is the function of restriction endonucleases in genetic engineering?", back:"They recognize specific <b>palindromic</b> DNA sequences and cut both strands at those sites, acting as \"molecular scissors\" (e.g., <b>EcoRI</b>)."},
  {id:"bio28-molecular-scissors-glue-enzymes-c6", front:"Which enzyme joins DNA fragments together, and what is it commonly called?", back:"<b>DNA ligase</b> joins DNA fragments produced by restriction enzymes; it is often called \"molecular glue.\""}],
"bio28-cloning-vectors": [
  {id:"bio28-cloning-vectors-c1", front:"What is commonly used as a cloning vector to carry foreign DNA into a host?", back:"A <b>plasmid</b>."}
,
  {id:"bio28-cloning-vectors-c5", front:"Name three essential features of a good cloning vector.", back:"An <b>origin of replication (ori)</b>, a <b>selectable marker</b> gene, and unique <b>restriction/cloning sites</b>."},
  {id:"bio28-cloning-vectors-c6", front:"What is insertional inactivation, and how does it help detect recombinants?", back:"Inserting foreign DNA into a restriction site within a <b>marker gene</b> (e.g., an antibiotic-resistance gene) inactivates it, letting <b>recombinants</b> be distinguished from non-recombinants by loss of the marker's function."},
  {id:"bio28-cloning-vectors-c7", front:"Name a classic plasmid cloning vector and its selectable markers.", back:"<b>pBR322</b> is a classic cloning vector carrying <b>ampicillin</b>- and <b>tetracycline</b>-resistance genes as selectable markers."}],
"bio28-getting-dna-into-host": [
  {id:"bio28-getting-dna-into-host-c1", front:"Name a method used to introduce foreign DNA into a host cell.", back:"<b>Microinjection, gene gun, or bacterial transformation</b>."}
,
  {id:"bio28-getting-dna-into-host-c5", front:"How are bacterial cells made \"competent\" to take up foreign DNA?", back:"Cells are treated with a divalent cation like <b>CaCl2</b> to increase membrane permeability, then given a brief <b>heat shock</b> (42°C) after ice incubation, allowing DNA to enter."},
  {id:"bio28-getting-dna-into-host-c6", front:"What method directly delivers DNA into an animal cell's nucleus?", back:"<b>Micro-injection</b>, in which DNA is injected directly into the nucleus of the recipient cell."},
  {id:"bio28-getting-dna-into-host-c7", front:"How does the gene gun (biolistics) method introduce DNA into plant cells?", back:"Cells are bombarded with high-velocity <b>microparticles of gold or tungsten coated with DNA</b>, a method also called <b>biolistics</b>."}],
"bio28-polymerase-chain-reaction-pcr": [
  {id:"bio28-polymerase-chain-reaction-pcr-c1", front:"What does PCR do?", back:"<b>Amplifies a specific DNA segment</b> into millions of copies."},
  {id:"bio28-polymerase-chain-reaction-pcr-c2", front:"What heat-stable enzyme is used in PCR?", back:"<b>Taq polymerase</b>."}
,
  {id:"bio28-polymerase-chain-reaction-pcr-c5", front:"What are the three steps of one PCR cycle?", back:"<b>Denaturation</b> (strand separation), <b>annealing</b> (primer binding), and <b>extension</b> (new strand synthesis by DNA polymerase)."},
  {id:"bio28-polymerase-chain-reaction-pcr-c6", front:"Why is Taq polymerase used in PCR instead of a normal DNA polymerase?", back:"<b>Taq polymerase</b>, isolated from the thermophilic bacterium <b>Thermus aquaticus</b>, remains active at the high denaturation temperatures used in PCR."}],
"bio28-downstream-processing-bioreactors": [
  {id:"bio28-downstream-processing-bioreactors-c1", front:"What is downstream processing?", back:"<b>Purification and formulation of a product</b> after it is made in a bioreactor."}
,
  {id:"bio28-downstream-processing-bioreactors-c5", front:"What is a bioreactor, and why is it used in industrial biotechnology?", back:"A large vessel in which raw materials are biologically converted into a specific product by cells or enzymes under optimum <b>temperature, pH, substrate, and oxygen</b>, enabling production at volumes of 100–1000 litres."},
  {id:"bio28-downstream-processing-bioreactors-c6", front:"What is the function of a sparger in a stirred-tank bioreactor?", back:"A <b>sparger</b> bubbles air/oxygen into the culture to maintain adequate <b>dissolved oxygen</b> for the growing cells."},
  {id:"bio28-downstream-processing-bioreactors-c7", front:"What is downstream processing?", back:"The series of steps—<b>separation, purification, and formulation</b>—carried out after biosynthesis to convert the product into a marketable form, including quality-control testing."}],
"bio29-bt-crops-insect-resistance": [
  {id:"bio29-bt-crops-insect-resistance-c1", front:"What gives Bt cotton its insect resistance?", back:"A <b>toxin gene from Bacillus thuringiensis</b>, inserted into the plant."}
,
  {id:"bio29-bt-crops-insect-resistance-c5", front:"What are cry genes, and where do they come from?", back:"<b>cry genes</b> (e.g., <b>cryIAc</b>, <b>cryIIAb</b>) encode insecticidal <b>Bt toxin</b> proteins from the bacterium <b>Bacillus thuringiensis</b>."},
  {id:"bio29-bt-crops-insect-resistance-c6", front:"How does Bt toxin kill insect larvae?", back:"The inactive protoxin is activated by the <b>alkaline pH</b> of the insect gut; the active toxin binds midgut epithelial cells and creates pores, causing cell <b>swelling and lysis</b>, killing the larva."},
  {id:"bio29-bt-crops-insect-resistance-c7", front:"Which cry genes confer resistance against cotton bollworms in Bt cotton?", back:"<b>cryIAc</b> and <b>cryIIAb</b> genes confer resistance against cotton bollworms."}],
"bio29-rna-interference-pest-resistance": [
  {id:"bio29-rna-interference-pest-resistance-c1", front:"How does RNA interference (RNAi) protect a plant from a pest?", back:"<b>Double-stranded RNA silences the pest's own mRNA</b>, preventing it from surviving on the plant."}
,
  {id:"bio29-rna-interference-pest-resistance-c5", front:"What is RNA interference (RNAi), and what natural role does it serve?", back:"A method of <b>gene silencing</b> using double-stranded RNA; in eukaryotes it acts as a cellular defense against invasion by <b>transposons</b> and <b>viruses</b>."},
  {id:"bio29-rna-interference-pest-resistance-c6", front:"How was RNAi used to make tobacco resistant to the nematode Meloidogyne incognita?", back:"Nematode-specific genes were introduced via <b>Agrobacterium</b> in both sense and antisense orientation, producing <b>dsRNA</b> in host cells that silenced the nematode's specific mRNA and prevented infestation."},
  {id:"bio29-rna-interference-pest-resistance-c7", front:"Which enzyme processes double-stranded RNA in the RNAi pathway?", back:"The <b>Dicer</b> enzyme cleaves dsRNA into small fragments that bind and silence the complementary <b>mRNA</b>."}],
"bio29-recombinant-therapeutics-insulin-vaccines": [
  {id:"bio29-recombinant-therapeutics-insulin-vaccines-c1", front:"What organism is genetically engineered to produce human insulin (Humulin)?", back:"<b>Escherichia coli (E. coli)</b>."}
,
  {id:"bio29-recombinant-therapeutics-insulin-vaccines-c5", front:"How is human insulin (Humulin) produced using recombinant DNA technology?", back:"DNA sequences for the <b>A and B chains</b> of insulin are inserted into plasmids and expressed separately in <b>E. coli</b>; the chains are then extracted and joined by <b>disulfide bonds</b> to form mature insulin."},
  {id:"bio29-recombinant-therapeutics-insulin-vaccines-c6", front:"What problem with earlier animal-extracted insulin did recombinant insulin solve?", back:"Insulin extracted from the pancreas of slaughtered cattle/pigs often caused <b>allergic reactions</b>; recombinant human insulin (<b>Humulin</b>) eliminated this problem."},
  {id:"bio29-recombinant-therapeutics-insulin-vaccines-c7", front:"Give an example of a recombinant vaccine and its production system.", back:"The <b>Hepatitis B</b> vaccine is produced by expressing the viral surface antigen gene in <b>yeast</b>."}],
"bio29-gene-therapy": [
  {id:"bio29-gene-therapy-c1", front:"What is gene therapy?", back:"<b>Correcting a genetic defect by inserting a normal gene</b> into a patient's cells."}
,
  {id:"bio29-gene-therapy-c5", front:"What genetic disorder was treated in the first approved gene therapy attempt (1990)?", back:"<b>Adenosine deaminase (ADA) deficiency</b>, caused by deletion of the gene for the ADA enzyme critical to immune function."},
  {id:"bio29-gene-therapy-c6", front:"Describe the procedure used in early ADA gene therapy.", back:"Lymphocytes were taken from the patient's blood, grown in culture, and a functional <b>ADA gene</b> was introduced using a <b>retroviral vector</b>, then the cells were returned to the patient."},
  {id:"bio29-gene-therapy-c7", front:"Why was early ADA gene therapy not a permanent cure?", back:"Since the corrected <b>lymphocytes are not immortal</b>, treatment had to be repeated periodically; a permanent cure requires correcting <b>bone marrow stem cells</b> at an early embryonic stage."}],
"bio29-molecular-diagnosis": [
  {id:"bio29-molecular-diagnosis-c1", front:"Name a technique used for early/molecular disease diagnosis.", back:"<b>PCR or ELISA</b>."}
,
  {id:"bio29-molecular-diagnosis-c5", front:"How is PCR used for early diagnosis of diseases like HIV or cancer?", back:"PCR amplifies minute amounts of pathogen or mutated gene nucleic acid, allowing detection of infections like <b>HIV</b> before <b>antibodies</b> appear, or early identification of cancer-related mutations."},
  {id:"bio29-molecular-diagnosis-c6", front:"What principle does ELISA use to detect infection?", back:"ELISA relies on <b>antigen-antibody interaction</b> to detect the presence of a specific antigen or antibody in a patient's sample."},
  {id:"bio29-molecular-diagnosis-c7", front:"How does DNA probe hybridization detect a genetic disorder like sickle cell anemia?", back:"A labeled DNA <b>probe</b> complementary to the mutated sequence hybridizes specifically with it, revealing the presence of the mutation causing <b>sickle cell anemia</b>."}],
"bio29-transgenic-animals": [
  {id:"bio29-transgenic-animals-c1", front:"What is a transgenic animal?", back:"An animal that <b>carries a foreign gene deliberately inserted into its genome</b>."}
,
  {id:"bio29-transgenic-animals-c5", front:"What is a transgenic animal?", back:"An animal that has had a foreign gene (<b>transgene</b>) deliberately inserted into its genome, present and expressed in every cell."},
  {id:"bio29-transgenic-animals-c6", front:"Name the first transgenic cow and what made it notable.", back:"<b>Rosie</b>, the first transgenic cow, produced milk enriched with the human protein <b>alpha-lactalbumin</b>, giving a more nutritionally balanced milk for infants."},
  {id:"bio29-transgenic-animals-c7", front:"Give an example of transgenic animals used to test vaccine safety.", back:"<b>Transgenic mice</b> are used to test the safety of the <b>polio vaccine</b> before it is used on humans."}],
"bio29-gmos-benefits-biosafety-regulation": [
  {id:"bio29-gmos-benefits-biosafety-regulation-c1", front:"What body regulates GMOs in India?", back:"The <b>GEAC (Genetic Engineering Appraisal Committee)</b>."}
,
  {id:"bio29-gmos-benefits-biosafety-regulation-c5", front:"What is Golden Rice, and why was it developed?", back:"A <b>genetically engineered</b> rice variety enriched with <b>beta-carotene</b> (a Vitamin A precursor) in the endosperm, developed to combat vitamin A deficiency."},
  {id:"bio29-gmos-benefits-biosafety-regulation-c6", front:"Which body regulates the use and release of GMOs in India?", back:"The <b>GEAC</b> (Genetic Engineering Appraisal Committee) decides on the validity of GM research and the safety of releasing GM organisms in India."},
  {id:"bio29-gmos-benefits-biosafety-regulation-c7", front:"Name two potential biosafety concerns associated with GM crops.", back:"Possible unintended harm to <b>non-target organisms</b>, and <b>gene flow</b> of transgenes to wild relatives or other species, reducing the effectiveness of biocontrol measures."}],
"bio30-organisms-environment": [
  {id:"bio30-organisms-environment-c1", front:"What is the difference between habitat and niche?", back:"<b>Habitat</b> is where an organism lives; <b>niche</b> is its functional role in the ecosystem."},
  {id:"bio30-organisms-environment-c2", front:"What is hibernation?", back:"<b>Dormancy during winter</b> to escape unfavorable cold conditions."}
],
"bio30-population-interactions": [
  {id:"bio30-population-interactions-c1", front:"What is mutualism?", back:"An interaction where <b>both species benefit</b>."},
  {id:"bio30-population-interactions-c2", front:"What is predation?", back:"An interaction where <b>one organism (predator) kills and consumes another (prey)</b>."}
,
  {id:"bio30-population-interactions-c5", front:"What is commensalism?", back:"An interaction where one species <b>benefits</b> and the other is neither harmed nor helped, e.g., an orchid growing on a mango tree."},
  {id:"bio30-population-interactions-c6", front:"What is Gause's Competitive Exclusion Principle?", back:"Two closely related species competing for the same limiting resource cannot <b>coexist indefinitely</b>; the competitively superior species eliminates the other."}],
"bio30-population-attributes-growth": [
  {id:"bio30-population-attributes-growth-c1", front:"What are the four basic attributes of a population?", back:"<b>Birth rate, death rate, sex ratio, and age distribution</b>."},
  {id:"bio30-population-attributes-growth-c2", front:"What is the difference between exponential and logistic population growth?", back:"<b>Exponential</b> growth is unlimited (J-shaped); <b>logistic</b> growth levels off at carrying capacity (S-shaped)."}
,
  {id:"bio30-population-attributes-growth-c5", front:"Name key attributes of a population not shown by individual organisms.", back:"<b>Birth rate (natality)</b>, <b>death rate (mortality)</b>, sex ratio, and age distribution."},
  {id:"bio30-population-attributes-growth-c6", front:"Write the exponential growth equation for a population.", back:"<b>dN/dt = rN</b>, where N is population size and <b>r</b> is the intrinsic rate of natural increase, assuming unlimited resources."}],
"bio31-ecosystem-structure-components": [
  {id:"bio31-ecosystem-structure-components-c1", front:"What are the two main components of an ecosystem?", back:"<b>Biotic (living) and abiotic (non-living)</b> components."}
,
  {id:"bio31-ecosystem-structure-components-c5", front:"What are the two main components of an ecosystem?", back:"<b>Abiotic components</b> (physical/chemical factors like climate, soil) and <b>biotic components</b> (producers, consumers, decomposers)."},
  {id:"bio31-ecosystem-structure-components-c6", front:"Differentiate between primary and secondary consumers.", back:"<b>Primary consumers</b> (herbivores) feed directly on producers; <b>secondary consumers</b> (primary carnivores) feed on primary consumers."},
  {id:"bio31-ecosystem-structure-components-c7", front:"What role do decomposers play in an ecosystem?", back:"Decomposers (like fungi and bacteria) break down complex organic matter in <b>dead remains</b> and release simple inorganic substances back into the soil, a process called <b>decomposition</b>."}],
"bio31-productivity-decomposition": [
  {id:"bio31-productivity-decomposition-c1", front:"What is the difference between GPP and NPP?", back:"<b>GPP (gross primary productivity)</b> is total energy fixed; <b>NPP (net primary productivity)</b> is GPP minus respiration losses."}
,
  {id:"bio31-productivity-decomposition-c5", front:"Differentiate between Gross Primary Productivity (GPP) and Net Primary Productivity (NPP).", back:"<b>GPP</b> is the total rate of organic matter production by photosynthesis; <b>NPP</b> is GPP minus respiration losses (<b>NPP = GPP - R</b>), the biomass available to consumers."},
  {id:"bio31-productivity-decomposition-c6", front:"What is humification in the process of decomposition?", back:"The process leading to accumulation of a dark-coloured, amorphous substance called <b>humus</b>, which is resistant to microbial action and decomposes very slowly."},
  {id:"bio31-productivity-decomposition-c7", front:"Name the main steps involved in decomposition of detritus.", back:"<b>Fragmentation, leaching, catabolism, humification, and mineralisation</b> are the sequential steps by which detritivores and decomposers break down organic matter."}],
"bio31-energy-flow": [
  {id:"bio31-energy-flow-c1", front:"What is the 10% law of energy transfer?", back:"Only about <b>10% of energy is transferred from one trophic level to the next</b>."}
,
  {id:"bio31-energy-flow-c5", front:"What is the ultimate source of energy for almost all ecosystems?", back:"The <b>Sun</b>; producers capture solar energy through photosynthesis, converting it to chemical energy that flows through the <b>food chain</b>."},
  {id:"bio31-energy-flow-c6", front:"State the 10 per cent law of energy transfer.", back:"Only about <b>10%</b> of the energy available at one trophic level is transferred to the next trophic level; the rest is lost mainly as <b>heat</b> (Lindeman's law)."},
  {id:"bio31-energy-flow-c7", front:"Why is energy flow in an ecosystem unidirectional, unlike nutrient cycling?", back:"Energy captured by producers flows to consumers and decomposers but is progressively lost as <b>heat</b> at each trophic level and cannot be recycled, unlike nutrients."}],
"bio31-ecological-pyramids": [
  {id:"bio31-ecological-pyramids-c1", front:"Is the pyramid of energy always upright?", back:"<b>Yes</b> — energy always decreases at each successive trophic level."}
,
  {id:"bio31-ecological-pyramids-c5", front:"What are the three types of ecological pyramids?", back:"Pyramid of <b>numbers</b>, pyramid of <b>biomass</b>, and pyramid of <b>energy</b>, all constructed to represent trophic levels of an ecosystem."},
  {id:"bio31-ecological-pyramids-c6", front:"Why is the pyramid of energy always upright?", back:"Because energy flow is unidirectional and some energy is always lost as <b>heat</b> at each transfer, so energy at a lower trophic level is always greater than the level above it."},
  {id:"bio31-ecological-pyramids-c7", front:"Give an example of an ecosystem with an inverted pyramid of biomass.", back:"In a <b>pond/marine ecosystem</b>, the biomass of producers (phytoplankton) at any instant is less than that of consumers (zooplankton/fish), giving an <b>inverted pyramid of biomass</b>."}],
"bio31-nutrient-cycling-succession": [
  {id:"bio31-nutrient-cycling-succession-c1", front:"What is ecological succession?", back:"The <b>gradual, sequential change of a community</b> from pioneer species to a stable climax community."},
  {id:"bio31-nutrient-cycling-succession-c2", front:"In the carbon cycle, what process removes CO2 from the atmosphere?", back:"<b>Photosynthesis</b>."}
],
"bio32-concept-patterns-biodiversity": [
  {id:"bio32-concept-patterns-biodiversity-c1", front:"How does species richness generally vary with latitude?", back:"It is <b>highest near the equator and decreases toward the poles</b> (latitudinal gradient)."}
,
  {id:"bio32-concept-patterns-biodiversity-c5", front:"Define species richness.", back:"The <b>number of species</b> per unit area; one of the components of biodiversity, along with genetic and ecological diversity."},
  {id:"bio32-concept-patterns-biodiversity-c6", front:"What is the latitudinal gradient in species diversity?", back:"Species diversity generally <b>decreases</b> as one moves away from the equator towards the poles, with <b>tropical regions</b> showing more species richness than temperate ones."},
  {id:"bio32-concept-patterns-biodiversity-c7", front:"State the species-area relationship proposed by Alexander von Humboldt.", back:"Within a region, species richness increases with increasing explored area, following the equation <b>log S = log C + Z log A</b>, where Z is the slope of the line (regression coefficient)."}],
"bio32-importance-biodiversity": [
  {id:"bio32-importance-biodiversity-c1", front:"What term describes the benefits ecosystems provide to humans?", back:"<b>Ecosystem services</b>."}
,
  {id:"bio32-importance-biodiversity-c5", front:"What is the 'rivet popper hypothesis' proposed by Paul Ehrlich?", back:"It compares species in an ecosystem to <b>rivets</b> holding an aeroplane together; losing species (rivets) one by one makes the ecosystem (plane) progressively weaker until it fails."},
  {id:"bio32-importance-biodiversity-c6", front:"Differentiate between direct and indirect economic value of biodiversity.", back:"<b>Direct value</b> comes from products harvested directly like food, drugs, and fibre; <b>indirect value</b> includes ecosystem services like pollination, oxygen production, and climate regulation."},
  {id:"bio32-importance-biodiversity-c7", front:"What is 'ecosystem services' in the context of biodiversity value?", back:"Benefits provided by ecosystems such as <b>pollination, oxygen production, and nutrient cycling</b>, given a very high economic value in estimates like Robert Costanza's valuation of the biosphere."}],
"bio32-loss-biodiversity": [
  {id:"bio32-loss-biodiversity-c1", front:"What is the single biggest cause of biodiversity loss?", back:"<b>Habitat destruction/loss</b>."}
,
  {id:"bio32-loss-biodiversity-c5", front:"What does 'HIPPO' stand for as causes of biodiversity loss?", back:"<b>H</b>abitat loss/fragmentation, <b>I</b>nvasive species, <b>P</b>ollution, <b>P</b>opulation growth (human), and <b>O</b>ver-exploitation — the major causes of biodiversity loss."},
  {id:"bio32-loss-biodiversity-c6", front:"How do alien/invasive species threaten native biodiversity?", back:"Invasive species introduced into a habitat, like <b>Lantana camara</b> or the Nile perch in Lake Victoria, outcompete and cause the decline or extinction of native species."},
  {id:"bio32-loss-biodiversity-c7", front:"What is meant by Amazon forest destruction as an example of habitat loss?", back:"Large-scale clearing for agriculture and cattle ranching is destroying vast tracts of the <b>Amazon rainforest</b>, a mega-diverse habitat, considered a leading cause of biodiversity loss."}],
"bio32-biodiversity-conservation-strategies": [
  {id:"bio32-biodiversity-conservation-strategies-c1", front:"What is in-situ conservation?", back:"Protecting species <b>in their natural habitat</b> (e.g. national parks, sanctuaries)."},
  {id:"bio32-biodiversity-conservation-strategies-c2", front:"What is ex-situ conservation?", back:"Protecting species <b>outside their natural habitat</b> (e.g. zoos, seed banks)."}
,
  {id:"bio32-biodiversity-conservation-strategies-c5", front:"Differentiate between in-situ and ex-situ conservation.", back:"<b>In-situ conservation</b> protects species in their natural habitat (e.g., national parks, biosphere reserves); <b>ex-situ conservation</b> protects species outside their habitat (e.g., zoos, seed banks)."},
  {id:"bio32-biodiversity-conservation-strategies-c6", front:"What is a biodiversity hotspot?", back:"A region with very high levels of <b>species richness</b> and high <b>endemism</b> that is also under threat, prioritized for conservation; India has hotspots like the Western Ghats and Himalaya."}],
"bio2-five-kingdom-system": [
  {id:"bio2-five-kingdom-system-c1", front:"Who proposed the five kingdom system of classification?", back:"<b>R.H. Whittaker</b>."},
  {id:"bio2-five-kingdom-system-c2", front:"List the five kingdoms in Whittaker's classification.", back:"<b>Monera, Protista, Fungi, Plantae, Animalia</b>."},
  {id:"bio2-five-kingdom-system-c3", front:"On what criteria are the five kingdoms distinguished?", back:"<b>Cell structure</b> (prokaryotic/eukaryotic), <b>mode of nutrition</b>, <b>body organisation</b>, and <b>reproduction/phylogeny</b>."}
,
  {id:"bio2-five-kingdom-system-c5", front:"Who proposed the five kingdom classification and what are the five kingdoms?", back:"<b>R.H. Whittaker</b> (1969) proposed <b>Monera, Protista, Fungi, Plantae, and Animalia</b>, based on cell structure, nutrition, and body organization."}],
"bio2-monera": [
  {id:"bio2-monera-c1", front:"What is the cell type of Monera?", back:"<b>Prokaryotic</b>."},
  {id:"bio2-monera-c2", front:"Name the four basic shapes of bacteria.", back:"<b>Coccus</b> (spherical), <b>bacillus</b> (rod-shaped), <b>vibrium</b> (comma-shaped), <b>spirillum</b> (spiral)."},
  {id:"bio2-monera-c3", front:"What is the cell wall of bacteria made of?", back:"<b>Peptidoglycan</b> (murein)."},
  {id:"bio2-monera-c4", front:"What allows archaebacteria to survive in extreme environments?", back:"Their <b>cell wall structure</b> is different from other bacteria, letting them survive extreme salt, heat, or acid conditions."},
  {id:"bio2-monera-c5", front:"What are cyanobacteria commonly known as, and what can some of them do?", back:"<b>Blue-green algae</b> — photosynthetic, and some can fix atmospheric nitrogen."},
  {id:"bio2-monera-c6", front:"What structure allows certain cyanobacteria to fix atmospheric nitrogen?", back:"Specialised cells called <b>heterocysts</b>."},
  {id:"bio2-monera-c7", front:"What is distinctive about Mycoplasma?", back:"The smallest living cells known, and they completely <b>lack a cell wall</b>."},
  {id:"bio2-monera-c8", front:"How do most bacteria reproduce?", back:"Mainly <b>asexually</b> (fission, spore formation); genetic recombination can also occur via conjugation."}
],
"bio2-protista": [
  {id:"bio2-protista-c1", front:"What is the cell organisation of Protista?", back:"<b>Unicellular eukaryotic</b>."},
  {id:"bio2-protista-c2", front:"Name the three functional groups of protists based on nutrition.", back:"<b>Photosynthetic</b> (e.g. diatoms), <b>consumer/predatory</b> (e.g. protozoans), and <b>decomposer</b> (slime moulds)."},
  {id:"bio2-protista-c3", front:"What is unique about the cell wall of diatoms?", back:"Made of <b>silica</b> and virtually indestructible — accumulated diatom walls form \"diatomaceous earth.\""},
  {id:"bio2-protista-c4", front:"What locomotory structures do amoeboid, flagellated, and ciliated protozoans each use?", back:"Amoeboid: <b>pseudopodia</b>; flagellated: <b>flagella</b>; ciliated: <b>cilia</b>."},
  {id:"bio2-protista-c5", front:"Give an example of a parasitic protozoan and the disease it causes.", back:"<b>Plasmodium</b> — causes malaria."},
  {id:"bio2-protista-c6", front:"What is bioluminescence, and which protist group commonly shows it?", back:"Emission of <b>light</b> by a living organism; shown by some <b>dinoflagellates</b>."}
],
"bio2-fungi": [
  {id:"bio2-fungi-c1", front:"What is the cell wall of fungi made of?", back:"<b>Chitin</b>."},
  {id:"bio2-fungi-c2", front:"What is the mode of nutrition in fungi?", back:"<b>Heterotrophic</b> — saprophytic (on dead matter) or parasitic."},
  {id:"bio2-fungi-c3", front:"What is a mycelium?", back:"The network of thread-like <b>hyphae</b> that makes up a fungus's body."},
  {id:"bio2-fungi-c4", front:"Distinguish septate from aseptate (coenocytic) hyphae.", back:"Septate hyphae have <b>cross-walls</b> dividing cells; aseptate hyphae are <b>continuous</b>, without septa."},
  {id:"bio2-fungi-c5", front:"Name the four classes of fungi.", back:"<b>Phycomycetes, Ascomycetes, Basidiomycetes, Deuteromycetes</b>."},
  {id:"bio2-fungi-c6", front:"What is distinctive about Deuteromycetes (\"imperfect fungi\")?", back:"Only their <b>asexual/vegetative</b> reproductive stages are known."}
],
"bio2-lichens": [
  {id:"bio2-lichens-c1", front:"What is a lichen?", back:"A symbiotic association between a <b>fungus</b> (mycobiont) and an <b>alga/cyanobacterium</b> (phycobiont)."},
  {id:"bio2-lichens-c2", front:"What role does the algal partner play in a lichen?", back:"<b>Photosynthesis</b> — provides food to the association."},
  {id:"bio2-lichens-c3", front:"What role does the fungal partner play in a lichen?", back:"Provides <b>shelter</b> and absorbs <b>water and minerals</b> for the alga."},
  {id:"bio2-lichens-c4", front:"Why are lichens used as pollution indicators?", back:"They are highly sensitive to air pollution and <b>don't grow in polluted (SO₂-rich) areas</b>."}
],
"bio2-viruses-viroids": [
  {id:"bio2-viruses-viroids-c1", front:"Are viruses living or non-living, and why?", back:"<b>Inert outside a host</b> cell (can form crystals), but show life-like replication only <b>inside</b> a living host cell."},
  {id:"bio2-viruses-viroids-c2", front:"What is a virus's genetic material — DNA, RNA, or both?", back:"<b>Either DNA or RNA</b>, never both."},
  {id:"bio2-viruses-viroids-c3", front:"What is a capsid?", back:"The <b>protein coat</b> enclosing a virus's nucleic acid, made of protein subunits called capsomeres."},
  {id:"bio2-viruses-viroids-c4", front:"What is a viroid, and how does it differ from a virus?", back:"An infectious agent made of <b>only free RNA</b> (no protein coat) — smaller than a virus."},
  {id:"bio2-viruses-viroids-c5", front:"What is a prion?", back:"An infectious agent made of <b>only abnormally-folded protein</b> (no nucleic acid)."},
  {id:"bio2-viruses-viroids-c6", front:"What is a bacteriophage?", back:"A <b>virus that infects bacteria</b>."}
],
"bio3-algae": [
  {id:"bio3-algae-c1", front:"What pigment and stored food are characteristic of Chlorophyceae (green algae)?", back:"<b>Chlorophyll a & b</b>; stores <b>starch</b>."},
  {id:"bio3-algae-c2", front:"What pigment and stored food are characteristic of Phaeophyceae (brown algae)?", back:"<b>Fucoxanthin</b>; stores <b>mannitol and laminarin</b>."},
  {id:"bio3-algae-c3", front:"What pigment and stored food are characteristic of Rhodophyceae (red algae)?", back:"<b>Phycoerythrin</b>; stores <b>floridean starch</b>."},
  {id:"bio3-algae-c4", front:"What is the cell wall of algae made of?", back:"<b>Cellulose</b>."},
  {id:"bio3-algae-c5", front:"Distinguish isogamous, anisogamous, and oogamous sexual reproduction.", back:"<b>Isogamous</b>: similar gametes fuse. <b>Anisogamous</b>: dissimilar motile gametes fuse. <b>Oogamous</b>: a large non-motile female gamete fuses with a small motile male gamete."},
  {id:"bio3-algae-c6", front:"Name one economic/ecological importance of algae.", back:"<b>Agar</b> (from red algae) is used in labs, and algae carry out <b>at least half of the total CO₂ fixation</b> on Earth through photosynthesis."}
],
"bio3-bryophytes": [
  {id:"bio3-bryophytes-c1", front:"Why are bryophytes called \"amphibians of the plant kingdom\"?", back:"They need <b>water for fertilisation</b> but otherwise live on land."},
  {id:"bio3-bryophytes-c2", front:"Do bryophytes have true roots, stems, and leaves?", back:"<b>No</b> — only root-like, stem-like, and leaf-like structures (rhizoids, not true roots)."},
  {id:"bio3-bryophytes-c3", front:"Which phase dominates the bryophyte life cycle?", back:"The <b>gametophyte</b> (haploid) phase."},
  {id:"bio3-bryophytes-c4", front:"How does the sporophyte relate to the gametophyte in bryophytes?", back:"The sporophyte is <b>not free-living</b> — it stays attached to and dependent on the gametophyte."},
  {id:"bio3-bryophytes-c5", front:"Name the main classes of bryophytes.", back:"<b>Liverworts, Mosses, and Hornworts</b>."},
  {id:"bio3-bryophytes-c6", front:"Give one economic use of bryophytes.", back:"<b>Sphagnum</b> (moss) provides peat, used as fuel and as a water-retaining packing material."}
],
"bio3-pteridophytes": [
  {id:"bio3-pteridophytes-c1", front:"What makes pteridophytes significant compared to bryophytes?", back:"The first plants with true <b>vascular tissue</b> (xylem & phloem) and differentiated roots, stems, leaves."},
  {id:"bio3-pteridophytes-c2", front:"Which phase dominates the pteridophyte life cycle?", back:"The <b>sporophyte</b> (diploid) phase."},
  {id:"bio3-pteridophytes-c3", front:"Where are spores produced in a pteridophyte?", back:"In <b>sporangia</b>, borne on sporophylls."},
  {id:"bio3-pteridophytes-c4", front:"What is heterospory?", back:"Production of <b>two kinds of spores</b> — microspores (male) and megaspores (female) — by the same plant."},
  {id:"bio3-pteridophytes-c5", front:"Why is heterospory in pteridophytes evolutionarily significant?", back:"It's considered the <b>precursor to the seed habit</b>, since the megaspore develops partly on the parent sporophyte."}
],
"bio3-gymnosperms": [
  {id:"bio3-gymnosperms-c1", front:"What does \"gymnosperm\" (naked seed) describe?", back:"Seeds are <b>not enclosed</b> within a fruit/ovary wall."},
  {id:"bio3-gymnosperms-c2", front:"Are gymnosperms homosporous or heterosporous?", back:"<b>Heterosporous</b> — produce microspores (male) and megaspores (female)."},
  {id:"bio3-gymnosperms-c3", front:"Where are microspores and megaspores produced in gymnosperms?", back:"In <b>male and female cones (strobili)</b> respectively."},
  {id:"bio3-gymnosperms-c4", front:"How does pollination occur in gymnosperms?", back:"Always by <b>wind (anemophilous)</b>."},
  {id:"bio3-gymnosperms-c5", front:"Give two examples of gymnosperms.", back:"<b>Pinus</b> and <b>Cycas</b>."}
],
"bio3-plant-life-cycles": [
  {id:"bio3-plant-life-cycles-c1", front:"What is a haplontic life cycle?", back:"The <b>haploid gametophyte</b> is the dominant, free-living phase; the diploid phase is short-lived (e.g. most algae)."},
  {id:"bio3-plant-life-cycles-c2", front:"What is a diplontic life cycle?", back:"The <b>diploid sporophyte</b> is the dominant, free-living phase; the gametophyte is reduced to a few cells (e.g. gymnosperms, angiosperms)."},
  {id:"bio3-plant-life-cycles-c3", front:"What is a haplo-diplontic life cycle?", back:"Both gametophyte and sporophyte phases are multicellular, but <b>one dominates</b> (e.g. bryophytes: gametophyte-dominant; pteridophytes: sporophyte-dominant)."},
  {id:"bio3-plant-life-cycles-c4", front:"What does \"alternation of generations\" mean?", back:"A plant life cycle <b>alternates</b> between a haploid gametophytic phase and a diploid sporophytic phase."}
],
"bio4-basis-classification": [
  {id:"bio4-basis-classification-c1", front:"Distinguish radial from bilateral symmetry.", back:"<b>Radial</b>: body parts arranged around a central axis. <b>Bilateral</b>: symmetrical left and right halves along one plane."},
  {id:"bio4-basis-classification-c2", front:"Distinguish diploblastic from triploblastic animals.", back:"<b>Diploblastic</b>: two germ layers (ectoderm & endoderm). <b>Triploblastic</b>: three germ layers (ectoderm, mesoderm, endoderm)."},
  {id:"bio4-basis-classification-c3", front:"Define coelom.", back:"A body cavity <b>lined by mesoderm</b> on both sides (gut and body wall)."},
  {id:"bio4-basis-classification-c4", front:"Distinguish coelomate, pseudocoelomate, and acoelomate animals.", back:"<b>Coelomate</b>: true mesoderm-lined cavity. <b>Pseudocoelomate</b>: cavity present but not fully mesoderm-lined. <b>Acoelomate</b>: no body cavity."},
  {id:"bio4-basis-classification-c5", front:"What is metameric segmentation?", back:"Repetition of <b>body segments</b> externally and internally along the main body axis."},
  {id:"bio4-basis-classification-c6", front:"Distinguish protostomes from deuterostomes.", back:"<b>Protostomes</b>: blastopore becomes the mouth. <b>Deuterostomes</b>: blastopore becomes the anus; mouth forms separately."}
],
"bio4-non-chordates-i": [
  {id:"bio4-non-chordates-i-c1", front:"What is the key feature of Porifera (sponges)?", back:"<b>Cellular-level organisation</b> with a unique water canal system for feeding and gas exchange."},
  {id:"bio4-non-chordates-i-c2", front:"What supports/protects the body of Porifera?", back:"<b>Spicules</b> or spongin fibres."},
  {id:"bio4-non-chordates-i-c3", front:"What is a key defining feature of Cnidaria?", back:"<b>Tissue-level organisation</b>, radial symmetry, and stinging cells called cnidoblasts."},
  {id:"bio4-non-chordates-i-c4", front:"What is polymorphism in Cnidaria?", back:"Two body forms — <b>polyp</b> (sessile) and <b>medusa</b> (free-swimming) — sometimes both in one life cycle."},
  {id:"bio4-non-chordates-i-c5", front:"What is a key feature of Ctenophora?", back:"Marine, biradial symmetry, and locomotion by eight rows of cilia called <b>comb plates</b>."},
  {id:"bio4-non-chordates-i-c6", front:"What is a key feature of Platyhelminthes (flatworms)?", back:"Bilateral symmetry, dorsoventrally flattened, <b>acoelomate</b>; many are endoparasites."},
  {id:"bio4-non-chordates-i-c7", front:"What is a key feature of Nematoda (roundworms)?", back:"Cylindrical, unsegmented, <b>pseudocoelomate</b> body; complete digestive tract (e.g. Ascaris)."},
  {id:"bio4-non-chordates-i-c8", front:"What is a key feature of Annelida?", back:"True <b>coelomate</b>, metamerically segmented body, with a closed circulatory system."}
],
"bio4-non-chordates-ii": [
  {id:"bio4-non-chordates-ii-c1", front:"Which is the largest animal phylum, and what is its key feature?", back:"<b>Arthropoda</b> — jointed appendages, chitinous exoskeleton, open circulatory system."},
  {id:"bio4-non-chordates-ii-c2", front:"What respiratory organs do different arthropods use?", back:"<b>Gills, book lungs, or tracheal tubes</b>, depending on the group."},
  {id:"bio4-non-chordates-ii-c3", front:"What is a key feature of Mollusca?", back:"Soft, unsegmented body typically with a calcareous <b>shell</b>, a muscular foot, and a mantle."},
  {id:"bio4-non-chordates-ii-c4", front:"What is the radula in molluscs?", back:"A file-like <b>rasping/scraping</b> feeding structure in the mouth."},
  {id:"bio4-non-chordates-ii-c5", front:"What is a key feature of Echinodermata?", back:"Spiny-skinned, coelomate marine animals with an exclusive <b>water vascular system</b> for locomotion."},
  {id:"bio4-non-chordates-ii-c6", front:"How does symmetry differ between echinoderm larvae and adults?", back:"Larvae are <b>bilaterally</b> symmetrical; adults are <b>radially</b> symmetrical."},
  {id:"bio4-non-chordates-ii-c7", front:"What is a key feature of Hemichordata?", back:"Worm-like marine deuterostomes with a <b>proboscis, collar, and trunk</b>."}
],
"bio4-chordates-i": [
  {id:"bio4-chordates-i-c1", front:"Name the three fundamental features that define a chordate.", back:"A <b>notochord</b>, a dorsal hollow <b>nerve cord</b>, and paired <b>pharyngeal gill slits</b> at some life stage."},
  {id:"bio4-chordates-i-c2", front:"How does the fate of the notochord differ between non-vertebrate chordates and Vertebrata?", back:"In non-vertebrate chordates it <b>persists</b> (in larva or throughout life); in Vertebrata it's <b>replaced by a vertebral column</b> in the adult."},
  {id:"bio4-chordates-i-c3", front:"What is unique about Cyclostomes (e.g. lamprey)?", back:"<b>Jawless</b>, and ectoparasitic on other fish, feeding by attaching with a sucking mouth."},
  {id:"bio4-chordates-i-c4", front:"What is the key feature distinguishing Chondrichthyes?", back:"A <b>cartilaginous</b> endoskeleton (no bone) — e.g. sharks, rays."},
  {id:"bio4-chordates-i-c5", front:"What is the key feature distinguishing Osteichthyes?", back:"A <b>bony</b> endoskeleton."}
],
"bio4-chordates-ii": [
  {id:"bio4-chordates-ii-c1", front:"What key adaptation lets amphibians live both in water and on land?", back:"They can respire through <b>skin, gills (larvae), or lungs (adults)</b>."},
  {id:"bio4-chordates-ii-c2", front:"What is a key feature of Reptilia?", back:"<b>Dry, scaly skin</b>, and the first group to lay hard-shelled (amniotic) eggs on land."},
  {id:"bio4-chordates-ii-c3", front:"What is a key feature of Aves (birds)?", back:"<b>Warm-blooded</b>, body covered in feathers, forelimbs modified into wings."},
  {id:"bio4-chordates-ii-c4", front:"What is a key feature of Mammalia?", back:"Presence of <b>mammary glands</b> and (in most) hair on the skin."},
  {id:"bio4-chordates-ii-c5", front:"What are egg-laying mammals called, and give an example.", back:"<b>Monotremes</b> — e.g. the Platypus."},
  {id:"bio4-chordates-ii-c6", front:"Distinguish poikilothermous from homeothermous animals.", back:"<b>Poikilothermous</b>: body temperature varies with environment (fish, amphibians, reptiles). <b>Homeothermous</b>: constant body temperature (birds, mammals)."}
]
};
